fun interpolateMultiColor(colors: List<androidx.compose.ui.graphics.Color>, fraction: Float): androidx.compose.ui.graphics.Color {
    if (colors.isEmpty()) return androidx.compose.ui.graphics.Color.Transparent
    if (colors.size == 1) return colors.first()
    val f = fraction.coerceIn(0f, 1f)
    val segmentCount = colors.size - 1
    val segmentFloat = f * segmentCount
    val index = segmentFloat.toInt().coerceIn(0, segmentCount - 1)
    val localFraction = segmentFloat - index
    val c1 = colors[index]
    val c2 = colors[index + 1]
    return androidx.compose.ui.graphics.Color(
        red = c1.red + (c2.red - c1.red) * localFraction,
        green = c1.green + (c2.green - c1.green) * localFraction,
        blue = c1.blue + (c2.blue - c1.blue) * localFraction,
        alpha = c1.alpha + (c2.alpha - c1.alpha) * localFraction
    )
}

inline fun projectPointOnSegment(
    px: Float, py: Float,
    ax: Float, ay: Float,
    bx: Float, by: Float
): Triple<Float, Float, Float> {
    val abX = bx - ax
    val abY = by - ay
    val abLenSq = abX * abX + abY * abY
    if (abLenSq <= 0f) return Triple(0f, ax, ay)
    val apX = px - ax
    val apY = py - ay
    val t = ((apX * abX + apY * abY) / abLenSq).coerceIn(0f, 1f)
    val projX = ax + t * abX
    val projY = ay + t * abY
    return Triple(t, projX, projY)
}

val processedImageBitmapCache = object : java.util.concurrent.ConcurrentHashMap<String, androidx.compose.ui.graphics.ImageBitmap>() {
    override fun put(key: String, value: androidx.compose.ui.graphics.ImageBitmap): androidx.compose.ui.graphics.ImageBitmap? {
        if (this.size > 16) {
            val keysToEvict = this.keys().toList().take(8)
            for (k in keysToEvict) {
                this.remove(k)
            }
        }
        return super.put(key, value)
    }
}
val pixelStretchBitmapsCache = java.util.concurrent.ConcurrentHashMap<String, android.graphics.Bitmap>()

fun extractPixelStretchBitmap(
    source: android.graphics.Bitmap,
    sliceLine: Float,
    horizontalOrientation: Boolean
): android.graphics.Bitmap {
    val srcW = source.width
    val srcH = source.height
    try {
        if (horizontalOrientation) {
            val initialX = (sliceLine * (srcW - 1)).toInt().coerceIn(0, srcW - 1)
            var targetX = initialX
            val column = IntArray(srcH)
            var foundNonTransparent = false
            
            // Check initial target column
            source.getPixels(column, 0, 1, targetX, 0, 1, srcH)
            if (column.any { ((it shr 24) and 0xff) > 5 }) {
                foundNonTransparent = true
            } else {
                // Outward content-aware scan to locate nearest non-transparent column
                for (offset in 1 until srcW) {
                    val leftX = initialX - offset
                    if (leftX >= 0) {
                        source.getPixels(column, 0, 1, leftX, 0, 1, srcH)
                        if (column.any { ((it shr 24) and 0xff) > 5 }) {
                            targetX = leftX
                            foundNonTransparent = true
                            break
                        }
                    }
                    val rightX = initialX + offset
                    if (rightX < srcW) {
                        source.getPixels(column, 0, 1, rightX, 0, 1, srcH)
                        if (column.any { ((it shr 24) and 0xff) > 5 }) {
                            targetX = rightX
                            foundNonTransparent = true
                            break
                        }
                    }
                }
            }
            
            // Fallback if fully transparent
            if (!foundNonTransparent) {
                targetX = initialX
                source.getPixels(column, 0, 1, targetX, 0, 1, srcH)
            }
            
            val sliceBmp = android.graphics.Bitmap.createBitmap(256, srcH, android.graphics.Bitmap.Config.ARGB_8888)
            val pixels = IntArray(256 * srcH)
            for (y in 0 until srcH) {
                val color = column[y]
                val rowOffset = y * 256
                for (x in 0 until 256) {
                    pixels[rowOffset + x] = color
                }
            }
            sliceBmp.setPixels(pixels, 0, 256, 0, 0, 256, srcH)
            return sliceBmp
        } else {
            val initialY = (sliceLine * (srcH - 1)).toInt().coerceIn(0, srcH - 1)
            var targetY = initialY
            val row = IntArray(srcW)
            var foundNonTransparent = false
            
            // Check initial target row
            source.getPixels(row, 0, srcW, 0, targetY, srcW, 1)
            if (row.any { ((it shr 24) and 0xff) > 5 }) {
                foundNonTransparent = true
            } else {
                // Outward content-aware scan to locate nearest non-transparent row
                for (offset in 1 until srcH) {
                    val upY = initialY - offset
                    if (upY >= 0) {
                        source.getPixels(row, 0, srcW, 0, upY, srcW, 1)
                        if (row.any { ((it shr 24) and 0xff) > 5 }) {
                            targetY = upY
                            foundNonTransparent = true
                            break
                        }
                    }
                    val downY = initialY + offset
                    if (downY < srcH) {
                        source.getPixels(row, 0, srcW, 0, downY, srcW, 1)
                        if (row.any { ((it shr 24) and 0xff) > 5 }) {
                            targetY = downY
                            foundNonTransparent = true
                            break
                        }
                    }
                }
            }
            
            // Fallback if fully transparent
            if (!foundNonTransparent) {
                targetY = initialY
                source.getPixels(row, 0, srcW, 0, targetY, srcW, 1)
            }
            
            val sliceBmp = android.graphics.Bitmap.createBitmap(srcW, 256, android.graphics.Bitmap.Config.ARGB_8888)
            val pixels = IntArray(srcW * 256)
            for (y in 0 until 256) {
                val rowOffset = y * srcW
                System.arraycopy(row, 0, pixels, rowOffset, srcW)
            }
            sliceBmp.setPixels(pixels, 0, srcW, 0, 0, srcW, 256)
            return sliceBmp
        }
    } catch (e: Exception) {
        e.printStackTrace()
        return source
    }
}

fun extractSubjectForeground(
    source: android.graphics.Bitmap,
    threshold: Float,
    subjectOpacity: Float
): android.graphics.Bitmap {
    // 2. High-performance downsampling (maintains crisp detail but avoids processing millions of pixels in Kotlin)
    val maxDimension = 1024
    var workingSource = source
    val srcW = source.width
    val srcH = source.height
    val needsResize = srcW > maxDimension || srcH > maxDimension
    if (needsResize) {
        val (newW, newH) = if (srcW > srcH) {
            maxDimension to (srcH * maxDimension / srcW)
        } else {
            (srcW * maxDimension / srcH) to maxDimension
        }
        try {
            workingSource = android.graphics.Bitmap.createScaledBitmap(source, newW, newH, true)
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }

    val w = workingSource.width
    val h = workingSource.height
    try {
        val result = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
        val pixels = IntArray(w * h)
        workingSource.getPixels(pixels, 0, w, 0, 0, w, h)
        
        val threshInt = threshold.toInt()
        val opacityMul = subjectOpacity
        
        // Detect if the canvas already has transparency (like text, shapes, vector icons).
        // If so, do not execute destructive luma thresholding, just apply the opacity overlay.
        var transparentCount = 0
        val sampleCount = minOf(150, pixels.size)
        val sampleStep = maxOf(1, pixels.size / sampleCount)
        var sampledPixels = 0
        for (i in 0 until pixels.size step sampleStep) {
            val a = (pixels[i] shr 24) and 0xff
            if (a < 240) {
                transparentCount++
            }
            sampledPixels++
        }
        val isAlreadyTransparent = sampledPixels > 0 && (transparentCount.toFloat() / sampledPixels.toFloat()) > 0.05f
        
        if (isAlreadyTransparent) {
            for (i in pixels.indices) {
                val color = pixels[i]
                val a = (color shr 24) and 0xff
                val r = (color shr 16) and 0xff
                val g = (color shr 8) and 0xff
                val b = color and 0xff
                val alphaMask = (a * opacityMul).toInt().coerceIn(0, 255)
                pixels[i] = (alphaMask shl 24) or (r shl 16) or (g shl 8) or b
            }
            result.setPixels(pixels, 0, w, 0, 0, w, h)
            if (needsResize && workingSource != source) {
                try { workingSource.recycle() } catch (e: Exception) {}
            }
            return result
        }
        
        // 3. Dual-path outer loop to completely remove inside-loop branching conditions
        if (threshInt >= 128) {
            val denom = 255f - threshold
            val floatDenom = if (denom <= 0f) 1f else denom
            for (i in pixels.indices) {
                val color = pixels[i]
                val a = (color shr 24) and 0xff
                val r = (color shr 16) and 0xff
                val g = (color shr 8) and 0xff
                val b = color and 0xff
                
                // Ultra-fast integer-only luminance approximation (0.299R + 0.587G + 0.114B becomes integer math)
                val luma = (r * 77 + g * 150 + b * 29) shr 8
                
                val alphaMask = if (luma > threshInt) {
                    val diff = luma - threshInt
                    val pct = (diff / floatDenom).coerceIn(0f, 1f)
                    (a * (1f - pct) * opacityMul).toInt()
                } else {
                    (a * opacityMul).toInt()
                }
                
                pixels[i] = (alphaMask shl 24) or (r shl 16) or (g shl 8) or b
            }
        } else {
            val floatThreshold = if (threshold <= 0f) 1f else threshold
            for (i in pixels.indices) {
                val color = pixels[i]
                val a = (color shr 24) and 0xff
                val r = (color shr 16) and 0xff
                val g = (color shr 8) and 0xff
                val b = color and 0xff
                
                val luma = (r * 77 + g * 150 + b * 29) shr 8
                
                val alphaMask = if (luma < threshInt) {
                    val pct = (luma / floatThreshold).coerceIn(0f, 1f)
                    (a * pct * opacityMul).toInt()
                } else {
                    (a * opacityMul).toInt()
                }
                
                pixels[i] = (alphaMask shl 24) or (r shl 16) or (g shl 8) or b
            }
        }
        
        result.setPixels(pixels, 0, w, 0, 0, w, h)
        
        if (needsResize && workingSource != source) {
            try {
                workingSource.recycle()
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
        return result
    } catch (e: Exception) {
        e.printStackTrace()
        return source
    }
}

var globalAppContext: android.content.Context? = null

data class AnchorPoint(
    val position: Offset,
    val handleIn: Offset = position,
    val handleOut: Offset = position
)

fun List<Offset>.toAnchorPoints(): List<AnchorPoint> {
    val results = mutableListOf<AnchorPoint>()
    var i = 0
    while (i < this.size) {
        val pos = this[i]
        val hIn = this.getOrNull(i + 1) ?: pos
        val hOut = this.getOrNull(i + 2) ?: pos
        results.add(AnchorPoint(pos, hIn, hOut))
        i += 3
    }
    return results
}

// Shaders and LightroomFilter are managed by CameraRAWFilterEngine.kt

private fun getLayerGeometryHash(layer: StudioLayer): Int {
    var result = layer.id.hashCode()
    result = 31 * result + layer.type.ordinal
    result = 31 * result + java.lang.Float.floatToIntBits(layer.width)
    result = 31 * result + java.lang.Float.floatToIntBits(layer.height)
    result = 31 * result + java.lang.Float.floatToIntBits(layer.cornerRadius)
    result = 31 * result + layer.polygonEdges
    result = 31 * result + java.lang.Float.floatToIntBits(layer.starInnerRadiusRatio)
    result = 31 * result + java.lang.Float.floatToIntBits(layer.strokeThickness)
    if (layer.brushPoints.isNotEmpty()) {
        result = 31 * result + layer.brushPoints.hashCode()
    }
    return result
}

private fun rotateOffset(offset: Offset, degrees: Float): Offset {
    val rad = Math.toRadians(degrees.toDouble())
    val cos = Math.cos(rad)
    val sin = Math.sin(rad)
    val rx = offset.x * cos - offset.y * sin
    val ry = offset.x * sin + offset.y * cos
    return Offset(rx.toFloat(), ry.toFloat())
}

class GPUImageNoiseFilter(var noiseAmount: Float = 0.05f) : jp.co.cyberagent.android.gpuimage.filter.GPUImageFilter(
    NOISE_VERTEX_SHADER,
    NOISE_FRAGMENT_SHADER
) {
    private var uNoiseAmountLocation: Int = -1

    override fun onInit() {
        super.onInit()
        uNoiseAmountLocation = android.opengl.GLES20.glGetUniformLocation(program, "uNoiseAmount")
    }

    override fun onInitialized() {
        super.onInitialized()
        applyParameters()
    }

    fun setAmount(amount: Float) {
        this.noiseAmount = amount
        applyParameters()
    }

    private fun applyParameters() {
        if (uNoiseAmountLocation != -1) setFloat(uNoiseAmountLocation, noiseAmount)
    }
}

const val NOISE_VERTEX_SHADER = """
attribute vec4 position;
attribute vec4 inputTextureCoordinate;
varying vec2 textureCoordinate;
void main() {
    gl_Position = position;
    textureCoordinate = inputTextureCoordinate.xy;
}
"""

const val NOISE_FRAGMENT_SHADER = """
varying highp vec2 textureCoordinate;
uniform sampler2D inputImageTexture;
uniform highp float uNoiseAmount;

highp float rand(highp vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
    highp vec4 color = texture2D(inputImageTexture, textureCoordinate);
    highp float noise = (rand(textureCoordinate) - 0.5) * uNoiseAmount;
    gl_FragColor = vec4(color.rgb + vec3(noise), color.a);
}
"""

fun applyGPUImageFilters(
    context: android.content.Context,
    originalBitmap: android.graphics.Bitmap,
    effects: List<com.example.studio.model.StudioEffect>
): android.graphics.Bitmap {
    val activeEffects = effects.filter { it.isEnabled }
    if (activeEffects.isEmpty()) return originalBitmap

    try {
        val gpuImage = jp.co.cyberagent.android.gpuimage.GPUImage(context)
        gpuImage.setImage(originalBitmap)

        val filterGroup = jp.co.cyberagent.android.gpuimage.filter.GPUImageFilterGroup()
        var hasFilters = false

        for (effect in activeEffects) {
            when (effect) {
                is com.example.studio.model.StudioEffect.ColorBalance -> {
                    val brightnessVal = effect.parameters["Brightness"]?.value ?: 1.0f
                    val brightnessShift = (brightnessVal - 1.0f).coerceIn(-1.0f, 1.0f)
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBrightnessFilter(brightnessShift))

                    val hueShift = effect.parameters["HueShift"]?.value ?: 0f
                    if (hueShift != 0f) {
                        val hueDeg = (hueShift + 360f) % 360f
                        filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageHueFilter(hueDeg))
                    }

                    val saturationVal = effect.parameters["Saturation"]?.value ?: 1.0f
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSaturationFilter(saturationVal.coerceIn(0.0f, 2.0f)))
                    hasFilters = true
                }
                is com.example.studio.model.StudioEffect.Invert -> {
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageColorInvertFilter())
                    hasFilters = true
                }
                is com.example.studio.model.StudioEffect.Threshold -> {
                    val threshVal = effect.parameters["Threshold"]?.value ?: 0.5f
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageLuminanceThresholdFilter(threshVal))
                    hasFilters = true
                }
                is com.example.studio.model.StudioEffect.Posterize -> {
                    val levelsVal = effect.parameters["Levels"]?.value ?: 4f
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImagePosterizeFilter(levelsVal.toInt().coerceIn(1, 256)))
                    hasFilters = true
                }
                is com.example.studio.model.StudioEffect.PhotoshopEffect -> {
                    when (effect.effectType) {
                        "CameraRaw", "ColorGrading" -> {
                            val exposure = effect.parameters["Exposure"]?.value ?: 0f
                            val contrast = effect.parameters["Contrast"]?.value ?: 0f
                            val highlights = effect.parameters["Highlights"]?.value ?: 0f
                            val shadows = effect.parameters["Shadows"]?.value ?: 0f
                            val whites = effect.parameters["Whites"]?.value ?: 0f
                            val blacks = effect.parameters["Blacks"]?.value ?: 0f
                            val temp = effect.parameters["Temp"]?.value ?: 0f
                            val tint = effect.parameters["Tint"]?.value ?: 0f
                            val vibrance = effect.parameters["Vibrance"]?.value ?: 0f
                            val saturation = effect.parameters["Saturation"]?.value ?: 0f
                            val texture = effect.parameters["Texture"]?.value ?: 0f
                            val clarity = effect.parameters["Clarity"]?.value ?: 0f
                            val dehaze = effect.parameters["Dehaze"]?.value ?: 0f
                            val profile = effect.parameters["Profile"]?.value ?: 0f

                            val lrFilter = LightroomFilter().apply {
                                updateParams(
                                    exposure = exposure,
                                    contrast = contrast,
                                    highlights = highlights,
                                    shadows = shadows,
                                    whites = whites,
                                    blacks = blacks,
                                    temp = temp,
                                    tint = tint,
                                    vibrance = vibrance,
                                    saturation = saturation,
                                    clarity = clarity,
                                    dehaze = dehaze,
                                    profile = profile
                                )
                            }
                            filterGroup.addFilter(lrFilter)
                            hasFilters = true

                            if (texture != 0f) {
                                if (texture > 0f) {
                                    val sharpFilter = jp.co.cyberagent.android.gpuimage.filter.GPUImageSharpenFilter().apply {
                                        setSharpness(texture / 100f * 2.0f)
                                    }
                                    filterGroup.addFilter(sharpFilter)
                                } else {
                                    val blurFilter = jp.co.cyberagent.android.gpuimage.filter.GPUImageGaussianBlurFilter().apply {
                                        setBlurSize(-texture / 100f * 4.0f)
                                    }
                                    filterGroup.addFilter(blurFilter)
                                }
                            }
                        }
                        "Solarize" -> {
                            val thresh = effect.parameters["Threshold"]?.value ?: 0.5f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSolarizeFilter().apply {
                                setThreshold(thresh)
                            })
                            hasFilters = true
                        }
                        "Emboss" -> {
                            val heightVal = effect.parameters["Height"]?.value ?: 2.0f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageEmbossFilter().apply {
                                setIntensity((heightVal / 10f).coerceIn(0.0f, 1.0f))
                            })
                            hasFilters = true
                        }
                        "FindEdges" -> {
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSobelEdgeDetectionFilter())
                            hasFilters = true
                        }
                        "ColorHalftone" -> {
                            val maxRadius = effect.parameters["MaxRadius"]?.value ?: 8f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageHalftoneFilter(maxRadius / 1000f))
                            hasFilters = true
                        }
                        "Sketch" -> {
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSketchFilter())
                            hasFilters = true
                        }
                        "Mosaic" -> {
                            val cellSize = effect.parameters["CellSize"]?.value ?: 8f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImagePixelationFilter().apply {
                                setPixel(cellSize.coerceIn(1f, 1000f))
                            })
                            hasFilters = true
                        }
                        "Twirl" -> {
                            val angleVal = effect.parameters["Angle"]?.value ?: 100f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSwirlFilter().apply {
                                setAngle(angleVal / 100f)
                                setRadius(0.5f)
                            })
                            hasFilters = true
                        }
                        "Spherize" -> {
                            val amt = effect.parameters["Amount"]?.value ?: 100f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBulgeDistortionFilter().apply {
                                setRadius(0.5f)
                                setScale(amt / 100f * 0.5f)
                            })
                            hasFilters = true
                        }
                        "GaussianBlur", "RadialBlur", "LensBlur" -> {
                            val radiusVal = effect.parameters["Radius"]?.value ?: effect.parameters["Amount"]?.value ?: 12f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageGaussianBlurFilter().apply {
                                setBlurSize(radiusVal / 5f)
                            })
                            hasFilters = true
                        }
                        "MotionBlur", "Wind" -> {
                            val distance = effect.parameters["Distance"]?.value ?: 15f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageGaussianBlurFilter().apply {
                                setBlurSize(distance / 6f)
                            })
                            hasFilters = true
                        }
                        "SmartSharpen", "UnsharpMask" -> {
                            val amt = effect.parameters["Amount"]?.value ?: 50f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSharpenFilter().apply {
                                setSharpness(amt / 100f * 2.0f)
                            })
                            hasFilters = true
                        }
                        "AddNoise", "Clouds", "Texture" -> {
                            val amt = (effect.parameters["Amount"]?.value ?: effect.parameters["Relief"]?.value ?: 10f) / 100f
                            filterGroup.addFilter(GPUImageNoiseFilter(amt.coerceAtLeast(0.05f)))
                            hasFilters = true
                        }
                        "Pinch" -> {
                            val amt = (effect.parameters["Amount"]?.value ?: 50f) / -100f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBulgeDistortionFilter().apply {
                                setRadius(0.6f)
                                setScale(amt * 0.5f)
                            })
                            hasFilters = true
                        }
                        "Ripple", "Wave", "ZigZag" -> {
                            val amt = effect.parameters["Amount"]?.value ?: effect.parameters["WaveAmplitude"]?.value ?: 30f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSwirlFilter().apply {
                                setRadius(0.6f)
                                setAngle(amt / 50f)
                            })
                            hasFilters = true
                        }
                        "Despeckle", "DustScratches", "Median", "NeuralFilters" -> {
                            val smooth = effect.parameters["SmoothSkin"]?.value ?: 50f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBilateralBlurFilter().apply {
                                setDistanceNormalizationFactor(0.002f + (smooth / 100f) * 0.008f)
                            })
                            hasFilters = true
                        }
                        "Crystallize", "Pointillize" -> {
                            val cellSize = effect.parameters["CellSize"]?.value ?: 10f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageHalftoneFilter(cellSize / 1000f))
                            hasFilters = true
                        }
                        "OilPaint", "Artistic", "BrushStrokes" -> {
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageToonFilter())
                            hasFilters = true
                        }
                        "HighPass" -> {
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSobelEdgeDetectionFilter())
                            hasFilters = true
                        }
                        "ColorOverlay" -> {
                            val hueShift = effect.parameters["HueShift"]?.value ?: 0f
                            val hueDeg = (hueShift + 360f) % 360f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageHueFilter(hueDeg))
                            hasFilters = true
                        }
                        "GradientOverlay", "PatternOverlay", "DropShadow", "InnerShadow", "OuterGlow", "InnerGlow", "BevelEmboss", "Satin", "Stroke", "BordersAndShadows", "GlassMorphism", "ReededGlass" -> {
                            val opacity = effect.parameters["Opacity"]?.value ?: 0.5f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageVignetteFilter().apply {
                                setVignetteStart(0.3f)
                                setVignetteEnd(0.7f + (1f - opacity) * 0.3f)
                            })
                            hasFilters = true
                        }
                        "LensFlare", "LightingEffects" -> {
                            val bright = (effect.parameters["Brightness"]?.value ?: effect.parameters["Intensity"]?.value ?: 100f) / 100f
                            val shift = (bright - 1.0f).coerceIn(-1.0f, 1.0f)
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBrightnessFilter(shift))
                            hasFilters = true
                        }
                        "Liquify" -> {
                            val size = effect.parameters["BrushSize"]?.value ?: 100f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBulgeDistortionFilter().apply {
                                setRadius(size / 300f)
                                setScale(0.3f)
                            })
                            hasFilters = true
                        }
                    }
                }
                else -> {}
            }
        }

        if (hasFilters) {
            gpuImage.setFilter(filterGroup)
            val filtered = gpuImage.bitmapWithFilterApplied
            if (filtered != null) {
                return filtered
            }
        }
    } catch (e: Throwable) {
        android.util.Log.e("GPUImage", "Failed to apply GPUImage filters", e)
    }
    return originalBitmap
}

fun Modifier.dropShadow(
    color: Color = Color.Black,
    blur: Dp = 8.dp,
    dx: Dp = 0.dp,
    dy: Dp = 0.dp,
    spread: Dp = 0.dp,
    isEnabled: Boolean = true
): Modifier = if (isEnabled) {
    this.drawBehind {
        val bPx = blur.toPx()
        val dxPx = dx.toPx()
        val dyPx = dy.toPx()
        val spreadPx = spread.toPx()
        
        val paint = Paint().asFrameworkPaint().apply {
            this.color = android.graphics.Color.argb(
                (color.alpha * 255).toInt(),
                (color.red * 255).toInt(),
                (color.green * 255).toInt(),
                (color.blue * 255).toInt()
            )
            if (bPx > 0f) {
                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                    try {
                        val setMethod = this.javaClass.getMethod("setRenderEffect", android.graphics.RenderEffect::class.java)
                        setMethod.invoke(this, android.graphics.RenderEffect.createBlurEffect(bPx, bPx, android.graphics.Shader.TileMode.DECAL))
                    } catch (t: Throwable) {
                        maskFilter = android.graphics.BlurMaskFilter(bPx, android.graphics.BlurMaskFilter.Blur.NORMAL)
                    }
                } else {
                    maskFilter = android.graphics.BlurMaskFilter(bPx, android.graphics.BlurMaskFilter.Blur.NORMAL)
                }
            }
        }
        val dSize = this.size
        val sizeWithSpread = dSize.copy(
            width = dSize.width + spreadPx * 2f,
            height = dSize.height + spreadPx * 2f
        )
        val topLeftWithOffset = Offset(
            dxPx - spreadPx,
            dyPx - spreadPx
        )
        this.drawContext.canvas.nativeCanvas.drawRect(
            topLeftWithOffset.x,
            topLeftWithOffset.y,
            topLeftWithOffset.x + sizeWithSpread.width,
            topLeftWithOffset.y + sizeWithSpread.height,
            paint
        )
    }
} else {
    this
}

private fun screenToCanvas(
    screenPos: Offset,
    viewportWidth: Float,
    viewportHeight: Float,
    canvasPanX: Float,
    canvasPanY: Float,
    canvasRotation: Float,
    totalScale: Float,
    canvasWidth: Float,
    canvasHeight: Float
): Offset {
    val p3 = Offset(
        screenPos.x - (viewportWidth / 2f + canvasPanX),
        screenPos.y - (viewportHeight / 2f + canvasPanY)
    )
    val p2 = rotateOffset(p3, -canvasRotation)
    val p1 = p2 / totalScale.coerceAtLeast(0.001f)
    return Offset(
        p1.x + canvasWidth / 2f,
        p1.y + canvasHeight / 2f
    )
}

private fun screenDeltaToCanvas(
    delta: Offset,
    canvasRotation: Float,
    totalScale: Float
): Offset {
    val rotated = rotateOffset(delta, -canvasRotation)
    return rotated / totalScale.coerceAtLeast(0.001f)
}

private fun canvasToLayerLocal(canvasPos: Offset, layer: StudioLayer): Offset {
    // 1. Translation: shift relative to layer's top-left position
    val shifted = Offset(canvasPos.x - layer.positionX, canvasPos.y - layer.positionY)
    
    // 2. Rotation around pivot (layer.width * layer.pivotX, layer.height * layer.pivotY)
    val pivot = Offset(layer.width * layer.pivotX, layer.height * layer.pivotY)
    val toPivot = shifted - pivot
    val unrotated = rotateOffset(toPivot, -layer.rotation)
    val posAfterRotation = unrotated + pivot
    
    // 3. Scaling around pivot
    val unscaledX = (posAfterRotation.x - pivot.x) / layer.scaleX.coerceAtLeast(0.01f) + pivot.x
    val unscaledY = (posAfterRotation.y - pivot.y) / layer.scaleY.coerceAtLeast(0.01f) + pivot.y
    
    return Offset(unscaledX, unscaledY)
}

class CappedHistoryStack(private val maxLimit: Int = 40) {
    val list = androidx.compose.runtime.mutableStateListOf<List<com.example.studio.model.StudioLayer>>()
    
    val size: Int get() = list.size
    
    fun isNotEmpty(): Boolean = list.isNotEmpty()
    fun isEmpty(): Boolean = list.isEmpty()
    
    fun add(element: List<com.example.studio.model.StudioLayer>) {
        list.add(element)
        while (list.size > maxLimit) {
            list.removeAt(0)
        }
    }
    
    fun removeAt(index: Int): List<com.example.studio.model.StudioLayer> {
        return list.removeAt(index)
    }
    
    fun clear() {
        list.clear()
    }
}

data class StudioRuler(
    val id: String = java.util.UUID.randomUUID().toString(),
    val name: String = "Ruler",
    val enabled: Boolean = true,
    val orientation: String = "Horizontal",
    val position: Float = 300f,
    val angle: Float = 0f,
    val locked: Boolean = false
)

private fun snapPointToRulers(
    px: Float,
    py: Float,
    rulers: List<StudioRuler>,
    canvasWidth: Float,
    canvasHeight: Float
): Offset {
    var bestPoints = Offset(px, py)
    var minDistanceSq = Float.MAX_VALUE
    for (ruler in rulers) {
        if (!ruler.enabled) continue
        val w = canvasWidth
        val h = canvasHeight
        val angleRad = (ruler.angle * Math.PI / 180.0)
        val dX: Float
        val dY: Float
        val aX: Float
        val aY: Float
        if (ruler.orientation == "Horizontal") {
            dX = Math.cos(angleRad).toFloat()
            dY = Math.sin(angleRad).toFloat()
            aX = w / 2f
            aY = ruler.position
        } else {
            dX = -Math.sin(angleRad).toFloat()
            dY = Math.cos(angleRad).toFloat()
            aX = ruler.position
            aY = h / 2f
        }
        val t = (px - aX) * dX + (py - aY) * dY
        val snappedX = aX + t * dX
        val snappedY = aY + t * dY
        val distSq = (px - snappedX) * (px - snappedX) + (py - snappedY) * (py - snappedY)
        if (distSq < minDistanceSq) {
            minDistanceSq = distSq
            bestPoints = Offset(snappedX, snappedY)
        }
    }
    return bestPoints
}

data class WorkspaceRulerSettings(
    val rulers: List<StudioRuler> = emptyList(),
    val onRulersChange: (List<StudioRuler>) -> Unit = {},
    val selectedRulerId: String = "",
    val onSelectedRulerIdChange: (String) -> Unit = {},
    val snapToRuler: Boolean = true,
    val onSnapToRulerChange: (Boolean) -> Unit = {},
    val allRulersLocked: Boolean = false,
    val onAllRulersLockedChange: (Boolean) -> Unit = {}
)

val LocalRulerSettings = androidx.compose.runtime.compositionLocalOf { WorkspaceRulerSettings() }

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun WorkspaceScreen(modifier: Modifier = Modifier) {
    val context = androidx.compose.ui.platform.LocalContext.current
    globalAppContext = context.applicationContext
    val workspaceViewModel: WorkspaceViewModel = viewModel()
    val previousProjects by workspaceViewModel.previousProjects.collectAsStateWithLifecycle()
    val scope = rememberCoroutineScope()

    val adaptiveInfo = currentWindowAdaptiveInfo()
    val isLandscape = adaptiveInfo.windowSizeClass.windowWidthSizeClass == WindowWidthSizeClass.EXPANDED || 
                      adaptiveInfo.windowSizeClass.windowWidthSizeClass == WindowWidthSizeClass.MEDIUM ||
                      androidx.compose.ui.platform.LocalConfiguration.current.orientation == android.content.res.Configuration.ORIENTATION_LANDSCAPE

    var projectId by remember { mutableStateOf("") }
    var projectName by remember { mutableStateOf("") }
    var showRenameProjectDialog by remember { mutableStateOf(false) }
    var projectRenameValue by remember { mutableStateOf("") }

    var showFontScannerDialog by remember { mutableStateOf(false) }
    var discoveredFonts by remember { mutableStateOf<List<com.example.studio.ui.FontScanner.DiscoveredFont>>(emptyList()) }
    val selectedFontIndexes = remember { androidx.compose.runtime.mutableStateMapOf<Int, Boolean>() }
    var selectedFontCount by remember { mutableStateOf(0) }
    var isFontScanning by remember { mutableStateOf(false) }
    var isBatchImportingFonts by remember { mutableStateOf(false) }
    var fontScanStatusMessage by remember { mutableStateOf("") }
    val selectedFoldersToScan = remember { androidx.compose.runtime.mutableStateMapOf<String, Boolean>().apply {
        put("Download", true)
        put("Fonts", true)
        put("Documents", false)
        put("MediaStore", true)
        put("Root", false)
    } }

    var hasStoragePermission by remember {
        mutableStateOf(
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                true
            } else {
                androidx.core.content.ContextCompat.checkSelfPermission(
                    context,
                    android.Manifest.permission.READ_EXTERNAL_STORAGE
                ) == android.content.pm.PackageManager.PERMISSION_GRANTED
            }
        )
    }

    // Initial State Setup - Empty to allow user manually adding anything they want, Canvas-style!
    var layers by remember {
        mutableStateOf(emptyList<StudioLayer>())
    }

    var selectedLayerId by remember { mutableStateOf("") }
    var snapVerticalLine by remember { mutableStateOf<Float?>(null) }
    var snapHorizontalLine by remember { mutableStateOf<Float?>(null) }
    var snapIndicatorMsg by remember { mutableStateOf<String?>(null) }
    var activeTool by remember { mutableStateOf("Brush") } // Brush, Move, Shapes, Text

    val undoStack = remember { CappedHistoryStack(40) }
    val redoStack = remember { CappedHistoryStack(40) }

    // State managers for dynamic brush parameters
    var brushSize by remember { mutableStateOf(16f) }
    var eraserSize by remember { mutableStateOf(24f) }
    var eraserHardness by remember { mutableStateOf(0.5f) }
    var brushOpacity by remember { mutableStateOf(1.0f) }
    var brushColor by remember { mutableStateOf(Color(0xFFFFB300)) }
    var brushSmoothing by remember { mutableStateOf(true) }
    var brushPresetIndex by remember { mutableStateOf(0) }
    val strokeTracker = remember { OpenGLBrushRenderer.HighPerformanceStrokeTracker() }
    val strokeDrawTrigger = remember { mutableStateOf(0) }
    var debounceUpdateLayerJob by remember { mutableStateOf<kotlinx.coroutines.Job?>(null) }
    var currentStrokePoints by remember { mutableStateOf<List<Offset>>(emptyList()) }
    val sharedTransformMatrix = remember { androidx.compose.ui.graphics.Matrix() }
    var reusableBackdropBitmap by remember { mutableStateOf<android.graphics.Bitmap?>(null) }
    var activeBezierPointIndex by remember { mutableStateOf(-1) }
    var activeGradientStopIndex by remember { mutableStateOf(-1) }
    var showGradientColorPickerDialog by remember { mutableStateOf(false) }

    var isResizingActive by remember { mutableStateOf(false) }
    var activeResizingLayerId by remember { mutableStateOf<String?>(null) }
    var liveDragScaleX by remember { mutableStateOf(1.0f) }
    var liveDragScaleY by remember { mutableStateOf(1.0f) }
    var startingLayerForResize by remember { mutableStateOf<com.example.studio.model.StudioLayer?>(null) }

    // Floating UI selector for adding specific shapes
    var showAddShapeDialog by remember { mutableStateOf(false) }
    var showBrushesLibrary by remember { mutableStateOf(false) }

    var rulers by remember {
        mutableStateOf(
            listOf(
                StudioRuler(
                    id = "default_ruler",
                    name = "Primary Ruler",
                    enabled = false,
                    orientation = "Horizontal",
                    position = 300f,
                    angle = 0f,
                    locked = false
                )
            )
        )
    }
    var selectedRulerId by remember { mutableStateOf("default_ruler") }
    val activeRuler = rulers.find { it.id == selectedRulerId } ?: rulers.firstOrNull() ?: StudioRuler()
    val rulerEnabled = activeRuler.enabled
    val rulerOrientation = activeRuler.orientation
    val rulerPosition = activeRuler.position
    val rulerAngle = activeRuler.angle
    val rulerLocked = activeRuler.locked

    var gridEnabled by remember { mutableStateOf(false) }
    var showExportResolutionDialog by remember { mutableStateOf(false) }
    var snapToRuler by remember { mutableStateOf(true) }
    var allRulersLocked by remember { mutableStateOf(false) }
    var gridColumns by remember { mutableStateOf(8) }
    var gridRows by remember { mutableStateOf(8) }
    var isLeftToolbarExpanded by remember { mutableStateOf(true) }

    var fontSearchQuery by remember { mutableStateOf("") }
    var selectedCategoryFilter by remember { mutableStateOf("All") }

    var favoriteFontsList by remember { mutableStateOf(getFavoriteFonts(context)) }
    val imagePickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            try {
                context.contentResolver.takePersistableUriPermission(
                    it,
                    android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION
                )
            } catch (e: Exception) {
            }
            undoStack.add(layers)
            redoStack.clear()
            var initialW = 400f
            var initialH = 400f
            try {
                val options = android.graphics.BitmapFactory.Options().apply {
                    inJustDecodeBounds = true
                }
                context.contentResolver.openInputStream(it)?.use { stream ->
                    android.graphics.BitmapFactory.decodeStream(stream, null, options)
                }
                val imageW = options.outWidth
                val imageH = options.outHeight
                if (imageW > 0 && imageH > 0) {
                    val aspectRatio = imageW.toFloat() / imageH.toFloat()
                    if (aspectRatio > 1.0f) {
                        initialW = 400f
                        initialH = 400f / aspectRatio
                    } else {
                        initialH = 400f
                        initialW = 400f * aspectRatio
                    }
                }
            } catch (e: Exception) {
                e.printStackTrace()
            }

            val newL = com.example.studio.model.StudioLayer(
                name = "Imported Image",
                type = com.example.studio.model.LayerType.IMAGE_CARD,
                positionX = 150f,
                positionY = 200f,
                width = initialW,
                height = initialH,
                baseColor = Color.White,
                imageUri = it.toString(),
                isAspectLocked = true
            )
            layers = listOf(newL) + layers
            selectedLayerId = newL.id
            showAddShapeDialog = false
        }
    }

    val performFontScan: () -> Unit = {
        isFontScanning = true
        val activeFolders = selectedFoldersToScan.filter { it.value }.keys.toSet()
        val foldersStr = activeFolders.joinToString(", ")
        fontScanStatusMessage = "Crawling ($foldersStr)..."
        scope.launch {
            try {
                discoveredFonts = FontScanner.scanLocalFonts(context, activeFolders)
                selectedFontIndexes.clear()
                discoveredFonts.forEachIndexed { i, _ -> selectedFontIndexes[i] = true }
                selectedFontCount = discoveredFonts.size
                fontScanStatusMessage = if (discoveredFonts.isEmpty()) {
                    "No design fonts (.ttf/.otf) found in chosen directories."
                } else {
                    "Discovered ${discoveredFonts.size} custom design typography files!"
                }
            } catch (e: Exception) {
                fontScanStatusMessage = "Scanning failed: ${e.localizedMessage}"
            } finally {
                isFontScanning = false
            }
        }
    }

    val storagePermissionLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        hasStoragePermission = isGranted
        if (isGranted) {
            performFontScan()
        } else {
            android.widget.Toast.makeText(context, "Storage scanner permission declined. Use Manual Pick instead or grant in settings.", android.widget.Toast.LENGTH_LONG).show()
        }
    }

    val requestOrPromptStoragePermission: () -> Unit = {
        val hasPerm = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.R) {
            android.os.Environment.isExternalStorageManager() ||
            androidx.core.content.ContextCompat.checkSelfPermission(
                context,
                android.Manifest.permission.READ_EXTERNAL_STORAGE
            ) == android.content.pm.PackageManager.PERMISSION_GRANTED
        } else {
            androidx.core.content.ContextCompat.checkSelfPermission(
                context,
                android.Manifest.permission.READ_EXTERNAL_STORAGE
            ) == android.content.pm.PackageManager.PERMISSION_GRANTED
        }

        if (hasPerm) {
            hasStoragePermission = true
            performFontScan()
        } else {
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.R) {
                android.widget.Toast.makeText(context, "Zenith Studio needs All Files Access for auto font directory scan. Grant it in Settings.", android.widget.Toast.LENGTH_LONG).show()
                try {
                    val intent = android.content.Intent(android.provider.Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION).apply {
                        data = android.net.Uri.fromParts("package", context.packageName, null)
                        addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK)
                    }
                    context.startActivity(intent)
                } catch (e: Exception) {
                    try {
                        val intent = android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                            data = android.net.Uri.fromParts("package", context.packageName, null)
                            addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK)
                        }
                        context.startActivity(intent)
                    } catch (ex: Exception) {
                        ex.printStackTrace()
                    }
                }
            } else {
                storagePermissionLauncher.launch(android.Manifest.permission.READ_EXTERNAL_STORAGE)
            }
        }
    }

    val fontPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            try {
                val contentResolver = context.contentResolver
                var displayName = "imported_font_${System.currentTimeMillis()}.ttf"
                val cursor = contentResolver.query(it, null, null, null, null)
                cursor?.use { c ->
                    if (c.moveToFirst()) {
                        val nameIndex = c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                        if (nameIndex != -1) {
                            val name = c.getString(nameIndex)
                            if (!name.isNullOrEmpty()) {
                                displayName = name
                            }
                        }
                    }
                }
                
                val fontsDir = java.io.File(context.filesDir, "fonts")
                if (!fontsDir.exists()) {
                    fontsDir.mkdirs()
                }
                val destFile = java.io.File(fontsDir, displayName)
                contentResolver.openInputStream(it)?.use { input ->
                    destFile.outputStream().use { output ->
                        input.copyTo(output)
                    }
                }
                
                android.widget.Toast.makeText(context, "Font imported: ${destFile.nameWithoutExtension}", android.widget.Toast.LENGTH_SHORT).show()
                
                val cleanName = destFile.nameWithoutExtension.replace("_", " ").replace("-", " ")
                val category = if (cleanName.contains("script", ignoreCase = true)) {
                    "Script"
                } else if (cleanName.contains("hand", ignoreCase = true) || cleanName.contains("write", ignoreCase = true)) {
                    "Handwritten"
                } else if (cleanName.contains("mono", ignoreCase = true)) {
                    "Monospace"
                } else if (cleanName.contains("serif", ignoreCase = true)) {
                    "Serif"
                } else {
                    "Display"
                }
                workspaceViewModel.addCustomFont(cleanName, destFile.absolutePath, category)

                if (selectedLayerId.isNotEmpty()) {
                    val targetL = layers.find { it.id == selectedLayerId }
                    if (targetL != null && targetL.type == LayerType.TEXT) {
                        val cleanName = destFile.nameWithoutExtension.replace("_", " ").replace("-", " ")
                        undoStack.add(layers)
                        redoStack.clear()
                        layers = layers.map { l ->
                            if (l.id == selectedLayerId) {
                                l.copy(
                                    fontPath = destFile.absolutePath,
                                    fontFamilyName = cleanName
                                )
                            } else l
                        }
                    }
                }
            } catch (e: Exception) {
                e.printStackTrace()
                android.widget.Toast.makeText(context, "Failed to import font", android.widget.Toast.LENGTH_SHORT).show()
            }
        }
    }

    val imageBitmapCache = remember { mutableStateMapOf<String, androidx.compose.ui.graphics.ImageBitmap>() }
    // Global processedImageBitmapCache is used
    val loadingUris = remember { mutableStateOf(emptySet<String>()) }
    LaunchedEffect(layers) {
        val currentImageUris = layers.filter { it.type == LayerType.IMAGE_CARD && !it.imageUri.isNullOrEmpty() }
            .mapNotNull { it.imageUri }
            .toSet()
        val cacheKeys = imageBitmapCache.keys.toList()
        cacheKeys.forEach { key ->
            if (key !in currentImageUris) {
                imageBitmapCache.remove(key)
            }
        }
        layers.forEach { layer ->
            if (layer.type == LayerType.IMAGE_CARD && !layer.imageUri.isNullOrEmpty()) {
                val uriStr = layer.imageUri
                if (!imageBitmapCache.containsKey(uriStr) && !loadingUris.value.contains(uriStr)) {
                    loadingUris.value = loadingUris.value + uriStr
                    val loaded = withContext(Dispatchers.IO) {
                        try {
                            val imageLoader = coil.ImageLoader(context)
                            val request = coil.request.ImageRequest.Builder(context)
                                .data(uriStr)
                                .size(1024, 1024)
                                .scale(coil.size.Scale.FIT)
                                .allowHardware(false)
                                .memoryCachePolicy(coil.request.CachePolicy.ENABLED)
                                .diskCachePolicy(coil.request.CachePolicy.ENABLED)
                                .build()
                            val result = imageLoader.execute(request)
                            if (result is coil.request.SuccessResult) {
                                val bitmap = (result.drawable as android.graphics.drawable.BitmapDrawable).bitmap
                                bitmap.asImageBitmap()
                            } else {
                                null
                            }
                        } catch (t: Throwable) {
                            null
                        }
                    }
                    if (loaded != null) {
                        imageBitmapCache[uriStr] = loaded
                    }
                    loadingUris.value = loadingUris.value - uriStr
                }
            }
        }
    }

    var scaleFactor by remember { mutableStateOf(1.0f) }
    var canvasPanX by remember { mutableStateOf(0f) }
    var canvasPanY by remember { mutableStateOf(0f) }
    var canvasRotation by remember { mutableStateOf(0f) }

    // Start Unidirectional Asynchronous Event Loop
    androidx.compose.runtime.LaunchedEffect(Unit) {
        com.example.studio.ui.CanvasEventLoop.startProcessing(
            onUpdateTransform = { panX, panY, scale, rotation ->
                canvasPanX = panX
                canvasPanY = panY
                scaleFactor = scale
                canvasRotation = rotation
            },
            onUpdateSlider = { layerId, effectId, paramName, newValue ->
                layers = layers.map { layer ->
                    if (layer.id == layerId) {
                        val updatedEffects = layer.effects.map { eff ->
                            if (eff.id == effectId) {
                                eff.updateParameter(paramName, newValue)
                            } else eff
                        }
                        layer.copy(effects = updatedEffects)
                    } else layer
                }
            },
            onUpdateLayerProp = { layerId, propName, newValue ->
                layers = layers.map { layer ->
                    if (layer.id == layerId) {
                        when (propName) {
                            "opacity" -> layer.copy(opacity = newValue)
                            "positionX" -> layer.copy(positionX = newValue)
                            "positionY" -> layer.copy(positionY = newValue)
                            else -> layer
                        }
                    } else layer
                }
            }
        )
    }

    var isCanvasLocked by remember { mutableStateOf(false) }
    var isCanvasControlMinimized by remember { mutableStateOf(false) }
    var isMultiSelectMode by remember { mutableStateOf(false) }
    var selectedLayersSet by remember { mutableStateOf(setOf<String>()) }
    var collapsedGroupIds by remember { mutableStateOf(setOf<String>()) }

    // Collapsible Panel States
    var isLayersPanelVisible by remember { mutableStateOf(true) }
    var isBottomPanelVisible by remember { mutableStateOf(true) }
    var showEffectsGallery by remember { mutableStateOf(false) }
    var activeFullScreenSheet by remember { mutableStateOf<String?>(null) }

    // Layer Renaming States
    var renamingLayerId by remember { mutableStateOf<String?>(null) }
    var renamingLayerName by remember { mutableStateOf("") }

    // Selected effect ID mapping
    val selectedLayer = layers.find { it.id == selectedLayerId }
    var selectedEffectIndex by remember { mutableStateOf(0) }

    // Optimization cached states to avoid frame GC pressure inside DrawScope loops
    val pathCache = remember { SparseArray<Path>() }
    val pathPointsCountCache = remember { SparseIntArray() }
    val dashEffect8 = remember { PathEffect.dashPathEffect(floatArrayOf(8f, 8f)) }
    val dashEffect12 = remember { PathEffect.dashPathEffect(floatArrayOf(12f, 8f)) }

    val displayMetrics = androidx.compose.ui.platform.LocalContext.current.resources.displayMetrics
    val screenWidth = displayMetrics.widthPixels.toFloat()
    val screenHeight = displayMetrics.heightPixels.toFloat()
    val deviceAspect = if (screenWidth > 0f) screenHeight / screenWidth else 1350f / 1080f
    val defaultHeightStr = (1080f * deviceAspect).toInt().toString()

    // Canvas size initialization state variables
    var isProjectInitialized by remember { mutableStateOf(false) }
    var canvasWidthInput by remember { mutableStateOf("1080") }
    var canvasHeightInput by remember { mutableStateOf(defaultHeightStr) }
    var projectDpi by remember { mutableStateOf(300) }
    var selectedPresetIndex by remember { mutableStateOf(0) }
    
    var showExportSettingsDialog by remember { mutableStateOf(false) }
    var exportMultiplier by remember { mutableFloatStateOf(1.0f) }
    var exportIsCmyk by remember { mutableStateOf(false) }
    
    var canvasWidth by remember { mutableStateOf(1080f) }
    var canvasHeight by remember { mutableStateOf(1080f * deviceAspect) }

    var showDownscalePsdDialog by remember { mutableStateOf<PsdImportEngine.ParsedPsd?>(null) }
    var isPsdImporting by remember { mutableStateOf(false) }
    var psdImportProgressState by remember { mutableStateOf("") }
    var psdImportErrorMsg by remember { mutableStateOf<String?>(null) }

    var isAlightImporting by remember { mutableStateOf(false) }
    var alightImportErrorMsg by remember { mutableStateOf<String?>(null) }

    val loadParsedPsd: (PsdImportEngine.ParsedPsd, Boolean) -> Unit = { psd, downscale ->
        val scaleFactor = if (downscale) {
            val maxDim = maxOf(psd.canvasWidth, psd.canvasHeight)
            val limit = 2048f
            if (maxDim > limit) limit / maxDim else 1.0f
        } else {
            1.0f
        }

        val designWidth = psd.canvasWidth * scaleFactor
        val designHeight = psd.canvasHeight * scaleFactor

        val scaledLayers = psd.layers.map { layer ->
            layer.copy(
                width = layer.width * scaleFactor,
                height = layer.height * scaleFactor,
                positionX = layer.positionX * scaleFactor,
                positionY = layer.positionY * scaleFactor
            )
        }

        canvasWidth = designWidth
        canvasHeight = designHeight
        canvasWidthInput = designWidth.toInt().toString()
        canvasHeightInput = designHeight.toInt().toString()
        projectDpi = psd.projectDpi

        val nid = UUID.randomUUID().toString()
        projectId = nid
        projectName = "PSD Import ${designWidth.toInt()}x${designHeight.toInt()}"
        layers = scaledLayers
        selectedLayerId = if (scaledLayers.isNotEmpty()) scaledLayers[0].id else ""
        isProjectInitialized = true

        workspaceViewModel.saveProject(nid, projectName, designWidth, designHeight, scaledLayers, dpi = psd.projectDpi)
        android.widget.Toast.makeText(context, "PSD imported successfully with ${scaledLayers.size} layers!", android.widget.Toast.LENGTH_LONG).show()
    }

    val psdPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let { psdUri ->
            isPsdImporting = true
            psdImportProgressState = "Opening document..."
            psdImportErrorMsg = null
            
            scope.launch {
                try {
                    context.contentResolver.openInputStream(psdUri)?.use { inputStream ->
                        val parsed = PsdImportEngine.parsePsdStream(context, inputStream) { text ->
                            scope.launch(Dispatchers.Main) {
                                psdImportProgressState = text
                            }
                        }
                        if (parsed.layers.isEmpty()) {
                            isPsdImporting = false
                            psdImportErrorMsg = "No compatible layers found in PSD document. Keep in mind vector/shape layers are not raw pixels."
                            return@launch
                        }

                        if (parsed.canvasWidth > 3500f || parsed.canvasHeight > 3500f) {
                            showDownscalePsdDialog = parsed
                        } else {
                            loadParsedPsd(parsed, false)
                        }
                    }
                } catch (e: Throwable) {
                    e.printStackTrace()
                    isPsdImporting = false
                    psdImportErrorMsg = "PSD Parsing Failure: " + (e.localizedMessage ?: e.javaClass.simpleName)
                } finally {
                    isPsdImporting = false
                }
            }
        }
    }

    val alightXmlPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let { xmlUri ->
            isAlightImporting = true
            alightImportErrorMsg = null
            
            scope.launch {
                try {
                    context.contentResolver.openInputStream(xmlUri)?.use { inputStream ->
                        val activeW = canvasWidthInput.toFloatOrNull() ?: 1080f
                        val activeH = canvasHeightInput.toFloatOrNull() ?: 1350f
                        val parsed = AlightXmlEngine.parseAlightXml(inputStream, activeW, activeH)
                        
                        if (parsed.layers.isEmpty()) {
                            isAlightImporting = false
                            alightImportErrorMsg = "No compatible shapes or text layers found in Alight Motion XML template."
                            return@launch
                        }

                        // Set canvas dimensions and project details
                        canvasWidth = parsed.canvasWidth
                        canvasHeight = parsed.canvasHeight
                        canvasWidthInput = parsed.canvasWidth.toInt().toString()
                        canvasHeightInput = parsed.canvasHeight.toInt().toString()
                        projectDpi = 300

                        val nid = UUID.randomUUID().toString()
                        projectId = nid
                        projectName = "Alight Motion Import"
                        layers = parsed.layers
                        selectedLayerId = if (parsed.layers.isNotEmpty()) parsed.layers[0].id else ""
                        isProjectInitialized = true

                        workspaceViewModel.saveProject(nid, projectName, parsed.canvasWidth, parsed.canvasHeight, parsed.layers, dpi = 300)
                        android.widget.Toast.makeText(context, "Alight Motion XML imported successfully with ${parsed.layers.size} layers!", android.widget.Toast.LENGTH_LONG).show()
                    }
                } catch (e: Throwable) {
                    e.printStackTrace()
                    isAlightImporting = false
                    alightImportErrorMsg = "Alight XML Parsing Failure: " + (e.localizedMessage ?: e.javaClass.simpleName)
                } finally {
                    isAlightImporting = false
                }
            }
        }
    }

    // Background Auto-Save Side-Effect
    LaunchedEffect(layers, canvasWidth, canvasHeight, projectName, projectId, projectDpi) {
        if (isProjectInitialized && projectId.isNotEmpty()) {
            kotlinx.coroutines.delay(1000)
            workspaceViewModel.saveProject(
                id = projectId,
                name = projectName,
                width = canvasWidth,
                height = canvasHeight,
                layers = layers,
                dpi = projectDpi
            )
        }
    }

    LaunchedEffect(activeTool, rulerEnabled) {
        if (activeTool == "Ruler" || (rulerEnabled && rulers.size <= 1)) {
            if (rulers.size <= 1 || (rulers.size == 1 && rulers[0].id == "default_ruler")) {
                val h = if (canvasHeight > 0) canvasHeight else 1000f
                val w = if (canvasWidth > 0) canvasWidth else 1000f
                rulers = listOf(
                    StudioRuler(id = "r_h1", name = "Top Guideline", enabled = true, orientation = "Horizontal", position = h / 3f, angle = 0f, locked = false),
                    StudioRuler(id = "r_h2", name = "Bottom Guideline", enabled = true, orientation = "Horizontal", position = 2 * h / 3f, angle = 0f, locked = false),
                    StudioRuler(id = "r_v1", name = "Left Guideline", enabled = true, orientation = "Vertical", position = w / 3f, angle = 0f, locked = false),
                    StudioRuler(id = "r_v2", name = "Right Guideline", enabled = true, orientation = "Vertical", position = 2 * w / 3f, angle = 0f, locked = false)
                )
                selectedRulerId = "r_h1"
            }
            isBottomPanelVisible = true
        }
    }

    var viewportWidth by remember { mutableStateOf(1200f) }
    var viewportHeight by remember { mutableStateOf(1200f) }

    val fitScale = remember(viewportWidth, viewportHeight, canvasWidth, canvasHeight) {
        val scaleW = viewportWidth / canvasWidth
        val scaleH = viewportHeight / canvasHeight
        minOf(scaleW, scaleH) * 0.85f // 15% safety margin on mobile
    }
    val totalScale = fitScale * scaleFactor
    
    val canvasX = (viewportWidth - canvasWidth * totalScale) / 2f
    val canvasY = (viewportHeight - canvasHeight * totalScale) / 2f

    val currentLayersState = rememberUpdatedState(layers)
    val currentCanvasXState = rememberUpdatedState(canvasX)
    val currentCanvasYState = rememberUpdatedState(canvasY)
    val currentTotalScaleState = rememberUpdatedState(totalScale)
    val currentActiveToolState = rememberUpdatedState(activeTool)
    val currentSelectedLayerIdState = rememberUpdatedState(selectedLayerId)

    val currentCanvasPanXState = rememberUpdatedState(canvasPanX)
    val currentCanvasPanYState = rememberUpdatedState(canvasPanY)
    val currentCanvasRotationState = rememberUpdatedState(canvasRotation)
    val currentViewportWidthState = rememberUpdatedState(viewportWidth)
    val currentViewportHeightState = rememberUpdatedState(viewportHeight)
    val currentCanvasWidthState = rememberUpdatedState(canvasWidth)
    val currentCanvasHeightState = rememberUpdatedState(canvasHeight)

    val currentGridEnabledState = rememberUpdatedState(gridEnabled)
    val currentGridColumnsState = rememberUpdatedState(gridColumns)
    val currentGridRowsState = rememberUpdatedState(gridRows)
    val currentRulerEnabledState = rememberUpdatedState(rulerEnabled)
    val currentRulerOrientationState = rememberUpdatedState(rulerOrientation)
    val currentRulerPositionState = rememberUpdatedState(rulerPosition)
    val currentRulerAngleState = rememberUpdatedState(rulerAngle)
    val currentSnapToRulerState = rememberUpdatedState(snapToRuler)
    val currentRulersState = rememberUpdatedState(rulers)
    val currentSelectedRulerIdState = rememberUpdatedState(selectedRulerId)

    val executeArtworkExport: (Float, Boolean) -> Unit = { mult, cmyk ->
        android.widget.Toast.makeText(context, "Exporting high-resolution artwork to Gallery...", android.widget.Toast.LENGTH_SHORT).show()
        scope.launch {
            try {
                val targetW = canvasWidth * mult
                val targetH = canvasHeight * mult
                
                val exportedBitmap = withContext(Dispatchers.Default) {
                    exportCanvasToBitmap(
                        context = context,
                        canvasWidth = canvasWidth,
                        canvasHeight = canvasHeight,
                        layers = layers,
                        imageBitmapCache = imageBitmapCache,
                        targetWidth = targetW,
                        targetHeight = targetH,
                        isCmyk = cmyk
                    )
                }
                
                val filename = (if (projectName.isBlank()) "Masterpiece" else projectName) + "_" + (if (cmyk) "CMYK_" else "RGB_") + targetW.toInt() + "x" + targetH.toInt() + "_" + System.currentTimeMillis()
                val uri = withContext(Dispatchers.IO) {
                    saveBitmapToGallery(context, exportedBitmap, filename, projectDpi)
                }
                
                if (uri != null) {
                    android.widget.Toast.makeText(context, "Exported successfully to Public Pictures (${targetW.toInt()}x${targetH.toInt()})!", android.widget.Toast.LENGTH_LONG).show()
                } else {
                    android.widget.Toast.makeText(context, "Export failed. Please check device state.", android.widget.Toast.LENGTH_LONG).show()
                }
            } catch (e: Throwable) {
                android.widget.Toast.makeText(context, "Export error: ${e.localizedMessage ?: e.javaClass.simpleName}", android.widget.Toast.LENGTH_LONG).show()
            }
        }
    }

    val executePsdExport: () -> Unit = {
        android.widget.Toast.makeText(context, "Packing multi-layer PSD document...", android.widget.Toast.LENGTH_SHORT).show()
        scope.launch {
            try {
                val filename = (if (projectName.isBlank()) "Masterpiece" else projectName) + "_" + System.currentTimeMillis()
                val uri = PsdExportEngine.savePsdToGallery(
                    context = context,
                    layers = layers,
                    canvasWidth = canvasWidth,
                    canvasHeight = canvasHeight,
                    imageBitmapCache = imageBitmapCache,
                    filename = filename,
                    projectDpi = projectDpi
                )
                if (uri != null) {
                    android.widget.Toast.makeText(context, "Exported PSD layered successfully to Pictures/PhotoshopExports!", android.widget.Toast.LENGTH_LONG).show()
                } else {
                    android.widget.Toast.makeText(context, "Export failed. Please check device state.", android.widget.Toast.LENGTH_LONG).show()
                }
            } catch (e: Throwable) {
                android.widget.Toast.makeText(context, "PSD Export error: ${e.localizedMessage ?: e.javaClass.simpleName}", android.widget.Toast.LENGTH_LONG).show()
            }
        }
    }

    val executeAlightXmlExport: () -> Unit = {
        android.widget.Toast.makeText(context, "Exporting Alight Motion XML template...", android.widget.Toast.LENGTH_SHORT).show()
        scope.launch {
            try {
                val filename = (if (projectName.isBlank()) "AlightScene" else projectName) + "_" + System.currentTimeMillis()
                val uri = AlightXmlEngine.saveAlightXmlToDownloads(
                    context = context,
                    projectName = filename,
                    canvasWidth = canvasWidth,
                    canvasHeight = canvasHeight,
                    layers = layers
                )
                if (uri != null) {
                    android.widget.Toast.makeText(context, "Exported Alight XML successfully to Download/AlightExports!", android.widget.Toast.LENGTH_LONG).show()
                } else {
                    android.widget.Toast.makeText(context, "Export failed. Please check device state.", android.widget.Toast.LENGTH_LONG).show()
                }
            } catch (e: Throwable) {
                android.widget.Toast.makeText(context, "Alight XML Export error: ${e.localizedMessage ?: e.javaClass.simpleName}", android.widget.Toast.LENGTH_LONG).show()
            }
        }
    }

    val onExportArtwork: () -> Unit = {
        showExportSettingsDialog = true
    }

    if (!isProjectInitialized) {
        CanvasSetupScreen(
            canvasWidthInput = canvasWidthInput,
            canvasHeightInput = canvasHeightInput,
            selectedPresetIndex = selectedPresetIndex,
            onWidthChange = { canvasWidthInput = it },
            onHeightChange = { canvasHeightInput = it },
            onPresetSelect = { index ->
                selectedPresetIndex = index
                val displayMetrics = context.resources.displayMetrics
                val screenW = displayMetrics.widthPixels
                val screenH = displayMetrics.heightPixels
                val aspect = if (screenW > 0) screenH.toFloat() / screenW.toFloat() else 1350f / 1080f
                when (index) {
                    0 -> { canvasWidthInput = "1080"; canvasHeightInput = (1080f * aspect).toInt().toString() } // Perfect Fit (Device Screen)
                    1 -> { canvasWidthInput = "1080"; canvasHeightInput = "1350" } // Instagram Portrait
                    2 -> { canvasWidthInput = "1080"; canvasHeightInput = "1920" } // Instagram Story
                    3 -> { canvasWidthInput = "1080"; canvasHeightInput = "1080" } // Square Post
                    4 -> { canvasWidthInput = "1920"; canvasHeightInput = "1080" } // FHD Landscape
                    5 -> { canvasWidthInput = "1200"; canvasHeightInput = "1600" } // Modern Poster
                    6 -> { /* Custom size - let user adjust manually */ }
                }
            },
            onInitialize = { dpiChosen ->
                projectDpi = dpiChosen
                val w = canvasWidthInput.toFloatOrNull() ?: 1080f
                val h = canvasHeightInput.toFloatOrNull() ?: 1350f
                val finalW = w.coerceIn(100f, 8000f)
                val finalH = h.coerceIn(100f, 8000f)
                canvasWidth = finalW
                canvasHeight = finalH
                val nid = UUID.randomUUID().toString()
                projectId = nid
                projectName = "Design ${finalW.toInt()}x${finalH.toInt()}"
                layers = emptyList()
                isProjectInitialized = true
                workspaceViewModel.saveProject(nid, projectName, finalW, finalH, emptyList(), dpi = dpiChosen)
            },
            previousProjects = previousProjects,
            onLoadProject = { proj ->
                projectId = proj.id
                projectName = proj.name
                canvasWidth = proj.width
                canvasHeight = proj.height
                canvasWidthInput = proj.width.toInt().toString()
                canvasHeightInput = proj.height.toInt().toString()
                projectDpi = try { proj.dpi } catch (e: Exception) { 300 }
                scope.launch {
                    val decoded = withContext(Dispatchers.Default) {
                        LayerSerializer.deserialize(proj.layersJson)
                    }
                    layers = decoded
                    selectedLayerId = if (decoded.isNotEmpty()) decoded[0].id else ""
                    isProjectInitialized = true
                }
            },
            onDeleteProject = { id ->
                workspaceViewModel.deleteProject(id)
            },
            onRenameProject = { proj, newName ->
                workspaceViewModel.renameProject(proj, newName)
            },
            onImportPsdRequest = {
                psdPickerLauncher.launch("*/*")
            },
            onImportAlightRequest = {
                alightXmlPickerLauncher.launch("*/*")
            }
        )

        // Render PSD importing dialogs during Setup Phase
        if (showDownscalePsdDialog != null) {
            val psd = showDownscalePsdDialog!!
            AlertDialog(
                onDismissRequest = { showDownscalePsdDialog = null },
                title = {
                    Text(
                        text = " HIGH RESOLUTION WARNING",
                        style = Typography.titleMedium,
                        color = Color(0xFFFF8A80),
                        fontWeight = FontWeight.Bold
                    )
                },
                text = {
                    Text(
                        text = "This Photoshop file has a high-resolution canvas size of ${psd.rawWidth} × ${psd.rawHeight} px.\n\n" +
                               "High-resolution multi-layer files can easily exceed mobile GPU texture size limits and cause Out-Of-Memory crashing. " +
                               "To ensure smooth performance, we recommend downscaling the document canvas and layers appropriately.",
                        style = Typography.bodyMedium,
                        color = TextPrimary
                    )
                },
                confirmButton = {
                    Button(
                        onClick = {
                            val parsed = showDownscalePsdDialog
                            showDownscalePsdDialog = null
                            if (parsed != null) {
                                loadParsedPsd(parsed, true)
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = EnergeticYellow)
                    ) {
                        Text("Recommend Downscale (2048px Max)", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                    }
                },
                dismissButton = {
                    TextButton(
                        onClick = {
                            val parsed = showDownscalePsdDialog
                            showDownscalePsdDialog = null
                            if (parsed != null) {
                                loadParsedPsd(parsed, false)
                            }
                        }
                    ) {
                        Text("Import Original (Risk of Crashes)", style = Typography.labelSmall, color = TextSecondary)
                    }
                },
                containerColor = SlatePanel,
                shape = RoundedCornerShape(12.dp)
            )
        }

        if (isPsdImporting) {
            AlertDialog(
                onDismissRequest = {},
                title = {
                    Row(
                        verticalAlignment = androidx.compose.ui.Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        CircularProgressIndicator(
                            color = EnergeticYellow,
                            modifier = Modifier.size(24.dp),
                            strokeWidth = 2.5.dp
                        )
                        Text(
                            text = "IMPORTING PSD DOCUMENT",
                            style = Typography.titleMedium.copy(fontSize = 14.sp),
                            color = TextPrimary,
                            fontWeight = FontWeight.Bold
                        )
                    }
                },
                text = {
                    Column(
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text(
                            text = "We're parsing the Adobe layered structure and converting images safely.",
                            style = Typography.bodyMedium,
                            color = TextSecondary
                        )
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(DarkOnyx, RoundedCornerShape(6.dp))
                                .padding(horizontal = 12.dp, vertical = 8.dp)
                        ) {
                            Text(
                                text = psdImportProgressState,
                                style = Typography.bodySmall.copy(fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace, fontSize = 11.sp),
                                color = EnergeticYellow
                            )
                        }
                    }
                },
                confirmButton = {},
                containerColor = SlatePanel,
                shape = RoundedCornerShape(12.dp)
            )
        }

        if (psdImportErrorMsg != null) {
            AlertDialog(
                onDismissRequest = { psdImportErrorMsg = null },
                title = {
                    Text(
                        text = " PSD IMPORT ERROR",
                        style = Typography.titleMedium,
                        color = Color(0xFFFF8A80),
                        fontWeight = FontWeight.Bold
                    )
                },
                text = {
                    Text(
                        text = psdImportErrorMsg!!,
                        style = Typography.bodyMedium,
                        color = TextPrimary
                    )
                },
                confirmButton = {
                    Button(
                        onClick = { psdImportErrorMsg = null },
                        colors = ButtonDefaults.buttonColors(containerColor = EnergeticYellow)
                    ) {
                        Text("Dismiss", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                    }
                },
                containerColor = SlatePanel,
                shape = RoundedCornerShape(12.dp)
            )
        }

        if (isAlightImporting) {
            AlertDialog(
                onDismissRequest = {},
                title = {
                    Row(
                        verticalAlignment = androidx.compose.ui.Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        CircularProgressIndicator(
                            color = Color(0xFF00FF66),
                            modifier = Modifier.size(24.dp),
                            strokeWidth = 2.5.dp
                        )
                        Text(
                            text = "IMPORTING ALIGHT COMPOSITION",
                            style = Typography.titleMedium.copy(fontSize = 14.sp),
                            color = TextPrimary,
                            fontWeight = FontWeight.Bold
                        )
                    }
                },
                text = {
                    Text(
                        text = "Analyzing XML design structures, mapping nodes, and scaling vector coordinates. Please hold on.",
                        style = Typography.bodyMedium,
                        color = TextPrimary
                    )
                },
                confirmButton = {},
                containerColor = SlatePanel,
                shape = RoundedCornerShape(12.dp)
            )
        }

        if (alightImportErrorMsg != null) {
            AlertDialog(
                onDismissRequest = { alightImportErrorMsg = null },
                title = {
                    Text(
                        text = " ALIGHT XML IMPORT ERROR",
                        style = Typography.titleMedium,
                        color = Color(0xFFFF8A80),
                        fontWeight = FontWeight.Bold
                    )
                },
                text = {
                    Text(
                        text = alightImportErrorMsg!!,
                        style = Typography.bodyMedium,
                        color = TextPrimary
                    )
                },
                confirmButton = {
                    Button(
                        onClick = { alightImportErrorMsg = null },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF00FF66))
                    ) {
                        Text("Dismiss", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                    }
                },
                containerColor = SlatePanel,
                shape = RoundedCornerShape(12.dp)
            )
        }
    } else {
        @Composable
        fun RenderBottomEffectPanel(isLandscapeMode: Boolean) {
            val rulerSettings = remember(rulers, selectedRulerId, snapToRuler, allRulersLocked) {
                WorkspaceRulerSettings(
                    rulers = rulers,
                    onRulersChange = { rulers = it },
                    selectedRulerId = selectedRulerId,
                    onSelectedRulerIdChange = { selectedRulerId = it },
                    snapToRuler = snapToRuler,
                    onSnapToRulerChange = { snapToRuler = it },
                    allRulersLocked = allRulersLocked,
                    onAllRulersLockedChange = { allRulersLocked = it }
                )
            }
            CompositionLocalProvider(LocalRulerSettings provides rulerSettings) {
                BottomEffectPanel(
                selectedLayer = selectedLayer,
                onOpenColorPickerDialog = { idx ->
                    activeGradientStopIndex = idx
                    showGradientColorPickerDialog = true
                },
                selectedEffectIndex = selectedEffectIndex,
                onSelectEffectIndex = { selectedEffectIndex = it },
                onAddEffect = { effect ->
                    if (selectedLayer != null) {
                        layers = layers.map { layer ->
                            if (layer.id == selectedLayer.id) {
                                layer.copy(effects = layer.effects + effect)
                            } else layer
                        }
                    }
                },
                onUpdateEffectParam = { effectId, paramName, newValue ->
                    if (selectedLayer != null) {
                        com.example.studio.ui.CanvasEventLoop.emit(
                            com.example.studio.ui.CanvasEvent.UpdateSlider(
                                layerId = selectedLayer.id,
                                effectId = effectId,
                                paramName = paramName,
                                value = newValue
                            )
                        )
                    }
                },
                onRemoveEffect = { effectId ->
                    if (selectedLayer != null) {
                        undoStack.add(layers)
                        redoStack.clear()
                        layers = layers.map { layer ->
                            if (layer.id == selectedLayer.id) {
                                layer.copy(effects = layer.effects.filter { it.id != effectId })
                            } else layer
                        }
                    }
                },
                onToggleEffectEnabled = { effectId ->
                    if (selectedLayer != null) {
                        undoStack.add(layers)
                        redoStack.clear()
                        layers = layers.map { layer ->
                            if (layer.id == selectedLayer.id) {
                                val updatedEffects = layer.effects.map { eff ->
                                    if (eff.id == effectId) {
                                        eff.toggleEnabled()
                                    } else eff
                                }
                                layer.copy(effects = updatedEffects)
                            } else layer
                        }
                    }
                },
                onUpdateLayer = { updatedLayer ->
                    layers = layers.map { if (it.id == updatedLayer.id) updatedLayer else it }
                },
                onCloseBottomPanel = { isBottomPanelVisible = false },
                onOpenEffectsGallery = { showEffectsGallery = true },
                onOpenBrushesLibrary = { showBrushesLibrary = true },
                activeTool = activeTool,
                brushSize = brushSize,
                onBrushSizeChange = { brushSize = it },
                onBrushOpacityChange = { brushOpacity = it },
                brushOpacity = brushOpacity,
                brushColor = brushColor,
                onBrushColorChange = { brushColor = it },
                brushSmoothing = brushSmoothing,
                onBrushSmoothingChange = { brushSmoothing = it },
                brushPresetIndex = brushPresetIndex,
                onBrushPresetIndexChange = { brushPresetIndex = it },
                eraserSize = eraserSize,
                onEraserSizeChange = { eraserSize = it },
                eraserHardness = eraserHardness,
                onEraserHardnessChange = { eraserHardness = it },
                fontSearchQuery = fontSearchQuery,
                onFontSearchQueryChange = { fontSearchQuery = it },
                selectedCategoryFilter = selectedCategoryFilter,
                onSelectedCategoryFilterChange = { selectedCategoryFilter = it },
                onImportFontClick = { showFontScannerDialog = true },
                onExportCanvas = onExportArtwork,
                gridEnabled = gridEnabled,
                onGridEnabledChange = { gridEnabled = it },
                rulerEnabled = rulerEnabled,
                onRulerEnabledChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(enabled = value) else it } },
                rulerOrientation = rulerOrientation,
                onRulerOrientationChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(orientation = value) else it } },
                rulerPosition = rulerPosition,
                onRulerPositionChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(position = value) else it } },
                gridColumns = gridColumns,
                onGridColumnsChange = { gridColumns = it },
                gridRows = gridRows,
                onGridRowsChange = { gridRows = it },
                rulerAngle = rulerAngle,
                onRulerAngleChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(angle = value) else it } },
                rulerLocked = rulerLocked,
                onRulerLockedChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(locked = value) else it } },
                snapToRuler = snapToRuler,
                onSnapToRulerChange = { snapToRuler = it },
                activeFullScreenSheet = activeFullScreenSheet,
                onActiveFullScreenSheetChange = { activeFullScreenSheet = it },
                isLandscape = isLandscapeMode
            )
            }
        }

        // App Workspace UI Grid Root
        Box(
            modifier = modifier
                .fillMaxSize()
                .background(DarkOnyx)
                .windowInsetsPadding(WindowInsets.safeDrawing)
        ) {
        Column(modifier = Modifier.fillMaxSize()) {
            // -- TOP PLATFORM CONTROL SHELF --
            TopControlShelf(
                activeTool = activeTool,
                onToolChange = { activeTool = it },
                isLeftToolbarExpanded = isLeftToolbarExpanded,
                onToggleLeftToolbar = { isLeftToolbarExpanded = !isLeftToolbarExpanded },
                onUndo = {
                    if (undoStack.isNotEmpty()) {
                        val prev = undoStack.removeAt(undoStack.size - 1)
                        redoStack.add(layers)
                        layers = prev
                        advancedBrushResultCache.clear()
                    }
                },
                onRedo = {
                    if (redoStack.isNotEmpty()) {
                        val next = redoStack.removeAt(redoStack.size - 1)
                        undoStack.add(layers)
                        layers = next
                        advancedBrushResultCache.clear()
                    }
                },
                canUndo = undoStack.isNotEmpty(),
                canRedo = redoStack.isNotEmpty(),
                layersPanelVisible = isLayersPanelVisible,
                onToggleLayersPanel = { isLayersPanelVisible = !isLayersPanelVisible },
                bottomPanelVisible = isBottomPanelVisible,
                onToggleBottomPanel = { isBottomPanelVisible = !isBottomPanelVisible },
                onExitWorkspace = {
                    // Reset workspace when exiting to main menu
                    isProjectInitialized = false
                    projectId = ""
                    projectName = ""
                    layers = emptyList()
                    selectedLayerId = ""
                    activeTool = "Brush"
                    imageBitmapCache.clear()
                    advancedBrushResultCache.clear()
                },
                onExportCanvas = onExportArtwork
            )

            if (showRenameProjectDialog) {
                AlertDialog(
                    onDismissRequest = { showRenameProjectDialog = false },
                    title = { Text("Rename Design Masterpiece", color = TextPrimary, style = Typography.titleMedium) },
                    text = {
                        OutlinedTextField(
                            value = projectRenameValue,
                            onValueChange = { projectRenameValue = it },
                            label = { Text("Design Title", style = Typography.bodyMedium) },
                            textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedBorderColor = IndustrialAmber,
                                focusedLabelColor = IndustrialAmber,
                                cursorColor = IndustrialAmber,
                                unfocusedBorderColor = HighslateOutline,
                                unfocusedLabelColor = TextSecondary
                            ),
                            singleLine = true,
                            modifier = Modifier.fillMaxWidth()
                        )
                    },
                    confirmButton = {
                        Button(
                            onClick = {
                                if (projectRenameValue.isNotBlank()) {
                                    projectName = projectRenameValue
                                }
                                showRenameProjectDialog = false
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = IndustrialAmber)
                        ) {
                            Text("SAVE", color = DarkOnyx, fontWeight = FontWeight.Bold, style = Typography.bodyMedium)
                        }
                    },
                    dismissButton = {
                        TextButton(onClick = { showRenameProjectDialog = false }) {
                            Text("CANCEL", color = TextSecondary, style = Typography.bodyMedium)
                        }
                    },
                    containerColor = SlatePanel,
                    shape = RoundedCornerShape(12.dp)
                )
            }

            if (showDownscalePsdDialog != null) {
                val psd = showDownscalePsdDialog!!
                AlertDialog(
                    onDismissRequest = { showDownscalePsdDialog = null },
                    title = {
                        Text(
                            text = " HIGH RESOLUTION WARNING",
                            style = Typography.titleMedium,
                            color = Color(0xFFFF8A80),
                            fontWeight = FontWeight.Bold
                        )
                    },
                    text = {
                        Text(
                            text = "This Photoshop file has a high-resolution canvas size of ${psd.rawWidth} × ${psd.rawHeight} px.\n\n" +
                                   "High-resolution multi-layer files can easily exceed mobile GPU texture size limits and cause Out-Of-Memory crashing. " +
                                   "To ensure smooth performance, we recommend downscaling the document canvas and layers appropriately.",
                            style = Typography.bodyMedium,
                            color = TextPrimary
                        )
                    },
                    confirmButton = {
                        Button(
                            onClick = {
                                val parsed = showDownscalePsdDialog
                                showDownscalePsdDialog = null
                                if (parsed != null) {
                                    loadParsedPsd(parsed, true)
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = EnergeticYellow)
                        ) {
                            Text("Recommend Downscale (2048px Max)", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                        }
                    },
                    dismissButton = {
                        TextButton(
                            onClick = {
                                val parsed = showDownscalePsdDialog
                                showDownscalePsdDialog = null
                                if (parsed != null) {
                                    loadParsedPsd(parsed, false)
                                }
                            }
                        ) {
                            Text("Import Original (Risk of Crashes)", style = Typography.labelSmall, color = TextSecondary)
                        }
                    },
                    containerColor = SlatePanel,
                    shape = RoundedCornerShape(12.dp)
                )
            }

            if (isPsdImporting) {
                AlertDialog(
                    onDismissRequest = {}, // Modal, cannot be dismissed while parsing is in progress
                    title = {
                        Row(
                            verticalAlignment = androidx.compose.ui.Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            CircularProgressIndicator(
                                color = EnergeticYellow,
                                modifier = Modifier.size(24.dp),
                                strokeWidth = 2.5.dp
                            )
                            Text(
                                text = "IMPORTING PSD DOCUMENT",
                                style = Typography.titleMedium.copy(fontSize = 14.sp),
                                color = TextPrimary,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    },
                    text = {
                        Column(
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text(
                                text = "We're parsing the Adobe layered structure and converting images safely.",
                                style = Typography.bodyMedium,
                                color = TextSecondary
                            )
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(DarkOnyx, RoundedCornerShape(6.dp))
                                    .padding(horizontal = 12.dp, vertical = 8.dp)
                            ) {
                                Text(
                                    text = psdImportProgressState,
                                    style = Typography.bodySmall.copy(fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace, fontSize = 11.sp),
                                    color = EnergeticYellow
                                )
                            }
                        }
                    },
                    confirmButton = {}, // None, forced active modal
                    containerColor = SlatePanel,
                    shape = RoundedCornerShape(12.dp)
                )
            }

            if (psdImportErrorMsg != null) {
                AlertDialog(
                    onDismissRequest = { psdImportErrorMsg = null },
                    title = {
                        Text(
                            text = " PSD IMPORT ERROR",
                            style = Typography.titleMedium,
                            color = Color(0xFFFF8A80),
                            fontWeight = FontWeight.Bold
                        )
                    },
                    text = {
                        Text(
                            text = psdImportErrorMsg!!,
                            style = Typography.bodyMedium,
                            color = TextPrimary
                        )
                    },
                    confirmButton = {
                        Button(
                            onClick = { psdImportErrorMsg = null },
                            colors = ButtonDefaults.buttonColors(containerColor = EnergeticYellow)
                        ) {
                            Text("Dismiss", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                        }
                    },
                    containerColor = SlatePanel,
                    shape = RoundedCornerShape(12.dp)
                )
            }

            // -- MAIN CREATIVE CORE GRID --
            Row(
                modifier = Modifier
                    .weight(if (activeFullScreenSheet != null) 0.6f else 1f)
                    .fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                // Leftside Dock Panel: Compact dynamic utility toolstrip with collapsibility
                if (isLeftToolbarExpanded) {
                    LeftsideToolDock(
                        activeTool = activeTool,
                        onSelectTool = {
                            activeTool = it
                            if (it == "Shapes") {
                                showAddShapeDialog = true
                            } else if (it == "Import") {
                                imagePickerLauncher.launch("image/*")
                                activeTool = "Move"
                            } else if (it == "Text") {
                                val newL = StudioLayer(
                                    name = "Text Layer",
                                    type = LayerType.TEXT,
                                    positionX = 350f,
                                    positionY = 450f,
                                    width = 350f,
                                    height = 100f,
                                    baseColor = Color.White,
                                    textContent = "DOUBLE TAP TO EDIT"
                                )
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = listOf(newL) + layers
                                selectedLayerId = newL.id
                                activeTool = "Move"
                            } else if (it == "Grid") {
                                gridEnabled = true
                                isBottomPanelVisible = true
                            } else if (it == "Ruler") {
                                rulers = rulers.map { r -> if (r.id == selectedRulerId) r.copy(enabled = true) else r }
                                isBottomPanelVisible = true
                            }
                        }
                    )
                }

                // Central Workspace Canvas Container
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxHeight()
                        .padding(8.dp)
                        .clip(RoundedCornerShape(12.dp))
                        .background(Color(0xFF0F0F12))
                        .border(1.dp, HighslateOutline, RoundedCornerShape(12.dp))
                        .onSizeChanged { size ->
                            viewportWidth = size.width.toFloat()
                            viewportHeight = size.height.toFloat()
                        }
                        .testTag("canvas_viewport"),
                    contentAlignment = Alignment.Center
                ) {
                    // Chess board / transparency checker grid background simulation
                    Canvas(
                        modifier = Modifier
                            .fillMaxSize()
                            .drawBehind {
                                // Super-performant, single-draw background fill for the entire workspace
                                drawRect(
                                    color = Color(0xFF0C0C0E),
                                    topLeft = Offset.Zero,
                                    size = size
                                )
                            }
                            // Single unified pointer input block combining Tap selection, multi-touch Pan/Zoom/Rotate, and single-finger Layer Move/Resize/Draw
                            .pointerInput(Unit) {
                                awaitEachGesture {
                                    val down = awaitFirstDown(requireUnconsumed = false)
                                    var dragMode: String? = null
                                    var isTransforming = false
                                    var hasMovedPastSlop = false
                                    val touchSlop = viewConfiguration.touchSlop
                                    var accumOffset = Offset.Zero

                                    val ts = currentTotalScaleState.value
                                    val lyrs = currentLayersState.value
                                    val selId = currentSelectedLayerIdState.value
                                    val tool = currentActiveToolState.value

                                    val localStartOffset = screenToCanvas(
                                        screenPos = down.position,
                                        viewportWidth = currentViewportWidthState.value,
                                        viewportHeight = currentViewportHeightState.value,
                                        canvasPanX = currentCanvasPanXState.value,
                                        canvasPanY = currentCanvasPanYState.value,
                                        canvasRotation = currentCanvasRotationState.value,
                                        totalScale = ts,
                                        canvasWidth = currentCanvasWidthState.value,
                                        canvasHeight = currentCanvasHeightState.value
                                    )
                                    val localStartX = localStartOffset.x
                                    val localStartY = localStartOffset.y

                                    var draggedRulerId: String? = null
                                    if (tool == "Ruler") {
                                        val threshold = 35f / ts.coerceAtLeast(0.3f)
                                        var nearestRuler: StudioRuler? = null
                                        var minDistance = Float.MAX_VALUE
                                        for (ruler in currentRulersState.value) {
                                            if (!ruler.enabled) continue
                                            val dist = if (ruler.orientation == "Horizontal") {
                                                Math.abs(localStartY - ruler.position)
                                            } else {
                                                Math.abs(localStartX - ruler.position)
                                            }
                                            if (dist < threshold && dist < minDistance) {
                                                minDistance = dist
                                                nearestRuler = ruler
                                            }
                                        }
                                        if (nearestRuler != null) {
                                            draggedRulerId = nearestRuler.id
                                            selectedRulerId = nearestRuler.id
                                        }
                                    }

                                    var lastEvent = down

                                    do {
                                        val event = awaitPointerEvent()
                                        val activePointers = event.changes.filter { it.pressed }

                                        if (activePointers.size >= 2) {
                                            isTransforming = true
                                            dragMode = null

                                            val zoom = if (isCanvasLocked) 1f else event.calculateZoom()
                                            val rotation = if (isCanvasLocked) 0f else event.calculateRotation()
                                            val pan = if (isCanvasLocked) Offset.Zero else event.calculatePan()

                                             var newScale = scaleFactor
                                             var newRotation = canvasRotation
                                             var newPanX = canvasPanX
                                             var newPanY = canvasPanY
                                             if (zoom != 1f) {
                                                 newScale = (scaleFactor * zoom).coerceIn(0.3f, 5.0f)
                                             }
                                             if (rotation != 0f) {
                                                 newRotation = (canvasRotation + rotation) % 360f
                                             }
                                            if (pan != Offset.Zero) {
                                                val snappedNewPanX = canvasPanX + pan.x
                                                 val snappedNewPanY = canvasPanY + pan.y
                                                 val snappedFinalX = if (Math.abs(snappedNewPanX) < 25f) 0f else snappedNewPanX
                                                 val snappedFinalY = if (Math.abs(snappedNewPanY) < 25f) 0f else snappedNewPanY
                                                 newPanX = snappedFinalX
                                                 newPanY = snappedFinalY
                                            }
                                            com.example.studio.ui.CanvasEventLoop.emit(
                                                com.example.studio.ui.CanvasEvent.UpdateTransform(newPanX, newPanY, newScale, newRotation)
                                            )

                                            event.changes.forEach { it.consume() }
                                        } else if (activePointers.size == 1 && !isTransforming) {
                                            val pointer = activePointers[0]
                                            val position = pointer.position
                                            val prevPosition = pointer.previousPosition
                                            val diff = position - prevPosition

                                            accumOffset += diff

                                            if (!hasMovedPastSlop) {
                                                if (accumOffset.getDistance() > touchSlop) {
                                                    hasMovedPastSlop = true

                                                    if (tool == "Brush" || tool == "Eraser") {
                                                        var targetId = selId
                                                        var currentSelected = lyrs.find { it.id == selId }

                                                        if (tool == "Eraser" && currentSelected == null && lyrs.isNotEmpty()) {
                                                            currentSelected = lyrs.find { it.type == LayerType.FREEHAND_DRAWING } ?: lyrs.first()
                                                            targetId = currentSelected.id
                                                            selectedLayerId = currentSelected.id
                                                        }

                                                        val needsNewLayer = if (tool == "Brush") {
                                                            currentSelected == null || currentSelected.type != LayerType.FREEHAND_DRAWING
                                                        } else {
                                                            currentSelected == null
                                                        }

                                                        if (needsNewLayer) {
                                                            val newL = StudioLayer(
                                                                name = if (tool == "Eraser") "Eraser Layer" else "Drawing Layer ${lyrs.filter { it.type == LayerType.FREEHAND_DRAWING }.size + 1}",
                                                                type = LayerType.FREEHAND_DRAWING,
                                                                positionX = 0f,
                                                                positionY = 0f,
                                                                width = currentCanvasWidthState.value,
                                                                height = currentCanvasHeightState.value,
                                                                baseColor = brushColor,
                                                                effects = listOf(
                                                                    PhotoshopEffectTemplates.create(effectType = "BrushConfig").let { eff ->
                                                                        var updated = eff.updateParameter("Size", brushSize)
                                                                        updated = updated.updateParameter("Opacity", brushOpacity)
                                                                        updated = updated.updateParameter("Smoothing", if (brushSmoothing) 1.0f else 0.0f)
                                                                        updated = updated.updateParameter("Preset", brushPresetIndex.toFloat())
                                                                        updated
                                                                    }
                                                                ),
                                                                brushPoints = emptyList()
                                                            )
                                                            undoStack.add(layers)
                                                            redoStack.clear()
                                                            layers = listOf(newL) + layers
                                                            selectedLayerId = newL.id
                                                            targetId = newL.id
                                                        }
                                                        strokeTracker.clear()
                                                        var snappedStartX = localStartX
                                                        var snappedStartY = localStartY
                                                        if (snapToRuler && currentRulersState.value.any { it.enabled }) {
                                                            val snapped = snapPointToRulers(
                                                                px = localStartX,
                                                                py = localStartY,
                                                                rulers = currentRulersState.value,
                                                                canvasWidth = currentCanvasWidthState.value,
                                                                canvasHeight = currentCanvasHeightState.value
                                                            )
                                                            snappedStartX = snapped.x
                                                            snappedStartY = snapped.y
                                                        }
                                                        strokeTracker.clear()
                                                        val activeL = layers.find { it.id == targetId }
                                                        val mappedStart = if (activeL != null) canvasToLayerLocal(Offset(snappedStartX, snappedStartY), activeL) else Offset(snappedStartX, snappedStartY)
                                                        strokeTracker.addPoint(mappedStart.x, mappedStart.y)
                                                        OpenGLBrushRenderer.WetInkRenderer.init(
                                                            (activeL?.width?.toInt() ?: currentCanvasWidthState.value.toInt()).coerceAtLeast(1),
                                                            (activeL?.height?.toInt() ?: currentCanvasHeightState.value.toInt()).coerceAtLeast(1)
                                                        )
                                                        val initX = mappedStart.x
                                                        val initY = mappedStart.y
                                                        val points = listOf(Offset(initX, initY), Offset(initX + 0.01f, initY + 0.01f))
                                                        OpenGLBrushRenderer.WetInkRenderer.drawSegments(
                                                            points = points,
                                                            color = if (tool == "Eraser") androidx.compose.ui.graphics.Color.Black else brushColor,
                                                            size = if (tool == "Eraser") eraserSize else brushSize,
                                                            opacity = if (tool == "Eraser") 1.0f else brushOpacity,
                                                            presetIndex = if (tool == "Eraser") 3 else brushPresetIndex,
                                                            smoothing = if (tool == "Eraser") true else brushSmoothing
                                                        )
                                                        strokeDrawTrigger.value++
                                                    } else {
                                                        val currentSelected = lyrs.find { it.id == selId }
                                                        if (currentSelected != null && !currentSelected.isAlphaLocked) {
                                                            val brX = currentSelected.positionX + currentSelected.width
                                                            val brY = currentSelected.positionY + currentSelected.height
                                                            val distBr = (localStartX - brX) * (localStartX - brX) + (localStartY - brY) * (localStartY - brY)

                                                            var isNearBezier = false
                                                            if (currentSelected.type == LayerType.VECTOR_BEZIER) {
                                                                val touchLocal = canvasToLayerLocal(localStartOffset, currentSelected)
                                                                val thresholdTemp = 60f / ts.coerceAtLeast(0.3f)
                                                                val thresholdTempSq = thresholdTemp * thresholdTemp
                                                                if (currentSelected.brushPoints.isNotEmpty()) {
                                                                    var nearestIndex = -1
                                                                    var minDistanceSq = Float.MAX_VALUE
                                                                    for (idx in currentSelected.brushPoints.indices) {
                                                                        val pt = currentSelected.brushPoints[idx]
                                                                        val dx = (touchLocal.x - pt.x) * currentSelected.scaleX
                                                                        val dy = (touchLocal.y - pt.y) * currentSelected.scaleY
                                                                        val distSq = dx * dx + dy * dy
                                                                        if (distSq < thresholdTempSq && distSq < minDistanceSq) {
                                                                            minDistanceSq = distSq
                                                                            nearestIndex = idx
                                                                        }
                                                                    }
                                                                    if (nearestIndex >= 0) {
                                                                        activeBezierPointIndex = nearestIndex
                                                                        isNearBezier = true
                                                                    }
                                                                }
                                                            }

                                                            // Gradient overlay linear handles click/drag match detection on-canvas
                                                            var matchedGradientOption = false
                                                            val gradOverlay = currentSelected.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                                            val gradientTypeOrdinal = (gradOverlay?.parameters["GradientType"]?.value ?: 0f).toInt()
                                                            
                                                            if (gradOverlay != null) { // Support all gradient overlays on-canvas
                                                                val goScale = (gradOverlay.parameters["Scale"]?.value ?: 100f) / 100f
                                                                val goAngle = gradOverlay.parameters["Angle"]?.value ?: 90f
                                                                
                                                                val hasCustomHandles = gradOverlay.parameters["StartX"] != null
                                                                val startX: Float
                                                                val startY: Float
                                                                val endX: Float
                                                                val endY: Float
                                                                if (hasCustomHandles) {
                                                                    startX = (gradOverlay.parameters["StartX"]?.value ?: 0f) * currentSelected.width
                                                                    startY = (gradOverlay.parameters["StartY"]?.value ?: 0f) * currentSelected.height
                                                                    endX = (gradOverlay.parameters["EndX"]?.value ?: 1f) * currentSelected.width
                                                                    endY = (gradOverlay.parameters["EndY"]?.value ?: 1f) * currentSelected.height
                                                                } else {
                                                                    val rads = Math.toRadians(goAngle.toDouble())
                                                                    val cos = Math.cos(rads).toFloat()
                                                                    val sin = Math.sin(rads).toFloat()
                                                                    startX = currentSelected.width / 2f - (currentSelected.width / 2f * cos * goScale)
                                                                    startY = currentSelected.height / 2f - (currentSelected.height / 2f * sin * goScale)
                                                                    endX = currentSelected.width / 2f + (currentSelected.width / 2f * cos * goScale)
                                                                    endY = currentSelected.height / 2f + (currentSelected.height / 2f * sin * goScale)
                                                                }
                                                                
                                                                val touchLocal = canvasToLayerLocal(localStartOffset, currentSelected)
                                                                val handleThreshold = 80f / ts.coerceAtLeast(0.5f)
                                                                val handleThresholdSq = handleThreshold * handleThreshold
                                                                
                                                                val distToStartSq = (touchLocal.x - startX) * (touchLocal.x - startX) + (touchLocal.y - startY) * (touchLocal.y - startY)
                                                                val distToEndSq = (touchLocal.x - endX) * (touchLocal.x - endX) + (touchLocal.y - endY) * (touchLocal.y - endY)
                                                                
                                                                if (GradientEyedropperState.isActive) {
                                                                    var sampledColor = Color(0xFF29B6F6)
                                                                    val layerUnderTouch = layers.find { layer ->
                                                                        val left = layer.positionX
                                                                        val top = layer.positionY
                                                                        val right = left + layer.width
                                                                        val bottom = top + layer.height
                                                                        localStartX in left..right && localStartY in top..bottom
                                                                    }
                                                                    if (layerUnderTouch != null) {
                                                                        sampledColor = layerUnderTouch.baseColor
                                                                        val layerGradOverlay = layerUnderTouch.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                                                        if (layerGradOverlay != null) {
                                                                            val lStopCount = (layerGradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
                                                                            val lColors = mutableListOf<Color>()
                                                                            for (i in 0 until lStopCount) {
                                                                                val rVal = layerGradOverlay.parameters["CustomStop_${i}_R"]?.value ?: 0.5f
                                                                                val gVal = layerGradOverlay.parameters["CustomStop_${i}_G"]?.value ?: 0.5f
                                                                                val bVal = layerGradOverlay.parameters["CustomStop_${i}_B"]?.value ?: 0.5f
                                                                                val aVal = layerGradOverlay.parameters["CustomStop_${i}_A"]?.value ?: 1.0f
                                                                                lColors.add(Color(rVal, gVal, bVal, aVal))
                                                                            }
                                                                            val sX = (layerGradOverlay.parameters["StartX"]?.value ?: 0f) * layerUnderTouch.width
                                                                            val sY = (layerGradOverlay.parameters["StartY"]?.value ?: 0f) * layerUnderTouch.height
                                                                            val eX = (layerGradOverlay.parameters["EndX"]?.value ?: 1f) * layerUnderTouch.width
                                                                            val eY = (layerGradOverlay.parameters["EndY"]?.value ?: 1f) * layerUnderTouch.height
                                                                            val localTouch = canvasToLayerLocal(localStartOffset, layerUnderTouch)
                                                                            val ab = Offset(eX - sX, eY - sY)
                                                                            val ap = Offset(localTouch.x - sX, localTouch.y - sY)
                                                                            val abLenSq = ab.x * ab.x + ab.y * ab.y
                                                                            val t = if (abLenSq > 0f) {
                                                                                ((ap.x * ab.x + ap.y * ab.y) / abLenSq).coerceIn(0f, 1f)
                                                                            } else 0f
                                                                            sampledColor = interpolateMultiColor(lColors, t)
                                                                        }
                                                                    } else {
                                                                        sampledColor = Color(0xFF131317)
                                                                    }
                                                                    
                                                                    val targetStopIndex = activeGradientStopIndex.coerceIn(0, 100)
                                                                    layers = layers.map { layer ->
                                                                        if (layer.id == currentSelected.id) {
                                                                            val updatedEffects = layer.effects.map { eff ->
                                                                                if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                    val map = eff.parameters.toMutableMap()
                                                                                    map["CustomStop_${targetStopIndex}_R"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_R", sampledColor.red, 0f, 1f)
                                                                                    map["CustomStop_${targetStopIndex}_G"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_G", sampledColor.green, 0f, 1f)
                                                                                    map["CustomStop_${targetStopIndex}_B"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_B", sampledColor.blue, 0f, 1f)
                                                                                    map["CustomStop_${targetStopIndex}_A"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_A", sampledColor.alpha, 0f, 1f)
                                                                                    eff.copy(parameters = map)
                                                                                } else eff
                                                                            }
                                                                            layer.copy(effects = updatedEffects)
                                                                        } else layer
                                                                    }
                                                                    GradientEyedropperState.isActive = false
                                                                    android.widget.Toast.makeText(context, "Color sampled successfully!", android.widget.Toast.LENGTH_SHORT).show()
                                                                    matchedGradientOption = true
                                                                } else if (distToStartSq < handleThresholdSq) {
                                                                    dragMode = "gradient_start"
                                                                    matchedGradientOption = true
                                                                } else if (distToEndSq < handleThresholdSq) {
                                                                    dragMode = "gradient_end"
                                                                    matchedGradientOption = true
                                                                } else {
                                                                    val stopCount = (gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
                                                                    var nearestStopIdx = -1
                                                                    var minStopSq = Float.MAX_VALUE
                                                                    for (idx in 0 until stopCount) {
                                                                        val fraction = gradOverlay.parameters["CustomStop_${idx}_Pos"]?.value ?: (idx.toFloat() / (stopCount - 1).coerceAtLeast(1))
                                                                        val stopX = startX + (endX - startX) * fraction
                                                                        val stopY = startY + (endY - startY) * fraction
                                                                        val distSq = (touchLocal.x - stopX) * (touchLocal.x - stopX) + (touchLocal.y - stopY) * (touchLocal.y - stopY)
                                                                        if (distSq < handleThresholdSq && distSq < minStopSq) {
                                                                            minStopSq = distSq
                                                                            nearestStopIdx = idx
                                                                        }
                                                                    }
                                                                    if (nearestStopIdx != -1) {
                                                                        dragMode = "gradient_stop"
                                                                        activeGradientStopIndex = nearestStopIdx
                                                                        matchedGradientOption = true
                                                                        
                                                                        // Update selected stop parameter
                                                                        layers = layers.map { layer ->
                                                                            if (layer.id == currentSelected.id) {
                                                                                val updatedEffects = layer.effects.map { eff ->
                                                                                    if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                        val map = eff.parameters.toMutableMap()
                                                                                        map["SelectedStopIndex"] = com.example.studio.model.EffectParameter("SelectedStopIndex", nearestStopIdx.toFloat(), 0f, 10f)
                                                                                        eff.copy(parameters = map)
                                                                                    } else eff
                                                                                }
                                                                                layer.copy(effects = updatedEffects)
                                                                            } else layer
                                                                        }
                                                                    } else {
                                                                        // Check projection to add new color stop
                                                                        val proj = projectPointOnSegment(
                                                                            px = touchLocal.x, py = touchLocal.y,
                                                                            ax = startX, ay = startY,
                                                                            bx = endX, by = endY
                                                                        )
                                                                        val tFraction = proj.first
                                                                        val projX = proj.second
                                                                        val projY = proj.third
                                                                        
                                                                        val dx = touchLocal.x - projX
                                                                        val dy = touchLocal.y - projY
                                                                        val localDist = kotlin.math.sqrt(dx * dx + dy * dy)
                                                                        val distInScreenPx = localDist * ts
                                                                        val densityValue = this.density
                                                                        val distInDp = distInScreenPx / densityValue
                                                                        
                                                                        if (false && distInDp <= 24f && stopCount < 100) {
                                                                                    // Interpolate the colors list
                                                                                    val goPresetIdx = (gradOverlay.parameters["Preset"]?.value ?: 0f).toInt().coerceIn(0, 7)
                                                                                    val customColorsList = mutableListOf<androidx.compose.ui.graphics.Color>()
                                                                                    for (idx in 0 until stopCount) {
                                                                                        val rKey = "CustomStop_${idx}_R"
                                                                                        val gKey = "CustomStop_${idx}_G"
                                                                                        val bKey = "CustomStop_${idx}_B"
                                                                                        val rVal = gradOverlay.parameters[rKey]?.value ?: when(idx) {
                                                                                            0 -> gradOverlay.parameters["CustomStart_R"]?.value ?: 1.0f
                                                                                            1 -> gradOverlay.parameters["CustomEnd_R"]?.value ?: 0.0f
                                                                                            else -> 0.5f
                                                                                        }
                                                                                        val gVal = gradOverlay.parameters[gKey]?.value ?: when(idx) {
                                                                                            0 -> gradOverlay.parameters["CustomStart_G"]?.value ?: 0.0f
                                                                                            1 -> gradOverlay.parameters["CustomEnd_G"]?.value ?: 0.0f
                                                                                            else -> 0.5f
                                                                                        }
                                                                                        val bVal = gradOverlay.parameters[bKey]?.value ?: when(idx) {
                                                                                            0 -> gradOverlay.parameters["CustomStart_B"]?.value ?: 0.0f
                                                                                            1 -> gradOverlay.parameters["CustomEnd_B"]?.value ?: 1.0f
                                                                                            else -> 0.5f
                                                                                        }
                                                                                        customColorsList.add(Color(rVal, gVal, bVal))
                                                                                    }
                                                                                    val previewColors = if (goPresetIdx == 7) {
                                                                                        customColorsList
                                                                                    } else {
                                                                                        gradientPresets[goPresetIdx.coerceIn(0, gradientPresets.size - 1)]
                                                                                    }
                                                                                    val interpolatedColor = interpolateMultiColor(previewColors, tFraction)
                                                                                    
                                                                                    undoStack.add(layers)
                                                                                    redoStack.clear()
                                                                                    var tempTargetedIndex = stopCount
                                                                                    layers = layers.map { layer ->
                                                                                        if (layer.id == currentSelected.id) {
                                                                                            val updatedEffects = layer.effects.map { eff ->
                                                                                                if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                                    val map = eff.parameters.toMutableMap()
                                                                                                    val count = stopCount + 1
                                                                                                    map["Preset"] = com.example.studio.model.EffectParameter("Preset", 7f, 0f, 10f) // switch to custom stops
                                                                                                    map["CustomStopCount"] = com.example.studio.model.EffectParameter("CustomStopCount", (stopCount + 1).toFloat(), 0f, 10f)
                                                                                                     
                                                                                                     // Gather and sort all stops (including alpha!)
                                                                                                     val allStops = (0 until stopCount).map { i ->
                                                                                                         val posVal = map["CustomStop_${i}_Pos"]?.value ?: (i.toFloat() / (stopCount - 1).coerceAtLeast(1))
                                                                                                         val rVal = map["CustomStop_${i}_R"]?.value ?: 0.5f
                                                                                                         val gVal = map["CustomStop_${i}_G"]?.value ?: 0.5f
                                                                                                         val bVal = map["CustomStop_${i}_B"]?.value ?: 0.5f
                                                                                                         val aVal = map["CustomStop_${i}_A"]?.value ?: 1.0f
                                                                                                         Triple(posVal, Color(rVal, gVal, bVal, aVal), aVal)
                                                                                                     }.toMutableList()
                                                                                                     
                                                                                                     // Append new stop at calculated tFraction projection coordinate
                                                                                                     allStops.add(Triple(tFraction, interpolatedColor, 1.0f))
                                                                                                     allStops.sortBy { it.first }
                                                                                                     
                                                                                                     val newSortedIndex = allStops.indexOfFirst { it.first == tFraction }.coerceIn(0, allStops.size - 1)
                                                                                                     
                                                                                                     // Write back keys sequentially to preserve perfect indexing
                                                                                                     for (idx in allStops.indices) {
                                                                                                         val stopNode = allStops[idx]
                                                                                                         map["CustomStop_${idx}_Pos"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_Pos", stopNode.first, 0f, 1f)
                                                                                                         map["CustomStop_${idx}_R"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_R", stopNode.second.red, 0f, 1f)
                                                                                                         map["CustomStop_${idx}_G"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_G", stopNode.second.green, 0f, 1f)
                                                                                                         map["CustomStop_${idx}_B"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_B", stopNode.second.blue, 0f, 1f)
                                                                                                         map["CustomStop_${idx}_A"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_A", stopNode.third, 0f, 1f)
                                                                                                     }
                                                                                                     
                                                                                                     tempTargetedIndex = newSortedIndex
                                                                                                     activeGradientStopIndex = newSortedIndex
                                                                                                     map["SelectedStopIndex"] = com.example.studio.model.EffectParameter("SelectedStopIndex", newSortedIndex.toFloat(), 0f, 10f)
                                                                                                     /*
                                                                                                    // Populate existing custom stops with previewColors if switching preset format
                                                                                                    for (i in previewColors.indices) {
                                                                                                        val col = previewColors[i]
                                                                                                        map["CustomStop_${i}_R"] = com.example.studio.model.EffectParameter("CustomStop_${i}_R", col.red, 0f, 1f)
                                                                                                        map["CustomStop_${i}_G"] = com.example.studio.model.EffectParameter("CustomStop_${i}_G", col.green, 0f, 1f)
                                                                                                        map["CustomStop_${i}_B"] = com.example.studio.model.EffectParameter("CustomStop_${i}_B", col.blue, 0f, 1f)
                                                                                                        map["CustomStop_${i}_Pos"] = com.example.studio.model.EffectParameter("CustomStop_${i}_Pos", i.toFloat() / (previewColors.size - 1).coerceAtLeast(1), 0f, 1f)
                                                                                                    }
                                                                                                    
                                                                                                    map["CustomStop_${stopCount}_Pos"] = com.example.studio.model.EffectParameter("CustomStop_${stopCount}_Pos", tFraction, 0f, 1f)
                                                                                                    map["CustomStop_${stopCount}_R"] = com.example.studio.model.EffectParameter("CustomStop_${stopCount}_R", interpolatedColor.red, 0f, 1f)
                                                                                                    map["CustomStop_${stopCount}_G"] = com.example.studio.model.EffectParameter("CustomStop_${stopCount}_G", interpolatedColor.green, 0f, 1f)
                                                                                                    map["CustomStop_${stopCount}_B"] = com.example.studio.model.EffectParameter("CustomStop_${stopCount}_B", interpolatedColor.blue, 0f, 1f)
                                                                                                    */
                                                                                                    eff.copy(parameters = map)
                                                                                                } else eff
                                                                                            }
                                                                                            layer.copy(effects = updatedEffects)
                                                                                        } else layer
                                                                                    }
                                                                                    dragMode = "gradient_stop"
                                                                                    activeGradientStopIndex = tempTargetedIndex
                                                                                    matchedGradientOption = true
                                                                                    showGradientColorPickerDialog = true
                                                                                }
                                                                            }
                                                                }
                                                            }

                                                            val threshold = 60f / ts.coerceAtLeast(0.3f)
                                                            val thresholdSq = threshold * threshold
                                                            if (matchedGradientOption) {
                                                                // Handled on-canvas gradient selection/stops append
                                                            } else if (distBr < thresholdSq) {
                                                                dragMode = if (gradOverlay == null) "resize" else ""
                                                                isResizingActive = true
                                                                activeResizingLayerId = selId
                                                                startingLayerForResize = currentSelected
                                                                liveDragScaleX = 1.0f
                                                                liveDragScaleY = 1.0f
                                                            } else if (isNearBezier) {
                                                                dragMode = if (gradOverlay == null) "bezier" else ""
                                                            } else {
                                                                dragMode = if (gradOverlay == null) "move" else ""
                                                            }
                                                        } else {
                                                            dragMode = "move"
                                                        }
                                                    }
                                                }
                                            }

                                            if (hasMovedPastSlop) {
                                                val localChangeOffset = screenToCanvas(
                                                    screenPos = position,
                                                    viewportWidth = currentViewportWidthState.value,
                                                    viewportHeight = currentViewportHeightState.value,
                                                    canvasPanX = currentCanvasPanXState.value,
                                                    canvasPanY = currentCanvasPanYState.value,
                                                    canvasRotation = currentCanvasRotationState.value,
                                                    totalScale = ts,
                                                    canvasWidth = currentCanvasWidthState.value,
                                                    canvasHeight = currentCanvasHeightState.value
                                                )
                                                val localChangeX = localChangeOffset.x
                                                val localChangeY = localChangeOffset.y

                                                val localDragOffset = screenDeltaToCanvas(
                                                    delta = diff,
                                                    canvasRotation = currentCanvasRotationState.value,
                                                    totalScale = ts
                                                )
                                                val localDragX = localDragOffset.x
                                                val localDragY = localDragOffset.y

                                                if (tool == "Brush" || tool == "Eraser") {
                                                    var snappedX = localChangeX
                                                    var snappedY = localChangeY
                                                    if (snapToRuler && currentRulersState.value.any { it.enabled }) {
                                                        val snapped = snapPointToRulers(
                                                            px = localChangeX,
                                                            py = localChangeY,
                                                            rulers = currentRulersState.value,
                                                            canvasWidth = currentCanvasWidthState.value,
                                                            canvasHeight = currentCanvasHeightState.value
                                                        )
                                                        snappedX = snapped.x
                                                        snappedY = snapped.y
                                                    }
                                                    val activeMoveL = layers.find { it.id == selectedLayerId }
                                                    val mappedMove = if (activeMoveL != null) canvasToLayerLocal(Offset(snappedX, snappedY), activeMoveL) else Offset(snappedX, snappedY)
                                                    strokeTracker.addPoint(mappedMove.x, mappedMove.y)
                                                    val brushSizeVal = brushSize
                                                    val brushOpacityVal = brushOpacity
                                                    val brushColorVal = brushColor
                                                    val presetVal = brushPresetIndex
                                                    val smoothVal = brushSmoothing
                                                    val currentPointsList = strokeTracker.getPointsList()
                                                    OpenGLBrushRenderer.WetInkRenderer.drawSegments(
                                                        points = currentPointsList,
                                                        color = if (tool == "Eraser") androidx.compose.ui.graphics.Color.Black else brushColorVal,
                                                        size = if (tool == "Eraser") eraserSize else brushSizeVal,
                                                        opacity = if (tool == "Eraser") 1.0f else brushOpacityVal,
                                                        presetIndex = if (tool == "Eraser") 3 else presetVal,
                                                        smoothing = if (tool == "Eraser") true else smoothVal
                                                    )
                                                    strokeDrawTrigger.value++
                                                    pathCache.remove(999999)
                                                    pathCache.remove(1999999)
                                                } else if (tool == "Ruler") {
                                                    val activeId = draggedRulerId ?: currentSelectedRulerIdState.value
                                                    val activeR = currentRulersState.value.find { it.id == activeId }
                                                    if (activeR != null && !activeR.locked && !allRulersLocked) {
                                                        val newPos = if (activeR.orientation == "Horizontal") localChangeY else localChangeX
                                                        rulers = currentRulersState.value.map {
                                                            if (it.id == activeId) it.copy(position = newPos) else it
                                                        }
                                                    }
                                                } else {
                                                    if (dragMode == "resize") {
                                                        val startL = startingLayerForResize
                                                        if (startL != null) {
                                                            val localTouch = canvasToLayerLocal(Offset(localChangeX, localChangeY), startL)
                                                            val pivotX = startL.width / 2f
                                                            val pivotY = startL.height / 2f
                                                            val targetW = 2f * Math.abs(localTouch.x - pivotX)
                                                            val targetH = 2f * Math.abs(localTouch.y - pivotY)
                                                            var scaleX = targetW / startL.width.coerceAtLeast(1f)
                                                            var scaleY = targetH / startL.height.coerceAtLeast(1f)
                                                            
                                                            val minW = 20f
                                                            val minH = 20f
                                                            var scX = scaleX.coerceAtLeast(minW / startL.width.coerceAtLeast(1f))
                                                            var scY = scaleY.coerceAtLeast(minH / startL.height.coerceAtLeast(1f))
                                                            
                                                            if (startL.isAspectLocked) {
                                                                val scale = if (Math.abs(scX - 1f) >= Math.abs(scY - 1f)) scX else scY
                                                                scX = scale
                                                                scY = scale
                                                            }
                                                            
                                                            liveDragScaleX = scX
                                                            liveDragScaleY = scY
                                                        }
                                                    } else if (1 == 2) {
                                                        layers = layers.map { layer ->
                                                            if (layer.id == selId && !layer.isAlphaLocked) {
                                                                val initialW = (localChangeX - layer.positionX).coerceIn(20f, 2000f)
                                                                 val initialH = (localChangeY - layer.positionY).coerceIn(20f, 2000f)
                                                                 val (newW, computedNewH) = if (layer.isAspectLocked) {
                                                                     val ratio = if (layer.height > 0f) layer.width / layer.height else 1f
                                                                     val scaleFromWidth = Math.abs(initialW - layer.width) >= Math.abs(initialH - layer.height)
                                                                     if (scaleFromWidth) {
                                                                         val computedH = (initialW / ratio).coerceIn(20f, 2000f)
                                                                         Pair(computedH * ratio, computedH)
                                                                     } else {
                                                                         val computedW = (initialH * ratio).coerceIn(20f, 2000f)
                                                                         Pair(computedW, computedW / ratio)
                                                                     }
                                                                 } else {
                                                                     Pair(initialW, initialH)
                                                                 }
                                                                val newH = if (layer.isAspectLocked) computedNewH else (localChangeY - layer.positionY).coerceIn(20f, 2000f)
                                                                layer.copy(width = newW, height = newH)
                                                            } else layer
                                                        }
                                                    } else if (dragMode == "gradient_start") {
                                                        val currentSelected = layers.find { it.id == selId }
                                                        if (currentSelected != null) {
                                                            val localTouch = canvasToLayerLocal(localChangeOffset, currentSelected)
                                                            scope.launch(kotlinx.coroutines.Dispatchers.Default) {
                                                                val startRatioX = localTouch.x / currentSelected.width.coerceAtLeast(1f)
                                                                val startRatioY = localTouch.y / currentSelected.height.coerceAtLeast(1f)
                                                                val nextLayers = layers.map { layer ->
                                                                    if (layer.id == selId) {
                                                                        val updatedEffects = layer.effects.map { eff ->
                                                                            if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                val map = eff.parameters.toMutableMap()
                                                                                if (map["EndX"] == null) {
                                                                                    val goScale = (map["Scale"]?.value ?: 100f) / 100f
                                                                                    val goAngle = map["Angle"]?.value ?: 90f
                                                                                    val rads = Math.toRadians(goAngle.toDouble())
                                                                                    val cos = Math.cos(rads).toFloat()
                                                                                    val sin = Math.sin(rads).toFloat()
                                                                                    val defaultEndX = (currentSelected.width / 2f + (currentSelected.width / 2f * cos * goScale)) / currentSelected.width.coerceAtLeast(1f)
                                                                                    val defaultEndY = (currentSelected.height / 2f + (currentSelected.height / 2f * sin * goScale)) / currentSelected.height.coerceAtLeast(1f)
                                                                                    map["EndX"] = com.example.studio.model.EffectParameter("EndX", defaultEndX, 0f, 1f)
                                                                                    map["EndY"] = com.example.studio.model.EffectParameter("EndY", defaultEndY, 0f, 1f)
                                                                                }
                                                                                map["StartX"] = com.example.studio.model.EffectParameter("StartX", startRatioX, 0f, 1f)
                                                                                map["StartY"] = com.example.studio.model.EffectParameter("StartY", startRatioY, 0f, 1f)
                                                                                eff.copy(parameters = map)
                                                                            } else eff
                                                                        }
                                                                        layer.copy(effects = updatedEffects)
                                                                    } else layer
                                                                }
                                                                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                                                    layers = nextLayers
                                                                }
                                                            }
                                                        }
                                                    } else if (dragMode == "gradient_end") {
                                                        val currentSelected = layers.find { it.id == selId }
                                                        if (currentSelected != null) {
                                                            val localTouch = canvasToLayerLocal(localChangeOffset, currentSelected)
                                                            scope.launch(kotlinx.coroutines.Dispatchers.Default) {
                                                                val endRatioX = localTouch.x / currentSelected.width.coerceAtLeast(1f)
                                                                val endRatioY = localTouch.y / currentSelected.height.coerceAtLeast(1f)
                                                                val nextLayers = layers.map { layer ->
                                                                    if (layer.id == selId) {
                                                                        val updatedEffects = layer.effects.map { eff ->
                                                                            if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                val map = eff.parameters.toMutableMap()
                                                                                if (map["StartX"] == null) {
                                                                                    val goScale = (map["Scale"]?.value ?: 100f) / 100f
                                                                                    val goAngle = map["Angle"]?.value ?: 90f
                                                                                    val rads = Math.toRadians(goAngle.toDouble())
                                                                                    val cos = Math.cos(rads).toFloat()
                                                                                    val sin = Math.sin(rads).toFloat()
                                                                                    val defaultStartX = (currentSelected.width / 2f - (currentSelected.width / 2f * cos * goScale)) / currentSelected.width.coerceAtLeast(1f)
                                                                                    val defaultStartY = (currentSelected.height / 2f - (currentSelected.height / 2f * sin * goScale)) / currentSelected.height.coerceAtLeast(1f)
                                                                                    map["StartX"] = com.example.studio.model.EffectParameter("StartX", defaultStartX, 0f, 1f)
                                                                                    map["StartY"] = com.example.studio.model.EffectParameter("StartY", defaultStartY, 0f, 1f)
                                                                                }
                                                                                map["EndX"] = com.example.studio.model.EffectParameter("EndX", endRatioX, 0f, 1f)
                                                                                map["EndY"] = com.example.studio.model.EffectParameter("EndY", endRatioY, 0f, 1f)
                                                                                eff.copy(parameters = map)
                                                                            } else eff
                                                                        }
                                                                        layer.copy(effects = updatedEffects)
                                                                    } else layer
                                                                }
                                                                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                                                    layers = nextLayers
                                                                }
                                                            }
                                                        }
                                                    } else if (dragMode == "gradient_stop") {
                                                        val currentSelected = layers.find { it.id == selId }
                                                        val gradOverlay = currentSelected?.effects?.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                                        if (currentSelected != null && gradOverlay != null) {
                                                            val hasCustomHandles = gradOverlay.parameters["StartX"] != null
                                                            val startX: Float
                                                            val startY: Float
                                                            val endX: Float
                                                            val endY: Float
                                                            if (hasCustomHandles) {
                                                                startX = (gradOverlay.parameters["StartX"]?.value ?: 0f) * currentSelected.width
                                                                startY = (gradOverlay.parameters["StartY"]?.value ?: 0f) * currentSelected.height
                                                                endX = (gradOverlay.parameters["EndX"]?.value ?: 1f) * currentSelected.width
                                                                endY = (gradOverlay.parameters["EndY"]?.value ?: 1f) * currentSelected.height
                                                            } else {
                                                                val goScale = (gradOverlay.parameters["Scale"]?.value ?: 100f) / 100f
                                                                val goAngle = gradOverlay.parameters["Angle"]?.value ?: 90f
                                                                val rads = Math.toRadians(goAngle.toDouble())
                                                                val cos = Math.cos(rads).toFloat()
                                                                val sin = Math.sin(rads).toFloat()
                                                                startX = currentSelected.width / 2f - (currentSelected.width / 2f * cos * goScale)
                                                                startY = currentSelected.height / 2f - (currentSelected.height / 2f * sin * goScale)
                                                                endX = currentSelected.width / 2f + (currentSelected.width / 2f * cos * goScale)
                                                                endY = currentSelected.height / 2f + (currentSelected.height / 2f * sin * goScale)
                                                            }
                                                            
                                                            val localTouch = canvasToLayerLocal(localChangeOffset, currentSelected)
                                                            val ab = Offset(endX - startX, endY - startY)
                                                            val ap = Offset(localTouch.x - startX, localTouch.y - startY)
                                                            val abLenSq = ab.x * ab.x + ab.y * ab.y
                                                            val tFraction = if (abLenSq > 0f) {
                                                                ((ap.x * ab.x + ap.y * ab.y) / abLenSq).coerceIn(0f, 1f)
                                                            } else 0f
                                                             
                                                            layers = layers.map { layer ->
                                                                if (layer.id == selId) {
                                                                    val updatedEffects = layer.effects.map { eff ->
                                                                        if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                            val map = eff.parameters.toMutableMap()
                                                                            map["CustomStop_${activeGradientStopIndex}_Pos"] = com.example.studio.model.EffectParameter("CustomStop_${activeGradientStopIndex}_Pos", tFraction, 0f, 1f)
                                                                            eff.copy(parameters = map)
                                                                        } else eff
                                                                    }
                                                                    layer.copy(effects = updatedEffects)
                                                                } else layer
                                                            }
                                                        }
                                                    } else if (dragMode == "bezier") {
                                                        layers = layers.map { layer ->
                                                            if (layer.id == selId && !layer.isAlphaLocked && layer.type == LayerType.VECTOR_BEZIER) {
                                                                val localCtrl = canvasToLayerLocal(localChangeOffset, layer)
                                                                val updatedPoints = layer.brushPoints.toMutableList()
                                                                val idx = activeBezierPointIndex
                                                                if (idx in updatedPoints.indices) {
                                                                    updatedPoints[idx] = localCtrl
                                                                } else if (updatedPoints.isEmpty()) {
                                                                    updatedPoints.add(localCtrl)
                                                                }
                                                                layer.copy(brushPoints = updatedPoints)
                                                            } else layer
                                                        }
                                                    } else {
                                                        val hasGradOverlay = layers.find { it.id == selId }?.effects?.any { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } ?: false
                                                        if (!hasGradOverlay) {
                                                            layers = layers.map { layer ->
                                                                if (layer.id == selId && !layer.isAlphaLocked) {
                                                                val updatedBrushPoints = if (layer.type == LayerType.VECTOR_BEZIER) {
                                                                    layer.brushPoints
                                                                } else {
                                                                    layer.brushPoints
                                                                }
                                                                                                                                 var localDragX = localDragX
                                                                 var localDragY = localDragY

                                                                 // Calculate temporary unsnapped final positions
                                                                 var locSnapVerticalLine: Float? = null
                                                                 var locSnapHorizontalLine: Float? = null
                                                                 var locSnapIndicatorMsg: String? = null
                                                                 var matchedXVal: Float? = null
                                                                 var matchedXLabel: String? = null
                                                                 var matchedYVal: Float? = null
                                                                 var matchedYLabel: String? = null
                                                                 var tempFinalX = layer.positionX + localDragX
                                                                 var tempFinalY = layer.positionY + localDragY

                                                                 val snapThreshold = 30f // pixels in canvas space
                                                                 val canvasW = currentCanvasWidthState.value
                                                                 val canvasH = currentCanvasHeightState.value

                                                                 val activeGridEnabled = currentGridEnabledState.value
                                                                 val activeGridColumns = currentGridColumnsState.value
                                                                 val activeGridRows = currentGridRowsState.value
                                                                 val activeRulerEnabled = currentRulerEnabledState.value
                                                                 val activeRulerOrientation = currentRulerOrientationState.value
                                                                 val activeRulerPosition = currentRulerPositionState.value
                                                                 val activeRulerAngle = currentRulerAngleState.value
                                                                 val activeSnapToRuler = currentSnapToRulerState.value

                                                                 // 1. Grid Snapping
                                                                 if (activeGridEnabled) {
                                                                     val cols = activeGridColumns.coerceIn(1, 200)
                                                                     val rows = activeGridRows.coerceIn(1, 200)
                                                                     val colWidth = canvasW / cols
                                                                     val rowHeight = canvasH / rows

                                                                     var closestGridX = Float.MAX_VALUE
                                                                     var bestSnappedX = tempFinalX
                                                                     for (i in 0..cols) {
                                                                         val gridLineX = i * colWidth
                                                                         val dLeft = Math.abs(tempFinalX - gridLineX)
                                                                         if (dLeft < snapThreshold && dLeft < closestGridX) {
                                                                             closestGridX = dLeft
                                                                             bestSnappedX = gridLineX
                                                                         }
                                                                         val dRight = Math.abs((tempFinalX + layer.width) - gridLineX)
                                                                         if (dRight < snapThreshold && dRight < closestGridX) {
                                                                             closestGridX = dRight
                                                                             bestSnappedX = gridLineX - layer.width
                                                                         }
                                                                         val dMid = Math.abs((tempFinalX + layer.width / 2f) - gridLineX)
                                                                         if (dMid < snapThreshold && dMid < closestGridX) {
                                                                             closestGridX = dMid
                                                                             bestSnappedX = gridLineX - layer.width / 2f
                                                                         }
                                                                     }
                                                                     if (closestGridX < snapThreshold) {
                                                                         tempFinalX = bestSnappedX
                                                                         val possibleLineL = Math.round(bestSnappedX / colWidth) * colWidth
                                                                          val possibleLineR = Math.round((bestSnappedX + layer.width) / colWidth) * colWidth
                                                                          val possibleLineM = Math.round((bestSnappedX + layer.width / 2f) / colWidth) * colWidth
                                                                          locSnapVerticalLine = when {
                                                                              Math.abs(bestSnappedX - possibleLineL) < 1f -> possibleLineL
                                                                              Math.abs((bestSnappedX + layer.width) - possibleLineR) < 1f -> possibleLineR
                                                                              else -> possibleLineM
                                                                          }
                                                                         locSnapIndicatorMsg = "Snapped to Grid X"
                                                                     }

                                                                     var closestGridY = Float.MAX_VALUE
                                                                     var bestSnappedY = tempFinalY
                                                                     for (j in 0..rows) {
                                                                         val gridLineY = j * rowHeight
                                                                         val dTop = Math.abs(tempFinalY - gridLineY)
                                                                         if (dTop < snapThreshold && dTop < closestGridY) {
                                                                             closestGridY = dTop
                                                                             bestSnappedY = gridLineY
                                                                         }
                                                                         val dBot = Math.abs((tempFinalY + layer.height) - gridLineY)
                                                                         if (dBot < snapThreshold && dBot < closestGridY) {
                                                                             closestGridY = dBot
                                                                             bestSnappedY = gridLineY - layer.height
                                                                         }
                                                                         val dMidY = Math.abs((tempFinalY + layer.height / 2f) - gridLineY)
                                                                         if (dMidY < snapThreshold && dMidY < closestGridY) {
                                                                             closestGridY = dMidY
                                                                             bestSnappedY = gridLineY - layer.height / 2f
                                                                         }
                                                                     }
                                                                     if (closestGridY < snapThreshold) {
                                                                         tempFinalY = bestSnappedY
                                                                         val possibleLineT = Math.round(bestSnappedY / rowHeight) * rowHeight
                                                                          val possibleLineB = Math.round((bestSnappedY + layer.height) / rowHeight) * rowHeight
                                                                          val possibleLineM = Math.round((bestSnappedY + layer.height / 2f) / rowHeight) * rowHeight
                                                                          locSnapHorizontalLine = when {
                                                                              Math.abs(bestSnappedY - possibleLineT) < 1f -> possibleLineT
                                                                              Math.abs((bestSnappedY + layer.height) - possibleLineB) < 1f -> possibleLineB
                                                                              else -> possibleLineM
                                                                          }
                                                                         locSnapIndicatorMsg = if (locSnapVerticalLine != null) "Snapped to Grid Intersection" else "Snapped to Grid Y"
                                                                     }
                                                                 }

                                                                 // 2. Center Snapping && Axis Snapping && Sides Snapping
                                                                 if (!activeGridEnabled) {
                                                                     val canvasMinX = 0f
                                                                     val canvasMaxX = canvasW
                                                                     val canvasMinY = 0f
                                                                     val canvasMaxY = canvasH
                                                                     val canvasCenterX = canvasW / 2f
                                                                     val canvasCenterY = canvasH / 2f

                                                                     val objCenterX = tempFinalX + layer.width / 2f
                                                                     val objCenterY = tempFinalY + layer.height / 2f

                                                                     var bestSnappedX = tempFinalX
                                                                     var closestXDist = Float.MAX_VALUE

                                                                     val dMidX = Math.abs(objCenterX - canvasCenterX)
                                                                     if (dMidX < snapThreshold && dMidX < closestXDist) {
                                                                         closestXDist = dMidX
                                                                         bestSnappedX = canvasCenterX - layer.width / 2f
                                                                         matchedXVal = canvasCenterX
                                                                         matchedXLabel = "Canvas Center"
                                                                     }
                                                                     val dLeft = Math.abs(tempFinalX - canvasMinX)
                                                                     if (dLeft < snapThreshold && dLeft < closestXDist) {
                                                                         closestXDist = dLeft
                                                                         bestSnappedX = canvasMinX
                                                                         matchedXVal = canvasMinX
                                                                         matchedXLabel = "Left Edge"
                                                                     }
                                                                     val dRight = Math.abs((tempFinalX + layer.width) - canvasMaxX)
                                                                     if (dRight < snapThreshold && dRight < closestXDist) {
                                                                         closestXDist = dRight
                                                                         bestSnappedX = canvasMaxX - layer.width
                                                                         matchedXVal = canvasMaxX
                                                                         matchedXLabel = "Right Edge"
                                                                     }

                                                                     if (closestXDist < snapThreshold) {
                                                                         tempFinalX = bestSnappedX
                                                                         locSnapVerticalLine = matchedXVal
                                                                         locSnapIndicatorMsg = "Snapped to $matchedXLabel"
                                                                     }

                                                                     var bestSnappedY = tempFinalY
                                                                     var closestYDist = Float.MAX_VALUE

                                                                     val dMidY = Math.abs(objCenterY - canvasCenterY)
                                                                     if (dMidY < snapThreshold && dMidY < closestYDist) {
                                                                         closestYDist = dMidY
                                                                         bestSnappedY = canvasCenterY - layer.height / 2f
                                                                         matchedYVal = canvasCenterY
                                                                         matchedYLabel = "Canvas Center"
                                                                     }
                                                                     val dTop = Math.abs(tempFinalY - canvasMinY)
                                                                     if (dTop < snapThreshold && dTop < closestYDist) {
                                                                         closestYDist = dTop
                                                                         bestSnappedY = canvasMinY
                                                                         matchedYVal = canvasMinY
                                                                         matchedYLabel = "Top Edge"
                                                                     }
                                                                     val dBot = Math.abs((tempFinalY + layer.height) - canvasMaxY)
                                                                     if (dBot < snapThreshold && dBot < closestYDist) {
                                                                         closestYDist = dBot
                                                                         bestSnappedY = canvasMaxY - layer.height
                                                                         matchedYVal = canvasMaxY
                                                                         matchedYLabel = "Bottom Edge"
                                                                     }

                                                                     if (closestYDist < snapThreshold) {
                                                                         tempFinalY = bestSnappedY
                                                                         locSnapHorizontalLine = matchedYVal
                                                                         if (matchedXVal != null) {
                                                                             locSnapIndicatorMsg = "Snapped to Intersection ($matchedXLabel & $matchedYLabel)"
                                                                         } else {
                                                                             locSnapIndicatorMsg = "Snapped to $matchedYLabel"
                                                                         }
                                                                     }
                                                                 }

                                                                 // 3. Ruler Snapping on proximity (Multi-Guideline Magnetic Snapping)
                                                                 if (activeRulerEnabled && activeSnapToRuler) {
                                                                     val proxThreshold = 25f // Threshold for 5dp to 10dp approximation in canvas coordinates
                                                                     var bestSnappedRulerX = tempFinalX
                                                                     var closestRulerXDist = Float.MAX_VALUE
                                                                     var matchedRulerXVal: Float? = null
                                                                     var didSnapRulerX = false

                                                                     var bestSnappedRulerY = tempFinalY
                                                                     var closestRulerYDist = Float.MAX_VALUE
                                                                     var matchedRulerYVal: Float? = null
                                                                     var didSnapRulerY = false

                                                                     for (ruler in currentRulersState.value) {
                                                                         if (!ruler.enabled) continue

                                                                         if (ruler.orientation == "Vertical") {
                                                                             val lLeft = tempFinalX
                                                                             val lRight = tempFinalX + layer.width
                                                                             val lCenter = tempFinalX + layer.width / 2f

                                                                             val dLeft = Math.abs(lLeft - ruler.position)
                                                                             if (dLeft < proxThreshold && dLeft < closestRulerXDist) {
                                                                                 closestRulerXDist = dLeft
                                                                                 bestSnappedRulerX = ruler.position
                                                                                 matchedRulerXVal = ruler.position
                                                                                 didSnapRulerX = true
                                                                             }

                                                                             val dRight = Math.abs(lRight - ruler.position)
                                                                             if (dRight < proxThreshold && dRight < closestRulerXDist) {
                                                                                 closestRulerXDist = dRight
                                                                                 bestSnappedRulerX = ruler.position - layer.width
                                                                                 matchedRulerXVal = ruler.position
                                                                                 didSnapRulerX = true
                                                                             }

                                                                             val dCent = Math.abs(lCenter - ruler.position)
                                                                             if (dCent < proxThreshold && dCent < closestRulerXDist) {
                                                                                 closestRulerXDist = dCent
                                                                                 bestSnappedRulerX = ruler.position - layer.width / 2f
                                                                                 matchedRulerXVal = ruler.position
                                                                                 didSnapRulerX = true
                                                                             }
                                                                         } else {
                                                                             val lTop = tempFinalY
                                                                             val lBottom = tempFinalY + layer.height
                                                                             val lCenterY = tempFinalY + layer.height / 2f

                                                                             val dTop = Math.abs(lTop - ruler.position)
                                                                             if (dTop < proxThreshold && dTop < closestRulerYDist) {
                                                                                 closestRulerYDist = dTop
                                                                                 bestSnappedRulerY = ruler.position
                                                                                 matchedRulerYVal = ruler.position
                                                                                 didSnapRulerY = true
                                                                             }

                                                                             val dBot = Math.abs(lBottom - ruler.position)
                                                                             if (dBot < proxThreshold && dBot < closestRulerYDist) {
                                                                                 closestRulerYDist = dBot
                                                                                 bestSnappedRulerY = ruler.position - layer.height
                                                                                 matchedRulerYVal = ruler.position
                                                                                 didSnapRulerY = true
                                                                             }

                                                                             val dCentY = Math.abs(lCenterY - ruler.position)
                                                                             if (dCentY < proxThreshold && dCentY < closestRulerYDist) {
                                                                                 closestRulerYDist = dCentY
                                                                                 bestSnappedRulerY = ruler.position - layer.height / 2f
                                                                                 matchedRulerYVal = ruler.position
                                                                                 didSnapRulerY = true
                                                                             }
                                                                         }
                                                                     }

                                                                     if (didSnapRulerX) {
                                                                         tempFinalX = bestSnappedRulerX
                                                                         locSnapVerticalLine = matchedRulerXVal
                                                                     }
                                                                     if (didSnapRulerY) {
                                                                         tempFinalY = bestSnappedRulerY
                                                                         locSnapHorizontalLine = matchedRulerYVal
                                                                     }

                                                                     if (didSnapRulerX || didSnapRulerY) {
                                                                         locSnapIndicatorMsg = when {
                                                                             didSnapRulerX && didSnapRulerY -> "Snapped to Guidelines Intersection"
                                                                             didSnapRulerX -> "Snapped to Vertical Guideline"
                                                                             else -> "Snapped to Horizontal Guideline"
                                                                         }
                                                                     }
                                                                 }

                                                                 // Overwrite shadowed local delta deltas with correct snapped values
                                                                 localDragX = tempFinalX - layer.positionX
                                                                 localDragY = tempFinalY - layer.positionY

                                                                 // Shadow original ruler snapping block variables so it is bypassed
                                                                 val rulerEnabled = false
                                                                 val snapToRuler = false

                                                                 // Define the real var finalX using the snapped localDragX offset
                                                                 var finalX = layer.positionX + localDragX
                                                                var finalY = layer.positionY + localDragY
                                                                if (rulerEnabled && snapToRuler) {
                                                                    val angleRad = (rulerAngle * Math.PI / 180.0)
                                                                    val dX: Float
                                                                    val dY: Float
                                                                    val aX: Float
                                                                    val aY: Float
                                                                    if (rulerOrientation == "Horizontal") {
                                                                        dX = Math.cos(angleRad).toFloat()
                                                                        dY = Math.sin(angleRad).toFloat()
                                                                        aX = 0f
                                                                        aY = rulerPosition
                                                                    } else {
                                                                        dX = -Math.sin(angleRad).toFloat()
                                                                        dY = Math.cos(angleRad).toFloat()
                                                                        aX = rulerPosition
                                                                        aY = 0f
                                                                    }
                                                                    val lCenterX = finalX + layer.width / 2f
                                                                    val lCenterY = finalY + layer.height / 2f
                                                                    val tCent = (lCenterX - aX) * dX + (lCenterY - aY) * dY
                                                                    val snappedCenterX = aX + tCent * dX
                                                                    val snappedCenterY = aY + tCent * dY
                                                                    finalX += (snappedCenterX - lCenterX)
                                                                    finalY += (snappedCenterY - lCenterY)
                                                                }
                                                                snapVerticalLine = locSnapVerticalLine
                                                                snapHorizontalLine = locSnapHorizontalLine
                                                                snapIndicatorMsg = locSnapIndicatorMsg
                                                                layer.copy(
                                                                    positionX = finalX,
                                                                    positionY = finalY,
                                                                    brushPoints = updatedBrushPoints
                                                                )
                                                            } else layer
                                                        }
                                                        }
                                                    }
                                                }
                                                pointer.consume()
                                            }
                                        }
                                    } while (event.changes.any { it.pressed })

                                    // Gesture over: finalize actions
                                    if (isResizingActive && activeResizingLayerId != null && startingLayerForResize != null) {
                                        val targetId = activeResizingLayerId
                                        val startL = startingLayerForResize
                                        val finalDragScaleXSnapshot = liveDragScaleX
                                        val finalDragScaleYSnapshot = liveDragScaleY
                                        if (targetId != null && startL != null) {
                                            undoStack.add(layers)
                                            redoStack.clear()
                                            layers = layers.map { layer ->
                                                if (layer.id == targetId) {
                                                    val newW = (startL.width * finalDragScaleXSnapshot).coerceIn(20f, 2000f)
                                                    val newH = (startL.height * finalDragScaleYSnapshot).coerceIn(20f, 2000f)
                                                    val newX = startL.positionX + (startL.width - newW) / 2f
                                                    val newY = startL.positionY + (startL.height - newH) / 2f
                                                    layer.copy(
                                                        width = newW,
                                                        height = newH,
                                                        positionX = newX,
                                                        positionY = newY
                                                    )
                                                } else layer
                                            }
                                        }
                                    }
                                    isResizingActive = false
                                    activeResizingLayerId = null
                                    startingLayerForResize = null
                                    liveDragScaleX = 1.0f
                                    liveDragScaleY = 1.0f

                                    snapVerticalLine = null
                                    snapHorizontalLine = null
                                    snapIndicatorMsg = null
                                    if (!isTransforming) {
                                        activeBezierPointIndex = -1
                                        dragMode = null
                                        if (hasMovedPastSlop) {
                                            if ((tool == "Brush" || tool == "Eraser") && strokeTracker.pointCount > 0) {
                                                val targetId = selectedLayerId
                                                if (targetId.isNotEmpty()) {
                                                    undoStack.add(layers)
                                                    redoStack.clear()
                                                    val strokePointsList = strokeTracker.getPointsList()
                                                    val strokeToCommitHeader = if (tool == "Eraser") {
                                                        buildStrokeHeaderPoints(
                                                            isEraser = true,
                                                            presetIndex = 3,
                                                            size = eraserSize,
                                                            opacity = 1.0f,
                                                            smoothing = true,
                                                            hardness = eraserHardness
                                                        )
                                                    } else {
                                                        buildStrokeHeaderPoints(
                                                            isEraser = false,
                                                            presetIndex = brushPresetIndex,
                                                            size = brushSize,
                                                            opacity = brushOpacity,
                                                            smoothing = brushSmoothing,
                                                            hardness = 0.5f,
                                                            color = brushColor
                                                        )
                                                    }
                                                    layers = layers.map { layer ->
                                                        val isEligible = if (tool == "Eraser") {
                                                            layer.id == targetId && layer.type != LayerType.VECTOR_BEZIER
                                                        } else {
                                                            layer.id == targetId && layer.type == LayerType.FREEHAND_DRAWING
                                                        }
                                                        if (isEligible) {
                                                            pathCache.remove(layer.id.hashCode())
                                                            pathCache.remove(layer.id.hashCode() + 1000000)
                                                            val mappedPoints = strokePointsList
                                                            val strokeToCommitWrapped = strokeToCommitHeader + mappedPoints
                                                            val strokeToCommitDummy = buildStrokeHeaderPoints(
                                                                isEraser = (tool == "Eraser"),
                                                                presetIndex = brushPresetIndex,
                                                                size = brushSize,
                                                                opacity = brushOpacity,
                                                                smoothing = brushSmoothing
                                                             ) + strokePointsList
                                                            val updatedPoints = if (layer.brushPoints.isNotEmpty()) {
                                                                layer.brushPoints + androidx.compose.ui.geometry.Offset.Unspecified + strokeToCommitWrapped
                                                            } else {
                                                                strokeToCommitWrapped
                                                            }
                                                            layer.copy(brushPoints = updatedPoints)
                                                        } else layer
                                                    }
                                                }
                                                strokeTracker.clear()
                                                OpenGLBrushRenderer.WetInkRenderer.clear()
                                                pathCache.remove(999999)
                                                pathCache.remove(1999999)
                                            }
                                        } else {
                                            // Handle Tap Selection
                                            val tapOffset = down.position
                                            val localOffset = screenToCanvas(
                                                screenPos = tapOffset,
                                                viewportWidth = currentViewportWidthState.value,
                                                viewportHeight = currentViewportHeightState.value,
                                                canvasPanX = currentCanvasPanXState.value,
                                                canvasPanY = currentCanvasPanYState.value,
                                                canvasRotation = currentCanvasRotationState.value,
                                                totalScale = ts,
                                                canvasWidth = currentCanvasWidthState.value,
                                                canvasHeight = currentCanvasHeightState.value
                                            )
                                            val localX = localOffset.x
                                            val localY = localOffset.y

                                            if (tool == "Pen") {
                                                val clickPt = localOffset
                                                val currentSelected = lyrs.find { it.id == selectedLayerId }
                                                if (currentSelected != null && currentSelected.type == LayerType.VECTOR_BEZIER) {
                                                    val clickLocal = canvasToLayerLocal(clickPt, currentSelected)
                                                    val updatedPoints = currentSelected.brushPoints + clickLocal + clickLocal + clickLocal
                                                    undoStack.add(layers)
                                                    redoStack.clear()
                                                    layers = layers.map {
                                                        if (it.id == currentSelected.id) {
                                                            it.copy(brushPoints = updatedPoints)
                                                        } else it
                                                    }
                                                    pathCache.clear()
                                                } else {
                                                    val newL = StudioLayer(
                                                        name = "Pen Vector Path ${lyrs.filter { it.type == LayerType.VECTOR_BEZIER }.size + 1}",
                                                        type = LayerType.VECTOR_BEZIER,
                                                        positionX = 0f,
                                                        positionY = 0f,
                                                        width = currentCanvasWidthState.value,
                                                        height = currentCanvasHeightState.value,
                                                        baseColor = brushColor,
                                                        brushPoints = listOf(clickPt, clickPt, clickPt)
                                                     )
                                                     undoStack.add(layers)
                                                     redoStack.clear()
                                                     layers = listOf(newL) + layers
                                                     selectedLayerId = newL.id
                                                     pathCache.clear()
                                                 }
                                             } else {
                                                 val clicked = lyrs.find { layer ->
                                                     layer.isVisible && !layer.isAlphaLocked &&
                                                     layer.type != com.example.studio.model.LayerType.FREEHAND_DRAWING &&
                                                     localX >= layer.positionX &&
                                                     localX <= (layer.positionX + layer.width) &&
                                                     localY >= layer.positionY &&
                                                     localY <= (layer.positionY + layer.height)
                                                 }
                                                 if (clicked != null) {
                                                     selectedLayerId = clicked.id
                                                 }
                                             }
                                        }
                                    }
                                }
                            }
                    ) {
                        try {
                            if (pathCache.size() > 1024) {
                                // Smart selective trim: only garbage-collect old path hashes that aren't in current layers
                                val activeHashes = layers.map { getLayerGeometryHash(it) }.toSet()
                                val gridCacheKey = -9999 xor (canvasWidth.toInt() shl 16) xor canvasHeight.toInt()
                                val keysToRemove = mutableListOf<Int>()
                                for (i in 0 until pathCache.size()) {
                                    val key = pathCache.keyAt(i)
                                    if (key != gridCacheKey && key !in activeHashes && key != 999999 && key != 1999999) {
                                        keysToRemove.add(key)
                                    }
                                }
                                for (key in keysToRemove) {
                                    pathCache.remove(key)
                                }
                                if (pathCache.size() > 1024) {
                                    pathCache.clear()
                                }
                            }

                            val ts = currentTotalScaleState.value
                            // Non-destructive rendering pipeline passes
                            withTransform({
                                translate(left = currentViewportWidthState.value / 2f + currentCanvasPanXState.value, top = currentViewportHeightState.value / 2f + currentCanvasPanYState.value)
                                rotate(degrees = currentCanvasRotationState.value, pivot = Offset.Zero)
                                scale(scaleX = ts, scaleY = ts, pivot = Offset.Zero)
                                translate(left = -currentCanvasWidthState.value / 2f, top = -currentCanvasHeightState.value / 2f)
                                clipRect(left = 0f, top = 0f, right = currentCanvasWidthState.value, bottom = currentCanvasHeightState.value)
                            }) {
                                // 1. Solid backdrop fill for canvas limits
                                drawRect(
                                    color = Color.White,
                                    topLeft = Offset.Zero,
                                    size = Size(canvasWidth, canvasHeight)
                                )

                                // 2. Gorgeous, zero-lag, ultra-modern blueprint grid compiled into a single GPU call
                                val gridCacheKey = -9999 xor (canvasWidth.toInt() shl 16) xor canvasHeight.toInt()
                                var gridPath = pathCache.get(gridCacheKey)
                                if (gridPath == null) {
                                    val newPath = Path()
                                    val gridSpacing = 100f
                                    var gy = gridSpacing
                                    while (gy < canvasHeight) {
                                        newPath.moveTo(0f, gy)
                                        newPath.lineTo(canvasWidth, gy)
                                        gy += gridSpacing
                                    }
                                    var gx = gridSpacing
                                    while (gx < canvasWidth) {
                                        newPath.moveTo(gx, 0f)
                                        newPath.lineTo(gx, canvasHeight)
                                        gx += gridSpacing
                                    }
                                    gridPath = newPath
                                    pathCache.put(gridCacheKey, newPath)
                                }
                                drawPath(
                                    path = gridPath,
                                    color = Color(0xFFE5E5EA),
                                    style = Stroke(width = 1f)
                                )

                                // 3. Canvas boundary outline border
                                drawRect(
                                    color = Color(0xFF1E1E24),
                                    topLeft = Offset.Zero,
                                    size = Size(canvasWidth, canvasHeight),
                                    style = Stroke(width = 2.5f)
                                )

                                for (index in layers.indices.reversed()) {
                                    val originalLayer = layers[index]
                                    if (!originalLayer.isVisible) continue

                                    val isVisibleOnScreen = com.example.studio.ui.isLayerVisibleInViewport(
                                        layer = originalLayer,
                                        viewportWidth = currentViewportWidthState.value,
                                        viewportHeight = currentViewportHeightState.value,
                                        panX = currentCanvasPanXState.value,
                                        panY = currentCanvasPanYState.value,
                                        scale = ts,
                                        canvasWidth = currentCanvasWidthState.value,
                                        canvasHeight = currentCanvasHeightState.value
                                    )
                                    if (!isVisibleOnScreen) continue
                                    val layerOpacity = originalLayer.opacity
                                    val composeBlendMode = originalLayer.blendMode.toComposeBlendMode()

                                    // Non-destructive shadow copy applying dynamic adjustment color FX
                                    val layer = originalLayer

                                    val beneathLayer = if (index + 1 < layers.size) layers[index + 1] else null

                                                                         val clippedLayers = mutableListOf<com.example.studio.model.StudioLayer>()
                                     for (i in (index - 1) downTo 0) {
                                         if (i >= 0 && i < layers.size) {
                                             val prospect = layers[i]
                                             if (!prospect.isVisible) continue
                                             if (prospect.isClippingMask) {
                                                 clippedLayers.add(prospect)
                                             } else {
                                                 break
                                             }
                                         }
                                     }
                                     if (originalLayer.isClippingMask) continue
                                     var rootBaseLayer: com.example.studio.model.StudioLayer? = null
                                    if (layer.isClippingMask) {
                                        for (i in (index + 1) until layers.size) {
                                            val prospect = layers[i]
                                            if (prospect.isVisible) {
                                                if (!prospect.isClippingMask) {
                                                    rootBaseLayer = prospect
                                                    break
                                                }
                                            }
                                        }
                                    }

                                    val drawLayerWithTransforms = {
                                        var twirlFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
                                        var pinchFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
                                        var sphereFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
                                        for (effect in layer.effects) {
                                            if (!effect.isEnabled) continue
                                            if (effect is com.example.studio.model.StudioEffect.PhotoshopEffect) {
                                                when (effect.effectType) {
                                                    "Twirl" -> twirlFil = effect
                                                    "Pinch" -> pinchFil = effect
                                                    "Spherize" -> sphereFil = effect
                                                }
                                            }
                                        }

                                        val additionalTwirl = twirlFil?.let { (it.parameters["Angle"]?.value ?: 100f) * 0.12f } ?: 0f
                                        val additionalScale = (pinchFil?.let { 1f + (it.parameters["Amount"]?.value ?: 50f) / 100f * 0.15f } ?: 1f) *
                                                              (sphereFil?.let { 1f + (it.parameters["Amount"]?.value ?: 100f) / 100f * 0.20f } ?: 1f)

                                        withTransform({
                                            translate(left = layer.positionX, top = layer.positionY)
                                        }) {
                                            val centerX = layer.width * layer.pivotX
                                            val centerY = layer.height * layer.pivotY

                                            val nativeMatrix = CanvasMatrixHolder.transformMatrix.apply {
                                                reset()
                                                // 1. Move pivot center to local origin (0, 0)
                                                preTranslate(-centerX, -centerY)

                                                val vals = CanvasMatrixHolder.matrixValues
                                                getValues(vals)
                                                vals[android.graphics.Matrix.MSKEW_X] = layer.skewX
                                                vals[android.graphics.Matrix.MSKEW_Y] = layer.skewY
                                                vals[6] = layer.perspX // MPERSP_0 control point
                                                vals[7] = layer.perspY // MPERSP_1 control point
                                                setValues(vals)

                                                // 3. Move coordinate framework back to position
                                                postTranslate(centerX, centerY)

                                                // 4. Apply scale and rotation around center pivot
                                                postScale(layer.scaleX * additionalScale, layer.scaleY * additionalScale, centerX, centerY)
                                                postRotate(layer.rotation + additionalTwirl, centerX, centerY)
                                            }
                                            drawContext.canvas.nativeCanvas.concat(nativeMatrix)
                                            if (false) {
                                                val matrix = sharedTransformMatrix.apply {
                                                reset()
                                                val centerX = layer.width * layer.pivotX
                                                val centerY = layer.height * layer.pivotY
                                                
                                                translate(centerX, centerY)
                                                
                                                val sx = layer.skewX
                                                val sy = layer.skewY
                                                val px = layer.perspX
                                                val py = layer.perspY
                                                
                                                if (sx != 0f || sy != 0f || px != 0f || py != 0f) {
                                                    val skewPersp = androidx.compose.ui.graphics.Matrix().apply {
                                                        reset()
                                                        if (sx != 0f) {
                                                            values[4] = sx
                                                        }
                                                        if (sy != 0f) {
                                                            values[1] = sy
                                                        }
                                                        if (px != 0f) {
                                                            values[3] = px
                                                        }
                                                        if (py != 0f) {
                                                            values[7] = py
                                                        }
                                                    }
                                                    timesAssign(skewPersp)
                                                }
                                                
                                                rotateZ(layer.rotation + additionalTwirl)
                                                scale(layer.scaleX * additionalScale, layer.scaleY * additionalScale, 1f)
                                                translate(-centerX, -centerY)
                                            }
                                            drawContext.canvas.concat(matrix)
                                            }
                                            drawAllEffectsAndLayersLocal(
                                                layer = layer,
                                                layerOpacity = layerOpacity,
                                                selectedLayerId = selectedLayerId,
                                                pathCache = pathCache,
                                                pathPointsCountCache = pathPointsCountCache,
                                                totalScale = totalScale,
                                                dashEffect = dashEffect8, imageBitmapCache = imageBitmapCache,
                                                composeBlendMode = composeBlendMode,
                                                activeTool = activeTool
                                             )
                                         }
                                     }

                                     val oldDrawLayerWithTransformsDummy = {
                                        withTransform({
                                            translate(left = layer.positionX, top = layer.positionY)
                                            rotate(degrees = layer.rotation, pivot = Offset(layer.width * layer.pivotX, layer.height * layer.pivotY))
                                            scale(scaleX = layer.scaleX, scaleY = layer.scaleY, pivot = Offset(layer.width * layer.pivotX, layer.height * layer.pivotY))
                                        }) {
                                        // Draw layer basis in local coordinates
                                        when (layer.type) {
                                            LayerType.VECTOR_RECT -> {
                                                // Gaussian blur effect visual simulator: overlapping soft draw states
                                                val blurRadius = getBlurRadius(layer)
                                                if (blurRadius > 0f) {
                                                    for (o in 1..4) {
                                                        drawRect(
                                                            color = layer.baseColor.copy(alpha = layerOpacity * 0.18f),
                                                            topLeft = Offset(-o * blurRadius * 0.4f, -o * blurRadius * 0.4f),
                                                            size = Size(layer.width + o * blurRadius * 0.8f, layer.height + o * blurRadius * 0.8f),
                                                            blendMode = composeBlendMode
                                                        )
                                                    }
                                                }

                                                drawRect(
                                                    color = layer.baseColor.copy(alpha = layerOpacity),
                                                    topLeft = Offset.Zero,
                                                    size = Size(layer.width, layer.height),
                                                    blendMode = composeBlendMode
                                                )

                                                // Inner Glow effect visual simulator
                                                val glowIntensity = getGlowIntensity(layer)
                                                if (glowIntensity > 0f) {
                                                    drawRect(
                                                        color = Color(0xFFFF9800).copy(alpha = layerOpacity * 0.5f),
                                                        topLeft = Offset.Zero,
                                                        size = Size(layer.width, layer.height),
                                                        style = Stroke(width = glowIntensity * 0.5f)
                                                    )
                                                }
                                            }
                                            
                                            LayerType.VECTOR_TRIANGLE -> {
                                                val cacheKey = getLayerGeometryHash(layer)
                                                var path = pathCache.get(cacheKey)
                                                if (path == null) {
                                                    val newPath = Path().apply {
                                                        moveTo(layer.width / 2f, 0f)
                                                        lineTo(layer.width, layer.height)
                                                        lineTo(0f, layer.height)
                                                        close()
                                                    }
                                                    pathCache.put(cacheKey, newPath)
                                                    path = newPath
                                                }
                                                val blurRadius = getBlurRadius(layer)
                                                if (blurRadius > 0f) {
                                                    for (o in 1..4) {
                                                        drawPath(
                                                            path = path,
                                                            color = layer.baseColor.copy(alpha = layerOpacity * 0.12f),
                                                            style = Stroke(width = o * blurRadius),
                                                            blendMode = composeBlendMode
                                                        )
                                                    }
                                                }
                                                drawPath(
                                                    path = path,
                                                    color = layer.baseColor.copy(alpha = layerOpacity),
                                                    blendMode = composeBlendMode
                                                )
                                            }
 
                                            LayerType.VECTOR_PENTAGON -> {
                                                val cacheKey = getLayerGeometryHash(layer)
                                                var path = pathCache.get(cacheKey)
                                                if (path == null) {
                                                    val newPath = Path().apply {
                                                        val cx = layer.width / 2f
                                                        val cy = layer.height / 2f
                                                        val rx = layer.width / 2f
                                                        val ry = layer.height / 2f
                                                        for (i in 0 until 5) {
                                                            val angle = Math.toRadians((i * 72 - 90).toDouble())
                                                            val x = (cx + rx * Math.cos(angle)).toFloat()
                                                            val y = (cy + ry * Math.sin(angle)).toFloat()
                                                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                                                        }
                                                        close()
                                                    }
                                                    pathCache.put(cacheKey, newPath)
                                                    path = newPath
                                                }
                                                val blurRadius = getBlurRadius(layer)
                                                if (blurRadius > 0f) {
                                                    for (o in 1..4) {
                                                        drawPath(
                                                            path = path,
                                                            color = layer.baseColor.copy(alpha = layerOpacity * 0.12f),
                                                            style = Stroke(width = o * blurRadius),
                                                            blendMode = composeBlendMode
                                                        )
                                                    }
                                                }
                                                drawPath(
                                                    path = path,
                                                    color = layer.baseColor.copy(alpha = layerOpacity),
                                                    blendMode = composeBlendMode
                                                )
                                            }
 
                                            LayerType.VECTOR_HEXAGON -> {
                                                val cacheKey = getLayerGeometryHash(layer)
                                                var path = pathCache.get(cacheKey)
                                                if (path == null) {
                                                    val newPath = Path().apply {
                                                        val cx = layer.width / 2f
                                                        val cy = layer.height / 2f
                                                        val rx = layer.width / 2f
                                                        val ry = layer.height / 2f
                                                        for (i in 0 until 6) {
                                                            val angle = Math.toRadians((i * 60 - 90).toDouble())
                                                            val x = (cx + rx * Math.cos(angle)).toFloat()
                                                            val y = (cy + ry * Math.sin(angle)).toFloat()
                                                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                                                        }
                                                        close()
                                                    }
                                                    pathCache.put(cacheKey, newPath)
                                                    path = newPath
                                                }
                                                val blurRadius = getBlurRadius(layer)
                                                if (blurRadius > 0f) {
                                                    for (o in 1..4) {
                                                        drawPath(
                                                            path = path,
                                                            color = layer.baseColor.copy(alpha = layerOpacity * 0.12f),
                                                            style = Stroke(width = o * blurRadius),
                                                            blendMode = composeBlendMode
                                                        )
                                                    }
                                                }
                                                drawPath(
                                                    path = path,
                                                    color = layer.baseColor.copy(alpha = layerOpacity),
                                                    blendMode = composeBlendMode
                                                )
                                            }
 
                                            LayerType.VECTOR_OVAL -> {
                                                val blurRadius = getBlurRadius(layer)
                                                if (blurRadius > 0f) {
                                                    for (o in 1..4) {
                                                        drawOval(
                                                            color = layer.baseColor.copy(alpha = layerOpacity * 0.15f),
                                                            topLeft = Offset(-o * blurRadius * 0.4f, -o * blurRadius * 0.4f),
                                                            size = Size(layer.width + o * blurRadius * 0.8f, layer.height + o * blurRadius * 0.8f),
                                                            blendMode = composeBlendMode
                                                        )
                                                    }
                                                }
                                                drawOval(
                                                    color = layer.baseColor.copy(alpha = layerOpacity),
                                                    topLeft = Offset.Zero,
                                                    size = Size(layer.width, layer.height),
                                                    blendMode = composeBlendMode
                                                )
                                            }
 
                                            LayerType.VECTOR_LINE -> {
                                                val blurRadius = getBlurRadius(layer)
                                                if (blurRadius > 0f) {
                                                    for (o in 1..4) {
                                                        drawLine(
                                                            color = layer.baseColor.copy(alpha = layerOpacity * 0.18f),
                                                            start = Offset.Zero,
                                                            end = Offset(layer.width, layer.height),
                                                            strokeWidth = 6f + o * blurRadius * 0.5f,
                                                            blendMode = composeBlendMode
                                                        )
                                                    }
                                                }
                                                drawLine(
                                                    color = layer.baseColor.copy(alpha = layerOpacity),
                                                    start = Offset.Zero,
                                                    end = Offset(layer.width, layer.height),
                                                    strokeWidth = 6f,
                                                    blendMode = composeBlendMode
                                                )
                                            }
 
                                            LayerType.VECTOR_BEZIER -> {
                                                val start = Offset(0f, layer.height)
                                                val end = Offset(layer.width, layer.height)
                                                val controlLocal = layer.brushPoints.getOrNull(0) ?: Offset(layer.width / 2f, 0f)

                                                val cacheKey = getLayerGeometryHash(layer)
                                                var path = pathCache.get(cacheKey)
                                                if (path == null) {
                                                    val newPath = Path().apply {
                                                        val anchors = layer.brushPoints.toAnchorPoints()
                                                        if (anchors.isNotEmpty()) {
                                                            val first = anchors[0]
                                                            moveTo(first.position.x, first.position.y)
                                                            for (index in 0 until anchors.size - 1) {
                                                                val current = anchors[index]
                                                                val next = anchors[index + 1]
                                                                cubicTo(
                                                                    current.handleOut.x, current.handleOut.y,
                                                                    next.handleIn.x, next.handleIn.y,
                                                                    next.position.x, next.position.y
                                                                )
                                                            }
                                                        } else {
                                                            moveTo(start.x, start.y)
                                                            quadraticTo(controlLocal.x, controlLocal.y, end.x, end.y)
                                                        }
                                                    }
                                                    pathCache.put(cacheKey, newPath)
                                                    path = newPath
                                                }
                                                val blurRadius = getBlurRadius(layer)
                                                val shapeStyle = if (layer.isAlphaLocked) {
                                                    androidx.compose.ui.graphics.drawscope.Fill
                                                } else {
                                                    Stroke(width = 8f)
                                                }

                                                if (blurRadius > 0f) {
                                                    for (o in 1..4) {
                                                        val blurStyle = if (layer.isAlphaLocked) {
                                                            androidx.compose.ui.graphics.drawscope.Fill
                                                        } else {
                                                            Stroke(width = 8f + o * blurRadius * 0.5f)
                                                        }
                                                        drawPath(
                                                            path = path,
                                                            color = layer.baseColor.copy(alpha = layerOpacity * 0.15f),
                                                            style = blurStyle,
                                                            blendMode = composeBlendMode
                                                        )
                                                    }
                                                }
                                                drawPath(
                                                    path = path,
                                                    color = layer.baseColor.copy(alpha = layerOpacity),
                                                    style = shapeStyle,
                                                    blendMode = composeBlendMode
                                                )

                                                // Paint support guidelines if layer is selected
                                                if (layer.id == selectedLayerId) {
                                                    val anchors = layer.brushPoints.toAnchorPoints()
                                                    if (anchors.isNotEmpty()) {
                                                        for (ap in anchors) {
                                                            if (ap.handleIn != ap.position) {
                                                                drawLine(
                                                                    color = Color.LightGray.copy(alpha = 0.6f),
                                                                    start = ap.position,
                                                                    end = ap.handleIn,
                                                                    strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                                                                    pathEffect = dashEffect8
                                                                )
                                                                drawCircle(
                                                                    color = IndustrialAmber,
                                                                    radius = 8.5f / totalScale.coerceAtLeast(0.5f),
                                                                    center = ap.handleIn
                                                                )
                                                                drawCircle(
                                                                    color = Color.White,
                                                                    radius = 4f / totalScale.coerceAtLeast(0.5f),
                                                                    center = ap.handleIn
                                                                )
                                                            }
                                                            if (ap.handleOut != ap.position) {
                                                                drawLine(
                                                                    color = Color.LightGray.copy(alpha = 0.6f),
                                                                    start = ap.position,
                                                                    end = ap.handleOut,
                                                                    strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                                                                    pathEffect = dashEffect8
                                                                )
                                                                drawCircle(
                                                                    color = IndustrialAmber,
                                                                    radius = 8.5f / totalScale.coerceAtLeast(0.5f),
                                                                    center = ap.handleOut
                                                                )
                                                                drawCircle(
                                                                    color = Color.White,
                                                                    radius = 4f / totalScale.coerceAtLeast(0.5f),
                                                                    center = ap.handleOut
                                                                )
                                                            }

                                                            drawCircle(
                                                                color = Color(0xFF00E5FF),
                                                                radius = 9f / totalScale.coerceAtLeast(0.5f),
                                                                center = ap.position
                                                            )
                                                            drawCircle(
                                                                color = Color.White,
                                                                radius = 4.5f / totalScale.coerceAtLeast(0.5f),
                                                                center = ap.position
                                                            )
                                                        }
                                                    } else {
                                                        drawLine(
                                                            color = Color.LightGray.copy(alpha = 0.5f),
                                                            start = start,
                                                            end = controlLocal,
                                                            strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                                                            pathEffect = dashEffect8
                                                        )
                                                        drawLine(
                                                            color = Color.LightGray.copy(alpha = 0.5f),
                                                            start = end,
                                                            end = controlLocal,
                                                            strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                                                            pathEffect = dashEffect8
                                                        )
                                                        drawCircle(
                                                            color = IndustrialAmber,
                                                            radius = 10f / totalScale.coerceAtLeast(0.5f),
                                                            center = controlLocal
                                                        )
                                                        drawCircle(
                                                            color = Color.White,
                                                            radius = 5f / totalScale.coerceAtLeast(0.5f),
                                                            center = controlLocal
                                                        )
                                                    }
                                                }
                                            }
 
                                            LayerType.VECTOR_CIRCLE -> {
                                                val radius = layer.width / 2f
                                                val center = Offset(radius, layer.height / 2f)

                                                val blurRadius = getBlurRadius(layer)
                                                if (blurRadius > 0f) {
                                                    for (o in 1..4) {
                                                        drawCircle(
                                                            color = layer.baseColor.copy(alpha = layerOpacity * 0.15f),
                                                            radius = radius + o * blurRadius * 0.4f,
                                                            center = center,
                                                            blendMode = composeBlendMode
                                                        )
                                                    }
                                                }
 
                                                drawCircle(
                                                    color = layer.baseColor.copy(alpha = layerOpacity),
                                                    radius = radius,
                                                    center = center,
                                                    blendMode = composeBlendMode
                                                )
                                            }
 
                                            LayerType.VECTOR_STAR -> {
                                                val cacheKey = getLayerGeometryHash(layer)
                                                var path = pathCache.get(cacheKey)
                                                if (path == null) {
                                                    val pathStar = Path()
                                                    val cx = layer.width / 2f
                                                    val cy = layer.height / 2f
                                                    val rOuter = layer.width / 2f
                                                    val rInner = rOuter * 0.4f
                                                    var angle = Math.PI / 2.0 * 3.0
                                                    val step = Math.PI / 5.0

                                                    pathStar.moveTo(
                                                        (cx + Math.cos(angle) * rOuter).toFloat(),
                                                        (cy + Math.sin(angle) * rOuter).toFloat()
                                                    )

                                                    for (i in 0..10) {
                                                        val r = if (i % 2 == 0) rOuter else rInner
                                                        pathStar.lineTo(
                                                            (cx + Math.cos(angle) * r).toFloat(),
                                                            (cy + Math.sin(angle) * r).toFloat()
                                                        )
                                                        angle += step
                                                    }
                                                    pathStar.close()
                                                    pathCache.put(cacheKey, pathStar)
                                                    path = pathStar
                                                }
                                                val blurRadius = getBlurRadius(layer)
                                                if (blurRadius > 0f) {
                                                    for (o in 1..4) {
                                                        drawPath(
                                                            path = path,
                                                            color = layer.baseColor.copy(alpha = layerOpacity * 0.12f),
                                                            style = Stroke(width = o * blurRadius),
                                                            blendMode = composeBlendMode
                                                        )
                                                    }
                                                }
 
                                                drawPath(
                                                    path = path,
                                                    color = layer.baseColor.copy(alpha = layerOpacity),
                                                    blendMode = composeBlendMode
                                                )
                                            }

                                            LayerType.TEXT -> {
                                                drawTextLayerInternal(
                                                    layer = layer,
                                                    opacityMultiplier = layerOpacity,
                                                    composeBlendMode = composeBlendMode
                                                )
                                            }

                                            LayerType.FREEHAND_DRAWING -> {
                                                if (layer.brushPoints.size > 1) {
                                                    val brushConfig = layer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                                    val bSize = brushConfig?.parameters?.get("Size")?.value ?: 12f
                                                    val bOpacity = brushConfig?.parameters?.get("Opacity")?.value ?: 1.0f
                                                    val bSmoothing = (brushConfig?.parameters?.get("Smoothing")?.value ?: 1.0f) > 0.5f
                                                    val bPreset = brushConfig?.parameters?.get("Preset")?.value?.toInt() ?: 0

                                                    drawBrushStroke(
                                                        points = layer.brushPoints,
                                                        color = layer.baseColor,
                                                        size = bSize,
                                                        opacity = bOpacity * layerOpacity,
                                                        presetIndex = bPreset,
                                                        smoothing = bSmoothing,
                                                        originX = layer.positionX,
                                                        originY = layer.positionY,
                                                        composeBlendMode = composeBlendMode,
                                                        pathCache = pathCache,
                                                        pathPointsCountCache = pathPointsCountCache,
                                                        cacheKey = layer.id.hashCode()
                                                    )
                                                }
                                            }

                                            com.example.studio.model.LayerType.GROUP -> {}
                                            LayerType.IMAGE_CARD -> {
                                                val uriStr = layer.imageUri
                                                val loadedBitmap = if (!uriStr.isNullOrEmpty()) imageBitmapCache[uriStr] else null
                                                if (loadedBitmap != null) {
                                                    drawImage(
                                                        image = loadedBitmap,
                                                        dstSize = androidx.compose.ui.unit.IntSize(layer.width.toInt(), layer.height.toInt()),
                                                        alpha = layerOpacity,
                                                        blendMode = composeBlendMode
                                                    )
                                                } else {
                                                    // Draws a beautifully stylized placeholder graphics pattern card
                                                    drawRect(
                                                        color = Color(0xFF37474F).copy(alpha = layerOpacity),
                                                        topLeft = Offset.Zero,
                                                        size = Size(layer.width, layer.height),
                                                        blendMode = composeBlendMode
                                                    )
                                                    // Inner details representing nested comps
                                                    drawCircle(
                                                        color = Color(0xFFFFCC80).copy(alpha = layerOpacity * 0.7f),
                                                        radius = 35f,
                                                        center = Offset(layer.width / 2f, layer.height / 2f)
                                                    )
                                                }
                                            }
                                        }

                                        // Overlay selected layer bounds and sizing anchor highlights
                                        if (layer.id == selectedLayerId) {
                                            drawRect(
                                                color = IndustrialAmber.copy(0.8f),
                                                topLeft = Offset(-6f, -6f),
                                                size = Size(layer.width + 12f, layer.height + 12f),
                                                style = Stroke(
                                                    width = 1.5f / totalScale.coerceAtLeast(0.5f),
                                                    pathEffect = PathEffect.dashPathEffect(floatArrayOf(12f / totalScale.coerceAtLeast(0.5f), 8f / totalScale.coerceAtLeast(0.5f)))
                                                )
                                            )
                                            // Handle anchor points
                                            drawCircle(
                                                color = EnergeticYellow,
                                                radius = 8f / totalScale.coerceAtLeast(0.5f),
                                                center = Offset.Zero
                                            )
                                            // Distinct accent badge on active resize corner handle
                                            drawCircle(
                                                color = EnergeticYellow,
                                                radius = 11f / totalScale.coerceAtLeast(0.5f),
                                                center = Offset(layer.width, layer.height)
                                            )
                                            drawCircle(
                                                color = Color(0xFFFF5722),
                                                radius = 5.5f / totalScale.coerceAtLeast(0.5f),
                                                center = Offset(layer.width, layer.height)
                                            )
                                        }
                                        
                                    }
                                    }

                                    val activeEffectsList = layer.effects.filter { it.isEnabled }
                                    val hasAdjustmentEffect = layer.type != com.example.studio.model.LayerType.IMAGE_CARD && 
                                        layer.type != com.example.studio.model.LayerType.TEXT && 
                                        layer.type != com.example.studio.model.LayerType.FREEHAND_DRAWING &&
                                        activeEffectsList.any { 
                                            it is com.example.studio.model.StudioEffect.ColorBalance || 
                                            it is com.example.studio.model.StudioEffect.Invert || 
                                            it is com.example.studio.model.StudioEffect.Threshold || 
                                            it is com.example.studio.model.StudioEffect.Posterize || 
                                            (it is com.example.studio.model.StudioEffect.PhotoshopEffect && 
                                             it.effectType in listOf("CameraRaw", "ColorGrading", "Solarize", "Emboss", "FindEdges", "ColorHalftone", "Sketch", "Mosaic", "Twirl", "Spherize", "GaussianBlur", "SmartSharpen", "UnsharpMask", "AddNoise")) 
                                        }
                                    val hasGlassEffect = layer.effects.any { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && (it.effectType == "GlassMorphism" || it.effectType == "ReededGlass") }
                                    val needsBackdrop = hasGlassEffect || hasAdjustmentEffect || layer.effects.any { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType !in listOf("BrushConfig", "DropShadow", "InnerShadow", "BordersAndShadows", "OuterGlow", "InnerGlow", "BevelEmboss", "Satin", "GradientOverlay", "PatternOverlay", "Stroke", "GlassMorphism", "ReededGlass") }
                                    val currentBackdrop = if (needsBackdrop) {
                                        val computedBackdrop = generateBackdropForLayer(
                                            layers = layers,
                                            currentIndex = index,
                                            canvasWidth = canvasWidth,
                                            canvasHeight = canvasHeight,
                                            imageBitmapCache = imageBitmapCache,
                                            pathCache = pathCache,
                                            pathPointsCountCache = pathPointsCountCache,
                                            existingBitmap = reusableBackdropBitmap
                                         )
                                         if (computedBackdrop != null) {
                                             reusableBackdropBitmap = computedBackdrop
                                         }
                                         computedBackdrop
                                    } else {
                                        null
                                    }

                                    // Invoke drawing lambda, constraining within Clipping Mask boundaries if enabled
                                    if (clippedLayers.isNotEmpty()) {
                                        try {
                                            // 1. Draw the base shape layer first (with standard selection highlights if selected)
                                            drawSingleConnectedLayer(
                                                layer = layer,
                                                layerOpacity = layerOpacity,
                                                selectedLayerId = selectedLayerId,
                                                pathCache = pathCache,
                                                pathPointsCountCache = pathPointsCountCache,
                                                totalScale = totalScale,
                                                dashEffect = dashEffect8,
                                                imageBitmapCache = imageBitmapCache,
                                                composeBlendMode = composeBlendMode,
                                                sharedTransformMatrix = sharedTransformMatrix,
                                                backdropBitmap = currentBackdrop,
                                                globalX = layer.positionX,
                                                globalY = layer.positionY,
                                                activeTool = activeTool,
                                                allLayers = layers,
                                                liveDragScaleX = if (isResizingActive && layer.id == activeResizingLayerId) liveDragScaleX else 1.0f,
                                                liveDragScaleY = if (isResizingActive && layer.id == activeResizingLayerId) liveDragScaleY else 1.0f,
                                                viewportWidth = currentViewportWidthState.value,
                                                viewportHeight = currentViewportHeightState.value,
                                                panX = currentCanvasPanXState.value,
                                                panY = currentCanvasPanYState.value,
                                                canvasWidth = canvasWidth,
                                                canvasHeight = canvasHeight
                                            )

                                            // 2. Perform Advanced multi-layer clipping composition
                                            val bounds = androidx.compose.ui.geometry.Rect(0f, 0f, canvasWidth, canvasHeight)
                                            
                                            // Outer saveLayer (to hold the destination mask shape)
                                            drawContext.canvas.saveLayer(bounds, androidx.compose.ui.graphics.Paint())

                                            // Draw base shape AGAIN (this becomes the destination alpha)
                                            drawSingleConnectedLayer(
                                                layer = layer,
                                                layerOpacity = layer.opacity,
                                                selectedLayerId = null,
                                                pathCache = pathCache,
                                                pathPointsCountCache = pathPointsCountCache,
                                                totalScale = totalScale,
                                                dashEffect = dashEffect8,
                                                imageBitmapCache = imageBitmapCache,
                                                composeBlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
                                                 liveDragScaleX = if (isResizingActive && layer.id == activeResizingLayerId) liveDragScaleX else 1.0f,
                                                 liveDragScaleY = if (isResizingActive && layer.id == activeResizingLayerId) liveDragScaleY else 1.0f,
                                                sharedTransformMatrix = sharedTransformMatrix,
                                                backdropBitmap = null,
                                                globalX = layer.positionX,
                                                globalY = layer.positionY,
                                                activeTool = activeTool,
                                                allLayers = layers,
                                                viewportWidth = currentViewportWidthState.value,
                                                viewportHeight = currentViewportHeightState.value,
                                                panX = currentCanvasPanXState.value,
                                                panY = currentCanvasPanYState.value,
                                                canvasWidth = canvasWidth,
                                                canvasHeight = canvasHeight
                                            )

                                            // Inner saveLayer (groups all consecutive clipped layers together using BlendMode.SrcIn)
                                            val groupPaint = androidx.compose.ui.graphics.Paint().apply {
                                                blendMode = androidx.compose.ui.graphics.BlendMode.SrcIn
                                             }
                                             drawContext.canvas.saveLayer(bounds, groupPaint)

                                             // Draw all consecutive clipped layers on top of each other inside the clip-group
                                             for (clipped in clippedLayers) {
                                                 drawSingleConnectedLayer(
                                                     layer = clipped,
                                                     layerOpacity = clipped.opacity,
                                                     selectedLayerId = selectedLayerId,
                                                     pathCache = pathCache,
                                                     pathPointsCountCache = pathPointsCountCache,
                                                     totalScale = totalScale,
                                                     dashEffect = dashEffect8,
                                                     imageBitmapCache = imageBitmapCache,
                                                     composeBlendMode = clipped.blendMode.toComposeBlendMode(),
                                                     liveDragScaleX = if (isResizingActive && clipped.id == activeResizingLayerId) liveDragScaleX else 1.0f,
                                                     liveDragScaleY = if (isResizingActive && clipped.id == activeResizingLayerId) liveDragScaleY else 1.0f,
                                                     sharedTransformMatrix = sharedTransformMatrix,
                                                     backdropBitmap = null,
                                                     globalX = clipped.positionX,
                                                     globalY = clipped.positionY,
                                                     activeTool = activeTool,
                                                     allLayers = layers,
                                                     viewportWidth = currentViewportWidthState.value,
                                                     viewportHeight = currentViewportHeightState.value,
                                                     panX = currentCanvasPanXState.value,
                                                     panY = currentCanvasPanYState.value,
                                                     canvasWidth = canvasWidth,
                                                     canvasHeight = canvasHeight
                                                 )
                                             }

                                             drawContext.canvas.restore() // Restore Inner saveLayer (composites clipped content with base shape)
                                             drawContext.canvas.restore() // Restore Outer saveLayer (composites onto canvas)
                                         } catch (e: Exception) {
                                             e.printStackTrace()
                                         }
                                     } else {
                                         // Draw single normal layer - live scaling enabled
                                          drawSingleConnectedLayer(
                                              layer = layer,
                                              layerOpacity = layerOpacity,
                                              selectedLayerId = selectedLayerId,
                                              pathCache = pathCache,
                                              pathPointsCountCache = pathPointsCountCache,
                                              totalScale = totalScale,
                                              dashEffect = dashEffect8,
                                              imageBitmapCache = imageBitmapCache,
                                              composeBlendMode = composeBlendMode,
                                              sharedTransformMatrix = sharedTransformMatrix,
                                              backdropBitmap = currentBackdrop,
                                              globalX = layer.positionX,
                                              globalY = layer.positionY,
                                              activeTool = activeTool,
                                              allLayers = layers,
                                              liveDragScaleX = if (isResizingActive && layer.id == activeResizingLayerId) liveDragScaleX else 1.0f,
                                              liveDragScaleY = if (isResizingActive && layer.id == activeResizingLayerId) liveDragScaleY else 1.0f,
                                              viewportWidth = currentViewportWidthState.value,
                                              viewportHeight = currentViewportHeightState.value,
                                              panX = currentCanvasPanXState.value,
                                              panY = currentCanvasPanYState.value,
                                              canvasWidth = canvasWidth,
                                              canvasHeight = canvasHeight
                                          )
                                                                            }
                                      if (false) {
                                         drawSingleConnectedLayer(
                                             layer = layer,
                                             layerOpacity = layerOpacity,
                                             selectedLayerId = selectedLayerId,
                                             pathCache = pathCache,
                                             pathPointsCountCache = pathPointsCountCache,
                                             totalScale = totalScale,
                                             dashEffect = dashEffect8,
                                             imageBitmapCache = imageBitmapCache,
                                             composeBlendMode = composeBlendMode,
                                             sharedTransformMatrix = sharedTransformMatrix,
                                             backdropBitmap = currentBackdrop,
                                             globalX = layer.positionX,
                                             globalY = layer.positionY,
                                             activeTool = activeTool,
                                             allLayers = layers
                                         )
                                     }
                                }

                                if (gridEnabled) {
                                    val w = canvasWidth
                                    val h = canvasHeight
                                    val cols = gridColumns.coerceIn(1, 200)
                                    val rows = gridRows.coerceIn(1, 200)
                                    val colWidth = w / cols
                                    val rowHeight = h / rows
                                    
                                    for (i in 0..cols) {
                                        val x = i * colWidth
                                        drawLine(
                                            color = Color(0xFF00E5FF).copy(alpha = 0.55f),
                                            start = Offset(x, 0f),
                                            end = Offset(x, h),
                                            strokeWidth = 1.6f / totalScale.coerceAtLeast(0.5f)
                                        )
                                    }
                                    for (j in 0..rows) {
                                        val y = j * rowHeight
                                        drawLine(
                                            color = Color(0xFF00E5FF).copy(alpha = 0.55f),
                                            start = Offset(0f, y),
                                            end = Offset(w, y),
                                            strokeWidth = 1.6f / totalScale.coerceAtLeast(0.5f)
                                        )
                                    }
                                }

                                if (rulerEnabled) {
                                    val w = canvasWidth
                                    val h = canvasHeight
                                    val rulerColor = Color(0xFFFF00FF)
                                    val strokeW = 2.4f / totalScale.coerceAtLeast(0.5f)
                                    
                                    if (rulerOrientation == "Horizontal") {
                                        withTransform({
                                            rotate(degrees = rulerAngle, pivot = Offset(w / 2f, rulerPosition))
                                        }) {
                                            drawLine(
                                                color = rulerColor,
                                                start = Offset(0f, rulerPosition),
                                                end = Offset(w, rulerPosition),
                                                strokeWidth = strokeW
                                            )
                                            val tickSpacing = 20f
                                            val maxTicks = (w / tickSpacing).toInt().coerceAtLeast(0).coerceAtMost(500)
                                            for (i in 0..maxTicks) {
                                                val xCoordinate = i * tickSpacing
                                                val isMajor = xCoordinate.toInt() % 100 == 0
                                                val tickLen = if (isMajor) 15f else 7f
                                                drawLine(
                                                    color = rulerColor.copy(alpha = if (isMajor) 0.9f else 0.6f),
                                                    start = Offset(xCoordinate, rulerPosition - tickLen / totalScale.coerceAtLeast(0.5f)),
                                                    end = Offset(xCoordinate, rulerPosition + tickLen / totalScale.coerceAtLeast(0.5f)),
                                                    strokeWidth = (if (isMajor) 1.6f else 1.0f) / totalScale.coerceAtLeast(0.5f)
                                                )
                                            }
                                        }
                                    } else {
                                        withTransform({
                                            rotate(degrees = rulerAngle, pivot = Offset(rulerPosition, h / 2f))
                                        }) {
                                            drawLine(
                                                color = rulerColor,
                                                start = Offset(rulerPosition, 0f),
                                                end = Offset(rulerPosition, h),
                                                strokeWidth = strokeW
                                            )
                                            val tickSpacing = 20f
                                            val maxTicks = (h / tickSpacing).toInt().coerceAtLeast(0).coerceAtMost(500)
                                            for (j in 0..maxTicks) {
                                                val yCoordinate = j * tickSpacing
                                                val isMajor = yCoordinate.toInt() % 100 == 0
                                                val tickLen = if (isMajor) 15f else 7f
                                                drawLine(
                                                    color = rulerColor.copy(alpha = if (isMajor) 0.9f else 0.6f),
                                                    start = Offset(rulerPosition - tickLen / totalScale.coerceAtLeast(0.5f), yCoordinate),
                                                    end = Offset(rulerPosition + tickLen / totalScale.coerceAtLeast(0.5f), yCoordinate),
                                                    strokeWidth = (if (isMajor) 1.6f else 1.0f) / totalScale.coerceAtLeast(0.5f)
                                                )
                                            }
                                        }
                                    }
                                }

                                // Listen to the high-frequency trigger without recomposing the whole UI
                                val _strokeTrigger = strokeDrawTrigger.value

                                if (OpenGLBrushRenderer.WetInkRenderer.isInitialized()) {
                                    val isFreehandSelected = layers.any { it.id == selectedLayerId && it.type == com.example.studio.model.LayerType.FREEHAND_DRAWING }
                                    if (!isFreehandSelected && activeTool != "Eraser") {
                                        OpenGLBrushRenderer.WetInkRenderer.getWetInkBitmap()?.let { b ->
                                            drawImage(
                                                image = b.asImageBitmap(),
                                                topLeft = Offset.Zero,
                                                blendMode = androidx.compose.ui.graphics.BlendMode.SrcOver
                                            )
                                        }
                                    }
                                }

                                // Draw Red Snapping / Alignment Guide Lines
                                snapVerticalLine?.let { snapX ->
                                    // Styled vertical line and inline badge
                                    drawLine(
                                        color = Color(0xFFFF3333),
                                        start = Offset(snapX, 0f),
                                        end = Offset(snapX, canvasHeight),
                                        strokeWidth = 3f / ts.coerceAtLeast(0.5f)
                                    )
                                    
                                    val textPaint = android.graphics.Paint().apply {
                                        color = android.graphics.Color.WHITE
                                        textSize = 13f / ts.coerceAtLeast(0.3f)
                                        typeface = android.graphics.Typeface.create(android.graphics.Typeface.DEFAULT, android.graphics.Typeface.BOLD)
                                        isAntiAlias = true
                                    }
                                    
                                    val bgPaint = android.graphics.Paint().apply {
                                        color = android.graphics.Color.parseColor("#E53935")
                                        style = android.graphics.Paint.Style.FILL
                                        isAntiAlias = true
                                    }
                                    
                                    val borderPaint = android.graphics.Paint().apply {
                                        color = android.graphics.Color.WHITE
                                        style = android.graphics.Paint.Style.STROKE
                                        strokeWidth = 1.5f / ts.coerceAtLeast(0.5f)
                                        isAntiAlias = true
                                    }
                                    
                                    val text = snapIndicatorMsg ?: "Snapped"
                                    val textWidth = textPaint.measureText(text)
                                    val textHeight = textPaint.fontMetrics.descent - textPaint.fontMetrics.ascent
                                     
                                    val paddingX = 14f / ts.coerceAtLeast(0.5f)
                                    val paddingY = 7f / ts.coerceAtLeast(0.5f)
                                     
                                    val badgeWidth = textWidth + paddingX * 2
                                    val badgeHeight = textHeight + paddingY * 2
                                     
                                    val badgeX = snapX - badgeWidth / 2f
                                    val badgeY = (canvasHeight * 0.15f) - badgeHeight / 2f
                                    val safeBadgeX = badgeX.coerceIn(0f, canvasWidth - badgeWidth)
                                     
                                    val rectF = android.graphics.RectF(safeBadgeX, badgeY, safeBadgeX + badgeWidth, badgeY + badgeHeight)
                                    val rx = 6f / ts.coerceAtLeast(0.5f)
                                    drawContext.canvas.nativeCanvas.drawRoundRect(rectF, rx, rx, bgPaint)
                                    drawContext.canvas.nativeCanvas.drawRoundRect(rectF, rx, rx, borderPaint)
                                     
                                    val textX = safeBadgeX + paddingX
                                    val textY = badgeY + paddingY - textPaint.fontMetrics.ascent
                                    drawContext.canvas.nativeCanvas.drawText(text, textX, textY, textPaint)
                                }
                                snapHorizontalLine?.let { snapY ->
                                    drawLine(
                                        color = Color(0xFFFF3333),
                                        start = Offset(0f, snapY),
                                        end = Offset(canvasWidth, snapY),
                                        strokeWidth = 3f / ts.coerceAtLeast(0.5f)
                                    )
                                    
                                    if (snapVerticalLine == null) {
                                         val textPaint = android.graphics.Paint().apply {
                                             color = android.graphics.Color.WHITE
                                             textSize = 13f / ts.coerceAtLeast(0.3f)
                                             typeface = android.graphics.Typeface.create(android.graphics.Typeface.DEFAULT, android.graphics.Typeface.BOLD)
                                             isAntiAlias = true
                                         }
                                         
                                         val bgPaint = android.graphics.Paint().apply {
                                             color = android.graphics.Color.parseColor("#E53935")
                                             style = android.graphics.Paint.Style.FILL
                                             isAntiAlias = true
                                         }
                                         
                                         val borderPaint = android.graphics.Paint().apply {
                                             color = android.graphics.Color.WHITE
                                             style = android.graphics.Paint.Style.STROKE
                                             strokeWidth = 1.5f / ts.coerceAtLeast(0.5f)
                                             isAntiAlias = true
                                         }
                                         
                                         val text = snapIndicatorMsg ?: "Snapped"
                                         val textWidth = textPaint.measureText(text)
                                         val textHeight = textPaint.fontMetrics.descent - textPaint.fontMetrics.ascent
                                         
                                         val paddingX = 14f / ts.coerceAtLeast(0.5f)
                                         val paddingY = 7f / ts.coerceAtLeast(0.5f)
                                         
                                         val badgeWidth = textWidth + paddingX * 2
                                         val badgeHeight = textHeight + paddingY * 2
                                         
                                         val badgeX = (canvasWidth * 0.15f) - badgeWidth / 2f
                                         val badgeY = snapY - badgeHeight / 2f
                                         val safeBadgeY = badgeY.coerceIn(0f, canvasHeight - badgeHeight)
                                         
                                         val rectF = android.graphics.RectF(badgeX.coerceAtLeast(0f), safeBadgeY, badgeX.coerceAtLeast(0f) + badgeWidth, safeBadgeY + badgeHeight)
                                         val rx = 6f / ts.coerceAtLeast(0.5f)
                                         drawContext.canvas.nativeCanvas.drawRoundRect(rectF, rx, rx, bgPaint)
                                         drawContext.canvas.nativeCanvas.drawRoundRect(rectF, rx, rx, borderPaint)
                                         
                                         val textX = badgeX.coerceAtLeast(0f) + paddingX
                                         val textY = safeBadgeY + paddingY - textPaint.fontMetrics.ascent
                                         drawContext.canvas.nativeCanvas.drawText(text, textX, textY, textPaint)
                                    }
                                }
                            }
                        } catch (e: Exception) {
                            // Fail-safe compilation error handler
                        }
                    }

                    // Live, independent high-performance guides rendering overlay
                    val currentRulersVal = rulers
                    val currentSelectedRulerIdVal = selectedRulerId
                    val currentRulerEnabledVal = rulerEnabled || activeTool == "Ruler"

                    if (currentRulerEnabledVal) {
                        Canvas(
                            modifier = Modifier
                                .fillMaxSize()
                        ) {
                            val w = canvasWidth
                            val h = canvasHeight
                            val ts = currentTotalScaleState.value

                            withTransform({
                                translate(left = currentViewportWidthState.value / 2f + currentCanvasPanXState.value, top = currentViewportHeightState.value / 2f + currentCanvasPanYState.value)
                                rotate(degrees = currentCanvasRotationState.value, pivot = Offset.Zero)
                                scale(scaleX = ts, scaleY = ts, pivot = Offset.Zero)
                                translate(left = -currentCanvasWidthState.value / 2f, top = -currentCanvasHeightState.value / 2f)
                                clipRect(left = 0f, top = 0f, right = currentCanvasWidthState.value, bottom = currentCanvasHeightState.value)
                            }) {
                                currentRulersVal.forEach { ruler ->
                                    if (!ruler.enabled) return@forEach

                                    val isSelected = ruler.id == currentSelectedRulerIdVal

                                    // Check if this particular ruler is snapped right now
                                    val isSnappedX = snapVerticalLine != null && ruler.orientation == "Vertical" && Math.abs(ruler.position - (snapVerticalLine ?: -999f)) < 1f
                                    val isSnappedY = snapHorizontalLine != null && ruler.orientation == "Horizontal" && Math.abs(ruler.position - (snapHorizontalLine ?: -999f)) < 1f

                                    val rulerColor = when {
                                        isSnappedX || isSnappedY -> Color(0xFFFF1744) // Snapped highlight
                                        isSelected -> Color(0xFFFF00FF) // Selected highlight
                                        else -> Color(0xFFFF00FF).copy(alpha = 0.65f) // Normal guide path
                                    }

                                    val strokeW = (if (isSelected || isSnappedX || isSnappedY) 3.2f else 2.0f) / ts.coerceAtLeast(0.5f)

                                    if (ruler.orientation == "Horizontal") {
                                        drawLine(
                                            color = rulerColor,
                                            start = Offset(0f, ruler.position),
                                            end = Offset(w, ruler.position),
                                            strokeWidth = strokeW
                                        )
                                        // Draw clean ticks
                                        val tickSpacing = 20f
                                        val maxTicks = (w / tickSpacing).toInt().coerceAtLeast(0).coerceAtMost(500)
                                        for (i in 0..maxTicks) {
                                            val xCoordinate = i * tickSpacing
                                            val isMajor = xCoordinate.toInt() % 100 == 0
                                            val tickLen = if (isMajor) 15f else 7f
                                            drawLine(
                                                color = rulerColor.copy(alpha = if (isMajor) 0.85f else 0.55f),
                                                start = Offset(xCoordinate, ruler.position - tickLen / ts.coerceAtLeast(0.5f)),
                                                end = Offset(xCoordinate, ruler.position + tickLen / ts.coerceAtLeast(0.5f)),
                                                strokeWidth = (if (isMajor) 1.6f else 0.9f) / ts.coerceAtLeast(0.5f)
                                            )
                                        }
                                    } else {
                                        drawLine(
                                            color = rulerColor,
                                            start = Offset(ruler.position, 0f),
                                            end = Offset(ruler.position, h),
                                            strokeWidth = strokeW
                                        )
                                        // Draw vertical ticks
                                        val tickSpacing = 20f
                                        val maxTicks = (h / tickSpacing).toInt().coerceAtLeast(0).coerceAtMost(500)
                                        for (j in 0..maxTicks) {
                                            val yCoordinate = j * tickSpacing
                                            val isMajor = yCoordinate.toInt() % 100 == 0
                                            val tickLen = if (isMajor) 15f else 7f
                                            drawLine(
                                                color = rulerColor.copy(alpha = if (isMajor) 0.85f else 0.55f),
                                                start = Offset(ruler.position - tickLen / ts.coerceAtLeast(0.5f), yCoordinate),
                                                end = Offset(ruler.position + tickLen / ts.coerceAtLeast(0.5f), yCoordinate),
                                                strokeWidth = (if (isMajor) 1.6f else 0.9f) / ts.coerceAtLeast(0.5f)
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }

                    // On-screen Canvas controls info sticker & Export group layout
                    Column(
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(8.dp),
                        horizontalAlignment = Alignment.End,
                        verticalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .background(DarkOnyx.copy(alpha = 0.85f), RoundedCornerShape(6.dp))
                                .border(0.5.dp, HighslateOutline, RoundedCornerShape(6.dp))
                                .padding(horizontal = 10.dp, vertical = 6.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.AspectRatio,
                                contentDescription = "Canvas Info",
                                tint = IndustrialAmber,
                                modifier = Modifier.size(14.dp)
                            )
                            Text(
                                text = "Canvas: ${canvasWidth.toInt()}x${canvasHeight.toInt()} px | Zoom: ${(scaleFactor * 100).toInt()}%" + 
                                    if (canvasRotation != 0f) " | Rot: ${canvasRotation.toInt()}°" else "",
                                style = Typography.labelSmall,
                                color = TextSecondary
                            )
                            if (canvasRotation != 0f || canvasPanX != 0f || canvasPanY != 0f || scaleFactor != 1.0f) {
                                Spacer(modifier = Modifier.width(2.dp))
                                Box(
                                    modifier = Modifier
                                        .size(20.dp)
                                        .background(IndustrialAmber, RoundedCornerShape(4.dp))
                                        .clickable {
                                            scaleFactor = 1.0f
                                            canvasPanX = 0f
                                            canvasPanY = 0f
                                            canvasRotation = 0f
                                        },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Refresh,
                                        contentDescription = "Reset Viewport",
                                        tint = DarkOnyx,
                                        modifier = Modifier.size(12.dp)
                                    )
                                }
                            }
                        }
                    }

                    // Hand tool helper button
                    Box(
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(8.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                        ) {
                            androidx.compose.animation.AnimatedVisibility(
                                visible = !isCanvasControlMinimized,
                                enter = androidx.compose.animation.expandHorizontally() + androidx.compose.animation.fadeIn(),
                                exit = androidx.compose.animation.shrinkHorizontally() + androidx.compose.animation.fadeOut()
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    IconButton(
                                        onClick = { scaleFactor += 0.1f },
                                        modifier = Modifier
                                            .size(36.dp)
                                            .background(MidSlate, RoundedCornerShape(4.dp)),
                                    ) {
                                        Icon(Icons.Default.Add, "Zoom In", tint = TextPrimary, modifier = Modifier.size(16.dp))
                                    }
                                    IconButton(
                                        onClick = { if (scaleFactor > 0.3f) scaleFactor -= 0.1f },
                                        modifier = Modifier
                                            .size(36.dp)
                                            .background(MidSlate, RoundedCornerShape(4.dp)),
                                    ) {
                                        Icon(Icons.Default.Remove, "Zoom Out", tint = TextPrimary, modifier = Modifier.size(16.dp))
                                    }
                                    IconButton(
                                        onClick = { isCanvasLocked = !isCanvasLocked },
                                        modifier = Modifier
                                            .size(36.dp)
                                            .background(if (isCanvasLocked) IndustrialAmber else MidSlate, RoundedCornerShape(4.dp))
                                            .testTag("lock_canvas_button"),
                                    ) {
                                        Icon(
                                            imageVector = if (isCanvasLocked) Icons.Default.Lock else Icons.Default.LockOpen,
                                            contentDescription = "Lock Canvas Viewport",
                                            tint = if (isCanvasLocked) DarkOnyx else TextPrimary,
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                }
                            }

                            // Minimalistic Arrow toggle button on the right edge
                            IconButton(
                                onClick = { isCanvasControlMinimized = !isCanvasControlMinimized },
                                modifier = Modifier
                                    .size(36.dp)
                                    .background(MidSlate, RoundedCornerShape(4.dp))
                                    .testTag("canvas_minimizer_button"),
                            ) {
                                Icon(
                                    imageVector = if (isCanvasControlMinimized) Icons.Default.KeyboardArrowRight else Icons.Default.KeyboardArrowLeft,
                                    contentDescription = "Toggle Canvas Controls",
                                    tint = TextPrimary,
                                    modifier = Modifier.size(16.dp)
                                )
                            }
                        }
                    }



                    if (!isBottomPanelVisible) {
                        Row(
                            modifier = Modifier
                                .align(Alignment.BottomEnd)
                                .padding(bottom = 8.dp, end = 8.dp),
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Button(
                                onClick = { isBottomPanelVisible = true },
                                colors = ButtonDefaults.buttonColors(containerColor = MidSlate),
                                shape = RoundedCornerShape(24.dp),
                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 8.dp),
                                modifier = Modifier.height(38.dp)
                            ) {
                                Icon(Icons.Default.Tune, "Show parameters", tint = TextPrimary, modifier = Modifier.size(16.dp))
                                Spacer(Modifier.width(4.dp))
                                Text("PARAMETERS", style = Typography.labelSmall.copy(fontSize = 10.sp), color = TextPrimary, fontWeight = FontWeight.Bold)
                            }
                        }
                    }

                    // Elegant Snapping Indicator Badge Overlay
                    snapIndicatorMsg?.let { msg ->
                        Box(
                            modifier = Modifier
                                .align(Alignment.TopCenter)
                                .padding(12.dp)
                                .background(Color(0xFFCC0000).copy(alpha = 0.9f), RoundedCornerShape(8.dp))
                                .border(1.2.dp, Color.Red, RoundedCornerShape(8.dp))
                                .padding(horizontal = 14.dp, vertical = 8.dp)
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.GridOn,
                                    contentDescription = "Snapping Indicator",
                                    tint = Color.White,
                                    modifier = Modifier.size(16.dp)
                                )
                                Text(
                                    text = msg,
                                    style = Typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                                    color = Color.White
                                )
                            }
                        }
                    }

                    // Compact Floating Layer Manager Panel
                    androidx.compose.animation.AnimatedVisibility(
                        visible = isLayersPanelVisible,
                        enter = slideInHorizontally(initialOffsetX = { it }) + fadeIn(),
                        exit = slideOutHorizontally(targetOffsetX = { it }) + fadeOut(),
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(top = 56.dp, end = 12.dp)
                    ) {
                        RightsideLayerDrawer(
                            layers = layers,
                            selectedLayerId = selectedLayerId,
                            onSelectLayer = { selectedLayerId = it },
                            onChangeVisibility = { id ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(isVisible = !it.isVisible) else it }
                            },
                            onChangeAlphaLock = { id ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(isAlphaLocked = !it.isAlphaLocked) else it }
                            },
                            onChangeClippingMask = { id ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(isClippingMask = !it.isClippingMask) else it }
                            },
                            onLayerReorderUp = { index ->
                                if (index > 0) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    val list = layers.toMutableList()
                                    val removed = list.removeAt(index)
                                    list.add(index - 1, removed)
                                    layers = list
                                }
                            },
                            onLayerReorderDown = { index ->
                                if (index < layers.size - 1) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    val list = layers.toMutableList()
                                    val removed = list.removeAt(index)
                                    list.add(index + 1, removed)
                                    layers = list
                                }
                            },
                            onAddLayer = {
                                undoStack.add(layers)
                                redoStack.clear()
                                val newL = StudioLayer(
                                    name = "Empty Layer ${layers.size + 1}",
                                    type = LayerType.FREEHAND_DRAWING,
                                    positionX = 0f,
                                    positionY = 0f,
                                    width = canvasWidth,
                                    height = canvasHeight,
                                    baseColor = Color.Transparent,
                                    effects = listOf(
                                        PhotoshopEffectTemplates.create(effectType = "BrushConfig").let { eff ->
                                            var updated = eff.updateParameter("Size", brushSize)
                                            updated = updated.updateParameter("Opacity", brushOpacity)
                                            updated = updated.updateParameter("Smoothing", if (brushSmoothing) 1.0f else 0.0f)
                                            updated = updated.updateParameter("Preset", brushPresetIndex.toFloat())
                                            updated
                                        }
                                    ),
                                    brushPoints = emptyList()
                                )
                                layers = listOf(newL) + layers
                                selectedLayerId = newL.id
                            },
                            onDuplicateLayer = { id ->
                                val orig = layers.find { it.id == id }
                                if (orig != null) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    val copy = orig.copy(
                                        id = UUID.randomUUID().toString(),
                                        name = "${orig.name} (Copy)",
                                        positionX = orig.positionX + 40f,
                                        positionY = orig.positionY + 40f
                                    )
                                    layers = listOf(copy) + layers
                                    selectedLayerId = copy.id
                                }
                            },
                            onDeleteLayer = { id ->
                                if (layers.size > 1) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    layers = layers.filter { it.id != id }
                                    selectedLayerId = layers[0].id
                                }
                            },
                            onBlendModeChange = { id, mode ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(blendMode = mode) else it }
                            },
                            onOpacityChange = { id, op ->
                                layers = layers.map { if (it.id == id) it.copy(opacity = op) else it }
                            },
                            onTriggerRename = { id, currentName ->
                                renamingLayerId = id
                                renamingLayerName = currentName
                            },
                            onCloseDrawer = { isLayersPanelVisible = false },
                            isMultiSelectMode = isMultiSelectMode,
                            onToggleMultiSelect = {
                                isMultiSelectMode = !isMultiSelectMode
                                if (!isMultiSelectMode) {
                                    selectedLayersSet = emptySet()
                                }
                            },
                            selectedLayersSet = selectedLayersSet,
                            onToggleSelectLayerMulti = { id ->
                                selectedLayersSet = if (selectedLayersSet.contains(id)) {
                                    selectedLayersSet - id
                                } else {
                                    selectedLayersSet + id
                                }
                            },
                            onGroupSelected = {
                                if (selectedLayersSet.size >= 2) {
                                    val newGroupId = UUID.randomUUID().toString()
                                    val selectedIndices = layers.indices.filter { layers[it].id in selectedLayersSet }
                                    val topIndex = selectedIndices.minOrNull() ?: 0
                                    
                                    val newGroupLayer = com.example.studio.model.StudioLayer(
                                        id = newGroupId,
                                        name = "Group ${layers.filter { it.type == com.example.studio.model.LayerType.GROUP }.size + 1}",
                                        type = com.example.studio.model.LayerType.GROUP,
                                        positionX = 0f,
                                        positionY = 0f,
                                        width = canvasWidth,
                                        height = canvasHeight,
                                        isVisible = true,
                                        opacity = 1.0f
                                    )
                                    
                                    val updatedLayers = layers.map { 
                                        if (it.id in selectedLayersSet) {
                                            it.copy(parentGroupId = newGroupId)
                                        } else {
                                            it
                                        }
                                    }.toMutableList()
                                    
                                    updatedLayers.add(topIndex, newGroupLayer)
                                    
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    
                                    layers = updatedLayers
                                    selectedLayerId = newGroupId
                                    
                                    selectedLayersSet = emptySet()
                                    isMultiSelectMode = false
                                }
                            },
                            onMergeDown = { id ->
                                val activeIndex = layers.indexOfFirst { it.id == id }
                                if (activeIndex != -1 && activeIndex < layers.size - 1) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    mergeDownLayer(
                                        activeLayerIndex = activeIndex,
                                        layers = layers,
                                        canvasWidth = canvasWidth,
                                        canvasHeight = canvasHeight,
                                        context = context,
                                        imageBitmapCache = imageBitmapCache,
                                        pathCache = pathCache,
                                        pathPointsCountCache = pathPointsCountCache,
                                        dashEffect8 = dashEffect8,
                                        onLayersChanged = { 
                                            layers = it
                                        }
                                    )
                                }
                            },
                            collapsedGroupIds = collapsedGroupIds,
                            onToggleGroupCollapse = { id ->
                                collapsedGroupIds = if (collapsedGroupIds.contains(id)) {
                                    collapsedGroupIds - id
                                } else {
                                    collapsedGroupIds + id
                                }
                            },
                            modifier = Modifier
                        )
                    }
                }

                if (isLandscape && isBottomPanelVisible && activeFullScreenSheet == null) {
                    RenderBottomEffectPanel(isLandscapeMode = true)
                }
            }

            // -- BOTTOM EFFECTS & PARAMETERS PANEL / SPLIT-SHEET OVERLAY (with smooth animated transition) --
            if (activeFullScreenSheet != null) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(0.4f)
                        .background(SlatePanel)
                        .border(BorderStroke(1.2.dp, HighslateOutline))
                        .padding(horizontal = 16.dp, vertical = 8.dp)
                ) {
                    Column(modifier = Modifier.fillMaxSize()) {
                        // Header Area
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(52.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                IconButton(
                                    onClick = { activeFullScreenSheet = null },
                                    modifier = Modifier.size(36.dp)
                                ) {
                                    Icon(Icons.Default.ArrowBack, "Back", tint = EnergeticYellow, modifier = Modifier.size(24.dp))
                                }
                                Column {
                                    val headerText = when (activeFullScreenSheet) {
                                        "Color" -> "Color & Fill Designer"
                                        "Border" -> "Border & Shadows Studio"
                                        "Transform" -> "Geometrical Canvas Transforms"
                                        "Shape" -> "Edit Shape & Typography"
                                        "Effects" -> "Filters & FX Config Stack"
                                        "Brush" -> "Paint Brush Studio Settings"
                                        "Grid" -> "Grid Alignment Calibration"
                                        "Ruler" -> "Ruler Guideline Calibration"
                                        else -> "Border & Shadows Studio"
                                    }
                                    Text(headerText, style = Typography.titleMedium, color = EnergeticYellow, fontWeight = FontWeight.Bold)
                                    selectedLayer?.let {
                                        Text("Active Item: ${it.name}", style = Typography.labelSmall, color = TextSecondary, fontSize = 11.sp)
                                    }
                                }
                            }
                            
                            IconButton(
                                onClick = { activeFullScreenSheet = null },
                                modifier = Modifier.size(32.dp)
                            ) {
                                Icon(Icons.Default.Close, "Close Panel", tint = TextSecondary, modifier = Modifier.size(20.dp))
                            }
                        }
                        
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(0.5.dp)
                                .background(HighslateOutline)
                        )
                        Spacer(Modifier.height(8.dp))

                        // Render lightweight property panel inside the lower 40% bounds
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .weight(1f)
                        ) {
                            when (activeFullScreenSheet) {
                                "Color" -> {
                                    if (selectedLayer != null) {
                                        HsvColorPickerPanel(
                                            currentColor = selectedLayer.baseColor,
                                            currentOpacity = selectedLayer.opacity,
                                            onColorChanged = { newColor ->
                                                layers = layers.map { if (it.id == selectedLayer.id) it.copy(baseColor = newColor) else it }
                                            },
                                            selectedLayer = selectedLayer,
                                            onUpdateLayer = { updatedLayer ->
                                                layers = layers.map { if (it.id == updatedLayer.id) updatedLayer else it }
                                            },
                                            onOpenColorPickerDialog = { idx ->
                                                activeGradientStopIndex = idx
                                                showGradientColorPickerDialog = true
                                            },
                                            modifier = Modifier.fillMaxSize()
                                        )
                                    } else {
                                        Text("No selected shape layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }
                                "Border" -> {
                                    if (selectedLayer != null) {
                                        BordersAndShadowsTabPanel(
                                            selectedLayer = selectedLayer,
                                            onAddEffect = { effect ->
                                                undoStack.add(layers)
                                                redoStack.clear()
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        layer.copy(effects = layer.effects + effect)
                                                    } else layer
                                                }
                                                selectedEffectIndex = selectedLayer.effects.size
                                            },
                                            onUpdateEffectParam = { effectId, paramName, newValue ->
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        val updatedEffects = layer.effects.map { eff ->
                                                            if (eff.id == effectId) {
                                                                eff.updateParameter(paramName, newValue)
                                                            } else eff
                                                        }
                                                        layer.copy(effects = updatedEffects)
                                                    } else layer
                                                }
                                            }
                                        )
                                    } else {
                                        Text("No selected shape/vector layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }
                                "Transform" -> {
                                    if (selectedLayer != null) {
                                        TransformDetailView(
                                            selectedLayer = selectedLayer,
                                            onUpdateLayer = { updatedLayer ->
                                                layers = layers.map { if (it.id == updatedLayer.id) updatedLayer else it }
                                            }
                                        )
                                    } else {
                                        Text("No selected shape layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }
                                "Shape" -> {
                                    if (selectedLayer != null) {
                                        TypographyOrShapeDetailView(
                                            selectedLayer = selectedLayer,
                                            onUpdateLayer = { updatedLayer ->
                                                layers = layers.map { if (it.id == updatedLayer.id) updatedLayer else it }
                                            },
                                            fontSearchQuery = fontSearchQuery,
                                            onFontSearchQueryChange = { fontSearchQuery = it },
                                            selectedCategoryFilter = selectedCategoryFilter,
                                            onSelectedCategoryFilterChange = { selectedCategoryFilter = it },
                                            onImportFontClick = { showFontScannerDialog = true }
                                        )
                                    } else {
                                        Text("No selected shape layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }
                                "Effects" -> {
                                    if (selectedLayer != null) {
                                        FiltersAndFxDetailView(
                                            selectedLayer = selectedLayer,
                                            selectedEffectIndex = selectedEffectIndex,
                                            onSelectEffectIndex = { selectedEffectIndex = it },
                                            onRemoveEffect = { effectId ->
                                                undoStack.add(layers)
                                                redoStack.clear()
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        layer.copy(effects = layer.effects.filter { it.id != effectId })
                                                    } else layer
                                                }
                                            },
                                            onToggleEffectEnabled = { effectId ->
                                                undoStack.add(layers)
                                                redoStack.clear()
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        val updatedEffects = layer.effects.map { eff ->
                                                            if (eff.id == effectId) {
                                                                eff.toggleEnabled()
                                                            } else eff
                                                        }
                                                        layer.copy(effects = updatedEffects)
                                                    } else layer
                                                }
                                            },
                                            onUpdateEffectParam = { effectId, paramName, newValue ->
                                                com.example.studio.ui.CanvasEventLoop.emit(
                                                    com.example.studio.ui.CanvasEvent.UpdateSlider(
                                                        layerId = selectedLayer.id,
                                                        effectId = effectId,
                                                        paramName = paramName,
                                                        value = newValue
                                                    )
                                                )
                                            },
                                            onOpenEffectsGallery = { showEffectsGallery = true }
                                        )
                                    } else {
                                        Text("No selected shape layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }
                                "Brush" -> {
                                    val currentSmoothing = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                        val valSmooth = (selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect)?.parameters?.get("Smoothing")?.value ?: 0.0f
                                        valSmooth > 0.5f
                                    } else {
                                        brushSmoothing
                                    }
                                    val currentPreset = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                        val config = selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                        config?.parameters?.get("Preset")?.value?.toInt() ?: brushPresetIndex
                                    } else {
                                        brushPresetIndex
                                    }
                                    val currentSize = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                        (selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect)?.parameters?.get("Size")?.value ?: brushSize
                                    } else {
                                        brushSize
                                    }
                                    val currentOpacity = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                        (selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect)?.parameters?.get("Opacity")?.value ?: brushOpacity
                                    } else {
                                        brushOpacity
                                    }
                                    val updateBrushParamsLocal = { newSize: Float?, newOpacity: Float?, newSmooth: Boolean?, newPreset: Int?, newColor: Color? ->
                                        if (newSize != null) brushSize = newSize
                                        if (newOpacity != null) brushOpacity = newOpacity
                                        if (newSmooth != null) brushSmoothing = newSmooth
                                        if (newPreset != null) brushPresetIndex = newPreset
                                        if (newColor != null) brushColor = newColor

                                        if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                            val config = selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                            if (config != null) {
                                                var updatedConfig = config
                                                if (newSize != null) updatedConfig = updatedConfig.updateParameter("Size", newSize) as com.example.studio.model.StudioEffect.PhotoshopEffect
                                                if (newOpacity != null) updatedConfig = updatedConfig.updateParameter("Opacity", newOpacity) as com.example.studio.model.StudioEffect.PhotoshopEffect
                                                if (newSmooth != null) updatedConfig = updatedConfig.updateParameter("Smoothing", if (newSmooth) 1.0f else 0.0f) as com.example.studio.model.StudioEffect.PhotoshopEffect
                                                if (newPreset != null) updatedConfig = updatedConfig.updateParameter("Preset", newPreset.toFloat()) as com.example.studio.model.StudioEffect.PhotoshopEffect

                                                val updatedEffects = selectedLayer.effects.map { if (it.id == config.id) updatedConfig else it }
                                                layers = layers.map {
                                                    if (it.id == selectedLayer.id) {
                                                        it.copy(
                                                            baseColor = newColor ?: selectedLayer.baseColor,
                                                            effects = updatedEffects
                                                        )
                                                    } else it
                                                }
                                            } else {
                                                layers = layers.map {
                                                    if (it.id == selectedLayer.id) {
                                                        it.copy(baseColor = newColor ?: selectedLayer.baseColor)
                                                    } else it
                                                }
                                            }
                                        }
                                    }
                                    
                                    BrushStudioControlPane(
                                        currentPreset = currentPreset,
                                        currentSize = currentSize,
                                        currentOpacity = currentOpacity,
                                        currentColor = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) selectedLayer.baseColor else brushColor,
                                        currentSmoothing = currentSmoothing,
                                        updateBrushParams = updateBrushParamsLocal,
                                        onOpenBrushesLibrary = { showBrushesLibrary = true },
                                        gridEnabled = gridEnabled,
                                        onGridEnabledChange = { gridEnabled = it },
                                        rulerEnabled = rulerEnabled,
                                        onRulerEnabledChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(enabled = value) else it } },
                                        rulerOrientation = rulerOrientation,
                                        onRulerOrientationChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(orientation = value) else it } },
                                        rulerPosition = rulerPosition,
                                        onRulerPositionChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(position = value) else it } },
                                        activeTool = activeTool,
                                        eraserSize = eraserSize,
                                        onEraserSizeChange = { eraserSize = it },
                                        eraserHardness = eraserHardness,
                                        onEraserHardnessChange = { eraserHardness = it },
                                        modifier = Modifier.fillMaxSize()
                                    )
                                }
                                "Grid" -> {
                                    GridControlPane(
                                        gridEnabled = gridEnabled,
                                        onGridEnabledChange = { gridEnabled = it },
                                        gridColumns = gridColumns,
                                        onGridColumnsChange = { gridColumns = it },
                                        gridRows = gridRows,
                                        onGridRowsChange = { gridRows = it },
                                        modifier = Modifier.fillMaxSize()
                                    )
                                }
                                "Ruler" -> {
                                    val settings = WorkspaceRulerSettings(
                                        rulers = rulers,
                                        onRulersChange = { rulers = it },
                                        selectedRulerId = selectedRulerId,
                                        onSelectedRulerIdChange = { selectedRulerId = it },
                                        snapToRuler = snapToRuler,
                                        onSnapToRulerChange = { snapToRuler = it },
                                        allRulersLocked = allRulersLocked,
                                        onAllRulersLockedChange = { allRulersLocked = it }
                                    )
                                    CompositionLocalProvider(LocalRulerSettings provides settings) {
                                        Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                                            Card(
                                                colors = CardDefaults.cardColors(containerColor = MidSlate),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                                    Text("Guide Indicator Attributes", style = Typography.labelMedium, color = EnergeticYellow, fontWeight = FontWeight.Bold)
                                                    Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                                                        Text("Magnet: ${if (snapToRuler) "ON" else "OFF"}", style = Typography.labelSmall, color = if (snapToRuler) Color(0xFF00FF66) else TextSecondary)
                                                        Text("Angle Lock: ${if (allRulersLocked) "LOCKED" else "FREE"}", style = Typography.labelSmall, color = if (allRulersLocked) Color.Red else TextSecondary)
                                                    }
                                                }
                                            }
                                            RulerControlPane(
                                                modifier = Modifier.fillMaxWidth().weight(1f)
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                if (!isLandscape) {
                    AnimatedVisibility(
                        visible = isBottomPanelVisible,
                        enter = expandVertically() + fadeIn(),
                        exit = shrinkVertically() + fadeOut()
                    ) {
                        RenderBottomEffectPanel(isLandscapeMode = false)
                    }
                }
            }

            if (showEffectsGallery && selectedLayer != null) {
                EffectsGalleryOverlay(
                    onClose = { showEffectsGallery = false },
                    onAddEffect = { effect ->
                        undoStack.add(layers)
                        redoStack.clear()
                        layers = layers.map { layer ->
                            if (layer.id == selectedLayer.id) {
                                layer.copy(effects = layer.effects + effect)
                            } else layer
                        }
                        selectedEffectIndex = selectedLayer.effects.size
                    }
                )
            }

            if (showBrushesLibrary) {
                BrushesLibraryOverlay(
                    currentPreset = brushPresetIndex,
                    onPresetChange = { 
                        brushPresetIndex = it
                        if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                            layers = layers.map { layer ->
                                if (layer.id == selectedLayer.id) {
                                    val updatedEffects = layer.effects.map { eff ->
                                        if (eff.name == "BrushConfig") {
                                            eff.updateParameter("Preset", it.toFloat())
                                        } else eff
                                    }
                                    layer.copy(effects = updatedEffects)
                                } else layer
                            }
                        }
                    },
                    currentSize = brushSize,
                    onSizeChange = {
                        brushSize = it
                        if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                            layers = layers.map { layer ->
                                if (layer.id == selectedLayer.id) {
                                    val updatedEffects = layer.effects.map { eff ->
                                        if (eff.name == "BrushConfig") {
                                            eff.updateParameter("Size", it)
                                        } else eff
                                    }
                                    layer.copy(effects = updatedEffects)
                                } else layer
                            }
                        }
                    },
                    currentOpacity = brushOpacity,
                    onOpacityChange = {
                        brushOpacity = it
                        if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                            layers = layers.map { layer ->
                                if (layer.id == selectedLayer.id) {
                                    val updatedEffects = layer.effects.map { eff ->
                                        if (eff.name == "BrushConfig") {
                                            eff.updateParameter("Opacity", it)
                                        } else eff
                                    }
                                    layer.copy(effects = updatedEffects)
                                } else layer
                            }
                        }
                    },
                    currentColor = brushColor,
                    currentSmoothing = brushSmoothing,
                    onClose = { showBrushesLibrary = false }
                )
            }
        }

        // Layer renaming Dialog Box overlay to make the Layers stack completely editable
        if (renamingLayerId != null) {
            AlertDialog(
                onDismissRequest = { renamingLayerId = null },
                title = { Text("Rename Layer Source", style = Typography.titleLarge, color = TextPrimary) },
                text = {
                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Text("Provide a descriptive tag name inside the compositing list.", style = Typography.bodyMedium, color = TextSecondary)
                        OutlinedTextField(
                            value = renamingLayerName,
                            onValueChange = { renamingLayerName = it },
                            modifier = Modifier.fillMaxWidth(),
                            textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedBorderColor = IndustrialAmber,
                                unfocusedBorderColor = HighslateOutline,
                                cursorColor = IndustrialAmber
                            )
                        )
                    }
                },
                confirmButton = {
                    Button(
                        onClick = {
                            undoStack.add(layers)
                            redoStack.clear()
                            layers = layers.map {
                                if (it.id == renamingLayerId) it.copy(name = renamingLayerName) else it
                            }
                            renamingLayerId = null
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = IndustrialAmber)
                    ) {
                        Text("Rename", color = DarkOnyx, fontWeight = FontWeight.Bold)
                    }
                },
                dismissButton = {
                    TextButton(onClick = { renamingLayerId = null }) {
                        Text("Cancel", color = TextSecondary)
                    }
                },
                containerColor = SlatePanel
            )
        }

        // Advanced high-density and color-space export popup Settings Dialog
        if (showExportSettingsDialog) {
            AlertDialog(
                onDismissRequest = { showExportSettingsDialog = false },
                title = {
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        Icon(Icons.Default.Download, contentDescription = null, tint = EnergeticYellow)
                        Text("Export Pro Canvas Settings", style = Typography.titleLarge, color = TextPrimary)
                    }
                },
                text = {
                    Column(
                        modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Text("Configure your design resolution up to ultra-sharp 8K and select color spaces optimized for print or screen layout outputs.", style = Typography.bodyMedium, color = TextSecondary)
                        
                        // Section 1: Resolution Multiplier
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text("Export Resolution Preset", style = Typography.labelSmall, color = EnergeticYellow)
                            
                            val originalW = canvasWidth.toInt()
                            val originalH = canvasHeight.toInt()
                            
                            listOf(
                                Triple(1.0f, "Standard (1x)", "${originalW}x${originalH}"),
                                Triple(2.0f, "Quad HD (2x)", "${originalW * 2}x${originalH * 2}"),
                                Triple(4.0f, "Ultra HD (4x)", "${originalW * 4}x${originalH * 4}"),
                                Triple(8000f / maxOf(canvasWidth, canvasHeight), "8K Masterpiece", "${((canvasWidth * (8000f / maxOf(canvasWidth, canvasHeight)))).toInt()}x${((canvasHeight * (8000f / maxOf(canvasWidth, canvasHeight)))).toInt()}")
                            ).forEach { (mult, label, resStr) ->
                                val isSelected = exportMultiplier == mult || (mult > 7f && exportMultiplier > 7f)
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(if (isSelected) Color(0xFF1B3B2B) else Color(0xFF131317))
                                        .border(BorderStroke(if (isSelected) 1.5.dp else 1.dp, if (isSelected) Color(0xFF00FF66) else HighslateOutline), RoundedCornerShape(8.dp))
                                        .clickable { 
                                            exportMultiplier = mult 
                                        }
                                        .padding(horizontal = 12.dp, vertical = 10.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column {
                                        Text(label, style = Typography.bodyMedium, color = if (isSelected) Color(0xFF00FF66) else TextPrimary, fontWeight = FontWeight.Bold)
                                        Text(resStr, style = Typography.labelSmall, color = TextSecondary)
                                    }
                                    RadioButton(
                                        selected = isSelected,
                                        onClick = { exportMultiplier = mult },
                                        colors = RadioButtonDefaults.colors(selectedColor = Color(0xFF00FF66), unselectedColor = TextSecondary)
                                    )
                                }
                            }
                        }
                        
                        // Section 2: Color Space Profile
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text("Primary Color Space Profile", style = Typography.labelSmall, color = EnergeticYellow)
                            
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                // RGB option
                                Column(
                                    modifier = Modifier
                                        .weight(1f)
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(if (!exportIsCmyk) Color(0xFF1B3B2B) else Color(0xFF131317))
                                        .border(BorderStroke(if (!exportIsCmyk) 1.5.dp else 1.dp, if (!exportIsCmyk) Color(0xFF00FF66) else HighslateOutline), RoundedCornerShape(8.dp))
                                        .clickable { exportIsCmyk = false }
                                        .padding(12.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Text("RGB Profile", style = Typography.bodyMedium, color = if (!exportIsCmyk) Color(0xFF00FF66) else TextPrimary, fontWeight = FontWeight.Bold)
                                    Spacer(Modifier.height(4.dp))
                                    Text("Screen & Digital", style = Typography.labelSmall, color = TextSecondary, fontSize = 9.sp)
                                }
                                
                                // CMYK option
                                Column(
                                    modifier = Modifier
                                        .weight(1f)
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(if (exportIsCmyk) Color(0xFF1B3B2B) else Color(0xFF131317))
                                        .border(BorderStroke(if (exportIsCmyk) 1.5.dp else 1.dp, if (exportIsCmyk) Color(0xFF00FF66) else HighslateOutline), RoundedCornerShape(8.dp))
                                        .clickable { exportIsCmyk = true }
                                        .padding(12.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Text("CMYK Proofing", style = Typography.bodyMedium, color = if (exportIsCmyk) Color(0xFF00FF66) else TextPrimary, fontWeight = FontWeight.Bold)
                                    Spacer(Modifier.height(4.dp))
                                    Text("Offset Ink Printing", style = Typography.labelSmall, color = TextSecondary, fontSize = 9.sp)
                                }
                            }
                        }
                    }
                },
                confirmButton = {
                    Column(
                        verticalArrangement = Arrangement.spacedBy(8.dp),
                        horizontalAlignment = Alignment.End,
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Button(
                            onClick = {
                                showExportSettingsDialog = false
                                executePsdExport()
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = EnergeticYellow),
                            shape = RoundedCornerShape(6.dp),
                            modifier = Modifier.fillMaxWidth().testTag("psd_export_button")
                        ) {
                            Text("Export Layered PSD (Photoshop)", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                        }

                        Button(
                            onClick = {
                                showExportSettingsDialog = false
                                executeAlightXmlExport()
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF00FF66)),
                            shape = RoundedCornerShape(6.dp),
                            modifier = Modifier.fillMaxWidth().testTag("alight_export_button")
                        ) {
                            Text("Export Alight Motion XML Layout", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                        }

                        Button(
                            onClick = {
                                showExportSettingsDialog = false
                                executeArtworkExport(exportMultiplier, exportIsCmyk)
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF29B6F6)),
                            shape = RoundedCornerShape(6.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text("Export Flattened Canvas Image", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                        }
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showExportSettingsDialog = false }) {
                        Text("Cancel", style = Typography.labelSmall, color = TextSecondary)
                    }
                },
                containerColor = SlatePanel
            )
        }

        // --- HOVER ACTIVE GRADIENT STOP COLOR PICKER OVERLAY ---
        if (showGradientColorPickerDialog && selectedLayer != null && activeGradientStopIndex != -1) {
            val idx = activeGradientStopIndex
            val gradOverlay = selectedLayer.effects.find { it is StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? StudioEffect.PhotoshopEffect
            if (gradOverlay != null) {
                val rKey = "CustomStop_${idx}_R"
                val gKey = "CustomStop_${idx}_G"
                val bKey = "CustomStop_${idx}_B"
                val aKey = "CustomStop_${idx}_A"
                val posKey = "CustomStop_${idx}_Pos"

                val rVal = gradOverlay.parameters[rKey]?.value ?: when(idx) {
                    0 -> gradOverlay.parameters["CustomStart_R"]?.value ?: 1.0f
                    1 -> gradOverlay.parameters["CustomEnd_R"]?.value ?: 0.0f
                    else -> 0.5f
                }
                val gVal = gradOverlay.parameters[gKey]?.value ?: when(idx) {
                    0 -> gradOverlay.parameters["CustomStart_G"]?.value ?: 0.0f
                    1 -> gradOverlay.parameters["CustomEnd_G"]?.value ?: 0.0f
                    else -> 0.5f
                }
                val bVal = gradOverlay.parameters[bKey]?.value ?: when(idx) {
                    0 -> gradOverlay.parameters["CustomStart_B"]?.value ?: 0.0f
                    1 -> gradOverlay.parameters["CustomEnd_B"]?.value ?: 1.0f
                    else -> 0.5f
                }
                val aVal = gradOverlay.parameters[aKey]?.value ?: 1.0f
                val posVal = gradOverlay.parameters[posKey]?.value ?: (idx.toFloat() / ((gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt() - 1).coerceAtLeast(1))

                var r by remember(idx, selectedLayerId) { mutableStateOf(rVal) }
                var g by remember(idx, selectedLayerId) { mutableStateOf(gVal) }
                var b by remember(idx, selectedLayerId) { mutableStateOf(bVal) }
                var alpha by remember(idx, selectedLayerId) { mutableStateOf(aVal) }
                var stopPos by remember(idx, selectedLayerId) { mutableStateOf(posVal) }

                var hsv by remember(r, g, b) {
                    val hsvArr = FloatArray(3)
                    android.graphics.Color.RGBToHSV((r * 255).toInt(), (g * 255).toInt(), (b * 255).toInt(), hsvArr)
                    mutableStateOf(Triple(hsvArr[0], hsvArr[1], hsvArr[2]))
                }

                AlertDialog(
                    onDismissRequest = { showGradientColorPickerDialog = false },
                    title = {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(imageVector = Icons.Default.Palette, contentDescription = null, tint = IndustrialAmber, modifier = Modifier.size(24.dp))
                            Spacer(Modifier.width(8.dp))
                            Text("Edit Stop Node #${idx + 1}", style = Typography.titleMedium, color = TextPrimary)
                        }
                    },
                    text = {
                        Column(
                            verticalArrangement = Arrangement.spacedBy(14.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(12.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(60.dp)
                                        .clip(RoundedCornerShape(8.dp))
                                        .drawBehind {
                                            val cellSize = 8.dp.toPx()
                                            for (x in 0 until (size.width / cellSize).toInt() + 1) {
                                                for (y in 0 until (size.height / cellSize).toInt() + 1) {
                                                    val color = if ((x + y) % 2 == 0) Color(0xFFD0D0D4) else Color(0xFFFFFFFF)
                                                    drawRect(
                                                        color = color,
                                                        topLeft = Offset(x * cellSize, y * cellSize),
                                                        size = Size(cellSize, cellSize)
                                                    )
                                                }
                                            }
                                        }
                                        .background(Color(r, g, b, alpha))
                                        .border(1.dp, Color(0x33FFFFFF), RoundedCornerShape(8.dp))
                                )
                                Column(
                                    verticalArrangement = Arrangement.spacedBy(4.dp),
                                    modifier = Modifier.weight(1f)
                                ) {
                                    val hexCode = String.format("#%02X%02X%02X%02X", (alpha * 255).toInt(), (r * 255).toInt(), (g * 255).toInt(), (b * 255).toInt())
                                    Text("RGBA Hex: $hexCode", style = Typography.labelSmall, color = TextPrimary)
                                    Text("Position: ${(stopPos * 100).toInt()}%", style = Typography.labelSmall, color = TextSecondary)
                                }
                                
                                Button(
                                    onClick = {
                                        GradientEyedropperState.isActive = true
                                        showGradientColorPickerDialog = false
                                    },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = if (GradientEyedropperState.isActive) IndustrialAmber else Color(0xFF161622)
                                    ),
                                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                                    modifier = Modifier.height(32.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Colorize,
                                        contentDescription = "Canvas Eyedropper",
                                        tint = if (GradientEyedropperState.isActive) Color.Black else Color.White,
                                        modifier = Modifier.size(13.dp)
                                    )
                                    Spacer(Modifier.width(4.dp))
                                    Text("Sample Canvas", style = Typography.labelSmall.copy(fontSize = 10.sp), color = if (GradientEyedropperState.isActive) Color.Black else Color.White)
                                }
                            }

                            Box(
                                modifier = Modifier
                                    .size(150.dp)
                                    .clip(CircleShape)
                                    .border(1.dp, HighslateOutline, CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Canvas(
                                    modifier = Modifier
                                        .fillMaxSize()
                                        .pointerInput(idx) {
                                            detectTapGestures { offset ->
                                                val centerX = size.width / 2f
                                                val centerY = size.height / 2f
                                                val dx = offset.x - centerX
                                                val dy = offset.y - centerY
                                                val dist = kotlin.math.sqrt(dx * dx + dy * dy)
                                                val maxRadius = size.width / 2f
                                                if (dist <= maxRadius) {
                                                    val angleRad = kotlin.math.atan2(dy, dx)
                                                    val angleDeg = (Math.toDegrees(angleRad.toDouble()).toFloat() + 360f) % 360f
                                                    val sat = (dist / maxRadius).coerceIn(0f, 1f)
                                                    hsv = Triple(angleDeg, sat, hsv.third)
                                                    
                                                    val rgbInt = android.graphics.Color.HSVToColor(floatArrayOf(hsv.first, hsv.second, hsv.third))
                                                    r = android.graphics.Color.red(rgbInt) / 255f
                                                    g = android.graphics.Color.green(rgbInt) / 255f
                                                    b = android.graphics.Color.blue(rgbInt) / 255f
                                                }
                                            }
                                        }
                                        .pointerInput(idx) {
                                            detectDragGestures { change, _ ->
                                                val centerX = size.width / 2f
                                                val centerY = size.height / 2f
                                                val dx = change.position.x - centerX
                                                val dy = change.position.y - centerY
                                                val dist = kotlin.math.sqrt(dx * dx + dy * dy)
                                                val maxRadius = size.width / 2f
                                                val angleRad = kotlin.math.atan2(dy, dx)
                                                val angleDeg = (Math.toDegrees(angleRad.toDouble()).toFloat() + 360f) % 360f
                                                val sat = (dist / maxRadius).coerceIn(0f, 1f)
                                                hsv = Triple(angleDeg, sat, hsv.third)

                                                val rgbInt = android.graphics.Color.HSVToColor(floatArrayOf(hsv.first, hsv.second, hsv.third))
                                                r = android.graphics.Color.red(rgbInt) / 255f
                                                g = android.graphics.Color.green(rgbInt) / 255f
                                                b = android.graphics.Color.blue(rgbInt) / 255f
                                            }
                                        }
                                ) {
                                    val centerX = size.width / 2f
                                    val centerY = size.height / 2f
                                    val radius = size.width / 2f
                                    
                                    val sweepBrush = androidx.compose.ui.graphics.Brush.sweepGradient(
                                        colors = listOf(
                                            Color.Red, Color.Yellow, Color.Green, Color.Cyan, Color.Blue, Color.Magenta, Color.Red
                                        ),
                                        center = Offset(centerX, centerY)
                                    )
                                    drawCircle(brush = sweepBrush, radius = radius)
                                    
                                    val radialBrush = androidx.compose.ui.graphics.Brush.radialGradient(
                                        colors = listOf(Color.White, Color.Transparent),
                                        center = Offset(centerX, centerY),
                                        radius = radius
                                    )
                                    drawCircle(brush = radialBrush, radius = radius)

                                    val handleAngleRad = Math.toRadians(hsv.first.toDouble())
                                    val handleDist = hsv.second * radius
                                    val handleX = centerX + handleDist * kotlin.math.cos(handleAngleRad).toFloat()
                                    val handleY = centerY + handleDist * kotlin.math.sin(handleAngleRad).toFloat()
                                    
                                    drawCircle(
                                        color = Color.Black,
                                        radius = 7.dp.toPx(),
                                        center = Offset(handleX, handleY)
                                    )
                                    drawCircle(
                                        color = Color.White,
                                        radius = 5.dp.toPx(),
                                        center = Offset(handleX, handleY)
                                    )
                                }
                            }

                            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Brightness (Value)", style = Typography.labelSmall, color = TextSecondary)
                                    Text("${(hsv.third * 100).toInt()}%", style = Typography.labelSmall, color = TextPrimary)
                                }
                                Slider(
                                    value = hsv.third,
                                    onValueChange = { newVal ->
                                        hsv = Triple(hsv.first, hsv.second, newVal)
                                        val rgbInt = android.graphics.Color.HSVToColor(floatArrayOf(hsv.first, hsv.second, hsv.third))
                                        r = android.graphics.Color.red(rgbInt) / 255f
                                        g = android.graphics.Color.green(rgbInt) / 255f
                                        b = android.graphics.Color.blue(rgbInt) / 255f
                                    },
                                    valueRange = 0f..1f,
                                    colors = SliderDefaults.colors(
                                        activeTrackColor = IndustrialAmber,
                                        thumbColor = Color.White
                                    )
                                )
                            }

                            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Opacity (Stop Alpha)", style = Typography.labelSmall, color = TextSecondary)
                                    Text("${(alpha * 100).toInt()}%", style = Typography.labelSmall, color = TextPrimary)
                                }
                                Slider(
                                    value = alpha,
                                    onValueChange = { alpha = it },
                                    valueRange = 0f..1f,
                                    colors = SliderDefaults.colors(
                                        activeTrackColor = IndustrialAmber,
                                        thumbColor = Color.White
                                    )
                                )
                            }

                            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Stop Position along line", style = Typography.labelSmall, color = TextSecondary)
                                    Text("${(stopPos * 100).toInt()}%", style = Typography.labelSmall, color = TextPrimary)
                                }
                                Slider(
                                    value = stopPos,
                                    onValueChange = { stopPos = it },
                                    valueRange = 0f..1f,
                                    colors = SliderDefaults.colors(
                                        activeTrackColor = EnergeticYellow,
                                        thumbColor = Color.White
                                    )
                                )
                            }
                        }
                    },
                    confirmButton = {
                        TextButton(
                            onClick = {
                                val updatedGo = gradOverlay.updateParameter("CustomStop_${idx}_R", r)
                                    .updateParameter("CustomStop_${idx}_G", g)
                                    .updateParameter("CustomStop_${idx}_B", b)
                                    .updateParameter("CustomStop_${idx}_A", alpha)
                                    .updateParameter("CustomStop_${idx}_Pos", stopPos)
                                
                                val nextEffects = selectedLayer.effects.map { if (it.id == gradOverlay.id) updatedGo else it }
                                val updatedLayer = selectedLayer.copy(effects = nextEffects)
                                
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == selectedLayer.id) updatedLayer else it }
                                showGradientColorPickerDialog = false
                            }
                        ) {
                            Text("Apply Aesthetics", color = EnergeticYellow, style = Typography.labelSmall)
                        }
