                            Button(onClick = { onSpawnShape("Vector Triangle", LayerType.VECTOR_TRIANGLE, Color(0xFFFFB300), 180f, 180f, false) }, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = MidSlate)) {
