@Composable
fun PresetSilhouette(index: Int, isSelected: Boolean) {
    Box(
        modifier = Modifier
            .size(48.dp)
            .background(if (isSelected) IndustrialAmber.copy(0.08f) else MidSlate, RoundedCornerShape(8.dp))
            .border(BorderStroke(1.dp, if (isSelected) IndustrialAmber.copy(0.6f) else HighslateOutline.copy(alpha = 0.4f)), RoundedCornerShape(8.dp)),
        contentAlignment = Alignment.Center
    ) {
        Canvas(modifier = Modifier.size(28.dp)) {
            val color = if (isSelected) IndustrialAmber else TextSecondary.copy(alpha = 0.7f)
            val stroke = Stroke(
                width = 1.5.dp.toPx(),
                pathEffect = PathEffect.dashPathEffect(floatArrayOf(5f, 5f), 0f)
            )
            val fillBrush = androidx.compose.ui.graphics.Brush.linearGradient(
                colors = if (isSelected) listOf(IndustrialAmber.copy(alpha = 0.2f), EnergeticYellow.copy(alpha = 0.05f))
                        else listOf(Color.Transparent, Color.Transparent)
            )
            
            when (index) {
                0 -> { // Perfect Fit (Device Screen) - Draw a phone outline
                    val w = 11.dp.toPx()
                    val h = 23.dp.toPx()
                    val topLeft = Offset((size.width - w) / 2, (size.height - h) / 2)
                    drawRect(
                        brush = fillBrush,
                        topLeft = topLeft,
                        size = Size(w, h)
                    )
                    drawRect(
                        color = color,
                        topLeft = topLeft,
                        size = Size(w, h),
                        style = stroke
                    )
                    // Tiny notch at top
                    drawLine(
                        color = color,
                        start = Offset(size.width / 2 - 2.dp.toPx(), topLeft.y + 1.5.dp.toPx()),
                        end = Offset(size.width / 2 + 2.dp.toPx(), topLeft.y + 1.5.dp.toPx()),
                        strokeWidth = 1f
                    )
                    // Home indicator at bottom
                    drawLine(
                        color = color,
                        start = Offset(size.width / 2 - 3.dp.toPx(), topLeft.y + h - 1.5.dp.toPx()),
                        end = Offset(size.width / 2 + 3.dp.toPx(), topLeft.y + h - 1.5.dp.toPx()),
                        strokeWidth = 1f
                    )
                }
                1 -> { // Instagram Portrait (4:5)
                    val w = 16.dp.toPx()
                    val h = 20.dp.toPx()
                    val topLeft = Offset((size.width - w) / 2, (size.height - h) / 2)
                    drawRect(
                        brush = fillBrush,
                        topLeft = topLeft,
                        size = Size(w, h)
                    )
                    drawRect(
                        color = color,
                        topLeft = topLeft,
                        size = Size(w, h),
                        style = stroke
                    )
                }
                2 -> { // Instagram Story (9:16)
                    val w = 12.dp.toPx()
                    val h = 21.33.dp.toPx()
                    val topLeft = Offset((size.width - w) / 2, (size.height - h) / 2)
                    drawRect(
                        brush = fillBrush,
                        topLeft = topLeft,
                        size = Size(w, h)
                    )
                    drawRect(
                        color = color,
                        topLeft = topLeft,
                        size = Size(w, h),
                        style = stroke
                    )
                }
                3 -> { // Square (1:1)
                    val w = 18.dp.toPx()
                    val h = 18.dp.toPx()
                    val topLeft = Offset((size.width - w) / 2, (size.height - h) / 2)
                    drawRect(
                        brush = fillBrush,
                        topLeft = topLeft,
                        size = Size(w, h)
                    )
                    drawRect(
                        color = color,
                        topLeft = topLeft,
                        size = Size(w, h),
                        style = stroke
                    )
                }
                4 -> { // FHD Landscape (16:9)
                    val w = 24.dp.toPx()
                    val h = 13.5.dp.toPx()
                    val topLeft = Offset((size.width - w) / 2, (size.height - h) / 2)
                    drawRect(
                        brush = fillBrush,
                        topLeft = topLeft,
                        size = Size(w, h)
                    )
                    drawRect(
                        color = color,
                        topLeft = topLeft,
                        size = Size(w, h),
                        style = stroke
                    )
                }
                5 -> { // Modern Poster (3:4)
                    val w = 16.dp.toPx()
                    val h = 21.33.dp.toPx()
                    val topLeft = Offset((size.width - w) / 2, (size.height - h) / 2)
                    drawRect(
                        brush = fillBrush,
                        topLeft = topLeft,
                        size = Size(w, h)
                    )
                    drawRect(
                        color = color,
                        topLeft = topLeft,
                        size = Size(w, h),
                        style = stroke
                    )
                }
                else -> { // Custom size (crosshair dynamic target representation)
                    drawLine(
                        color = color,
                        start = Offset(2.dp.toPx(), size.height / 2),
                        end = Offset(size.width - 2.dp.toPx(), size.height / 2),
                        strokeWidth = 1.dp.toPx()
                    )
                    drawLine(
                        color = color,
                        start = Offset(size.width / 2, 2.dp.toPx()),
                        end = Offset(size.width / 2, size.height - 2.dp.toPx()),
                        strokeWidth = 1.dp.toPx()
                    )
                    drawCircle(
                        color = color,
                        radius = 4.dp.toPx(),
                        center = Offset(size.width / 2, size.height / 2),
                        style = stroke
                    )
                }
            }
        }
    }
}

@Composable
fun CanvasSetupScreen(
    canvasWidthInput: String,
    canvasHeightInput: String,
    selectedPresetIndex: Int,
    onWidthChange: (String) -> Unit,
    onHeightChange: (String) -> Unit,
    onPresetSelect: (Int) -> Unit,
    onInitialize: (Int) -> Unit,
    previousProjects: List<ProjectEntity>,
    onLoadProject: (ProjectEntity) -> Unit,
    onDeleteProject: (String) -> Unit,
    onRenameProject: (ProjectEntity, String) -> Unit,
    onImportPsdRequest: () -> Unit,
    onImportAlightRequest: () -> Unit
) {
    var activeMenuTab by remember { mutableStateOf(0) } // 0 for Create Canvas, 1 for Previous Projects
    var activeUnit by remember { mutableStateOf("Pixels") }
    var physicalWidthInput by remember { mutableStateOf("8.5") }
    var physicalHeightInput by remember { mutableStateOf("11.0") }
    var targetDpiOption by remember { mutableStateOf(300) } // 72, 150, 300, 0 (custom)
    var customDpiText by remember { mutableStateOf("300") }

    val evaluatedDpi = if (targetDpiOption > 0) targetDpiOption else (customDpiText.toIntOrNull() ?: 300).coerceIn(1, 1200)

    androidx.compose.runtime.LaunchedEffect(
        activeUnit, physicalWidthInput, physicalHeightInput, targetDpiOption, customDpiText
    ) {
        if (activeUnit == "Inches") {
            val wValue = physicalWidthInput.toFloatOrNull() ?: 8.5f
            val hValue = physicalHeightInput.toFloatOrNull() ?: 11.0f
            val computedW = (wValue * evaluatedDpi).toInt().coerceIn(100, 8000)
            val computedH = (hValue * evaluatedDpi).toInt().coerceIn(100, 8000)
            onWidthChange(computedW.toString())
            onHeightChange(computedH.toString())
        } else if (activeUnit == "Centimeters") {
            val wValue = physicalWidthInput.toFloatOrNull() ?: 21.0f
            val hValue = physicalHeightInput.toFloatOrNull() ?: 29.7f
            val computedW = ((wValue / 2.54f) * evaluatedDpi).toInt().coerceIn(100, 8000)
            val computedH = ((hValue / 2.54f) * evaluatedDpi).toInt().coerceIn(100, 8000)
            onWidthChange(computedW.toString())
            onHeightChange(computedH.toString())
        }
    }

    androidx.compose.runtime.LaunchedEffect(selectedPresetIndex) {
        if (selectedPresetIndex != 6) {
            activeUnit = "Pixels"
        }
    }

    val layerCounts = remember { androidx.compose.runtime.mutableStateMapOf<String, Int>() }
    androidx.compose.runtime.LaunchedEffect(previousProjects) {
        val newCounts = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Default) {
            previousProjects.mapNotNull { proj ->
                if (!layerCounts.containsKey(proj.id)) {
                    val count = try {
                        val layerList = LayerSerializer.deserialize(proj.layersJson)
                        layerList.size
                    } catch (e: Exception) { 0 }
                    proj.id to count
                } else null
            }
        }
        newCounts.forEach { (id, count) ->
            layerCounts[id] = count
        }
    }

    // States for manage dialogs inside lander
    var projectToRename by remember { mutableStateOf<ProjectEntity?>(null) }
    var renameValue by remember { mutableStateOf("") }
    var projectToDeleteId by remember { mutableStateOf<String?>(null) }

    // Aspect ratio locking states
    var isRatioLocked by remember { mutableStateOf(false) }
    var lockedRatio by remember { mutableStateOf(1080f / 1350f) }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(DarkOnyx)
            .drawBehind {
                // Draw luxury engineering blueprint grid lines
                val gridSize = 42.dp.toPx()
                val baseLinePaint = Color(0xFF161922)
                val accentLinePaint = Color(0xFF1E2230)
                
                // Horizontal lines
                val stepSizeVal = gridSize.toInt().coerceAtLeast(10)
                for (y in 0..size.height.toInt() step stepSizeVal) {
                    drawLine(
                        color = if (y % (stepSizeVal * 4) == 0) accentLinePaint else baseLinePaint,
                        start = Offset(0f, y.toFloat()),
                        end = Offset(size.width, y.toFloat()),
                        strokeWidth = if (y % (stepSizeVal * 4) == 0) 1.5f else 0.8f
                    )
                }
                // Vertical lines
                for (x in 0..size.width.toInt() step stepSizeVal) {
                    drawLine(
                        color = if (x % (stepSizeVal * 4) == 0) accentLinePaint else baseLinePaint,
                        start = Offset(x.toFloat(), 0f),
                        end = Offset(x.toFloat(), size.height),
                        strokeWidth = if (x % (stepSizeVal * 4) == 0) 1.5f else 0.8f
                    )
                }

                // Smooth luxury glow points
                drawCircle(
                    color = IndustrialAmber.copy(alpha = 0.04f),
                    radius = 350.dp.toPx(),
                    center = Offset(0f, 0f)
                )
                drawCircle(
                    color = Color.Cyan.copy(alpha = 0.02f),
                    radius = 450.dp.toPx(),
                    center = Offset(size.width, size.height)
                )
            }
            .windowInsetsPadding(WindowInsets.statusBars)
            .windowInsetsPadding(WindowInsets.navigationBars)
            .padding(16.dp),
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(0.95f)
                .verticalScroll(rememberScrollState()),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(20.dp)
        ) {
            // Elegant premium studio branding header card
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 12.dp),
                colors = CardDefaults.cardColors(containerColor = SlatePanel.copy(alpha = 0.85f)),
                border = BorderStroke(1.dp, HighslateOutline.copy(alpha = 0.6f)),
                shape = RoundedCornerShape(16.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 20.dp, horizontal = 24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Zenith Studio Brand Logo & Wordmark
                    Row(
                        modifier = Modifier
                            .padding(bottom = 12.dp),
                        horizontalArrangement = Arrangement.Center,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Canvas(modifier = Modifier.size(56.dp)) {
                            val w = size.width
                            val h = size.height
                            val strokeZ = androidx.compose.ui.graphics.drawscope.Stroke(
                                width = 5.dp.toPx(),
                                join = androidx.compose.ui.graphics.StrokeJoin.Miter,
                                cap = androidx.compose.ui.graphics.StrokeCap.Square
                            )
                            val pathZ = Path().apply {
                                moveTo(w * 0.15f, h * 0.22f)
                                lineTo(w * 0.65f, h * 0.22f)
                                lineTo(w * 0.25f, h * 0.78f)
                                lineTo(w * 0.60f, h * 0.78f)
                            }
                            drawPath(pathZ, color = Color.White, style = strokeZ)

                            val pathS = Path().apply {
                                moveTo(w * 0.42f, h * 0.42f)
                                lineTo(w * 0.85f, h * 0.42f)
                                lineTo(w * 0.45f, h * 0.60f)
                                lineTo(w * 0.85f, h * 0.60f)
                                lineTo(w * 0.85f, h * 0.78f)
                                lineTo(w * 0.40f, h * 0.78f)
                            }
                            drawPath(pathS, color = Color.White, style = strokeZ)
                        }
                        Spacer(modifier = Modifier.width(16.dp))
                        Column(
                            verticalArrangement = Arrangement.Center
                        ) {
                            Text(
                                text = "ZENITH",
                                style = Typography.displaySmall.copy(
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 24.sp,
                                    letterSpacing = 2.sp,
                                    color = Color.White
                                )
                            )
                            Text(
                                text = "STUDIO",
                                style = Typography.bodyMedium.copy(
                                    fontWeight = FontWeight.W300,
                                    fontSize = 20.sp,
                                    letterSpacing = 2.sp,
                                    color = Color.White
                                )
                            )
                        }
                    }
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "NEON VECTOR DESIGN SUITE",
                        style = Typography.labelMedium.copy(
                            fontWeight = FontWeight.Bold,
                            letterSpacing = 3.sp,
                            color = TextSecondary
                        )
                    )
                    
                    Spacer(modifier = Modifier.height(10.dp))
                    
                    // Small status badge
                    Box(
                        modifier = Modifier
                            .background(IndustrialAmber.copy(0.1f), RoundedCornerShape(12.dp))
                            .border(BorderStroke(1.dp, IndustrialAmber.copy(0.25f)), RoundedCornerShape(12.dp))
                            .padding(horizontal = 10.dp, vertical = 4.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(6.dp)
                                    .background(IndustrialAmber, RoundedCornerShape(3.dp))
                            )
                            Text(
                                "GPU CORE v1.4 • HARDWARE ACCELERATED RENDERER",
                                style = Typography.labelSmall.copy(
                                    fontSize = 8.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = IndustrialAmber
                                )
                            )
                        }
                    }
                }
            }

            // Dual Tab Panel for clean Workspace separation
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(SlatePanel, RoundedCornerShape(12.dp))
                    .padding(4.dp),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                listOf("Create Canvas", "Previous Projects", "Import Layout").forEachIndexed { tabIdx, tabTitle ->
                    val isTabSelected = activeMenuTab == tabIdx
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .clip(RoundedCornerShape(8.dp))
                            .background(if (isTabSelected) IndustrialAmber else Color.Transparent)
                            .clickable { activeMenuTab = tabIdx }
                            .padding(vertical = 12.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.Center
                        ) {
                            Icon(
                                imageVector = when (tabIdx) {
                                    0 -> Icons.Default.AddCircleOutline
                                    1 -> Icons.Default.FolderSpecial
                                    else -> Icons.Default.FileOpen
                                },
                                contentDescription = null,
                                tint = if (isTabSelected) DarkOnyx else TextSecondary,
                                modifier = Modifier.size(18.dp)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = tabTitle,
                                style = Typography.bodyMedium.copy(fontSize = 11.sp),
                                fontWeight = if (isTabSelected) FontWeight.Bold else FontWeight.Medium,
                                color = if (isTabSelected) DarkOnyx else TextSecondary,
                                maxLines = 1
                            )
                            if (tabIdx == 1 && previousProjects.isNotEmpty()) {
                                Spacer(modifier = Modifier.width(6.dp))
                                Box(
                                    modifier = Modifier
                                        .background(if (isTabSelected) DarkOnyx else IndustrialAmber, RoundedCornerShape(10.dp))
                                        .padding(horizontal = 6.dp, vertical = 2.dp)
                                ) {
                                    Text(
                                        text = previousProjects.size.toString(),
                                        style = Typography.labelSmall,
                                        fontWeight = FontWeight.Bold,
                                        color = if (isTabSelected) IndustrialAmber else DarkOnyx
                                    )
                                }
                            }
                        }
                    }
                }
            }

            if (activeMenuTab == 0) {
                // Setup Details Card
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    colors = CardDefaults.cardColors(containerColor = SlatePanel.copy(alpha = 0.85f)),
                    border = BorderStroke(1.dp, HighslateOutline.copy(alpha = 0.5f)),
                    shape = RoundedCornerShape(16.dp)
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "CANVAS PRESETS",
                                style = Typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                                color = TextPrimary
                            )
                            Text(
                                text = "Touch below to choose a viewport size",
                                style = Typography.labelSmall,
                                color = TextSecondary.copy(alpha = 0.7f)
                            )
                        }

                        val displayMetrics = androidx.compose.ui.platform.LocalContext.current.resources.displayMetrics
                        val screenW = displayMetrics.widthPixels.toFloat()
                        val screenH = displayMetrics.heightPixels.toFloat()
                        val deviceAspect = if (screenW > 0) screenH / screenW else 1350f / 1080f

                        // Presets Grid Layout - 2 columns
                        val presets = listOf(
                            Triple("Perfect Fit (Device Screen)", "${screenW.toInt()} x ${screenH.toInt()} px", "Tailored to your exact screen size"),
                            Triple("Instagram Portrait (4:5)", "1080 x 1350 px", "Recommended for portrait content"),
                            Triple("Instagram Story (9:16)", "1080 x 1920 px", "Full immersive vertical layout"),
                            Triple("Square Grid (1:1)", "1080 x 1080 px", "Standard social grid post"),
                            Triple("FHD Landscape (16:9)", "1920 x 1080 px", "Standard presentation landscape"),
                            Triple("Modern Poster (3:4)", "1200 x 1600 px", "Premium physical printing proportion"),
                            Triple("Custom Dimensions", "Custom pixels", "Fully custom pixel resolution")
                        )

                        Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                            presets.chunked(2).forEach { rowPair ->
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    rowPair.forEach { preset ->
                                        val index = presets.indexOf(preset)
                                        val isSelected = selectedPresetIndex == index
                                        
                                        Box(
                                            modifier = Modifier
                                                .weight(1f)
                                                .padding(bottom = if (isSelected) 4.dp else 0.dp, end = if (isSelected) 4.dp else 0.dp)
                                        ) {
                                            if (isSelected) {
                                                Box(
                                                    modifier = Modifier
                                                        .matchParentSize()
                                                        .offset(x = 4.dp, y = 4.dp)
                                                        .background(SlatePanel.copy(alpha = 0.4f), RoundedCornerShape(12.dp))
                                                        .border(BorderStroke(1.dp, HighslateOutline.copy(alpha = 0.2f)), RoundedCornerShape(12.dp))
                                                )
                                            }
                                            Card(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .offset(x = if (isSelected) (-2).dp else 0.dp, y = if (isSelected) (-2).dp else 0.dp)
                                                    .clickable {
                                                        onPresetSelect(index)
                                                        val nextRatio = when (index) {
                                                            0 -> 1f / deviceAspect
                                                            1 -> 1080f / 1350f
                                                            2 -> 1080f / 1920f
                                                            3 -> 1f
                                                            4 -> 1920f / 1080f
                                                            5 -> 1200f / 1600f
                                                            else -> {
                                                                val wFloat = canvasWidthInput.toFloatOrNull() ?: 1080f
                                                                val hFloat = canvasHeightInput.toFloatOrNull() ?: 1350f
                                                                if (hFloat > 0f) wFloat / hFloat else 1f
                                                            }
                                                        }
                                                        lockedRatio = nextRatio
                                                    },
                                                shape = RoundedCornerShape(12.dp),
                                                colors = CardDefaults.cardColors(
                                                    containerColor = if (isSelected) MidSlate.copy(alpha = 0.65f) else SlatePanel.copy(alpha = 0.3f)
                                                ),
                                                border = BorderStroke(
                                                    1.2.dp,
                                                    if (isSelected) IndustrialAmber else HighslateOutline.copy(alpha = 0.3f)
                                                )
                                            ) {
                                            Column(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .padding(10.dp),
                                                horizontalAlignment = Alignment.CenterHorizontally,
                                                verticalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                // Dynamic silhouetted preview box
                                                PresetSilhouette(index = index, isSelected = isSelected)
                                                
                                                Column(
                                                    horizontalAlignment = Alignment.CenterHorizontally,
                                                    verticalArrangement = Arrangement.spacedBy(2.dp)
                                                ) {
                                                    Text(
                                                        text = preset.first.substringBefore(" ("),
                                                        style = Typography.bodyMedium.copy(fontWeight = FontWeight.Bold, fontSize = 12.sp),
                                                        color = if (isSelected) TextPrimary else TextSecondary,
                                                        textAlign = TextAlign.Center,
                                                        maxLines = 1
                                                    )
                                                    Text(
                                                        text = preset.second,
                                                        style = Typography.labelSmall.copy(fontWeight = FontWeight.SemiBold, fontSize = 10.sp),
                                                        color = if (isSelected) EnergeticYellow else TextSecondary.copy(alpha = 0.6f),
                                                        textAlign = TextAlign.Center
                                                    )
                                                }
                                            }
                                        }
                                        }
                                    }
                                }
                            }
                        }

                        // Divider helper
                        Box(modifier = Modifier.fillMaxWidth().height(1.dp).background(HighslateOutline.copy(alpha = 0.5f)))

                        // Unit Selector Tab Row
                        Text(
                            text = "MEASUREMENT UNIT PLANE",
                            style = Typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                            color = TextPrimary
                        )

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(SlatePanel.copy(alpha = 0.5f), RoundedCornerShape(10.dp))
                                .padding(4.dp),
                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                        ) {
                            listOf("Pixels", "Inches", "Centimeters").forEach { u ->
                                val isSelected = activeUnit == u
                                Box(
                                    modifier = Modifier
                                        .weight(1f)
                                        .background(if (isSelected) IndustrialAmber else Color.Transparent, RoundedCornerShape(8.dp))
                                        .clickable {
                                            activeUnit = u
                                            if (u != "Pixels") {
                                                if (u == "Inches") {
                                                    physicalWidthInput = "8.5"
                                                    physicalHeightInput = "11.0"
                                                } else {
                                                    physicalWidthInput = "21.0"
                                                    physicalHeightInput = "29.7"
                                                }
                                                val wF = physicalWidthInput.toFloatOrNull() ?: 8.5f
                                                val hF = physicalHeightInput.toFloatOrNull() ?: 11f
                                                lockedRatio = if (hF > 0f) wF / hF else 1f
                                            } else {
                                                val wF = canvasWidthInput.toFloatOrNull() ?: 1080f
                                                val hF = canvasHeightInput.toFloatOrNull() ?: 1350f
                                                lockedRatio = if (hF > 0f) wF / hF else 1f
                                            }
                                        }
                                        .padding(vertical = 8.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = u.uppercase(),
                                        style = Typography.labelMedium.copy(fontWeight = FontWeight.Bold, fontSize = 11.sp),
                                        color = if (isSelected) DarkOnyx else TextSecondary
                                    )
                                }
                            }
                        }

                        // Width & Height inputs based on selected measurement plane
                        Text(
                            text = "DIMENSION CONFIGURATION (" + activeUnit.uppercase() + ")",
                            style = Typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                            color = TextPrimary,
                            modifier = Modifier.padding(top = 4.dp)
                        )

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = "Width",
                                    style = Typography.labelMedium,
                                    color = TextSecondary,
                                    modifier = Modifier.padding(bottom = 4.dp)
                                )
                                if (activeUnit == "Pixels") {
                                    OutlinedTextField(
                                        value = canvasWidthInput,
                                        onValueChange = { newVal ->
                                            onWidthChange(newVal)
                                            if (isRatioLocked) {
                                                val wFloat = newVal.toFloatOrNull()
                                                if (wFloat != null) {
                                                    val calcH = (wFloat / lockedRatio).toInt().coerceIn(100, 8000)
                                                    onHeightChange(calcH.toString())
                                                }
                                            }
                                        },
                                        modifier = Modifier.fillMaxWidth().testTag("canvas_width_input"),
                                        textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                                        singleLine = true,
                                        suffix = { Text("px", color = TextSecondary, fontSize = 11.sp) },
                                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                            keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                                        ),
                                        colors = OutlinedTextFieldDefaults.colors(
                                            focusedBorderColor = IndustrialAmber,
                                            unfocusedBorderColor = HighslateOutline,
                                            cursorColor = IndustrialAmber,
                                            focusedContainerColor = MidSlate.copy(0.3f),
                                            unfocusedContainerColor = Color.Transparent
                                        )
                                    )
                                } else {
                                    OutlinedTextField(
                                        value = physicalWidthInput,
                                        onValueChange = { newVal ->
                                            physicalWidthInput = newVal
                                            if (isRatioLocked) {
                                                val wFloat = newVal.toFloatOrNull()
                                                if (wFloat != null) {
                                                    val calcH = (wFloat / lockedRatio)
                                                    physicalHeightInput = String.format(java.util.Locale.US, "%.2f", calcH)
                                                }
                                            }
                                        },
                                        modifier = Modifier.fillMaxWidth().testTag("physical_width_input"),
                                        textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                                        singleLine = true,
                                        suffix = { Text(if (activeUnit == "Inches") "in" else "cm", color = TextSecondary, fontSize = 11.sp) },
                                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                            keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                                        ),
                                        colors = OutlinedTextFieldDefaults.colors(
                                            focusedBorderColor = IndustrialAmber,
                                            unfocusedBorderColor = HighslateOutline,
                                            cursorColor = IndustrialAmber,
                                            focusedContainerColor = MidSlate.copy(0.3f),
                                            unfocusedContainerColor = Color.Transparent
                                        )
                                    )
                                }
                            }

                            // Dynamic aspect lock toggling link button
                            IconButton(
                                onClick = {
                                    isRatioLocked = !isRatioLocked
                                    if (isRatioLocked) {
                                        if (activeUnit == "Pixels") {
                                            val w = canvasWidthInput.toFloatOrNull() ?: 1080f
                                            val h = canvasHeightInput.toFloatOrNull() ?: 1350f
                                            lockedRatio = if (h > 0f) w / h else 1f
                                        } else {
                                            val w = physicalWidthInput.toFloatOrNull() ?: 8.5f
                                            val h = physicalHeightInput.toFloatOrNull() ?: 11.0f
                                            lockedRatio = if (h > 0f) w / h else 1f
                                        }
                                    }
                                },
                                modifier = Modifier
                                    .padding(top = 22.dp)
                                    .size(42.dp)
                                    .background(if (isRatioLocked) IndustrialAmber.copy(0.12f) else MidSlate.copy(0.3f), RoundedCornerShape(10.dp))
                                    .border(BorderStroke(1.dp, if (isRatioLocked) IndustrialAmber else HighslateOutline.copy(0.5f)), RoundedCornerShape(10.dp))
                            ) {
                                Icon(
                                    imageVector = if (isRatioLocked) Icons.Default.Link else Icons.Default.LinkOff,
                                    contentDescription = "Lock Ratio Limit",
                                    tint = if (isRatioLocked) IndustrialAmber else TextSecondary,
                                    modifier = Modifier.size(20.dp)
                                )
                            }

                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = "Height",
                                    style = Typography.labelMedium,
                                    color = TextSecondary,
                                    modifier = Modifier.padding(bottom = 4.dp)
                                )
                                if (activeUnit == "Pixels") {
                                    OutlinedTextField(
                                        value = canvasHeightInput,
                                        onValueChange = { newVal ->
                                            onHeightChange(newVal)
                                            if (isRatioLocked) {
                                                val hFloat = newVal.toFloatOrNull()
                                                if (hFloat != null) {
                                                    val calcW = (hFloat * lockedRatio).toInt().coerceIn(100, 8000)
                                                    onWidthChange(calcW.toString())
                                                }
                                            }
                                        },
                                        modifier = Modifier.fillMaxWidth().testTag("canvas_height_input"),
                                        textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                                        singleLine = true,
                                        suffix = { Text("px", color = TextSecondary, fontSize = 11.sp) },
                                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                            keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                                        ),
                                        colors = OutlinedTextFieldDefaults.colors(
                                            focusedBorderColor = IndustrialAmber,
                                            unfocusedBorderColor = HighslateOutline,
                                            cursorColor = IndustrialAmber,
                                            focusedContainerColor = MidSlate.copy(0.3f),
                                            unfocusedContainerColor = Color.Transparent
                                        )
                                    )
                                } else {
                                    OutlinedTextField(
                                        value = physicalHeightInput,
                                        onValueChange = { newVal ->
                                            physicalHeightInput = newVal
                                            if (isRatioLocked) {
                                                val hFloat = newVal.toFloatOrNull()
                                                if (hFloat != null) {
                                                    val calcW = (hFloat * lockedRatio)
                                                    physicalWidthInput = String.format(java.util.Locale.US, "%.2f", calcW)
                                                }
                                            }
                                        },
                                        modifier = Modifier.fillMaxWidth().testTag("physical_height_input"),
                                        textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                                        singleLine = true,
                                        suffix = { Text(if (activeUnit == "Inches") "in" else "cm", color = TextSecondary, fontSize = 11.sp) },
                                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                            keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                                        ),
                                        colors = OutlinedTextFieldDefaults.colors(
                                            focusedBorderColor = IndustrialAmber,
                                            unfocusedBorderColor = HighslateOutline,
                                            cursorColor = IndustrialAmber,
                                            focusedContainerColor = MidSlate.copy(0.3f),
                                            unfocusedContainerColor = Color.Transparent
                                        )
                                    )
                                }
                            }
                        }

                        // DPI Configuration Matrix
                        Text(
                            text = "TARGET RESOLUTION DENSITY (DPI)",
                            style = Typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                            color = TextPrimary,
                            modifier = Modifier.padding(top = 4.dp)
                        )

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            listOf(
                                72 to "72 DPI\n(Digital/Web)",
                                150 to "150 DPI\n(Draft Print)",
                                300 to "300 DPI\n(Pro HD Print)"
                            ).forEach { (dpi, label) ->
                                val isSelected = targetDpiOption == dpi
                                Card(
                                    modifier = Modifier
                                        .weight(1f)
                                        .clickable {
                                            targetDpiOption = dpi
                                        },
                                    colors = CardDefaults.cardColors(
                                        containerColor = if (isSelected) MidSlate.copy(alpha = 0.65f) else SlatePanel.copy(alpha = 0.3f)
                                    ),
                                    border = BorderStroke(
                                        1.dp,
                                        if (isSelected) IndustrialAmber else HighslateOutline.copy(alpha = 0.3f)
                                    ),
                                    shape = RoundedCornerShape(10.dp)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(vertical = 10.dp, horizontal = 4.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Text(
                                            text = label,
                                            style = Typography.bodyMedium.copy(fontWeight = FontWeight.Bold, fontSize = 11.sp),
                                            color = if (isSelected) TextPrimary else TextSecondary,
                                            textAlign = TextAlign.Center
                                        )
                                    }
                                }
                            }
                            
                            val isCustomSelected = targetDpiOption == 0
                            Card(
                                modifier = Modifier
                                    .weight(1f)
                                    .clickable {
                                        targetDpiOption = 0
                                    },
                                colors = CardDefaults.cardColors(
                                    containerColor = if (isCustomSelected) MidSlate.copy(alpha = 0.65f) else SlatePanel.copy(alpha = 0.3f)
                                ),
                                border = BorderStroke(
                                    1.dp,
                                    if (isCustomSelected) IndustrialAmber else HighslateOutline.copy(alpha = 0.3f)
                                ),
                                shape = RoundedCornerShape(10.dp)
                            ) {
                                Column(
                                    modifier = Modifier.padding(vertical = 10.dp, horizontal = 4.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Text(
                                        text = "Custom\nDPI",
                                        style = Typography.bodyMedium.copy(fontWeight = FontWeight.Bold, fontSize = 11.sp),
                                        color = if (isCustomSelected) TextPrimary else TextSecondary,
                                        textAlign = TextAlign.Center
                                    )
                                }
                            }
                        }

                        if (targetDpiOption == 0) {
                            OutlinedTextField(
                                value = customDpiText,
                                onValueChange = { customDpiText = it },
                                label = { Text("Custom Target DPI Density", color = TextSecondary) },
                                textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                                singleLine = true,
                                keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                    keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                                ),
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedBorderColor = IndustrialAmber,
                                    unfocusedBorderColor = HighslateOutline,
                                    focusedContainerColor = MidSlate.copy(0.3f),
                                    unfocusedContainerColor = Color.Transparent
                                ),
                                modifier = Modifier.fillMaxWidth().testTag("custom_dpi_input")
                            )
                        }

                        // Live Conversion Explanation Block
                        val explanationText = when (activeUnit) {
                            "Inches" -> {
                                val wIn = physicalWidthInput.toFloatOrNull() ?: 8.5f
                                val hIn = physicalHeightInput.toFloatOrNull() ?: 11.0f
                                val wPx = (wIn * evaluatedDpi).toInt()
                                val hPx = (hIn * evaluatedDpi).toInt()
                                " CONVERSION FORMULA:\nWidth: $wIn in × $evaluatedDpi DPI = $wPx px\nHeight: $hIn in × $evaluatedDpi DPI = $hPx px"
                            }
                            "Centimeters" -> {
                                val wCm = physicalWidthInput.toFloatOrNull() ?: 21.0f
                                val hCm = physicalHeightInput.toFloatOrNull() ?: 29.7f
                                val wIn = wCm / 2.54f
                                val hIn = hCm / 2.54f
                                val wPx = (wIn * evaluatedDpi).toInt()
                                val hPx = (hIn * evaluatedDpi).toInt()
                                " CONVERSION FORMULA (cm → in → px):\nWidth: ($wCm cm ÷ 2.54) × $evaluatedDpi DPI = $wPx px\nHeight: ($hCm cm ÷ 2.54) × $evaluatedDpi DPI = $hPx px"
                            }
                            else -> {
                                "Direct Pixel Plane Mapping Configured."
                            }
                        }

                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFF161922).copy(alpha = 0.5f)),
                            border = BorderStroke(1.dp, HighslateOutline.copy(0.3f)),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Column(
                                modifier = Modifier.padding(12.dp),
                                verticalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Text(
                                    text = " PHYSICAL RESOLUTION TRANSLATION",
                                    style = Typography.labelMedium.copy(fontWeight = FontWeight.Bold, color = EnergeticYellow)
                                )
                                Text(
                                    text = explanationText,
                                    style = androidx.compose.ui.text.TextStyle(fontSize = 11.sp, fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace, color = TextSecondary),
                                    lineHeight = 16.sp
                                )
                            }
                        }
                    }
                }

                // Validation info bounds
                val wVal = canvasWidthInput.toIntOrNull()
                val hVal = canvasHeightInput.toIntOrNull()
                val isInputValid = wVal != null && hVal != null && wVal in 100..8000 && hVal in 100..8000

                if (!isInputValid) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color(0xFF33161A), RoundedCornerShape(8.dp))
                            .border(BorderStroke(1.dp, Color.Red.copy(0.3f)), RoundedCornerShape(8.dp))
                            .padding(10.dp)
                    ) {
                        Text(
                            text = "Warning: Calculated dimensions must resolve between 100px and 8000px threshold.",
                            style = Typography.labelSmall,
                            color = Color(0xFFFF8A80),
                            modifier = Modifier.align(Alignment.Center)
                        )
                    }
                }

                // Start Workspace CTA Button
                Button(
                    onClick = { onInitialize(evaluatedDpi) },
                    enabled = isInputValid,
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(56.dp)
                        .testTag("initialize_workspace_button"),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = IndustrialAmber,
                        disabledContainerColor = MidSlate
                    ),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Icon(
                            imageVector = Icons.Default.Palette,
                            contentDescription = null,
                            tint = if (isInputValid) DarkOnyx else TextSecondary
                        )
                        Text(
                            text = "INITIALIZE CREATIVE CANVAS",
                            color = if (isInputValid) DarkOnyx else TextSecondary,
                            style = Typography.titleMedium.copy(fontWeight = FontWeight.Bold)
                        )
                    }
                }
                Spacer(modifier = Modifier.height(12.dp))
            } else if (activeMenuTab == 1) {
                // Recent Projects Tab
                if (previousProjects.isEmpty()) {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        colors = CardDefaults.cardColors(containerColor = SlatePanel.copy(alpha = 0.85f)),
                        border = BorderStroke(1.dp, HighslateOutline.copy(alpha = 0.5f)),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(36.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            // High fidelity abstract blueprint drawing in Compose Canvas
                            Canvas(modifier = Modifier.size(100.dp)) {
                                val gold = IndustrialAmber
                                val gray = TextSecondary.copy(alpha = 0.4f)
                                val stroke = Stroke(width = 1.5.dp.toPx(), pathEffect = PathEffect.dashPathEffect(floatArrayOf(6f, 6f), 0f))
                                
                                // Draw layout bounding box
                                drawRect(
                                    color = gold.copy(0.2f),
                                    topLeft = Offset(10.dp.toPx(), 15.dp.toPx()),
                                    size = Size(80.dp.toPx(), 70.dp.toPx()),
                                    style = stroke
                                )
                                
                                // Draw ruler guide alignment markers
                                drawLine(color = gold.copy(0.5f), start = Offset(10.dp.toPx(), 50.dp.toPx()), end = Offset(90.dp.toPx(), 50.dp.toPx()), strokeWidth = 1f.dp.toPx())
                                drawLine(color = gold.copy(0.5f), start = Offset(50.dp.toPx(), 15.dp.toPx()), end = Offset(50.dp.toPx(), 85.dp.toPx()), strokeWidth = 1f.dp.toPx())
                                
                                // Bezier control nodes representing active vector layers
                                drawCircle(color = gold, radius = 5.dp.toPx(), center = Offset(30.dp.toPx(), 50.dp.toPx()))
                                drawCircle(color = Color.Cyan, radius = 5.dp.toPx(), center = Offset(70.dp.toPx(), 50.dp.toPx()))
                                
                                val curvePath = Path().apply {
                                    moveTo(15.dp.toPx(), 65.dp.toPx())
                                    quadraticTo(
                                        50.dp.toPx(), 20.dp.toPx(),
                                        85.dp.toPx(), 65.dp.toPx()
                                    )
                                }
                                drawPath(path = curvePath, color = Color.White.copy(alpha = 0.6f), style = Stroke(width = 2.dp.toPx()))
                            }
                            
                            Text(
                                text = "Your Creative Vault is Empty",
                                style = Typography.bodyLarge,
                                fontWeight = FontWeight.Bold,
                                color = TextPrimary
                            )
                            Text(
                                text = "Every vector masterpiece you compose inside the editor will automatically persist safely in local storage as a quick-resume draft.",
                                style = Typography.bodyMedium,
                                color = TextSecondary,
                                textAlign = TextAlign.Center,
                                modifier = Modifier.padding(horizontal = 24.dp)
                            )
                            Button(
                                onClick = { activeMenuTab = 0 },
                                colors = ButtonDefaults.buttonColors(containerColor = IndustrialAmber),
                                shape = RoundedCornerShape(8.dp),
                                modifier = Modifier.padding(top = 8.dp)
                            ) {
                                Icon(Icons.Default.AddCircleOutline, null, tint = DarkOnyx, modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(8.dp))
                                Text("New Design Canvas", color = DarkOnyx, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                } else {
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "SAVED GRAPHICS ARCHIVE",
                                style = Typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                                color = TextPrimary
                            )
                            Text(
                                text = "${previousProjects.size} Designs Stored",
                                style = Typography.labelSmall,
                                color = IndustrialAmber,
                                fontWeight = FontWeight.Bold
                            )
                        }

                        // Highly visible explanation about the direct export feature on home screen
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(IndustrialAmber.copy(0.12f), RoundedCornerShape(8.dp))
                                .border(0.5.dp, IndustrialAmber.copy(0.4f), RoundedCornerShape(8.dp))
                                .padding(10.dp)
                        ) {
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Download,
                                    contentDescription = "Instant Export Info",
                                    tint = EnergeticYellow,
                                    modifier = Modifier.size(16.dp)
                                )
                                Text(
                                    text = "Tip: Tap the bright yellow Download icon on any project's card below to instantly export it as a PNG image to your Gallery!",
                                    style = Typography.labelSmall.copy(fontSize = 10.sp),
                                    color = TextPrimary
                                )
                            }
                        }

                        previousProjects.forEach { proj ->
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(bottom = 6.dp, end = 6.dp)
                            ) {
                                // Background offset shadow card for stacked physical aesthetics
                                Box(
                                    modifier = Modifier
                                        .matchParentSize()
                                        .offset(x = 6.dp, y = 6.dp)
                                        .background(SlatePanel.copy(alpha = 0.4f), RoundedCornerShape(16.dp))
                                        .border(BorderStroke(1.2.dp, HighslateOutline.copy(alpha = 0.25f)), RoundedCornerShape(16.dp))
                                )
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .border(BorderStroke(1.2.dp, HighslateOutline.copy(alpha = 0.6f)), RoundedCornerShape(16.dp))
                                        .clickable { onLoadProject(proj) },
                                    colors = CardDefaults.cardColors(containerColor = SlatePanel.copy(alpha = 0.8f)),
                                    shape = RoundedCornerShape(16.dp)
                                ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    // Left Section: Elegant circular initials avatar & meta text specs
                                    Row(
                                        modifier = Modifier.weight(1f),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(14.dp)
                                    ) {
                                        val isPortrait = proj.height > proj.width
                                        val isLandscape = proj.width > proj.height
                                        val count = layerCounts[proj.id] ?: 0

                                        // Glowing initial initials avatar
                                        val initials = proj.name.take(2).uppercase()
                                        Box(
                                            modifier = Modifier
                                                .size(48.dp)
                                                .background(
                                                    brush = androidx.compose.ui.graphics.Brush.linearGradient(
                                                        colors = listOf(
                                                            IndustrialAmber.copy(0.12f),
                                                            EnergeticYellow.copy(0.04f)
                                                        )
                                                    ),
                                                    shape = RoundedCornerShape(10.dp)
                                                )
                                                .border(BorderStroke(1.dp, IndustrialAmber.copy(0.3f)), RoundedCornerShape(10.dp)),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(
                                                text = initials,
                                                style = Typography.titleMedium.copy(fontWeight = FontWeight.Bold, fontSize = 15.sp),
                                                color = EnergeticYellow
                                            )
                                        }

                                        Column {
                                            Text(
                                                text = proj.name,
                                                style = Typography.bodyMedium,
                                                fontWeight = FontWeight.Bold,
                                                color = TextPrimary
                                            )
                                            Spacer(modifier = Modifier.height(4.dp))
                                            val dateStr = java.text.SimpleDateFormat(
                                                "MMM dd, HH:mm",
                                                java.util.Locale.getDefault()
                                            ).format(java.util.Date(proj.timestamp))
                                            
                                            // Badges row
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Box(
                                                    modifier = Modifier
                                                        .background(MidSlate.copy(0.5f), RoundedCornerShape(4.dp))
                                                        .padding(horizontal = 5.dp, vertical = 2.dp)
                                                ) {
                                                    Text(
                                                        text = "${proj.width.toInt()}×${proj.height.toInt()} px",
                                                        style = Typography.labelSmall.copy(fontSize = 9.sp, fontWeight = FontWeight.Bold, color = TextPrimary)
                                                    )
                                                }
                                                Box(
                                                    modifier = Modifier
                                                        .background(IndustrialAmber.copy(0.1f), RoundedCornerShape(4.dp))
                                                        .padding(horizontal = 5.dp, vertical = 2.dp)
                                                ) {
                                                    Text(
                                                        text = "$count layers",
                                                        style = Typography.labelSmall.copy(fontSize = 9.sp, fontWeight = FontWeight.Bold, color = IndustrialAmber)
                                                    )
                                                }
                                                Text(
                                                    text = dateStr,
                                                    style = Typography.labelSmall.copy(fontSize = 9.sp),
                                                    color = TextSecondary
                                                )
                                            }
                                        }
                                    }

                                    // Right Section: Action icon toolbar
                                    Row(
                                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        // Direct Instant Export Button on Home Screen Card
                                        val homeContext = androidx.compose.ui.platform.LocalContext.current
                                        val homeScope = androidx.compose.runtime.rememberCoroutineScope()
                                        IconButton(
                                            onClick = {
                                                android.widget.Toast.makeText(homeContext, "Preparing background PNG export...", android.widget.Toast.LENGTH_SHORT).show()
                                                homeScope.launch {
                                                    try {
                                                        val decodedLayers = withContext(Dispatchers.Default) {
                                                            LayerSerializer.deserialize(proj.layersJson)
                                                        }
                                                        
                                                        val exportedBitmap = withContext(Dispatchers.Default) {
                                                            exportCanvasToBitmap(
                                                                context = homeContext,
                                                                canvasWidth = proj.width,
                                                                canvasHeight = proj.height,
                                                                layers = decodedLayers,
                                                                imageBitmapCache = emptyMap()
                                                            )
                                                        }
                                                        
                                                        val filename = proj.name + "_Direct_" + System.currentTimeMillis()
                                                        val uri = withContext(Dispatchers.IO) {
                                                            saveBitmapToGallery(homeContext, exportedBitmap, filename, try { proj.dpi } catch (e: Exception) { 300 })
                                                        }
                                                        
                                                        if (uri != null) {
                                                            android.widget.Toast.makeText(homeContext, "Exported '${proj.name}' successfully to Gallery!", android.widget.Toast.LENGTH_LONG).show()
                                                        } else {
                                                            android.widget.Toast.makeText(homeContext, "Export failed. Please verify storage state.", android.widget.Toast.LENGTH_LONG).show()
                                                        }
                                                    } catch (e: Throwable) {
                                                        android.widget.Toast.makeText(homeContext, "Export error: ${e.localizedMessage ?: e.javaClass.simpleName}", android.widget.Toast.LENGTH_LONG).show()
                                                    }
                                                }
                                            }
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Download,
                                                contentDescription = "Direct Instant Export",
                                                tint = EnergeticYellow,
                                                modifier = Modifier.size(22.dp)
                                            )
                                        }

                                        IconButton(
                                            onClick = {
                                                projectToRename = proj
                                                renameValue = proj.name
                                            }
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.DriveFileRenameOutline,
                                                contentDescription = "Rename Project",
                                                tint = EnergeticYellow,
                                                modifier = Modifier.size(20.dp)
                                            )
                                        }

                                        IconButton(
                                            onClick = {
                                                projectToDeleteId = proj.id
                                            }
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.DeleteForever,
                                                contentDescription = "Delete Project",
                                                tint = Color.Red.copy(0.8f),
                                                modifier = Modifier.size(20.dp)
                                            )
                                        }
                                    }
                                }
                            }
                            }
                        }
                    }
                }
            } else {
                // Compositions / Import Services Tab (activeMenuTab == 2)
                Column(
                    modifier = Modifier
                        .fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(16.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Card 1: PSD Engine
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        colors = CardDefaults.cardColors(containerColor = SlatePanel.copy(alpha = 0.85f)),
                        border = BorderStroke(1.dp, HighslateOutline.copy(alpha = 0.5f)),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(24.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            Canvas(modifier = Modifier.size(80.dp)) {
                                val gold = EnergeticYellow
                                val blueAccent = Color(0xFF29B6F6)
                                val stroke = Stroke(width = 2.dp.toPx(), pathEffect = PathEffect.dashPathEffect(floatArrayOf(8f, 8f), 0f))
                                
                                drawRoundRect(
                                    color = blueAccent.copy(0.4f),
                                    topLeft = Offset(8.dp.toPx(), 8.dp.toPx()),
                                    size = Size(64.dp.toPx(), 64.dp.toPx()),
                                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(6.dp.toPx(), 6.dp.toPx()),
                                    style = stroke
                                )
                                
                                drawRect(color = gold.copy(0.15f), topLeft = Offset(20.dp.toPx(), 20.dp.toPx()), size = Size(40.dp.toPx(), 12.dp.toPx()))
                                drawRect(color = blueAccent.copy(0.15f), topLeft = Offset(20.dp.toPx(), 36.dp.toPx()), size = Size(40.dp.toPx(), 12.dp.toPx()))
                                drawRect(color = gold.copy(0.15f), topLeft = Offset(20.dp.toPx(), 52.dp.toPx()), size = Size(40.dp.toPx(), 12.dp.toPx()))
                            }

                            Text(
                                text = "ADOBE PHOTOSHOP PSD ENGINE",
                                style = Typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                                color = TextPrimary
                            )

                            Text(
                                text = "Extract and reassemble layered PSD compositions directly into fully editable vector/image layers. Supports RAW/RLE channels, transparencies, custom boundaries, bounds, and resolution checks.",
                                style = Typography.bodyMedium,
                                color = TextSecondary,
                                textAlign = TextAlign.Center
                            )

                            Button(
                                onClick = { onImportPsdRequest() },
                                colors = ButtonDefaults.buttonColors(containerColor = EnergeticYellow),
                                shape = RoundedCornerShape(10.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("psd_launcher_button")
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                    modifier = Modifier.padding(vertical = 4.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.FileOpen,
                                        contentDescription = "Select Photoshop File",
                                        tint = DarkOnyx
                                    )
                                    Text(
                                        "BROWSE AND IMPORT PSD",
                                        color = DarkOnyx,
                                        fontWeight = FontWeight.Bold,
                                        style = Typography.labelLarge
                                    )
                                }
                            }
                        }
                    }

                    // Card 2: Alight Motion XML Engine
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        colors = CardDefaults.cardColors(containerColor = SlatePanel.copy(alpha = 0.85f)),
                        border = BorderStroke(1.dp, HighslateOutline.copy(alpha = 0.5f)),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(24.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            Canvas(modifier = Modifier.size(80.dp)) {
                                val neonGreen = Color(0xFF00FF66)
                                val deepGreen = Color(0xFF1B5E20)
                                val stroke = Stroke(width = 2.dp.toPx(), pathEffect = PathEffect.dashPathEffect(floatArrayOf(8f, 8f), 0f))
                                
                                drawRoundRect(
                                    color = neonGreen.copy(0.3f),
                                    topLeft = Offset(8.dp.toPx(), 8.dp.toPx()),
                                    size = Size(64.dp.toPx(), 64.dp.toPx()),
                                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(6.dp.toPx(), 6.dp.toPx()),
                                    style = stroke
                                )
                                
                                drawCircle(
                                    color = neonGreen.copy(0.15f),
                                    radius = 16.dp.toPx(),
                                    center = Offset(40.dp.toPx(), 40.dp.toPx())
                                )
                                drawRect(
                                    color = neonGreen.copy(0.15f), 
                                    topLeft = Offset(24.dp.toPx(), 34.dp.toPx()), 
                                    size = Size(32.dp.toPx(), 12.dp.toPx())
                                )
                            }

                            Text(
                                text = "ALIGHT MOTION COMPATIBLE XML",
                                style = Typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                                color = TextPrimary
                            )

                            Text(
                                text = "Bi-directionally parse Alight Motion design templates into native layered canvas designs, or output layered compositions back into production-compatible Alight XML scenes.",
                                style = Typography.bodyMedium,
                                color = TextSecondary,
                                textAlign = TextAlign.Center
                            )

                            Button(
                                onClick = { onImportAlightRequest() },
                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF00FF66)),
                                shape = RoundedCornerShape(10.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("alight_launcher_button")
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                    modifier = Modifier.padding(vertical = 4.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.FileOpen,
                                        contentDescription = "Select Alight XML File",
                                        tint = DarkOnyx
                                    )
                                    Text(
                                        "BROWSE AND IMPORT ALIGHT XML",
                                        color = DarkOnyx,
                                        fontWeight = FontWeight.Bold,
                                        style = Typography.labelLarge
                                    )
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))
                }
            }
        }
    }

    // Rename project alert dialog inside landing screen
    if (projectToRename != null) {
        AlertDialog(
            onDismissRequest = { projectToRename = null },
            title = { Text("Rename Design Masterpiece", color = TextPrimary, style = Typography.titleMedium) },
            text = {
                OutlinedTextField(
                    value = renameValue,
                    onValueChange = { renameValue = it },
                    label = { Text("New Design Title", style = Typography.bodyMedium) },
                    textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = IndustrialAmber,
                        focusedLabelColor = IndustrialAmber,
                        cursorColor = IndustrialAmber,
                        unfocusedBorderColor = HighslateOutline,
                        unfocusedLabelColor = TextSecondary
                    ),
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth()
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        val proj = projectToRename
                        if (proj != null && renameValue.isNotBlank()) {
                            onRenameProject(proj, renameValue.trim())
                        }
                        projectToRename = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = IndustrialAmber)
                ) {
                    Text("RENAME", color = DarkOnyx, fontWeight = FontWeight.Bold, style = Typography.bodyMedium)
                }
            },
            dismissButton = {
                TextButton(onClick = { projectToRename = null }) {
                    Text("CANCEL", color = TextSecondary, style = Typography.bodyMedium)
                }
            },
            containerColor = SlatePanel,
            shape = RoundedCornerShape(12.dp)
        )
    }

    // Delete project alert dialog inside landing screen
    if (projectToDeleteId != null) {
        val deleteId = projectToDeleteId!!
        AlertDialog(
            onDismissRequest = { projectToDeleteId = null },
            title = { Text("Delete Design Masterpiece?", color = TextPrimary, style = Typography.titleMedium) },
            text = { Text("This will permanently remove this project and all its vector layers configuration from local storage. This action cannot be undone.", color = TextSecondary, style = Typography.bodyMedium) },
            confirmButton = {
                Button(
                    onClick = {
                        onDeleteProject(deleteId)
                        projectToDeleteId = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color.Red)
                ) {
                    Text("DELETE PERMANENTLY", color = Color.White, fontWeight = FontWeight.Bold, style = Typography.bodyMedium)
                }
            },
            dismissButton = {
                TextButton(onClick = { projectToDeleteId = null }) {
                    Text("CANCEL", color = TextSecondary, style = Typography.bodyMedium)
                }
            },
            containerColor = SlatePanel,
            shape = RoundedCornerShape(12.dp)
        )
    }
}

private fun getEffectDescription(effectType: String): String {
    return when (effectType) {
        // Layer Styles
        "DropShadow" -> "Adds a soft, customizable gradient depth shadow projecting behind layer boundaries."
        "InnerShadow" -> "Casts a smooth shadow along the interior edges, nesting the object inside the canvas."
        "OuterGlow" -> "Radiates a vibrant surrounding halo of colorful energy outward from layer boundaries."
        "InnerGlow" -> "Generates a clean ambient light source radiating inward from the perimeter edges."
        "BevelEmboss" -> "Applies 3D lighting highlights and edge contours to simulate chiseled depths."
        "Satin" -> "Generates beautiful glass-like wavy internal shading with metallic or silky qualities."
        "ColorOverlay" -> "Fills layer shapes with a solid color transition and opacity masking layers."
        "GradientOverlay" -> "Paints a highly customized linear or radial multi-stop directional color gradient."
        "PatternOverlay" -> "Fills layer contents with a repeating tile texture overlay model."
        "Stroke" -> "Traces the structural borders with a highly sharp primary outline stroke."

        // Core Filters
        "GaussianBlur" -> "Smoothly blurs pixel details using a standard non-destructive Gaussian bell curve distribution."
        "MotionBlur" -> "Simulates dynamic camera motion blur along adjustable directions and distances."
        "RadialBlur" -> "Casts spinning rotation or zoom blurs projecting from the center outwards."
        "LensBlur" -> "Simulates high-end professional camera aperture bokeh depth of field effects."
        "Pinch" -> "Displaces pixel coordinates inward or outward around a centered pinching node."
        "Ripple" -> "Applies organic undulating wavefront ripples along the layer boundaries."
        "Spherize" -> "Wraps the physical layout onto a spherical projection dome to add curved perspective."
        "Twirl" -> "Twists pixel coordinates in a localized spiral vortex around the layer's center."
        "Wave" -> "Deforms the geometry using clean continuous sine or cosine waves."
        "ZigZag" -> "Generates rigid, highly geometric zigzag noise offsets radiating from the center."
        "AddNoise" -> "Overlays a vintage film and digital sensor granular noise texture model."
        "Despeckle" -> "Traces and cleans localized speckle noise to smooth the digital output."
        "DustScratches" -> "Traces small foreign dots and scratches and blends them using neighborhood values."
        "Median" -> "Replaces pixel intensities with mid-range neighborhood values to reduce fine noise."
        "ColorHalftone" -> "Mimics classic printed retro halftone dots on separate CMYK color channels."
        "Crystallize" -> "Clumps adjacent pixels into gorgeous solid crystal polygonal shapes."
        "Mosaic" -> "Bridges classic pixelation square tiles often used for censoring or abstract art."
        "Pointillize" -> "Breaks down shapes into beautiful separate colored pointillism dots."
        "Clouds" -> "Procedurally generates dynamic gaseous noise clouds like natural smoke elements."
        "LensFlare" -> "Simulates cinematic vintage glass aperture element lens reflections and center hot spots."
        "LightingEffects" -> "Casts spotlights and directional bulbs onto the canvas layer."
        "UnsharpMask" -> "Boosts extreme border contrasts to recover lost edge details and crispness."
        "SmartSharpen" -> "Utilizes advanced detection algorithms to intelligently sharpen edge detail while ignoring flat regions."
        "HighPass" -> "Isolates and extracts high-frequency structural lines and edge detail."
        "FindEdges" -> "Traces the structural outline edges to construct highly organic neon-like line drawings."
        "Emboss" -> "Transforms shapes into standard raised or stamped paper contours."
        "OilPaint" -> "Applies thick virtual oil paint brush stroke textures across flat color transitions."
        "Solarize" -> "Partially inverts dark and bright values based on an adjustable luminance threshold."
        "Wind" -> "Applies high-speed directional kinetic wind noise streaks looking like particle storms."

        // Filter Gallery
        "Artistic" -> "Mimics traditional painting formats like colored pencils, fresco, poster edges, and dry brush."
        "BrushStrokes" -> "Applies specific virtual painting brushes like spatter, crosshatch, and sumi-e ink."
        "Sketch" -> "Converts artwork to stylized pencil sketch, bas-relief, charcoal, or photocopy."
        "Texture" -> "Embeds rich structural surfaces like stained glass, craquelure, patchwork, or canvas."

        // Advanced & AI Engines
        "Liquify" -> "Launches high-performance interactive pixel pushing, puckering, bloating, and warping brushes."
        "CameraRaw" -> "Brings professional color grading dials including exposure, contrast, clarity, and vibrance."
        "NeuralFilters" -> "Leverages machine learning processors to perform skin smoothing and facial adjust tweaks."
        else -> "Photoshop non-destructive filter engine."
    }
}

@Composable
fun EffectsGalleryOverlay(
    onClose: () -> Unit,
    onAddEffect: (StudioEffect) -> Unit
) {
    var searchQuery by remember { mutableStateOf("") }
    var selectedCategory by remember { mutableStateOf("Experimental") }

    val categoriesAlight = listOf("Experimental", "Color & Light", "Drawing & Edge", "Blur", "Distortion/Warp")

    androidx.compose.ui.window.Dialog(
        onDismissRequest = onClose,
        properties = androidx.compose.ui.window.DialogProperties(
            usePlatformDefaultWidth = false,
            dismissOnBackPress = true,
            dismissOnClickOutside = true
        )
    ) {
        Surface(
            modifier = Modifier.fillMaxSize(),
            color = Color(0xFF131317)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp)
            ) {
                // Header Area
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 12.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        IconButton(onClick = onClose, modifier = Modifier.size(36.dp)) {
                            Icon(
                                imageVector = Icons.Default.ArrowBack,
                                contentDescription = "Back to canvas",
                                tint = EnergeticYellow,
                                modifier = Modifier.size(24.dp)
                            )
                        }
                        Column {
                            Text(
                                text = "Filters & FX Library",
                                style = Typography.titleLarge,
                                color = TextPrimary,
                                fontWeight = FontWeight.Bold
                            )
                            Text(
                                text = "Instantly project non-destructive visual layers onto your canvas graphics.",
                                style = Typography.labelSmall,
                                color = TextSecondary,
                                fontSize = 11.sp
                            )
                        }
                    }
                    IconButton(onClick = onClose, modifier = Modifier.size(32.dp)) {
                        Icon(Icons.Default.Close, "Dismiss Browser", tint = TextSecondary, modifier = Modifier.size(20.dp))
                    }
                }

                // Search Bar
                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { searchQuery = it },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(48.dp),
                    leadingIcon = {
                        Icon(Icons.Default.Search, "Search FX", tint = TextSecondary, modifier = Modifier.size(16.dp))
                    },
                    placeholder = {
                        Text("Search 40+ high-fidelity VFX and layer styles...", style = Typography.labelSmall, color = TextSecondary)
                    },
                    singleLine = true,
                    textStyle = Typography.labelSmall.copy(color = TextPrimary),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = Color(0xFF00FFCC),
                        unfocusedBorderColor = HighslateOutline,
                        cursorColor = Color(0xFF00FFCC)
                    )
                )

                Spacer(Modifier.height(12.dp))

                // Horizontal Category Tab Slider Panel
                if (searchQuery.isBlank()) {
                    androidx.compose.foundation.lazy.LazyRow(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 4.dp)
                    ) {
                        items(categoriesAlight.size) { index ->
                            val cat = categoriesAlight[index]
                            val isSelected = cat == selectedCategory
                            
                            // Visual category color highlights
                            val themeColor = when (cat) {
                                "Experimental" -> Color(0xFFFFB300)
                                "Color & Light" -> Color(0xFF00FFCC)
                                "Drawing & Edge" -> Color(0xFFE91E63)
                                "Blur" -> Color(0xFF29B6F6)
                                "Distortion/Warp" -> Color(0xFFFF007F)
                                else -> IndustrialAmber
                            }

                            Box(
                                modifier = Modifier
                                    .clip(RoundedCornerShape(16.dp))
                                    .background(if (isSelected) themeColor.copy(alpha = 0.15f) else Color(0xFF1E1E24))
                                    .border(
                                        BorderStroke(
                                            if (isSelected) 1.5.dp else 0.5.dp,
                                            if (isSelected) themeColor else HighslateOutline
                                        ),
                                        RoundedCornerShape(16.dp)
                                    )
                                    .clickable { selectedCategory = cat }
                                    .padding(horizontal = 14.dp, vertical = 8.dp)
                            ) {
                                Text(
                                    text = cat,
                                    style = Typography.labelSmall,
                                    color = if (isSelected) themeColor else TextSecondary,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 11.sp
                                )
                            }
                        }
                    }
                    Spacer(Modifier.height(12.dp))
                }

                // Map FX list to Alight standard categories
                val activeCategoryEffects = remember(selectedCategory, searchQuery) {
                    val allTypes = listOf(
                        // Experimental
                        "Clouds", "LensFlare", "Crystallize", "Pointillize", "PixelStretch", "NeuralFilters",
                        // Color & Light
                        "ColorGrading", "ColorOverlay", "GradientOverlay", "Solarize", "CameraRaw", "OuterGlow", "InnerGlow", "LightingEffects",
                        // Drawing & Edge
                        "FindEdges", "Emboss", "Stroke", "OilPaint", "PatternOverlay", "BevelEmboss", "Satin", "UnsharpMask", "SmartSharpen", "HighPass",
                        // Blur
                        "GaussianBlur", "MotionBlur", "RadialBlur", "LensBlur", "AddNoise", "Despeckle", "DustScratches", "Median",
                        // Distortion/Warp
                        "Pinch", "Ripple", "Spherize", "Twirl", "Wave", "ZigZag", "GlassMorphism", "ReededGlass", "Liquify", "Mosaic", "Wind"
                    )

                    allTypes.map { type ->
                        PhotoshopEffectTemplates.create(effectType = type) as StudioEffect.PhotoshopEffect
                    }.filter { eff ->
                        val matchesSearch = searchQuery.isBlank() || eff.name.contains(searchQuery, ignoreCase = true) || eff.effectType.contains(searchQuery, ignoreCase = true)
                        if (!matchesSearch) return@filter false
                        
                        if (searchQuery.isNotBlank()) return@filter true

                        // Category distribution mapping
                        when (selectedCategory) {
                            "Experimental" -> eff.effectType in listOf("Clouds", "LensFlare", "Crystallize", "Pointillize", "PixelStretch", "NeuralFilters")
                            "Color & Light" -> eff.effectType in listOf("ColorGrading", "ColorOverlay", "GradientOverlay", "Solarize", "CameraRaw", "OuterGlow", "InnerGlow", "LightingEffects")
                            "Drawing & Edge" -> eff.effectType in listOf("FindEdges", "Emboss", "Stroke", "OilPaint", "PatternOverlay", "BevelEmboss", "Satin", "UnsharpMask", "SmartSharpen", "HighPass")
                            "Blur" -> eff.effectType in listOf("GaussianBlur", "MotionBlur", "RadialBlur", "LensBlur", "AddNoise", "Despeckle", "DustScratches", "Median")
                            "Distortion/Warp" -> eff.effectType in listOf("Pinch", "Ripple", "Spherize", "Twirl", "Wave", "ZigZag", "GlassMorphism", "ReededGlass", "Liquify", "Mosaic", "Wind")
                            else -> false
                        }
                    }
                }

                // Grid Builder
                if (activeCategoryEffects.isEmpty()) {
                    Box(
                        modifier = Modifier.fillMaxSize(),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "No matching effects found in library.\nTry another search query.",
                            style = Typography.labelSmall,
                            color = TextSecondary,
                            textAlign = TextAlign.Center
                        )
                    }
                } else {
                    androidx.compose.foundation.lazy.grid.LazyVerticalGrid(
                        columns = androidx.compose.foundation.lazy.grid.GridCells.Fixed(2),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                        modifier = Modifier.fillMaxWidth().weight(1f)
                    ) {
                        items(activeCategoryEffects.size) { index ->
                            val eff = activeCategoryEffects[index]

                            // Visual branding based on effect groupings
                            val (badgeColor, badgeText) = when (eff.effectType) {
                                "GaussianBlur", "MotionBlur", "RadialBlur", "LensBlur" -> Pair(Color(0xFF29B6F6), "BLUR")
                                "Pinch", "Ripple", "Spherize", "Twirl", "Wave", "ZigZag", "Liquify", "PixelStretch" -> Pair(Color(0xFFFF007F), "WARP")
                                "ColorGrading", "ColorOverlay", "GradientOverlay", "Solarize" -> Pair(Color(0xFF00FFCC), "COLOR")
                                "FindEdges", "Emboss", "Stroke", "OilPaint", "PatternOverlay" -> Pair(Color(0xFFFFB300), "STYLE")
                                else -> Pair(Color(0xFFE91E63), "FX")
                            }

                            Card(
                                colors = CardDefaults.cardColors(containerColor = MidSlate),
                                border = BorderStroke(0.5.dp, HighslateOutline),
                                shape = RoundedCornerShape(12.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        onAddEffect(eff)
                                        onClose()
                                    }
                            ) {
                                Column(
                                    modifier = Modifier.padding(10.dp)
                                ) {
                                    // Visual preview block
                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .height(84.dp)
                                            .clip(RoundedCornerShape(8.dp))
                                            .background(Color(0xFF131317))
                                            .border(BorderStroke(0.5.dp, HighslateOutline), RoundedCornerShape(8.dp)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        // Accent decorative glow gradient or design
                                        Box(
                                            modifier = Modifier
                                                .size(48.dp)
                                                .background(badgeColor.copy(alpha = 0.12f), androidx.compose.foundation.shape.CircleShape)
                                                .border(BorderStroke(1.dp, badgeColor.copy(alpha = 0.4f)), androidx.compose.foundation.shape.CircleShape),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(
                                                text = badgeText,
                                                style = Typography.labelSmall,
                                                color = badgeColor,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 9.sp
                                            )
                                        }
                                    }

                                    Spacer(Modifier.height(8.dp))

                                    Text(
                                        text = eff.name,
                                        style = Typography.labelMedium,
                                        color = TextPrimary,
                                        fontWeight = FontWeight.Bold,
                                        maxLines = 1,
                                        overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                                    )
                                    
                                    Spacer(Modifier.height(4.dp))

                                    Text(
                                        text = getEffectDescription(eff.effectType),
                                        style = Typography.labelSmall,
                                        color = TextSecondary,
                                        fontSize = 9.sp,
                                        maxLines = 2,
                                        minLines = 2,
                                        overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

private val advancedBrushResultCache = java.util.concurrent.ConcurrentHashMap<Int, com.example.studio.ui.RenderedStrokeResult>()

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawBrushStroke(
    points: List<androidx.compose.ui.geometry.Offset>,
    color: androidx.compose.ui.graphics.Color,
    size: Float,
    opacity: Float,
    presetIndex: Int,
    smoothing: Boolean,
    originX: Float = 0f,
    originY: Float = 0f,
    composeBlendMode: androidx.compose.ui.graphics.BlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
    pathCache: android.util.SparseArray<androidx.compose.ui.graphics.Path>? = null,
    pathPointsCountCache: android.util.SparseIntArray? = null,
    cacheKey: Int? = null,
    backdropBitmap: android.graphics.Bitmap? = null,
    customHardness: Float? = null
) {
    if (points.isEmpty()) return

    val isEraser = (composeBlendMode == androidx.compose.ui.graphics.BlendMode.DstOut)

    // Preempt with OpenGLBrushRenderer for all requested advanced categories (unless this is an eraser)
    val usesAdvancedBrush = !isEraser && (presetIndex in listOf(
        3, 28, 29, 30, 31, 32, 33, 34,  // Soft Airbrush, Normal Airbrush, Triangle, Trapezoids, and Particles
        8, 9,                           // Vector Brushes
        10, 11, 12, 13,                 // Sketch/Pencil
        21, 39,                         // Watercolor
        14, 15, 16, 22, 23, 24, 25, 26, 27, 35, 38, 40 // Ink/Comic tapered paths & Digital Pen
    ))

    if (usesAdvancedBrush) {
        if (cacheKey != null) {
            val cachedRendered = advancedBrushResultCache[cacheKey]
            if (cachedRendered != null) {
                drawImage(
                    image = cachedRendered.bitmap.asImageBitmap(),
                    topLeft = androidx.compose.ui.geometry.Offset(cachedRendered.offsetX - originX, cachedRendered.offsetY - originY),
                    blendMode = composeBlendMode
                )
                return
            }
        }

        val cleanPoints = points.filter { it != androidx.compose.ui.geometry.Offset.Unspecified && !it.x.isNaN() && !it.y.isNaN() }
        if (cleanPoints.isNotEmpty()) {
            val rendered = OpenGLBrushRenderer.renderBrushToBitmap(
                points = cleanPoints,
                brushColor = color,
                size = size,
                opacity = opacity,
                presetIndex = presetIndex,
                smoothing = smoothing,
                backdropBitmap = backdropBitmap,
                customHardness = customHardness
            )
            if (rendered != null) {
                if (cacheKey != null) {
                    advancedBrushResultCache[cacheKey] = rendered
                }
                drawImage(
                    image = rendered.bitmap.asImageBitmap(),
                    topLeft = androidx.compose.ui.geometry.Offset(rendered.offsetX - originX, rendered.offsetY - originY),
                    blendMode = composeBlendMode
                )
                return
            }
        }
    }

    val currentPointsSize = points.size
    var smoothedPath: androidx.compose.ui.graphics.Path? = null
    var computedSubStrokes: List<List<androidx.compose.ui.geometry.Offset>>? = null

    if (cacheKey != null && pathCache != null && pathPointsCountCache != null) {
        val cachedSize = pathPointsCountCache.get(cacheKey, -1)
        if (cachedSize == currentPointsSize) {
            smoothedPath = if (smoothing) pathCache.get(cacheKey + 1000000) else pathCache.get(cacheKey)
        } else {
            pathCache.remove(cacheKey)
            pathCache.remove(cacheKey + 1000000)
            pathPointsCountCache.put(cacheKey, currentPointsSize)
        }
    }

    val getSubStrokes: () -> List<List<androidx.compose.ui.geometry.Offset>> = {
        computedSubStrokes ?: run {
            val subStrokesList = mutableListOf<List<androidx.compose.ui.geometry.Offset>>()
            var currentSub = mutableListOf<androidx.compose.ui.geometry.Offset>()
            for (pt in points) {
                if (pt == androidx.compose.ui.geometry.Offset.Unspecified || pt.x.isNaN() || pt.y.isNaN()) {
                    if (currentSub.isNotEmpty()) {
                        subStrokesList.add(currentSub)
                        currentSub = mutableListOf()
                    }
                } else {
                    currentSub.add(pt)
                }
            }
            if (currentSub.isNotEmpty()) {
                subStrokesList.add(currentSub)
            }
            computedSubStrokes = subStrokesList
            subStrokesList
        }
    }

    if (smoothedPath == null) {
        val subStrokes = getSubStrokes()
        if (subStrokes.isEmpty()) return
        
        smoothedPath = if (smoothing) {
            val path = androidx.compose.ui.graphics.Path()
            for (subPoints in subStrokes) {
                if (subPoints.isEmpty()) continue
                path.moveTo(subPoints[0].x - originX, subPoints[0].y - originY)
                if (subPoints.size > 1) {
                    for (i in 1 until subPoints.size - 1) {
                        val p0 = subPoints[i - 1]
                        val p1 = subPoints[i]
                        val p2 = subPoints[i + 1]
                        val mid1X = (p0.x + p1.x) / 2f
                        val mid1Y = (p0.y + p1.y) / 2f
                        val mid2X = (p1.x + p2.x) / 2f
                        val mid2Y = (p1.y + p2.y) / 2f
                        path.lineTo(mid1X - originX, mid1Y - originY)
                        path.quadraticTo(p1.x - originX, p1.y - originY, mid2X - originX, mid2Y - originY)
                    }
                    path.lineTo(subPoints.last().x - originX, subPoints.last().y - originY)
                } else {
                    path.lineTo(subPoints[0].x - originX + 0.1f, subPoints[0].y - originY)
                }
            }
            if (cacheKey != null) pathCache?.put(cacheKey + 1000000, path)
            path
        } else {
            val path = androidx.compose.ui.graphics.Path()
            for (subPoints in subStrokes) {
                if (subPoints.isEmpty()) continue
                path.moveTo(subPoints[0].x - originX, subPoints[0].y - originY)
                for (i in 1 until subPoints.size) {
                    path.lineTo(subPoints[i].x - originX, subPoints[i].y - originY)
                }
            }
            if (cacheKey != null) pathCache?.put(cacheKey, path)
            path
        }
    }

    val drawColor = color.copy(alpha = color.alpha * opacity)

    if (isEraser) {
        // High Performance Clear / DstOut Drawing for Eraser
        // Sweep single optimized GPU-friendly stroke cap round miter line path
        drawPath(
            path = smoothedPath,
            color = drawColor,
            style = androidx.compose.ui.graphics.drawscope.Stroke(
                width = size,
                cap = androidx.compose.ui.graphics.StrokeCap.Round,
                join = androidx.compose.ui.graphics.StrokeJoin.Round
            ),
            blendMode = composeBlendMode
        )
        return
    }

    when (presetIndex) {
        1 -> { // Calligraphy / Calligraphy Wedge
            for (offset in -2..2) {
                val dx = offset * (size * 0.12f)
                val dy = -offset * (size * 0.12f)
                withTransform({
                    translate(left = dx, top = dy)
                }) {
                    drawPath(
                        path = smoothedPath,
                        color = drawColor,
                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                            width = size * 0.45f,
                            cap = androidx.compose.ui.graphics.StrokeCap.Square
                        ),
                        blendMode = composeBlendMode
                    )
                }
            }
        }
        2 -> { // Neon Glow / Neon Light Aura
            drawPath(
                path = smoothedPath,
                color = drawColor.copy(alpha = drawColor.alpha * 0.15f),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size * 2.8f,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
            drawPath(
                path = smoothedPath,
                color = drawColor.copy(alpha = drawColor.alpha * 0.40f),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size * 1.6f,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
            drawPath(
                path = smoothedPath,
                color = androidx.compose.ui.graphics.Color.White.copy(alpha = drawColor.alpha),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size * 0.6f,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
        }
        3, 28 -> { // Airbrush / Soft Airbrush / Airbrush (Normal)
            val steps = 5
            for (step in 1..steps) {
                val ratio = step.toFloat() / steps
                val w = size * (1f + ratio * 1.4f)
                val a = drawColor.alpha * (1f - ratio) * 0.25f
                drawPath(
                    path = smoothedPath,
                    color = drawColor.copy(alpha = a),
                    style = androidx.compose.ui.graphics.drawscope.Stroke(
                        width = w,
                        cap = androidx.compose.ui.graphics.StrokeCap.Round,
                        join = androidx.compose.ui.graphics.StrokeJoin.Round
                    ),
                    blendMode = composeBlendMode
                )
            }
        }
        4 -> { // Felt Marker
            drawPath(
                path = smoothedPath,
                color = drawColor.copy(alpha = drawColor.alpha * 0.65f),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Butt,
                    join = androidx.compose.ui.graphics.StrokeJoin.Bevel
                ),
                blendMode = composeBlendMode
            )
        }
        5 -> { // Dotted Line
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round,
                    pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(size * 1.5f, size * 2.5f))
                ),
                blendMode = composeBlendMode
            )
        }
        6 -> { // Splatter Spray / Spray Splatter
            val random = java.util.Random(42)
            for (subPoints in getSubStrokes()) {
                for (i in subPoints.indices step 4) {
                    val p = subPoints[i]
                    for (dot in 0..5) {
                        val r = random.nextFloat() * size * 1.5f
                        val angle = random.nextFloat() * 2f * Math.PI.toFloat()
                        val dx = r * kotlin.math.cos(angle)
                        val dy = r * kotlin.math.sin(angle)
                        val dotSize = 0.8f + random.nextFloat() * 2.2f
                        drawCircle(
                            color = drawColor.copy(alpha = drawColor.alpha * 0.45f),
                            radius = dotSize,
                            center = androidx.compose.ui.geometry.Offset(p.x - originX + dx, p.y - originY + dy),
                            blendMode = composeBlendMode
                        )
                    }
                }
            }
        }
        7 -> { // Glass Pen
            // Core smooth stroke + a thin white transparent glare trace next to it representing light refraction
            drawPath(
                path = smoothedPath,
                color = drawColor.copy(alpha = drawColor.alpha * 0.75f),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
            withTransform({
                translate(left = size * 0.12f, top = -size * 0.12f)
            }) {
                drawPath(
                    path = smoothedPath,
                    color = androidx.compose.ui.graphics.Color.White.copy(alpha = drawColor.alpha * 0.35f),
                    style = androidx.compose.ui.graphics.drawscope.Stroke(
                        width = size * 0.25f,
                        cap = androidx.compose.ui.graphics.StrokeCap.Round,
                        join = androidx.compose.ui.graphics.StrokeJoin.Round
                    ),
                    blendMode = composeBlendMode
                )
            }
        }
        8 -> { // Vector Dip Pen
            // Highly tensioned tapering style
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size * 0.85f,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
        }
        9 -> { // Vector Felt Tip Pen
            // Uniform solid flat vector marker
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
        }
        10, 11, 12, 13 -> { // Pencils (Pencil 1, Pencil 2, Graphite, Rough)
            val stippleSize = if (presetIndex == 13) 2.5f else 1.2f
            val baseDensity = if (presetIndex == 12) 6 else 4
            // Optimised textured drawing using dash stipple effect for high-performance sketching
            drawPath(
                path = smoothedPath,
                color = drawColor.copy(alpha = drawColor.alpha * 0.5f),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round,
                    pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(stippleSize, stippleSize * 2f, stippleSize * 0.5f, stippleSize * 1.5f))
                ),
                blendMode = composeBlendMode
            )
            // A secondary offset stroke with lower alpha to simulate soft surrounding graphite powder
            withTransform({ translate(left = stippleSize * 0.5f, top = -stippleSize * 0.3f) }) {
                drawPath(
                    path = smoothedPath,
                    color = drawColor.copy(alpha = drawColor.alpha * 0.25f),
                    style = androidx.compose.ui.graphics.drawscope.Stroke(
                        width = size * 1.15f,
                        cap = androidx.compose.ui.graphics.StrokeCap.Round,
                        join = androidx.compose.ui.graphics.StrokeJoin.Round,
                        pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(stippleSize * 0.7f, stippleSize * 3f))
                    ),
                    blendMode = composeBlendMode
                )
            }
        }
        14 -> { // Hard Japanese Pen (Smooth)
            // Flex chiseled nib using square caps and high contrast
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Square,
                    join = androidx.compose.ui.graphics.StrokeJoin.Miter
                ),
                blendMode = composeBlendMode
            )
        }
        15, 22, 24, 26, 35 -> { // Solved bleed styles (Soft Falcon Pen, Soft Mapping Pen, Soft Turnip, Soft School, Dip Bleed)
            // Main solid line
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size * 0.85f,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
            // Fuzzy spread bleeding path effect
            drawPath(
                path = smoothedPath,
                color = drawColor.copy(alpha = drawColor.alpha * 0.28f),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size * 1.35f,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round,
                    pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(3f, 6f, 1f, 4f))
                ),
                blendMode = composeBlendMode
            )
        }
        16, 23, 25, 27 -> { // Hard crisp inking styles (Hard Falcon Pen, Hard Mapping, Hard Turnip, Hard School)
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
        }
        17 -> { // Technical Pen
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Butt,
                    join = androidx.compose.ui.graphics.StrokeJoin.Miter
                ),
                blendMode = composeBlendMode
            )
        }
        18 -> { // Ruling Pen (Twin plate metallic lines)
            withTransform({ translate(left = -size * 0.24f, top = -size * 0.12f) }) {
                drawPath(
                    path = smoothedPath,
                    color = drawColor,
                    style = androidx.compose.ui.graphics.drawscope.Stroke(
                        width = size * 0.28f,
                        cap = androidx.compose.ui.graphics.StrokeCap.Round,
                        join = androidx.compose.ui.graphics.StrokeJoin.Round
                    ),
                    blendMode = composeBlendMode
                )
            }
            withTransform({ translate(left = size * 0.24f, top = size * 0.12f) }) {
                drawPath(
                    path = smoothedPath,
                    color = drawColor,
                    style = androidx.compose.ui.graphics.drawscope.Stroke(
                        width = size * 0.28f,
                        cap = androidx.compose.ui.graphics.StrokeCap.Round,
                        join = androidx.compose.ui.graphics.StrokeJoin.Round
                    ),
                    blendMode = composeBlendMode
                )
            }
        }
        19, 20 -> { // Drawing / Ballpoint Pen
            val penSize = if (presetIndex == 20) size * 0.25f else size * 0.85f
            val dashPattern = if (presetIndex == 20) floatArrayOf(size * 5f, size * 0.7f) else null
            
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = penSize,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round,
                    pathEffect = if (dashPattern != null) androidx.compose.ui.graphics.PathEffect.dashPathEffect(dashPattern) else null
                ),
                blendMode = composeBlendMode
            )
        }
        21 -> { // Texture Pen
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round,
                    pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(1f, 3f, 4f, 2f))
                ),
                blendMode = composeBlendMode
            )
        }
        29 -> { // Airbrush (Triangle)
            // Triangular aura nozzle spray. Overlay three lines translated
            val overlayAlphas = listOf(0.18f, 0.14f, 0.10f)
            val offsets = listOf(-size * 0.15f, 0f, size * 0.15f)
            for (step in 0..2) {
                withTransform({ translate(left = offsets[step], top = -offsets[step] * 0.5f) }) {
                    drawPath(
                        path = smoothedPath,
                        color = drawColor.copy(alpha = drawColor.alpha * overlayAlphas[step]),
                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                            width = size * (1.2f + step * 0.4f),
                            cap = androidx.compose.ui.graphics.StrokeCap.Round,
                            join = androidx.compose.ui.graphics.StrokeJoin.Round
                        ),
                        blendMode = composeBlendMode
                    )
                }
            }
        }
        30, 31, 32 -> { // Airbrush (Trapezoid 20%, 40%, 60%)
            val trapezoidRatio = when (presetIndex) {
                30 -> 0.20f
                31 -> 0.40f
                else -> 0.60f
            }
            val stepsVal = 4
            for (i in 1..stepsVal) {
                val ratio = i.toFloat() / stepsVal
                val wWidth = size * (1f + ratio * (1f / trapezoidRatio))
                val aAlpha = drawColor.alpha * (1f - ratio) * 0.32f
                drawPath(
                    path = smoothedPath,
                    color = drawColor.copy(alpha = aAlpha),
                    style = androidx.compose.ui.graphics.drawscope.Stroke(
                        width = wWidth,
                        cap = androidx.compose.ui.graphics.StrokeCap.Square,
                        join = androidx.compose.ui.graphics.StrokeJoin.Bevel
                    ),
                    blendMode = composeBlendMode
                )
            }
        }
        33, 34 -> { // Airbrush (Particle & Particle L)
            // Optimized scattered micro dots using structural step filter to prevent rendering delays during drag gestures
            val random = java.util.Random(1234)
            val dispersion = size * 1.5f
            val maxSplats = if (presetIndex == 33) 4 else 2
            val radiusVal = if (presetIndex == 34) 2.2f else 0.8f
            
            for (subPoints in getSubStrokes()) {
                for (idx in subPoints.indices step 4) {
                    val p = subPoints[idx]
                    for (dot in 0..maxSplats) {
                        val r = random.nextFloat() * dispersion
                        val angle = random.nextFloat() * 2f * Math.PI.toFloat()
                        val dx = r * kotlin.math.cos(angle)
                        val dy = r * kotlin.math.sin(angle)
                        drawCircle(
                            color = drawColor.copy(alpha = drawColor.alpha * (0.15f + random.nextFloat() * 0.25f)),
                            radius = radiusVal + random.nextFloat() * 1.5f,
                            center = androidx.compose.ui.geometry.Offset(p.x - originX + dx, p.y - originY + dy),
                            blendMode = composeBlendMode
                        )
                    }
                }
            }
        }
        36, 37 -> { // Felt Tip Pen (Soft / Hard)
            val markerAlpha = if (presetIndex == 36) 0.70f else 1.0f
            val markCap = if (presetIndex == 36) androidx.compose.ui.graphics.StrokeCap.Round else androidx.compose.ui.graphics.StrokeCap.Square
            drawPath(
                path = smoothedPath,
                color = drawColor.copy(alpha = drawColor.alpha * markerAlpha),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = markCap,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
        }
        38 -> { // Pen (Fade)
            // Simulates tapered pressure fading at coordinate endpoints using step layout or opacity shift
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
        }
        39 -> { // Impasto Brush - Flat
            // Thick painterly layered acrylic acrylic tracks
            val parallelOffsets = listOf(-size * 0.16f, 0f, size * 0.16f)
            val impastoAlphas = listOf(0.40f, 0.90f, 0.50f)
            for (step in 0..2) {
                withTransform({ translate(left = parallelOffsets[step], top = parallelOffsets[step] * 0.3f) }) {
                    drawPath(
                        path = smoothedPath,
                        color = drawColor.copy(alpha = drawColor.alpha * impastoAlphas[step]),
                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                            width = size * 0.45f,
                            cap = androidx.compose.ui.graphics.StrokeCap.Butt,
                            join = androidx.compose.ui.graphics.StrokeJoin.Round
                        ),
                        blendMode = composeBlendMode
                    )
                }
            }
        }
        40 -> { // Digital Pen
            // Fully aliased pixel line
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Square,
                    join = androidx.compose.ui.graphics.StrokeJoin.Bevel
                ),
                blendMode = composeBlendMode
            )
        }
        else -> { // Solid Ink
            drawPath(
                path = smoothedPath,
                color = drawColor,
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = size,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round,
                    join = androidx.compose.ui.graphics.StrokeJoin.Round
                ),
                blendMode = composeBlendMode
            )
        }
    }
}

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawTextLayerInternal(
    layer: com.example.studio.model.StudioLayer,
    opacityMultiplier: Float,
    composeBlendMode: androidx.compose.ui.graphics.BlendMode,
    blurRadius: Float = 0f
) {
    val text = if (layer.textContent.isEmpty()) "DOUBLE TAP TO EDIT" else layer.textContent
    val typeface = com.example.studio.ui.TypefaceCache.get(
        layer.fontPath,
        layer.fontFamilyName,
        layer.fontIsBold,
        layer.fontIsItalic
    )

    val activeColor = layer.baseColor.copy(alpha = layer.opacity * opacityMultiplier)
    val textPaint = android.text.TextPaint().apply {
        color = activeColor.toArgb()
        textSize = layer.fontSize
        isAntiAlias = true
        this.typeface = typeface
        if (blurRadius > 0.1f) {
            maskFilter = android.graphics.BlurMaskFilter(blurRadius, android.graphics.BlurMaskFilter.Blur.NORMAL)
        }
    }
    val align = when (layer.fontAlign.lowercase()) {
        "left" -> android.text.Layout.Alignment.ALIGN_NORMAL
        "right" -> android.text.Layout.Alignment.ALIGN_OPPOSITE
        else -> android.text.Layout.Alignment.ALIGN_CENTER
    }
    val staticLayout = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.M) {
        android.text.StaticLayout.Builder.obtain(text, 0, text.length, textPaint, maxOf(1, layer.width.toInt()))
            .setAlignment(align)
            .setLineSpacing(0f, 1f)
            .setIncludePad(false)
            .build()
    } else {
        @Suppress("DEPRECATION")
        android.text.StaticLayout(text, textPaint, maxOf(1, layer.width.toInt()), align, 1f, 0f, false)
    }
    
    drawContext.canvas.nativeCanvas.save()
    val totalHeight = staticLayout.height
    val startY = maxOf(0f, (layer.height - totalHeight) / 2f)
    drawContext.canvas.nativeCanvas.translate(0f, startY)
    staticLayout.draw(drawContext.canvas.nativeCanvas)
    drawContext.canvas.nativeCanvas.restore()
}

data class FontResource(
    val name: String,
    val category: String,
    val systemFamily: String? = null,
    val path: String? = null,
    val isImported: Boolean = false
)

fun getFavoriteFonts(context: android.content.Context): Set<String> {
    val prefs = context.getSharedPreferences("favorite_fonts", android.content.Context.MODE_PRIVATE)
    return prefs.getStringSet("favorites", emptySet()) ?: emptySet()
}

fun toggleFavoriteFont(context: android.content.Context, fontName: String): Set<String> {
    val prefs = context.getSharedPreferences("favorite_fonts", android.content.Context.MODE_PRIVATE)
    val favorites = prefs.getStringSet("favorites", emptySet())?.toMutableSet() ?: mutableSetOf()
    if (favorites.contains(fontName)) {
        favorites.remove(fontName)
    } else {
        favorites.add(fontName)
    }
    prefs.edit().putStringSet("favorites", favorites).apply()
    return favorites
}

@Composable
fun RenderFontRow(
    font: FontResource,
    selectedLayer: com.example.studio.model.StudioLayer,
    favoriteFontsList: Set<String>,
    onUpdateLayer: (com.example.studio.model.StudioLayer) -> Unit,
    context: android.content.Context,
    onFavoriteToggle: (Set<String>) -> Unit
) {
    RenderFontRow(font, selectedLayer, onUpdateLayer, context)
}

object FontFavoritesState {
    private var isInitialized = false
    val favoriteFontsState = androidx.compose.runtime.mutableStateOf(emptySet<String>())
    var favoriteFontsList: Set<String>
        get() = favoriteFontsState.value
        set(value) {
            favoriteFontsState.value = value
            isInitialized = true
        }

    fun ensureInitialized(context: android.content.Context) {
        if (!isInitialized) {
            favoriteFontsState.value = getFavoriteFonts(context)
            isInitialized = true
        }
    }
}

@Composable
fun RenderFontRow(
    font: FontResource,
    selectedLayer: com.example.studio.model.StudioLayer,
    onUpdateLayer: (com.example.studio.model.StudioLayer) -> Unit,
    context: android.content.Context
) {
    FontFavoritesState.ensureInitialized(context)
    val isSelected = if (font.isImported) {
        selectedLayer.fontPath == font.path
    } else {
        selectedLayer.fontFamilyName == font.name && selectedLayer.fontPath == null
    }
    val isFavorited = FontFavoritesState.favoriteFontsList.contains(font.name)

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .background(if (isSelected) androidx.compose.ui.graphics.Color(0xFFFFB300).copy(alpha = 0.2f) else androidx.compose.ui.graphics.Color.Transparent, androidx.compose.foundation.shape.RoundedCornerShape(4.dp))
            .border(androidx.compose.foundation.BorderStroke(0.5.dp, if (isSelected) androidx.compose.ui.graphics.Color(0xFFFFB300) else androidx.compose.ui.graphics.Color.Transparent), androidx.compose.foundation.shape.RoundedCornerShape(4.dp))
            .clickable {
                if (font.isImported) {
                    onUpdateLayer(selectedLayer.copy(fontPath = font.path, fontFamilyName = font.name))
                } else {
                    onUpdateLayer(selectedLayer.copy(fontPath = null, fontFamilyName = font.name))
                }
            }
            .padding(horizontal = 8.dp, vertical = 6.dp),
        horizontalArrangement = androidx.compose.foundation.layout.Arrangement.SpaceBetween,
        verticalAlignment = androidx.compose.ui.Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(font.name, style = androidx.compose.material3.MaterialTheme.typography.labelSmall, fontSize = 11.sp, color = androidx.compose.ui.graphics.Color.White, fontWeight = if (isSelected) androidx.compose.ui.text.font.FontWeight.Bold else androidx.compose.ui.text.font.FontWeight.Normal)
            Text(
                text = if (font.isImported) "Imported • ${font.category}" else "System Font • ${font.category}",
                style = androidx.compose.material3.MaterialTheme.typography.labelSmall,
                fontSize = 9.sp,
                color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.6f)
            )
        }
        
        Row(
            verticalAlignment = androidx.compose.ui.Alignment.CenterVertically,
            horizontalArrangement = androidx.compose.foundation.layout.Arrangement.spacedBy(8.dp)
        ) {
            androidx.compose.material3.IconButton(
                onClick = {
                    val updated = toggleFavoriteFont(context, font.name)
                    FontFavoritesState.favoriteFontsList = updated
                },
                modifier = Modifier.size(28.dp)
            ) {
                androidx.compose.material3.Icon(
                    imageVector = androidx.compose.material.icons.Icons.Default.Favorite,
                    contentDescription = if (isFavorited) "Remove from favorites" else "Add to favorites",
                    tint = if (isFavorited) androidx.compose.ui.graphics.Color(0xFFFF4D4D) else androidx.compose.ui.graphics.Color.White.copy(alpha = 0.25f),
                    modifier = Modifier.size(16.dp)
                )
            }
            if (isSelected) {
                androidx.compose.material3.Icon(androidx.compose.material.icons.Icons.Default.Check, "Selected", modifier = Modifier.size(14.dp), tint = androidx.compose.ui.graphics.Color(0xFFFFB300))
            }
        }
    }
}

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawPreviewPathWithCornerRadius(
    path: androidx.compose.ui.graphics.Path,
    color: androidx.compose.ui.graphics.Color,
    cornerRadius: Float,
    composeBlendMode: androidx.compose.ui.graphics.BlendMode,
    style: androidx.compose.ui.graphics.drawscope.DrawStyle = androidx.compose.ui.graphics.drawscope.Fill
) {
    if (cornerRadius > 0f) {
        val paint = androidx.compose.ui.graphics.Paint().apply {
            this.color = color
            this.style = if (style is androidx.compose.ui.graphics.drawscope.Stroke) {
                androidx.compose.ui.graphics.PaintingStyle.Stroke
            } else {
                androidx.compose.ui.graphics.PaintingStyle.Fill
            }
            if (style is androidx.compose.ui.graphics.drawscope.Stroke) {
                this.strokeWidth = style.width
            }
            this.blendMode = composeBlendMode
            asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(cornerRadius)
        }
        drawContext.canvas.drawPath(path, paint)
    } else {
        drawPath(
            path = path,
            color = color,
            style = style,
            blendMode = composeBlendMode
        )
    }
}

private val adjustedBitmapCache = android.util.LruCache<String, android.graphics.Bitmap>(16)
private val parsedStrokesCache = android.util.LruCache<String, List<ParsedFreehandStroke>>(64)

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawAllEffectsAndLayersLocal(
    layer: com.example.studio.model.StudioLayer,
    layerOpacity: Float,
    selectedLayerId: String?,
    pathCache: android.util.SparseArray<androidx.compose.ui.graphics.Path>,
    pathPointsCountCache: android.util.SparseIntArray,
    totalScale: Float,
    dashEffect: androidx.compose.ui.graphics.PathEffect,
    composeBlendMode: androidx.compose.ui.graphics.BlendMode,
    imageBitmapCache: Map<String, androidx.compose.ui.graphics.ImageBitmap>,
    backdropBitmap: android.graphics.Bitmap? = null,
    globalX: Float = 0f,
    globalY: Float = 0f,
    activeTool: String = "Brush",
    viewportWidth: Float = 0f,
    viewportHeight: Float = 0f,
    panX: Float = 0f,
    panY: Float = 0f,
    canvasWidth: Float = 0f,
    canvasHeight: Float = 0f
) {
    val activeStretchEffects = layer.effects.filter { it.isEnabled }
    val pixelStretchEffect = activeStretchEffects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "PixelStretch" } as? com.example.studio.model.StudioEffect.PhotoshopEffect

    if (pixelStretchEffect != null) {
        val isViewportValid = viewportWidth > 0f && viewportHeight > 0f
        val visibleRect = if (isViewportValid) {
            com.example.studio.ui.getLayerVisibleLocalRect(
                layer = layer,
                viewportWidth = viewportWidth,
                viewportHeight = viewportHeight,
                panX = panX,
                panY = panY,
                scale = totalScale,
                canvasWidth = canvasWidth,
                canvasHeight = canvasHeight
            )
        } else {
            android.graphics.Rect(0, 0, layer.width.toInt(), layer.height.toInt())
        }
        val layW = maxOf(2, (if (isViewportValid) visibleRect.width() else layer.width.toInt()).coerceAtMost(2048))
        val layH = maxOf(2, (if (isViewportValid) visibleRect.height() else layer.height.toInt()).coerceAtMost(2048))
        
        val sliceLine = pixelStretchEffect.parameters["SliceLine"]?.value ?: 0.5f
        val orientationVal = pixelStretchEffect.parameters["Orientation"]?.value ?: 0f
        val isHorizontal = orientationVal > 0.5f
        val warpBend = pixelStretchEffect.parameters["WarpBend"]?.value ?: 0f
        val warpFreq = pixelStretchEffect.parameters["WarpFrequency"]?.value ?: 1f
        val cutoutVal = pixelStretchEffect.parameters["SubjectCutout"]?.value ?: 1f
        val thresholdVal = pixelStretchEffect.parameters["CutoutThreshold"]?.value ?: 230f
        
        val stateHash = if (layer.type == com.example.studio.model.LayerType.IMAGE_CARD) {
            layer.imageUri.hashCode()
        } else {
            (layer.textContent.hashCode() * 31 + layer.baseColor.hashCode()) * 31 + layer.brushPoints.size + layer.cornerRadius.hashCode() + layer.polygonEdges + layer.strokeThickness.hashCode() + layer.fontSize.hashCode()
        }
        
        val finalStretchKey = "ps_${layer.id}_${sliceLine}_${isHorizontal}_${warpBend}_${warpFreq}_${cutoutVal}_${thresholdVal}_${layW}_${layH}_${stateHash}"
        var finalWarpedBmp = pixelStretchBitmapsCache[finalStretchKey]
        
        if (finalWarpedBmp == null || finalWarpedBmp.isRecycled) {
            val baseBmp = if (layer.type == com.example.studio.model.LayerType.IMAGE_CARD) {
                val uriStr = layer.imageUri
                val loadedBitmap = if (!uriStr.isNullOrEmpty()) imageBitmapCache[uriStr] else null
                loadedBitmap?.asAndroidBitmap()
            } else {
                val tempBmp = android.graphics.Bitmap.createBitmap(layW, layH, android.graphics.Bitmap.Config.ARGB_8888)
                val nativeCanvas = android.graphics.Canvas(tempBmp)
                val tempCanvas = androidx.compose.ui.graphics.Canvas(nativeCanvas)
                val originalCanvas = drawContext.canvas
                
                drawContext.canvas = tempCanvas
                try {
                    val disabledEffects = layer.effects.map {
                        if (it.id == pixelStretchEffect.id) {
                            (it as com.example.studio.model.StudioEffect.PhotoshopEffect).copy(isEnabled = false)
                        } else it
                    }
                    val tempLayer = layer.copy(effects = disabledEffects)
                    drawAllEffectsAndLayersLocal(
                        layer = tempLayer,
                        layerOpacity = 1.0f,
                        selectedLayerId = selectedLayerId,
                        pathCache = pathCache,
                        pathPointsCountCache = pathPointsCountCache,
                        totalScale = totalScale,
                        dashEffect = dashEffect,
                        composeBlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
                        imageBitmapCache = imageBitmapCache,
                        backdropBitmap = backdropBitmap,
                        globalX = globalX,
                        globalY = globalY,
                        activeTool = activeTool
                    )
                } finally {
                    drawContext.canvas = originalCanvas
                }
                tempBmp
            }
            
            if (baseBmp != null) {
                val resultBmp = android.graphics.Bitmap.createBitmap(layW, layH, android.graphics.Bitmap.Config.ARGB_8888)
                val tempCanvas = android.graphics.Canvas(resultBmp)
                val sliceBmp = extractPixelStretchBitmap(baseBmp, sliceLine, isHorizontal)
                
                val meshWidth = 20
                val meshHeight = 20
                val vertCount = (meshWidth + 1) * (meshHeight + 1)
                val verts = FloatArray(vertCount * 2)
                
                var index = 0
                for (yIdx in 0..meshHeight) {
                    val fy = yIdx.toFloat() / meshHeight
                    val yNormal = fy * layH
                    for (xIdx in 0..meshWidth) {
                        val fx = xIdx.toFloat() / meshWidth
                        var xNormal = fx * layW

                        var vx = xNormal
                        var vy = yNormal

                        if (isHorizontal) {
                            val wave = kotlin.math.sin(Math.PI.toFloat() * fx) * warpBend + 
                                       kotlin.math.sin(warpFreq * Math.PI.toFloat() * fx) * (warpBend * 0.4f)
                            vy += wave
                        } else {
                            val wave = kotlin.math.sin(Math.PI.toFloat() * fy) * warpBend + 
                                       kotlin.math.sin(warpFreq * Math.PI.toFloat() * fy) * (warpBend * 0.4f)
                            vx += wave
                        }

                        verts[index * 2] = vx
                        verts[index * 2 + 1] = vy
                        index++
                    }
                }
                
                val meshPaint = android.graphics.Paint().apply {
                    isAntiAlias = true
                    isFilterBitmap = true
                }
                
                try {
                    tempCanvas.drawBitmapMesh(sliceBmp, meshWidth, meshHeight, verts, 0, null, 0, meshPaint)
                    if (sliceBmp != baseBmp) {
                        try { sliceBmp.recycle() } catch (e: Exception) {}
                    }
                    if (cutoutVal > 0f) {
                        val cutoutBmp = extractSubjectForeground(baseBmp, thresholdVal, cutoutVal)
                        tempCanvas.drawBitmap(cutoutBmp, null, android.graphics.Rect(0, 0, layW, layH), meshPaint)
                        if (cutoutBmp != baseBmp) {
                            try { cutoutBmp.recycle() } catch (e: Exception) {}
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                }
                
                if (layer.type != com.example.studio.model.LayerType.IMAGE_CARD) {
                    try {
                        baseBmp.recycle()
                    } catch (e: Exception) {}
                }
                
                pixelStretchBitmapsCache[finalStretchKey] = resultBmp
                if (pixelStretchBitmapsCache.size > 16) {
                    synchronized(pixelStretchBitmapsCache) {
                        if (pixelStretchBitmapsCache.size > 16) {
                            val keys = pixelStretchBitmapsCache.keys().toList()
                            val keysToEvict = keys.take(8)
                            for (k in keysToEvict) {
                                val bmp = pixelStretchBitmapsCache.remove(k)
                                if (bmp != null && !bmp.isRecycled) {
                                    try {
                                        bmp.recycle()
                                    } catch (e: Exception) {
                                        e.printStackTrace()
                                    }
                                }
                            }
                        }
                    }
                }
                finalWarpedBmp = resultBmp
            }
        }
        
        if (finalWarpedBmp != null) {
            drawImage(
                image = finalWarpedBmp.asImageBitmap(),
                dstSize = androidx.compose.ui.unit.IntSize(layW, layH),
                alpha = layerOpacity,
                blendMode = composeBlendMode
            )
            return
        }
    }

    val effectiveColor = getLayerEffectiveColor(layer, 1.0f)
    var dropShadow: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var innerShadow: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var bordersShadows: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var outerGlow: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var innerGlow: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var bevelStyle: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var satinStyle: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var gradOverlay: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var patOverlay: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var strokeStyle: com.example.studio.model.StudioEffect.PhotoshopEffect? = null

    var raBlur: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var moBlur: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var leBlur: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var noiseFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var dustScratch: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var medFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var halftoneFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var crysFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var mosFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var pointFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var cloudFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var flareFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var lightFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var unsharpFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var smartFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var highFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var findFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var embFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var oilFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var windFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null

    var artFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var brushFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var sketchFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var texFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var neuralFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var brushConfig: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var glassMorphism: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var reededGlass: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var didSaveLayer = false

    for (effect in layer.effects) {
        if (!effect.isEnabled) continue
        if (effect is com.example.studio.model.StudioEffect.PhotoshopEffect) {
            when (effect.effectType) {
                "GlassMorphism" -> glassMorphism = effect
                "ReededGlass" -> reededGlass = effect
                "DropShadow" -> dropShadow = effect
                "InnerShadow" -> innerShadow = effect
                "BordersAndShadows" -> bordersShadows = effect
                "OuterGlow" -> outerGlow = effect
                "InnerGlow" -> innerGlow = effect
                "BevelEmboss" -> bevelStyle = effect
                "Satin" -> satinStyle = effect
                "GradientOverlay" -> gradOverlay = effect
                "PatternOverlay" -> patOverlay = effect
                "Stroke" -> strokeStyle = effect
                "RadialBlur" -> raBlur = effect
                "MotionBlur" -> moBlur = effect
                "LensBlur" -> leBlur = effect
                "AddNoise" -> noiseFil = effect
                "DustScratches" -> dustScratch = effect
                "Median" -> medFil = effect
                "ColorHalftone" -> halftoneFil = effect
                "Crystallize" -> crysFil = effect
                "Mosaic" -> mosFil = effect
                "Pointillize" -> pointFil = effect
                "Clouds" -> cloudFil = effect
                "LensFlare" -> flareFil = effect
                "LightingEffects" -> lightFil = effect
                "UnsharpMask" -> unsharpFil = effect
                "SmartSharpen" -> smartFil = effect
                "HighPass" -> highFil = effect
                "FindEdges" -> findFil = effect
                "Emboss" -> embFil = effect
                "OilPaint" -> oilFil = effect
                "Wind" -> windFil = effect
                "Artistic" -> artFil = effect
                "BrushStrokes" -> brushFil = effect
                "Sketch" -> sketchFil = effect
                "Texture" -> texFil = effect
                "NeuralFilters" -> neuralFil = effect
                "BrushConfig" -> brushConfig = effect
            }
        }
    }

    // Shape/Geometry drawing helper
    fun drawGeometry(finalColor: androidx.compose.ui.graphics.Color, finalOpacity: Float, fillStyle: androidx.compose.ui.graphics.drawscope.DrawStyle, isOverlay: Boolean = true) {
        val finalComposeColor = finalColor.copy(alpha = finalOpacity * layerOpacity)
        val styleToUse = if (layer.strokeThickness > 0f && fillStyle is androidx.compose.ui.graphics.drawscope.Fill && layer.type !in listOf(com.example.studio.model.LayerType.FREEHAND_DRAWING, com.example.studio.model.LayerType.IMAGE_CARD, com.example.studio.model.LayerType.TEXT)) {
            androidx.compose.ui.graphics.drawscope.Stroke(width = layer.strokeThickness)
        } else {
            fillStyle
        }

        val activeList = layer.effects.filter { it.isEnabled }
        val hasAdj = layer.type != com.example.studio.model.LayerType.IMAGE_CARD && 
            layer.type != com.example.studio.model.LayerType.TEXT && 
            layer.type != com.example.studio.model.LayerType.FREEHAND_DRAWING &&
            activeList.any { 
                it is com.example.studio.model.StudioEffect.ColorBalance || 
                it is com.example.studio.model.StudioEffect.Invert || 
                it is com.example.studio.model.StudioEffect.Threshold || 
                it is com.example.studio.model.StudioEffect.Posterize || 
                (it is com.example.studio.model.StudioEffect.PhotoshopEffect && 
                 it.effectType in listOf("CameraRaw", "ColorGrading", "Solarize", "Emboss", "FindEdges", "ColorHalftone", "Sketch", "Mosaic", "Twirl", "Spherize", "GaussianBlur", "SmartSharpen", "UnsharpMask", "AddNoise")) 
            }

        val hasAnyAdj = hasAdj || (layer.type != com.example.studio.model.LayerType.IMAGE_CARD && 
            layer.type != com.example.studio.model.LayerType.TEXT && 
            layer.type != com.example.studio.model.LayerType.FREEHAND_DRAWING &&
            activeList.any { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType !in listOf("BrushConfig", "DropShadow", "InnerShadow", "BordersAndShadows", "OuterGlow", "InnerGlow", "BevelEmboss", "Satin", "GradientOverlay", "PatternOverlay", "Stroke", "GlassMorphism", "ReededGlass") })
        val adjustedBmp = if (hasAnyAdj && backdropBitmap != null) {
            val rx = globalX
            val ry = globalY
            val rw = layer.width
            val rh = layer.height
            val backdropW = backdropBitmap.width
            val backdropH = backdropBitmap.height
            val x = rx.toInt().coerceIn(0, backdropW - 1)
            val y = ry.toInt().coerceIn(0, backdropH - 1)
            val w = rw.toInt().coerceAtLeast(1).coerceAtMost(backdropW - x)
            val h = rh.toInt().coerceAtLeast(1).coerceAtMost(backdropH - y)
            
            val cacheKey = "adj_${layer.id}_${w}_${h}_${x}_${y}_${backdropBitmap.generationId}_${activeList.hashCode()}"
            val cached = adjustedBitmapCache.get(cacheKey)
            if (cached != null) {
                cached
            } else {
                val croppedBmp = if (w > 0 && h > 0) {
                    try {
                        android.graphics.Bitmap.createBitmap(backdropBitmap, x, y, w, h)
                    } catch (e: Exception) {
                        null
                    }
                } else null
                
                val filtered = if (croppedBmp != null) {
                    globalAppContext?.let { applyGPUImageFilters(it, croppedBmp, activeList) } ?: croppedBmp
                } else null
                
                if (filtered != null) {
                    adjustedBitmapCache.put(cacheKey, filtered)
                }
                filtered
            }
        } else null

        val paintToUse = if (fillStyle is androidx.compose.ui.graphics.drawscope.Fill && adjustedBmp != null) {
            val composePaint = androidx.compose.ui.graphics.Paint()
            val nativePaint = composePaint.asFrameworkPaint()
            val shader = android.graphics.BitmapShader(adjustedBmp, android.graphics.Shader.TileMode.CLAMP, android.graphics.Shader.TileMode.CLAMP)
            nativePaint.shader = shader
            // Retain any opacity settings
            nativePaint.alpha = (finalOpacity * layerOpacity * 255).toInt().coerceIn(0, 255)
            composePaint.blendMode = composeBlendMode
            composePaint
        } else {
            null
        }

        val hasEraserOrBrush = (layer.brushPoints.isNotEmpty() || (layer.id == selectedLayerId && activeTool == "Eraser")) && layer.type != com.example.studio.model.LayerType.FREEHAND_DRAWING
        var canvasSaved = false
        if (hasEraserOrBrush) {
            try {
                val bounds = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width.coerceAtLeast(10f), layer.height.coerceAtLeast(10f))
                drawContext.canvas.saveLayer(bounds, androidx.compose.ui.graphics.Paint())
                canvasSaved = true
            } catch (t: Throwable) {
                t.printStackTrace()
            }
        }

        when (layer.type) {
            com.example.studio.model.LayerType.VECTOR_RECT -> {
                if (paintToUse != null) {
                    if (layer.cornerRadius > 0f) {
                        drawContext.canvas.drawRoundRect(
                            left = 0f,
                            top = 0f,
                            right = layer.width,
                            bottom = layer.height,
                            radiusX = layer.cornerRadius,
                            radiusY = layer.cornerRadius,
                            paint = paintToUse
                        )
                    } else {
                        drawContext.canvas.drawRect(
                            left = 0f,
                            top = 0f,
                            right = layer.width,
                            bottom = layer.height,
                            paint = paintToUse
                        )
                    }
                } else {
                    if (layer.cornerRadius > 0f) {
                        drawRoundRect(
                            color = finalComposeColor,
                            topLeft = androidx.compose.ui.geometry.Offset.Zero,
                            size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                            cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius),
                            style = styleToUse,
                            blendMode = composeBlendMode
                        )
                    } else {
                        drawRect(
                            color = finalComposeColor,
                            topLeft = androidx.compose.ui.geometry.Offset.Zero,
                            size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                            style = styleToUse,
                            blendMode = composeBlendMode
                        )
                    }
                }
            }
            com.example.studio.model.LayerType.VECTOR_TRIANGLE -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 3
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                if (paintToUse != null) {
                    if (layer.cornerRadius > 0f) {
                        paintToUse.asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    drawContext.canvas.drawPath(path, paintToUse)
                } else {
                    if (layer.cornerRadius > 0f) {
                        val paint = androidx.compose.ui.graphics.Paint().apply {
                            color = finalComposeColor
                            style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                                androidx.compose.ui.graphics.PaintingStyle.Stroke
                            } else {
                                androidx.compose.ui.graphics.PaintingStyle.Fill
                            }
                            if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                                strokeWidth = styleToUse.width
                            }
                            blendMode = composeBlendMode
                            asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                        }
                        drawContext.canvas.drawPath(path, paint)
                    } else {
                        drawPath(
                            path = path,
                            color = finalComposeColor,
                            style = styleToUse,
                            blendMode = composeBlendMode
                        )
                    }
                }
            }
            com.example.studio.model.LayerType.VECTOR_PENTAGON -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 5
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                if (paintToUse != null) {
                    if (layer.cornerRadius > 0f) {
                        paintToUse.asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    drawContext.canvas.drawPath(path, paintToUse)
                } else {
                    if (layer.cornerRadius > 0f) {
                        val paint = androidx.compose.ui.graphics.Paint().apply {
                            color = finalComposeColor
                            style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                                androidx.compose.ui.graphics.PaintingStyle.Stroke
                            } else {
                                androidx.compose.ui.graphics.PaintingStyle.Fill
                            }
                            if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                                strokeWidth = styleToUse.width
                            }
                            blendMode = composeBlendMode
                            asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                        }
                        drawContext.canvas.drawPath(path, paint)
                    } else {
                        drawPath(
                            path = path,
                            color = finalComposeColor,
                            style = styleToUse,
                            blendMode = composeBlendMode
                        )
                    }
                }
            }
            com.example.studio.model.LayerType.VECTOR_HEXAGON -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 6
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                if (paintToUse != null) {
                    if (layer.cornerRadius > 0f) {
                        paintToUse.asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    drawContext.canvas.drawPath(path, paintToUse)
                } else {
                    if (layer.cornerRadius > 0f) {
                        val paint = androidx.compose.ui.graphics.Paint().apply {
                            color = finalComposeColor
                            style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                                androidx.compose.ui.graphics.PaintingStyle.Stroke
                            } else {
                                androidx.compose.ui.graphics.PaintingStyle.Fill
                            }
                            if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                                strokeWidth = styleToUse.width
                            }
                            blendMode = composeBlendMode
                            asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                        }
                        drawContext.canvas.drawPath(path, paint)
                    } else {
                        drawPath(
                            path = path,
                            color = finalComposeColor,
                            style = styleToUse,
                            blendMode = composeBlendMode
                        )
                    }
                }
            }
            com.example.studio.model.LayerType.VECTOR_OVAL -> {
                if (paintToUse != null) {
                    drawContext.canvas.drawOval(
                        left = 0f,
                        top = 0f,
                        right = layer.width,
                        bottom = layer.height,
                        paint = paintToUse
                    )
                } else {
                    drawOval(
                        color = finalComposeColor,
                        topLeft = androidx.compose.ui.geometry.Offset.Zero,
                        size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                        style = styleToUse,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_LINE -> {
                val strokeW = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) styleToUse.width else (if (layer.strokeThickness > 0f) layer.strokeThickness else 6f)
                drawLine(
                    color = finalComposeColor,
                    start = androidx.compose.ui.geometry.Offset.Zero,
                    end = androidx.compose.ui.geometry.Offset(layer.width, layer.height),
                    strokeWidth = strokeW,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.VECTOR_BEZIER -> {
                if (layer.brushPoints.isNotEmpty()) {
                    val cacheKey = getLayerGeometryHash(layer)
                    var path = pathCache.get(cacheKey)
                    if (path == null) {
                        path = androidx.compose.ui.graphics.Path().apply {
                            val anchors = layer.brushPoints.toAnchorPoints()
                            if (anchors.isNotEmpty()) {
                                val first = anchors[0]
                                moveTo(first.position.x, first.position.y)
                                for (index in 0 until anchors.size - 1) {
                                    val current = anchors[index]
                                    val next = anchors[index + 1]
                                    cubicTo(
                                        current.handleOut.x, current.handleOut.y,
                                        next.handleIn.x, next.handleIn.y,
                                        next.position.x, next.position.y
                                    )
                                }
                            } else {
                                val startPt = layer.brushPoints[0]
                                moveTo(startPt.x, startPt.y)
                                lineTo(startPt.x + 0.1f, startPt.y)
                            }
                        }
                        pathCache.put(cacheKey, path)
                    }
                    if (paintToUse != null) {
                        drawContext.canvas.drawPath(path, paintToUse)
                    } else {
                        val shapeStyle = if (layer.isAlphaLocked) {
                            styleToUse
                        } else {
                            val strokeW = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) styleToUse.width else (if (layer.strokeThickness > 0f) layer.strokeThickness else 8f)
                            androidx.compose.ui.graphics.drawscope.Stroke(
                                width = strokeW,
                                cap = androidx.compose.ui.graphics.StrokeCap.Round,
                                join = androidx.compose.ui.graphics.StrokeJoin.Round
                            )
                        }
                        drawPath(
                            path = path,
                            color = finalComposeColor,
                            style = shapeStyle,
                            blendMode = composeBlendMode
                        )
                    }
                }
            }
            com.example.studio.model.LayerType.VECTOR_CIRCLE -> {
                val radius = layer.width / 2f
                val center = androidx.compose.ui.geometry.Offset(radius, layer.height / 2f)
                if (paintToUse != null) {
                    drawContext.canvas.drawCircle(
                        center = center,
                        radius = radius,
                        paint = paintToUse
                    )
                } else {
                    drawCircle(
                        color = finalComposeColor,
                        radius = radius,
                        center = center,
                        style = styleToUse,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_STAR -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rOuter = layer.width / 2f
                        val rInner = rOuter * layer.starInnerRadiusRatio.coerceIn(0.01f, 0.99f)
                        val pointsCount = if (layer.polygonEdges >= 3) layer.polygonEdges else 5
                        var angle = Math.PI / 2.0 * 3.0
                        val step = Math.PI / pointsCount

                        moveTo(
                            (cx + Math.cos(angle) * rOuter).toFloat(),
                            (cy + Math.sin(angle) * rOuter).toFloat()
                        )

                        for (i in 0..(pointsCount * 2)) {
                            val r = if (i % 2 == 0) rOuter else rInner
                            lineTo(
                                (cx + Math.cos(angle) * r).toFloat(),
                                (cy + Math.sin(angle) * r).toFloat()
                            )
                            angle += step
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                if (paintToUse != null) {
                    if (layer.cornerRadius > 0f) {
                        paintToUse.asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    drawContext.canvas.drawPath(path, paintToUse)
                } else {
                    if (layer.cornerRadius > 0f) {
                        val paint = androidx.compose.ui.graphics.Paint().apply {
                            color = finalComposeColor
                            style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                                androidx.compose.ui.graphics.PaintingStyle.Stroke
                            } else {
                                androidx.compose.ui.graphics.PaintingStyle.Fill
                            }
                            if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                                strokeWidth = styleToUse.width
                            }
                            blendMode = composeBlendMode
                            asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                        }
                        drawContext.canvas.drawPath(path, paint)
                    } else {
                        drawPath(
                            path = path,
                            color = finalComposeColor,
                            style = styleToUse,
                            blendMode = composeBlendMode
                        )
                    }
                }
            }
            com.example.studio.model.LayerType.TEXT -> {
                drawTextLayerInternal(
                    layer = layer,
                    opacityMultiplier = layerOpacity,
                    composeBlendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.FREEHAND_DRAWING -> {
                val canvas = drawContext.canvas
                val paint = androidx.compose.ui.graphics.Paint()
                val widthToUse = if (layer.width.isFinite() && layer.width > 0f) layer.width else 1000f
                val heightToUse = if (layer.height.isFinite() && layer.height > 0f) layer.height else 1000f
                val bounds = androidx.compose.ui.geometry.Rect(0f, 0f, widthToUse, heightToUse)

                var savedSuccessfully = false
                try {
                    canvas.saveLayer(bounds, paint)
                    savedSuccessfully = true
                } catch (t: Throwable) {
                    try {
                        canvas.save()
                        savedSuccessfully = true
                    } catch (t2: Throwable) {}
                }

                if (savedSuccessfully) {
                    try {
                        val activeFilters = layer.effects.filter { it.isEnabled && it.name != "BrushConfig" }
                        val effectsHash = activeFilters.sumOf { it.hashCode() }
                        val bSize = brushConfig?.parameters?.get("Size")?.value ?: 12f
                        val bOpacity = brushConfig?.parameters?.get("Opacity")?.value ?: 1.0f
                        val bSmoothing = (brushConfig?.parameters?.get("Smoothing")?.value ?: 1.0f) > 0.5f
                        val bPreset = brushConfig?.parameters?.get("Preset")?.value?.toInt() ?: 0

                        val w = widthToUse.toInt().coerceIn(1, 2048)
                        val h = heightToUse.toInt().coerceIn(1, 2048)

                        // Unified multi-layer caching key guaranteeing O(1) rendering cache-hits
                        val cacheKey = "drawing_${layer.id}_${layer.brushPoints.size}_${effectsHash}_${bSize}_${bOpacity}_${bSmoothing}_${bPreset}_${layerOpacity}_${finalComposeColor.hashCode()}_${w}_${h}"
                        var cachedProcessed = processedImageBitmapCache[cacheKey]

                        if (cachedProcessed == null) {
                            val offscreenBmp = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
                            val nativeCanvas = android.graphics.Canvas(offscreenBmp)
                            val tempCanvas = androidx.compose.ui.graphics.Canvas(nativeCanvas)
                            val originalCanvas = drawContext.canvas

                            drawContext.canvas = tempCanvas
                            nativeCanvas.drawColor(android.graphics.Color.TRANSPARENT, android.graphics.PorterDuff.Mode.CLEAR)

                            try {
                                if (layer.brushPoints.isNotEmpty()) {
                                    val strokesKey = "${layer.id}_${layer.brushPoints.size}_${bSize}_${bOpacity}_${bSmoothing}_${bPreset}_${layerOpacity}_${finalComposeColor.hashCode()}"
                                    var strokes = parsedStrokesCache.get(strokesKey)
                                    if (strokes == null) {
                                        strokes = parseFreehandStrokes(
                                            brushPoints = layer.brushPoints,
                                            defaultColor = finalComposeColor,
                                            defaultSize = bSize,
                                            defaultOpacity = bOpacity * layerOpacity,
                                            defaultPreset = bPreset,
                                            defaultSmoothing = bSmoothing
                                        )
                                        parsedStrokesCache.put(strokesKey, strokes)
                                    }

                                    for (stroke in strokes) {
                                        if (stroke.points.isNotEmpty()) {
                                            val strokeBlend = if (stroke.isEraser) androidx.compose.ui.graphics.BlendMode.DstOut else composeBlendMode
                                            drawBrushStroke(
                                                points = stroke.points,
                                                color = stroke.color,
                                                size = stroke.size,
                                                opacity = stroke.opacity,
                                                presetIndex = stroke.presetIndex,
                                                smoothing = stroke.smoothing,
                                                originX = 0f,
                                                originY = 0f,
                                                composeBlendMode = strokeBlend,
                                                pathCache = pathCache,
                                                pathPointsCountCache = pathPointsCountCache,
                                                cacheKey = layer.id.hashCode() + stroke.hashCode(),
                                                backdropBitmap = backdropBitmap
                                            )
                                        }
                                    }
                                }
                            } finally {
                                drawContext.canvas = originalCanvas
                            }

                            val filteredBmp = if (activeFilters.isNotEmpty() && globalAppContext != null) {
                                applyGPUImageFilters(globalAppContext!!, offscreenBmp, activeFilters)
                            } else {
                                offscreenBmp
                            }
                            cachedProcessed = filteredBmp.asImageBitmap()
                            processedImageBitmapCache[cacheKey] = cachedProcessed
                        }

                        cachedProcessed?.let { img ->
                            drawImage(
                                image = img,
                                topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                blendMode = composeBlendMode
                            )
                        }

                        // Render active real-time Wet Ink stroke on top separately; guarantees fluid 60 FPS feedback and zero filter freezes
                        if (layer.id == selectedLayerId && OpenGLBrushRenderer.WetInkRenderer.isInitialized()) {
                            OpenGLBrushRenderer.WetInkRenderer.getWetInkBitmap()?.let { b ->
                                drawImage(
                                    image = b.asImageBitmap(),
                                    topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                    blendMode = if (activeTool == "Eraser") androidx.compose.ui.graphics.BlendMode.DstOut else composeBlendMode
                                )
                            }
                        }
                    } catch (t: Throwable) {
                        t.printStackTrace()
                    } finally {
                        try {
                            canvas.restore()
                        } catch (t: Throwable) {}
                    }
                }
            }
            com.example.studio.model.LayerType.GROUP -> {}
            com.example.studio.model.LayerType.IMAGE_CARD -> {
                if (isOverlay) {
                    val uriStr = layer.imageUri
                    val loadedBitmap = if (!uriStr.isNullOrEmpty()) imageBitmapCache[uriStr] else null
                    if (loadedBitmap != null) {
                        val paintWithTint = androidx.compose.ui.graphics.Paint().apply {
                            this.color = finalComposeColor
                            this.blendMode = composeBlendMode
                            this.colorFilter = androidx.compose.ui.graphics.ColorFilter.tint(finalComposeColor, androidx.compose.ui.graphics.BlendMode.SrcIn)
                            val fwOrig = paintToUse?.asFrameworkPaint()
                            val fwSelf = this.asFrameworkPaint()
                            if (fwOrig != null) {
                                fwSelf.shader = fwOrig.shader
                                fwSelf.maskFilter = fwOrig.maskFilter
                            }
                        }
                        try {
                            val bounds = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height)
                            drawContext.canvas.saveLayer(bounds, paintWithTint)
                            drawContext.canvas.drawImageRect(
                                image = loadedBitmap,
                                dstSize = androidx.compose.ui.unit.IntSize(layer.width.toInt(), layer.height.toInt()),
                                paint = androidx.compose.ui.graphics.Paint().apply {
                                    this.color = finalComposeColor
                                    this.blendMode = androidx.compose.ui.graphics.BlendMode.SrcOver
                                    this.colorFilter = androidx.compose.ui.graphics.ColorFilter.tint(finalComposeColor, androidx.compose.ui.graphics.BlendMode.SrcIn)
                                }
                            )
                        } catch (e: Exception) {
                            drawContext.canvas.drawImageRect(
                                image = loadedBitmap,
                                dstSize = androidx.compose.ui.unit.IntSize(layer.width.toInt(), layer.height.toInt()),
                                paint = paintWithTint
                            )
                        } finally {
                            try {
                                drawContext.canvas.restore()
                            } catch (t: Throwable) {}
                        }
                    } else if (paintToUse != null) {
                        if (layer.cornerRadius > 0f) {
                            drawContext.canvas.drawRoundRect(
                                left = 0f,
                                top = 0f,
                                right = layer.width,
                                bottom = layer.height,
                                radiusX = layer.cornerRadius,
                                radiusY = layer.cornerRadius,
                                paint = paintToUse
                            )
                        } else {
                            drawContext.canvas.drawRect(
                                left = 0f,
                                top = 0f,
                                right = layer.width,
                                bottom = layer.height,
                                paint = paintToUse
                            )
                        }
                    } else {
                        if (layer.cornerRadius > 0f) {
                            drawRoundRect(
                                color = finalComposeColor,
                                topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                                cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius),
                                style = styleToUse,
                                blendMode = composeBlendMode
                            )
                        } else {
                            drawRect(
                                color = finalComposeColor,
                                topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                                style = styleToUse,
                                blendMode = composeBlendMode
                            )
                        }
                    }
                } else {
                    val uriStr = layer.imageUri
                    val loadedBitmap = if (!uriStr.isNullOrEmpty()) imageBitmapCache[uriStr] else null
                    if (loadedBitmap != null) {
                        val activeEffects = layer.effects.filter { it.isEnabled }
                        val _drawTrigger = rawFilterRedrawTrigger.value
                        val drawImage = if (activeEffects.isNotEmpty()) {
                            val effectHash = activeEffects.map { it.id + "_" + it.parameters.values.joinToString { p -> p.value.toString() } }.hashCode()
                            val processedKey = "${layer.id}_${uriStr}_${effectHash}"
                            var cachedProcessed = processedImageBitmapCache[processedKey]
                            if (cachedProcessed == null) {
                                CameraRAWFilterEngine.triggerBackgroundFilterRender(
                                    processedKey = processedKey,
                                    layerId = layer.id,
                                    loadedBitmap = loadedBitmap,
                                    activeEffects = activeEffects,
                                    context = globalAppContext
                                )
                                loadedBitmap
                            } else {
                                cachedProcessed
                            }
                        } else {
                            loadedBitmap
                        }
                        drawImage(
                            image = drawImage,
                            dstSize = androidx.compose.ui.unit.IntSize(layer.width.toInt(), layer.height.toInt()),
                            alpha = finalOpacity * layerOpacity,
                            blendMode = composeBlendMode
                        )
                    } else {
                        drawRect(
                            color = finalComposeColor,
                            topLeft = androidx.compose.ui.geometry.Offset.Zero,
                            size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                            style = fillStyle,
                            blendMode = composeBlendMode
                        )
                        drawCircle(
                            color = androidx.compose.ui.graphics.Color(0xFFFFCC80).copy(alpha = finalOpacity * layerOpacity * 0.7f),
                            radius = 35f,
                            center = androidx.compose.ui.geometry.Offset(layer.width / 2f, layer.height / 2f)
                        )
                    }
                }
            }
        }

        if (hasEraserOrBrush) {
            if (canvasSaved) {
                try {
                    val bSize = brushConfig?.parameters?.get("Size")?.value ?: 12f
                    val bOpacity = brushConfig?.parameters?.get("Opacity")?.value ?: 1.0f
                    val bSmoothing = (brushConfig?.parameters?.get("Smoothing")?.value ?: 1.0f) > 0.5f
                    val bPreset = brushConfig?.parameters?.get("Preset")?.value?.toInt() ?: 3

                    val cacheKey = "${layer.id}_${layer.brushPoints.size}_${bSize}_${bOpacity}_${bSmoothing}_${bPreset}_${layerOpacity}_${finalComposeColor.hashCode()}"
                    var strokes = parsedStrokesCache.get(cacheKey)
                    if (strokes == null) {
                        strokes = parseFreehandStrokes(
                            brushPoints = layer.brushPoints,
                            defaultColor = finalComposeColor,
                            defaultSize = bSize,
                            defaultOpacity = bOpacity * layerOpacity,
                            defaultPreset = bPreset,
                            defaultSmoothing = bSmoothing
                        )
                        parsedStrokesCache.put(cacheKey, strokes)
                    }

                    for (stroke in strokes) {
                        if (stroke.points.isNotEmpty()) {
                            val strokeBlend = if (stroke.isEraser) androidx.compose.ui.graphics.BlendMode.DstOut else composeBlendMode
                            drawBrushStroke(
                                points = stroke.points,
                                color = stroke.color,
                                size = stroke.size,
                                opacity = stroke.opacity,
                                presetIndex = stroke.presetIndex,
                                smoothing = stroke.smoothing,
                                originX = 0f,
                                originY = 0f,
                                composeBlendMode = strokeBlend,
                                pathCache = pathCache,
                                pathPointsCountCache = pathPointsCountCache,
                                cacheKey = layer.id.hashCode() + stroke.hashCode(),
                                backdropBitmap = backdropBitmap,
                                customHardness = stroke.hardness
                            )
                        }
                    }

                    // Render active real-time Wet Ink stroke on top separately if this layer is currently being erased
                    if (layer.id == selectedLayerId && OpenGLBrushRenderer.WetInkRenderer.isInitialized() && activeTool == "Eraser") {
                        OpenGLBrushRenderer.WetInkRenderer.getWetInkBitmap()?.let { b ->
                            drawImage(
                                image = b.asImageBitmap(),
                                topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                blendMode = androidx.compose.ui.graphics.BlendMode.DstOut
                            )
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                } finally {
                    try {
                        drawContext.canvas.restore()
                    } catch (t: Throwable) {}
                }
            }
        }
    }

    // Shape/Geometry drawing helper with high-quality GPU BlurMaskFilter support
    fun drawGeometryWithBlurAndOffset(finalColor: androidx.compose.ui.graphics.Color, finalOpacity: Float, fillStyle: androidx.compose.ui.graphics.drawscope.DrawStyle, blurRadius: Float, blurMode: android.graphics.BlurMaskFilter.Blur, offsetX: Float, offsetY: Float, isOverlay: Boolean = true) {
        val finalComposeColor = finalColor.copy(alpha = finalOpacity * layerOpacity)
        val styleToUse = if (layer.strokeThickness > 0f && fillStyle is androidx.compose.ui.graphics.drawscope.Fill && layer.type !in listOf(com.example.studio.model.LayerType.FREEHAND_DRAWING, com.example.studio.model.LayerType.IMAGE_CARD, com.example.studio.model.LayerType.TEXT)) {
            androidx.compose.ui.graphics.drawscope.Stroke(width = layer.strokeThickness)
        } else {
            fillStyle
        }

        if (blurRadius <= 0.2f && offsetX == 0f && offsetY == 0f) {
            drawGeometry(finalColor, finalOpacity, fillStyle)
        } else {
            val paint = androidx.compose.ui.graphics.Paint().apply {
                color = finalComposeColor
                this.style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                    androidx.compose.ui.graphics.PaintingStyle.Stroke
                } else {
                    androidx.compose.ui.graphics.PaintingStyle.Fill
                }
                if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                    this.strokeWidth = styleToUse.width
                }
                this.blendMode = composeBlendMode
                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                    val tileMode = if (blurMode == android.graphics.BlurMaskFilter.Blur.OUTER) {
                        android.graphics.Shader.TileMode.CLAMP
                    } else {
                        android.graphics.Shader.TileMode.DECAL
                    }
                    try {
                        val fwPaint = asFrameworkPaint()
                        val mSet = fwPaint.javaClass.getMethod("setRenderEffect", android.graphics.RenderEffect::class.java)
                        val blurEffect = android.graphics.RenderEffect.createBlurEffect(blurRadius, blurRadius, tileMode)
                        val chainEffect = if (offsetX != 0f || offsetY != 0f) {
                            android.graphics.RenderEffect.createOffsetEffect(offsetX, offsetY, blurEffect)
                        } else {
                            blurEffect
                        }
                        mSet.invoke(fwPaint, chainEffect)
                    } catch (t: Throwable) {
                        asFrameworkPaint().maskFilter = android.graphics.BlurMaskFilter(blurRadius, blurMode)
                    }
                } else {
                    asFrameworkPaint().maskFilter = android.graphics.BlurMaskFilter(blurRadius, blurMode)
                }
            }

            when (layer.type) {
                com.example.studio.model.LayerType.VECTOR_RECT -> {
                    if (layer.cornerRadius > 0f) {
                        val rRect = androidx.compose.ui.geometry.RoundRect(
                            rect = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height),
                            cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius)
                        )
                        val path = androidx.compose.ui.graphics.Path().apply { addRoundRect(rRect) }
                        drawContext.canvas.drawPath(path, paint)
                    } else {
                        drawContext.canvas.drawRect(
                            rect = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height),
                            paint = paint
                        )
                    }
                }
                com.example.studio.model.LayerType.VECTOR_TRIANGLE,
                com.example.studio.model.LayerType.VECTOR_PENTAGON,
                com.example.studio.model.LayerType.VECTOR_HEXAGON -> {
                    val cacheKey = getLayerGeometryHash(layer)
                    var path = pathCache.get(cacheKey)
                    if (path == null) {
                        path = androidx.compose.ui.graphics.Path().apply {
                            val edges = if (layer.type == com.example.studio.model.LayerType.VECTOR_HEXAGON) {
                                if (layer.polygonEdges in 3..25) layer.polygonEdges else 6
                            } else if (layer.type == com.example.studio.model.LayerType.VECTOR_PENTAGON) {
                                if (layer.polygonEdges in 3..25) layer.polygonEdges else 5
                            } else {
                                if (layer.polygonEdges in 3..25) layer.polygonEdges else 3
                            }
                            val cx = layer.width / 2f
                            val cy = layer.height / 2f
                            val rx = layer.width / 2f
                            val ry = layer.height / 2f
                            for (i in 0 until edges) {
                                val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                                val x = (cx + rx * Math.cos(angle)).toFloat()
                                val y = (cy + ry * Math.sin(angle)).toFloat()
                                if (i == 0) moveTo(x, y) else lineTo(x, y)
                            }
                            close()
                        }
                        pathCache.put(cacheKey, path)
                    }
                    if (layer.cornerRadius > 0f) {
                        paint.asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    drawContext.canvas.drawPath(path, paint)
                }
                com.example.studio.model.LayerType.VECTOR_OVAL -> {
                    val path = androidx.compose.ui.graphics.Path().apply {
                        addOval(androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height))
                    }
                    drawContext.canvas.drawPath(path, paint)
                }
                com.example.studio.model.LayerType.VECTOR_LINE -> {
                    val px = layer.width
                    val py = layer.height
                    val path = androidx.compose.ui.graphics.Path().apply {
                        moveTo(0f, 0f)
                        lineTo(px, py)
                    }
                    drawContext.canvas.drawPath(path, paint)
                }
                com.example.studio.model.LayerType.VECTOR_BEZIER -> {
                    if (layer.brushPoints.isNotEmpty()) {
                        val cacheKey = getLayerGeometryHash(layer)
                        var path = pathCache.get(cacheKey)
                        if (path == null) {
                            path = androidx.compose.ui.graphics.Path().apply {
                                val anchors = layer.brushPoints.toAnchorPoints()
                                if (anchors.isNotEmpty()) {
                                    val first = anchors[0]
                                    moveTo(first.position.x, first.position.y)
                                    for (index in 0 until anchors.size - 1) {
                                        val current = anchors[index]
                                        val next = anchors[index + 1]
                                        cubicTo(
                                            current.handleOut.x, current.handleOut.y,
                                            next.handleIn.x, next.handleIn.y,
                                            next.position.x, next.position.y
                                        )
                                    }
                                } else {
                                    val startPt = layer.brushPoints[0]
                                    moveTo(startPt.x, startPt.y)
                                    lineTo(startPt.x + 0.1f, startPt.y)
                                }
                            }
                            pathCache.put(cacheKey, path)
                        }
                        drawContext.canvas.drawPath(path, paint)
                    }
                }
                com.example.studio.model.LayerType.VECTOR_CIRCLE -> {
                    val radius = layer.width / 2f
                    val center = androidx.compose.ui.geometry.Offset(radius, layer.height / 2f)
                    drawContext.canvas.drawCircle(center, radius, paint)
                }
                com.example.studio.model.LayerType.VECTOR_STAR -> {
                    val cacheKey = getLayerGeometryHash(layer)
                    var path = pathCache.get(cacheKey)
                    if (path == null) {
                        path = androidx.compose.ui.graphics.Path().apply {
                            val cx = layer.width / 2f
                            val cy = layer.height / 2f
                            val rOuter = layer.width / 2f
                            val rInner = rOuter * layer.starInnerRadiusRatio.coerceIn(0.01f, 0.99f)
                            val pointsCount = if (layer.polygonEdges >= 3) layer.polygonEdges else 5
                            var angle = Math.PI / 2.0 * 3.0
                            val step = Math.PI / pointsCount

                            moveTo(
                                (cx + Math.cos(angle) * rOuter).toFloat(),
                                (cy + Math.sin(angle) * rOuter).toFloat()
                            )

                            for (i in 0..(pointsCount * 2)) {
                                val r = if (i % 2 == 0) rOuter else rInner
                                lineTo(
                                    (cx + Math.cos(angle) * r).toFloat(),
                                    (cy + Math.sin(angle) * r).toFloat()
                                )
                                angle += step
                            }
                            close()
                        }
                        pathCache.put(cacheKey, path)
                    }
                    if (layer.cornerRadius > 0f) {
                        paint.asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    drawContext.canvas.drawPath(path, paint)
                }
                com.example.studio.model.LayerType.TEXT -> {
                    drawTextLayerInternal(
                        layer = layer,
                        opacityMultiplier = finalOpacity,
                        composeBlendMode = composeBlendMode,
                        blurRadius = blurRadius
                    )
                }
                com.example.studio.model.LayerType.FREEHAND_DRAWING -> {
                    if (layer.brushPoints.isNotEmpty()) {
                        val cacheKey = layer.id.hashCode()
                        val cachedPath = pathCache.get(cacheKey)
                        val px = layer.positionX
                        val py = layer.positionY

                        val path = if (cachedPath != null) {
                            cachedPath
                        } else {
                            val newPath = androidx.compose.ui.graphics.Path().apply {
                                var isFirst = true
                                for (pt in layer.brushPoints) {
                                    if (pt == androidx.compose.ui.geometry.Offset.Unspecified || pt.x.isNaN() || pt.y.isNaN()) {
                                        isFirst = true
                                    } else {
                                        if (isFirst) {
                                            moveTo(pt.x - px, pt.y - py)
                                            isFirst = false
                                        } else {
                                            lineTo(pt.x - px, pt.y - py)
                                        }
                                    }
                                }
                            }
                            pathCache.put(cacheKey, newPath)
                            newPath
                        }
                        drawContext.canvas.drawPath(path, paint)
                    }
                }
                com.example.studio.model.LayerType.GROUP -> {}
                com.example.studio.model.LayerType.IMAGE_CARD -> {
                    if (isOverlay) {
                        val uriStr = layer.imageUri
                        val loadedBitmap = if (!uriStr.isNullOrEmpty()) imageBitmapCache[uriStr] else null
                        if (loadedBitmap != null) {
                            val paintWithTint = androidx.compose.ui.graphics.Paint().apply {
                                this.color = finalComposeColor
                                this.blendMode = paint.blendMode
                                this.colorFilter = androidx.compose.ui.graphics.ColorFilter.tint(finalComposeColor, androidx.compose.ui.graphics.BlendMode.SrcIn)
                                val fwOrig = paint.asFrameworkPaint()
                                val fwSelf = this.asFrameworkPaint()
                                fwSelf.shader = fwOrig.shader
                                fwSelf.maskFilter = fwOrig.maskFilter
                                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                                    try {
                                        val getMethod = fwOrig.javaClass.getMethod("getRenderEffect")
                                        val renderEffect = getMethod.invoke(fwOrig)
                                        if (renderEffect != null) {
                                            val setMethod = fwSelf.javaClass.getMethod("setRenderEffect", android.graphics.RenderEffect::class.java)
                                            setMethod.invoke(fwSelf, renderEffect)
                                        }
                                    } catch (e: Exception) {
                                        e.printStackTrace()
                                    }
                                }
                            }
                            try {
                                val bounds = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height)
                                drawContext.canvas.saveLayer(bounds, paintWithTint)
                                drawContext.canvas.drawImageRect(
                                    image = loadedBitmap,
                                    dstSize = androidx.compose.ui.unit.IntSize(layer.width.toInt(), layer.height.toInt()),
                                    paint = androidx.compose.ui.graphics.Paint().apply {
                                        this.color = finalComposeColor
                                        this.blendMode = androidx.compose.ui.graphics.BlendMode.SrcOver
                                        this.colorFilter = androidx.compose.ui.graphics.ColorFilter.tint(finalComposeColor, androidx.compose.ui.graphics.BlendMode.SrcIn)
                                    }
                                )
                            } catch (e: Exception) {
                                drawContext.canvas.drawImageRect(
                                    image = loadedBitmap,
                                    dstSize = androidx.compose.ui.unit.IntSize(layer.width.toInt(), layer.height.toInt()),
                                    paint = paintWithTint
                                )
                            } finally {
                                try {
                                    drawContext.canvas.restore()
                                } catch (t: Throwable) {}
                            }
                        } else {
                            if (layer.cornerRadius > 0f) {
                                val rRect = androidx.compose.ui.geometry.RoundRect(
                                    rect = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height),
                                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius)
                                )
                                val path = androidx.compose.ui.graphics.Path().apply { addRoundRect(rRect) }
                                drawContext.canvas.drawPath(path, paint)
                            } else {
                                drawContext.canvas.drawRect(
                                    rect = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height),
                                    paint = paint
                                )
                            }
                        }
                    } else {
                        val uriStr = layer.imageUri
                        val loadedBitmap = if (!uriStr.isNullOrEmpty()) imageBitmapCache[uriStr] else null
                        if (loadedBitmap != null) {
                            val activeEffects = layer.effects.filter { it.isEnabled }
                            val _drawTrigger = rawFilterRedrawTrigger.value
                            val drawImage = if (activeEffects.isNotEmpty()) {
                                val effectHash = activeEffects.map { it.id + "_" + it.parameters.values.joinToString { p -> p.value.toString() } }.hashCode()
                                val processedKey = "${layer.id}_${uriStr}_${effectHash}"
                                var cachedProcessed = processedImageBitmapCache[processedKey]
                                if (cachedProcessed == null) {
                                    CameraRAWFilterEngine.triggerBackgroundFilterRender(
                                        processedKey = processedKey,
                                        layerId = layer.id,
                                        loadedBitmap = loadedBitmap,
                                        activeEffects = activeEffects,
                                        context = globalAppContext
                                    )
                                    loadedBitmap
                                } else {
                                    cachedProcessed
                                }
                            } else {
                                loadedBitmap
                            }
                            drawContext.canvas.drawImageRect(
                                image = drawImage,
                                dstSize = androidx.compose.ui.unit.IntSize(layer.width.toInt(), layer.height.toInt()),
                                paint = paint
                            )
                        } else {
                            drawContext.canvas.drawRect(
                                rect = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height),
                                paint = paint
                            )
                        }
                    }
                }
            }
        }
    }

    fun drawGeometryWithBlur(finalColor: androidx.compose.ui.graphics.Color, finalOpacity: Float, fillStyle: androidx.compose.ui.graphics.drawscope.DrawStyle, blurRadius: Float, blurMode: android.graphics.BlurMaskFilter.Blur, isOverlay: Boolean = true) {
        drawGeometryWithBlurAndOffset(finalColor, finalOpacity, fillStyle, blurRadius, blurMode, 0f, 0f, isOverlay)
    }

    // Brush/Gradient drawing helper
    val drawGeometryWithBrush: (androidx.compose.ui.graphics.Brush, Float, androidx.compose.ui.graphics.drawscope.DrawStyle) -> Unit = { finalBrush, finalOpacity, fillStyle ->
        val brushAlpha = finalOpacity * layerOpacity
        val styleToUse = if (layer.strokeThickness > 0f && fillStyle is androidx.compose.ui.graphics.drawscope.Fill && layer.type !in listOf(com.example.studio.model.LayerType.FREEHAND_DRAWING, com.example.studio.model.LayerType.IMAGE_CARD, com.example.studio.model.LayerType.TEXT)) {
            androidx.compose.ui.graphics.drawscope.Stroke(width = layer.strokeThickness)
        } else {
            fillStyle
        }
        when (layer.type) {
            com.example.studio.model.LayerType.VECTOR_RECT -> {
                if (layer.cornerRadius > 0f) {
                    drawRoundRect(
                        brush = finalBrush,
                        topLeft = androidx.compose.ui.geometry.Offset.Zero,
                        size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius),
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                } else {
                    drawRect(
                        brush = finalBrush,
                        topLeft = androidx.compose.ui.geometry.Offset.Zero,
                        size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_TRIANGLE -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 3
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                if (layer.cornerRadius > 0f) {
                    val paint = androidx.compose.ui.graphics.Paint().apply {
                        style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            androidx.compose.ui.graphics.PaintingStyle.Stroke
                        } else {
                            androidx.compose.ui.graphics.PaintingStyle.Fill
                        }
                        if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            strokeWidth = styleToUse.width
                        }
                        blendMode = composeBlendMode
                        asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    finalBrush.applyTo(androidx.compose.ui.geometry.Size(layer.width, layer.height), paint, brushAlpha)
                    drawContext.canvas.drawPath(path, paint)
                } else {
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_PENTAGON -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 5
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                if (layer.cornerRadius > 0f) {
                    val paint = androidx.compose.ui.graphics.Paint().apply {
                        style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            androidx.compose.ui.graphics.PaintingStyle.Stroke
                        } else {
                            androidx.compose.ui.graphics.PaintingStyle.Fill
                        }
                        if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            strokeWidth = styleToUse.width
                        }
                        blendMode = composeBlendMode
                        asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    finalBrush.applyTo(androidx.compose.ui.geometry.Size(layer.width, layer.height), paint, brushAlpha)
                    drawContext.canvas.drawPath(path, paint)
                } else {
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_HEXAGON -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 6
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                if (layer.cornerRadius > 0f) {
                    val paint = androidx.compose.ui.graphics.Paint().apply {
                        style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            androidx.compose.ui.graphics.PaintingStyle.Stroke
                        } else {
                            androidx.compose.ui.graphics.PaintingStyle.Fill
                        }
                        if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            strokeWidth = styleToUse.width
                        }
                        blendMode = composeBlendMode
                        asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    finalBrush.applyTo(androidx.compose.ui.geometry.Size(layer.width, layer.height), paint, brushAlpha)
                    drawContext.canvas.drawPath(path, paint)
                } else {
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_OVAL -> {
                drawOval(
                    brush = finalBrush,
                    topLeft = androidx.compose.ui.geometry.Offset.Zero,
                    size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                    style = styleToUse,
                    alpha = brushAlpha,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.VECTOR_LINE -> {
                val strokeW = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) styleToUse.width else (if (layer.strokeThickness > 0f) layer.strokeThickness else 6f)
                drawLine(
                    brush = finalBrush,
                    start = androidx.compose.ui.geometry.Offset.Zero,
                    end = androidx.compose.ui.geometry.Offset(layer.width, layer.height),
                    strokeWidth = strokeW,
                    alpha = brushAlpha,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.VECTOR_BEZIER -> {
                val start = androidx.compose.ui.geometry.Offset(0f, layer.height)
                val end = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
                val controlLocal = layer.brushPoints.getOrNull(0) ?: androidx.compose.ui.geometry.Offset(layer.width / 2f, 0f)

                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val anchors = layer.brushPoints.toAnchorPoints()
                        if (anchors.isNotEmpty()) {
                            val first = anchors[0]
                            moveTo(first.position.x, first.position.y)
                            for (index in 0 until anchors.size - 1) {
                                val current = anchors[index]
                                val next = anchors[index + 1]
                                cubicTo(
                                    current.handleOut.x, current.handleOut.y,
                                    next.handleIn.x, next.handleIn.y,
                                    next.position.x, next.position.y
                                )
                            }
                        } else {
                            moveTo(start.x, start.y)
                            quadraticTo(controlLocal.x, controlLocal.y, end.x, end.y)
                        }
                    }
                    pathCache.put(cacheKey, path)
                }
                val shapeStyle = if (layer.isAlphaLocked) {
                    styleToUse
                } else {
                    val strokeW = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) styleToUse.width else (if (layer.strokeThickness > 0f) layer.strokeThickness else 8f)
                    androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW)
                }
                drawPath(
                    path = path,
                    brush = finalBrush,
                    style = shapeStyle,
                    alpha = brushAlpha,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.VECTOR_CIRCLE -> {
                val radius = layer.width / 2f
                val center = androidx.compose.ui.geometry.Offset(radius, layer.height / 2f)
                drawCircle(
                    brush = finalBrush,
                    radius = radius,
                    center = center,
                    style = styleToUse,
                    alpha = brushAlpha,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.VECTOR_STAR -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rOuter = layer.width / 2f
                        val rInner = rOuter * layer.starInnerRadiusRatio.coerceIn(0.01f, 0.99f)
                        val pointsCount = if (layer.polygonEdges >= 3) layer.polygonEdges else 5
                        var angle = Math.PI / 2.0 * 3.0
                        val step = Math.PI / pointsCount

                        moveTo(
                            (cx + Math.cos(angle) * rOuter).toFloat(),
                            (cy + Math.sin(angle) * rOuter).toFloat()
                        )

                        for (i in 0..(pointsCount * 2)) {
                            val r = if (i % 2 == 0) rOuter else rInner
                            lineTo(
                                (cx + Math.cos(angle) * r).toFloat(),
                                (cy + Math.sin(angle) * r).toFloat()
                            )
                            angle += step
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                if (layer.cornerRadius > 0f) {
                    val paint = androidx.compose.ui.graphics.Paint().apply {
                        style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            androidx.compose.ui.graphics.PaintingStyle.Stroke
                        } else {
                            androidx.compose.ui.graphics.PaintingStyle.Fill
                        }
                        if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            strokeWidth = styleToUse.width
                        }
                        blendMode = composeBlendMode
                        asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(layer.cornerRadius)
                    }
                    finalBrush.applyTo(androidx.compose.ui.geometry.Size(layer.width, layer.height), paint, brushAlpha)
                    drawContext.canvas.drawPath(path, paint)
                } else {
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.TEXT -> {
                drawTextLayerInternal(
                    layer = layer,
                    opacityMultiplier = layerOpacity * brushAlpha,
                    composeBlendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.FREEHAND_DRAWING -> {
                if (layer.brushPoints.isNotEmpty()) {
                    val cacheKey = layer.id.hashCode()
                    val cachedPath = pathCache.get(cacheKey)
                    val px = layer.positionX
                    val py = layer.positionY

                    val path = if (cachedPath != null) {
                        cachedPath
                    } else {
                        val newPath = androidx.compose.ui.graphics.Path().apply {
                            var isFirst = true
                            for (pt in layer.brushPoints) {
                                if (pt == androidx.compose.ui.geometry.Offset.Unspecified || pt.x.isNaN() || pt.y.isNaN()) {
                                    isFirst = true
                                } else {
                                    if (isFirst) {
                                        moveTo(pt.x - px, pt.y - py)
                                        isFirst = false
                                    } else {
                                        lineTo(pt.x - px, pt.y - py)
                                    }
                                }
                            }
                        }
                        pathCache.put(cacheKey, newPath)
                        newPath
                    }
                    val strokeW = if (fillStyle is androidx.compose.ui.graphics.drawscope.Stroke) fillStyle.width else 8f
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW),
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.GROUP -> {}
            com.example.studio.model.LayerType.IMAGE_CARD -> {
                drawRect(
                    brush = finalBrush,
                    topLeft = androidx.compose.ui.geometry.Offset.Zero,
                    size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                    style = fillStyle,
                    alpha = brushAlpha,
                    blendMode = composeBlendMode
                )
            }
        }
    }

    val layerPath: androidx.compose.ui.graphics.Path by lazy {
        val cacheKey = getLayerGeometryHash(layer)
        var p = pathCache.get(cacheKey)
        if (p == null) {
            p = androidx.compose.ui.graphics.Path().apply {
                when (layer.type) {
                    com.example.studio.model.LayerType.VECTOR_RECT -> {
                        if (layer.cornerRadius > 0f) {
                            addRoundRect(
                                androidx.compose.ui.geometry.RoundRect(
                                    rect = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height),
                                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius)
                                )
                            )
                        } else {
                            addRect(androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height))
                        }
                    }
                    com.example.studio.model.LayerType.VECTOR_CIRCLE,
                    com.example.studio.model.LayerType.VECTOR_OVAL -> {
                        addOval(androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height))
                    }
                    com.example.studio.model.LayerType.VECTOR_TRIANGLE -> {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 3
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    com.example.studio.model.LayerType.VECTOR_PENTAGON -> {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 5
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    com.example.studio.model.LayerType.VECTOR_HEXAGON -> {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 6
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    com.example.studio.model.LayerType.VECTOR_STAR -> {
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rOuter = layer.width / 2f
                        val rInner = rOuter * layer.starInnerRadiusRatio.coerceIn(0.01f, 0.99f)
                        val pointsCount = if (layer.polygonEdges >= 3) layer.polygonEdges else 5
                        var angle = Math.PI / 2.0 * 3.0
                        val step = Math.PI / pointsCount

                        moveTo(
                            (cx + Math.cos(angle) * rOuter).toFloat(),
                            (cy + Math.sin(angle) * rOuter).toFloat()
                        )

                        for (i in 0..(pointsCount * 2)) {
                            val r = if (i % 2 == 0) rOuter else rInner
                            lineTo(
                                (cx + Math.cos(angle) * r).toFloat(),
                                (cy + Math.sin(angle) * r).toFloat()
                            )
                            angle += step
                        }
                        close()
                    }
                    com.example.studio.model.LayerType.VECTOR_BEZIER -> {
                        val anchors = layer.brushPoints.toAnchorPoints()
                        if (anchors.isNotEmpty()) {
                            val first = anchors[0]
                            moveTo(first.position.x, first.position.y)
                            for (index in 0 until anchors.size - 1) {
                                val current = anchors[index]
                                val next = anchors[index + 1]
                                cubicTo(
                                    current.handleOut.x, current.handleOut.y,
                                    next.handleIn.x, next.handleIn.y,
                                    next.position.x, next.position.y
                                )
                            }
                        } else if (layer.brushPoints.isNotEmpty()) {
                            val startPt = layer.brushPoints[0]
                            moveTo(startPt.x, startPt.y)
                            lineTo(startPt.x + 0.1f, startPt.y)
                        }
                    }
                    else -> {
                        addRect(androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height))
                    }
                }
            }
            pathCache.put(cacheKey, p)
        }
        p ?: androidx.compose.ui.graphics.Path()
    }

    // 1. Drop Shadow Pass
    if (bordersShadows != null && (bordersShadows.parameters["DropShadow_Enabled"]?.value ?: 0f) > 0.5f) {
        val dsDistance = bordersShadows.parameters["DropShadow_Distance"]?.value ?: 10f
        val dsSize = bordersShadows.parameters["DropShadow_Size"]?.value ?: 15f
        val dsAngle = bordersShadows.parameters["DropShadow_Angle"]?.value ?: 120f
        val dsOpacity = bordersShadows.parameters["DropShadow_Opacity"]?.value ?: 0.5f
        val dsGlow = bordersShadows.parameters["DropShadow_Glow"]?.value ?: 0f
        val dsSharpen = (bordersShadows.parameters["DropShadow_Sharpen"]?.value ?: 0f) > 0.5f
        val dsZoom = bordersShadows.parameters["DropShadow_Zoom"]?.value ?: 1.0f
        val dsHardness = bordersShadows.parameters["DropShadow_Hardness"]?.value ?: 0f
        val dsAlpha = bordersShadows.parameters["DropShadow_Alpha"]?.value ?: 1.0f
        
        val r = bordersShadows.parameters["DropShadow_Color_R"]?.value ?: 0f
        val g = bordersShadows.parameters["DropShadow_Color_G"]?.value ?: 0f
        val b = bordersShadows.parameters["DropShadow_Color_B"]?.value ?: 0f
        val col = androidx.compose.ui.graphics.Color(r, g, b).copy(alpha = dsAlpha)

        val rads = Math.toRadians(dsAngle.toDouble())
        val dx = (dsDistance * Math.cos(rads)).toFloat()
        val dy = (dsDistance * Math.sin(rads)).toFloat()
        withTransform({
            translate(left = dx, top = dy)
            scale(scaleX = dsZoom, scaleY = dsZoom, pivot = androidx.compose.ui.geometry.Offset(layer.width / 2f, layer.height / 2f))
        }) {
            if (dsSize > 0.1f && !dsSharpen) {
                drawGeometryWithBlur(col, dsOpacity, androidx.compose.ui.graphics.drawscope.Fill, dsSize, android.graphics.BlurMaskFilter.Blur.NORMAL)
            } else {
                drawGeometry(col, dsOpacity, androidx.compose.ui.graphics.drawscope.Fill)
            }
        }
    } else if (dropShadow != null) {
        val dsDistance = dropShadow.parameters["Distance"]?.value ?: 10f
        val dsSize = dropShadow.parameters["Size"]?.value ?: 15f
        val dsAngle = dropShadow.parameters["Angle"]?.value ?: 120f
        val dsOpacity = dropShadow.parameters["Opacity"]?.value ?: 0.5f
        val rads = Math.toRadians(dsAngle.toDouble())
        val dx = (dsDistance * Math.cos(rads)).toFloat()
        val dy = (dsDistance * Math.sin(rads)).toFloat()
        withTransform({
            translate(left = dx, top = dy)
        }) {
            if (dsSize > 0.1f) {
                drawGeometryWithBlur(androidx.compose.ui.graphics.Color.Black, dsOpacity, androidx.compose.ui.graphics.drawscope.Fill, dsSize, android.graphics.BlurMaskFilter.Blur.NORMAL)
            } else {
                drawGeometry(androidx.compose.ui.graphics.Color.Black, dsOpacity, androidx.compose.ui.graphics.drawscope.Fill)
            }
        }
    }

    // --- Glass Morphism & Reeded Glass Shader Injection ---
    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
        val compiledEffect = if (glassMorphism != null && glassMorphism.isEnabled) {
            com.example.studio.ui.GlassShaders.compileGlassMorphismEffect(
                effect = glassMorphism,
                width = layer.width,
                height = layer.height,
                backdrop = backdropBitmap,
                globalX = globalX,
                globalY = globalY,
                zoomScale = totalScale
            )
        } else if (reededGlass != null && reededGlass.isEnabled) {
            com.example.studio.ui.GlassShaders.compileReededGlassEffect(
                effect = reededGlass,
                width = layer.width,
                height = layer.height,
                backdrop = backdropBitmap,
                globalX = globalX,
                globalY = globalY,
                zoomScale = totalScale
            )
        } else if (bevelStyle != null && bevelStyle.isEnabled) {
            com.example.studio.ui.GlassShaders.compileBevelEmbossEffect(
                effect = bevelStyle,
                width = layer.width,
                height = layer.height
            )
        } else {
            null
        }

        if (compiledEffect != null && android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
            val nativeCanvas = drawContext.canvas.nativeCanvas
            val paint = android.graphics.Paint()
            try {
                val setRenderEffectMethod = android.graphics.Paint::class.java.getMethod(
                    "setRenderEffect",
                    android.graphics.RenderEffect::class.java
                )
                setRenderEffectMethod.invoke(paint, compiledEffect as android.graphics.RenderEffect)
            } catch (e: Exception) {
                e.printStackTrace()
            }
            nativeCanvas.saveLayer(null, paint)
            didSaveLayer = true
        }
    }

    // 2. Outer Glow Pass
    if (outerGlow != null) {
        val ogSize = outerGlow.parameters["Size"]?.value ?: 20f
        val ogOpacity = outerGlow.parameters["Opacity"]?.value ?: 0.75f
        val ogColor = androidx.compose.ui.graphics.Color(0xFFFF9800)
        if (ogSize > 0.1f) {
            drawGeometryWithBlur(ogColor, ogOpacity, androidx.compose.ui.graphics.drawscope.Fill, ogSize, android.graphics.BlurMaskFilter.Blur.OUTER)
        }
    }

    // 3. Main Base Shape Pass with Blurs precomputed
    val bRadius = getBlurRadius(layer) +
            (raBlur?.let { (it.parameters["Amount"]?.value ?: 10f) * 0.15f } ?: 0f) +
            (moBlur?.let { (it.parameters["Distance"]?.value ?: 15f) * 0.1f } ?: 0f) +
            (leBlur?.let { (it.parameters["Radius"]?.value ?: 15f) * 0.1f } ?: 0f)

    // Draw Custom Outer Stroke & Outer Border BEFORE drawing main solid layer so the fill occludes the inner half!
    if (bordersShadows != null) {
        // 1. Outer Border
        if ((bordersShadows.parameters["OuterBorder_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadows.parameters["OuterBorder_Size"]?.value ?: 0f
            val opacity = bordersShadows.parameters["OuterBorder_Opacity"]?.value ?: 1f
            val r = bordersShadows.parameters["OuterBorder_Color_R"]?.value ?: 1f
            val g = bordersShadows.parameters["OuterBorder_Color_G"]?.value ?: 1f
            val b = bordersShadows.parameters["OuterBorder_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size * 2f))
            }
        }
        // 2. Outer Stroke
        if ((bordersShadows.parameters["OuterStroke_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadows.parameters["OuterStroke_Size"]?.value ?: 0f
            val opacity = bordersShadows.parameters["OuterStroke_Opacity"]?.value ?: 1f
            val r = bordersShadows.parameters["OuterStroke_Color_R"]?.value ?: 1f
            val g = bordersShadows.parameters["OuterStroke_Color_G"]?.value ?: 1f
            val b = bordersShadows.parameters["OuterStroke_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size * 2f))
            }
        }
    }

    // Main solid layer drawing
    if (gradOverlay == null) {
        if (bRadius > 0.1f) {
            drawGeometryWithBlur(effectiveColor, 1.0f, androidx.compose.ui.graphics.drawscope.Fill, bRadius, android.graphics.BlurMaskFilter.Blur.NORMAL, isOverlay = false)
        } else {
            drawGeometry(effectiveColor, 1.0f, androidx.compose.ui.graphics.drawscope.Fill, isOverlay = false)
        }
    }

    // 4. Gradient Overlay Pass
    if (gradOverlay != null) {
        val goScale = (gradOverlay.parameters["Scale"]?.value ?: 100f) / 100f
        val goAngle = gradOverlay.parameters["Angle"]?.value ?: 90f
        val goOpacity = gradOverlay.parameters["Opacity"]?.value ?: 1.0f
        val gradientTypeOrdinal = (gradOverlay.parameters["GradientType"]?.value ?: 0f).toInt().coerceIn(0, 6)

        val rads = Math.toRadians(goAngle.toDouble())
        val cos = Math.cos(rads).toFloat()
        val sin = Math.sin(rads).toFloat()
        val hasCustomHandles = gradOverlay.parameters["StartX"] != null
        val startX: Float
        val startY: Float
        val endX: Float
        val endY: Float
        if (hasCustomHandles) {
            startX = (gradOverlay.parameters["StartX"]?.value ?: 0f) * layer.width
            startY = (gradOverlay.parameters["StartY"]?.value ?: 0f) * layer.height
            endX = (gradOverlay.parameters["EndX"]?.value ?: 1f) * layer.width
            endY = (gradOverlay.parameters["EndY"]?.value ?: 1f) * layer.height
        } else {
            startX = layer.width / 2f - (layer.width / 2f * cos * goScale)
            startY = layer.height / 2f - (layer.height / 2f * sin * goScale)
            endX = layer.width / 2f + (layer.width / 2f * cos * goScale)
            endY = layer.height / 2f + (layer.height / 2f * sin * goScale)
        }

        val goPresetIdx = (gradOverlay.parameters["Preset"]?.value ?: 0f).toInt().coerceIn(0, 7)
        val stopPositions = if (goPresetIdx == 7) {
            val stopCount = (gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
            val list = mutableListOf<Float>()
            for (i in 0 until stopCount) {
                val posVal = gradOverlay.parameters["CustomStop_${i}_Pos"]?.value ?: (i.toFloat() / (stopCount - 1).coerceAtLeast(1))
                list.add(posVal)
            }
            list
        } else {
            null
        }

        val originalColors = if (goPresetIdx == 7) {
            val stopCount = (gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
            val list = mutableListOf<androidx.compose.ui.graphics.Color>()
            for (i in 0 until stopCount) {
                val rKey = "CustomStop_${i}_R"
                val gKey = "CustomStop_${i}_G"
                val bKey = "CustomStop_${i}_B"
                val aKey = "CustomStop_${i}_A"
                
                val r = gradOverlay.parameters[rKey]?.value ?: when(i) {
                    0 -> gradOverlay.parameters["CustomStart_R"]?.value ?: 1.0f
                    1 -> gradOverlay.parameters["CustomEnd_R"]?.value ?: 0.0f
                    2 -> 0.0f
                    3 -> 1.0f
                    4 -> 1.0f
                    else -> 0.5f
                }
                val g = gradOverlay.parameters[gKey]?.value ?: when(i) {
                    0 -> gradOverlay.parameters["CustomStart_G"]?.value ?: 0.0f
                    1 -> gradOverlay.parameters["CustomEnd_G"]?.value ?: 0.0f
                    2 -> 1.0f
                    3 -> 1.0f
                    4 -> 0.5f
                    else -> 0.0f
                }
                val b = gradOverlay.parameters[bKey]?.value ?: when(i) {
                    0 -> gradOverlay.parameters["CustomStart_B"]?.value ?: 0.0f
                    1 -> gradOverlay.parameters["CustomEnd_B"]?.value ?: 1.0f
                    2 -> 0.0f
                    3 -> 0.0f
                    4 -> 0.0f
                    else -> 1.0f
                }
                val a = gradOverlay.parameters[aKey]?.value ?: when(i) {
                    0 -> gradOverlay.parameters["CustomStart_A"]?.value ?: 1.0f
                    1 -> gradOverlay.parameters["CustomEnd_A"]?.value ?: 1.0f
                    else -> 1.0f
                }
                list.add(androidx.compose.ui.graphics.Color(red = r, green = g, blue = b, alpha = a))
            }
            list
        } else {
            gradientPresets[goPresetIdx.coerceIn(0, gradientPresets.size - 1)]
        }

        val colorStops = if (stopPositions != null) {
            stopPositions.zip(originalColors).map { Pair(it.first, it.second) }.sortedBy { it.first }.toTypedArray()
        } else {
            null
        }

        val finalColorStops = if (colorStops != null) {
            colorStops
        } else {
            val sz = originalColors.size
            if (sz > 1) {
                originalColors.mapIndexed { idx, col ->
                    Pair(idx.toFloat() / (sz - 1).coerceAtLeast(1), col)
                }.toTypedArray()
            } else if (sz == 1) {
                arrayOf(Pair(0f, originalColors[0]), Pair(1f, originalColors[0]))
            } else {
                null
            }
        }

        val getColorAtRatio = { ratio: Float ->
            val stops = finalColorStops
            if (stops != null && stops.isNotEmpty()) {
                val sortedStops = stops.sortedBy { it.first }
                if (ratio <= sortedStops.first().first) {
                    sortedStops.first().second
                } else if (ratio >= sortedStops.last().first) {
                    sortedStops.last().second
                } else {
                    var match: androidx.compose.ui.graphics.Color? = null
                    for (i in 0 until sortedStops.size - 1) {
                        val s1 = sortedStops[i]
                        val s2 = sortedStops[i + 1]
                        if (ratio >= s1.first && ratio <= s2.first) {
                            val t = (ratio - s1.first) / (s2.first - s1.first).coerceAtLeast(0.001f)
                            match = androidx.compose.ui.graphics.Color(
                                red = s1.second.red + (s2.second.red - s1.second.red) * t,
                                green = s1.second.green + (s2.second.green - s1.second.green) * t,
                                blue = s1.second.blue + (s2.second.blue - s1.second.blue) * t,
                                alpha = s1.second.alpha + (s2.second.alpha - s1.second.alpha) * t
                            )
                            break
                        }
                    }
                    match ?: interpolateMultiColor(originalColors, ratio)
                }
            } else {
                interpolateMultiColor(originalColors, ratio)
            }
        }

        val pathCachedObj = layerPath
        clipPath(pathCachedObj) {
            when (gradientTypeOrdinal) {
                0 -> { // Linear Gradient
                    val gradBrush = if (finalColorStops != null) {
                        androidx.compose.ui.graphics.Brush.linearGradient(
                            colorStops = finalColorStops,
                            start = androidx.compose.ui.geometry.Offset(startX, startY),
                            end = androidx.compose.ui.geometry.Offset(endX, endY)
                        )
                    } else {
                        androidx.compose.ui.graphics.Brush.linearGradient(
                            colors = originalColors,
                            start = androidx.compose.ui.geometry.Offset(startX, startY),
                            end = androidx.compose.ui.geometry.Offset(endX, endY)
                        )
                    }
                    drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                }
                1 -> { // Radial Gradient
                    val dist = Math.hypot((endX - startX).toDouble(), (endY - startY).toDouble()).toFloat()
                    val radius = if (dist > 1f) dist else ((Math.min(layer.width, layer.height) / 2f) * goScale)
                    val gradBrush = if (finalColorStops != null) {
                        androidx.compose.ui.graphics.Brush.radialGradient(
                            colorStops = finalColorStops,
                            center = androidx.compose.ui.geometry.Offset(startX, startY),
                            radius = radius.coerceAtLeast(1f)
                        )
                    } else {
                        androidx.compose.ui.graphics.Brush.radialGradient(
                            colors = originalColors,
                            center = androidx.compose.ui.geometry.Offset(startX, startY),
                            radius = radius.coerceAtLeast(1f)
                        )
                    }
                    drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                }
                2 -> { // Sweep / Angular Gradient
                    val dx = endX - startX
                    val dy = endY - startY
                    val lineAngle = if (Math.abs(dx) > 0.1f || Math.abs(dy) > 0.1f) {
                        Math.toDegrees(Math.atan2(dy.toDouble(), dx.toDouble())).toFloat()
                    } else {
                        goAngle
                    }
                    val gradBrush = if (finalColorStops != null) {
                        androidx.compose.ui.graphics.Brush.sweepGradient(
                            colorStops = finalColorStops,
                            center = androidx.compose.ui.geometry.Offset(startX, startY)
                        )
                    } else {
                        androidx.compose.ui.graphics.Brush.sweepGradient(
                            colors = originalColors,
                            center = androidx.compose.ui.geometry.Offset(startX, startY)
                        )
                    }
                    withTransform({
                        rotate(degrees = lineAngle, pivot = androidx.compose.ui.geometry.Offset(startX, startY))
                    }) {
                        drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                    }
                }
                3 -> { // Reflected Gradient
                    val reflectedColorStops = if (finalColorStops != null) {
                        val stopsList = mutableListOf<Pair<Float, androidx.compose.ui.graphics.Color>>()
                        finalColorStops.forEach { (fraction, color) ->
                            stopsList.add(Pair(0.5f - 0.5f * fraction, color))
                            stopsList.add(Pair(0.5f + 0.5f * fraction, color))
                        }
                        stopsList.sortBy { it.first }
                        stopsList.toTypedArray()
                    } else {
                        null
                    }
                    val brushStart = androidx.compose.ui.geometry.Offset(startX - (endX - startX), startY - (endY - startY))
                    val brushEnd = androidx.compose.ui.geometry.Offset(endX, endY)
                    val gradBrush = if (reflectedColorStops != null) {
                        androidx.compose.ui.graphics.Brush.linearGradient(
                            colorStops = reflectedColorStops,
                            start = brushStart,
                            end = brushEnd
                        )
                    } else {
                        val reflectedColors = originalColors.reversed() + originalColors.drop(1)
                        androidx.compose.ui.graphics.Brush.linearGradient(
                            colors = reflectedColors,
                            start = brushStart,
                            end = brushEnd
                        )
                    }
                    drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                }
                4 -> { // Shape-Conforming Concentric Gradient
                    val steps = 30
                    val refDist = Math.hypot((layer.width / 2f).toDouble(), (layer.height / 2f).toDouble()).toFloat().coerceAtLeast(1f)
                    val curDist = Math.hypot((endX - startX).toDouble(), (endY - startY).toDouble()).toFloat()
                    val finalScale = if (hasCustomHandles) (curDist / refDist) else goScale

                    for (step in steps downTo 1) {
                        val ratio = step.toFloat() / steps
                        val color = getColorAtRatio(ratio)
                        withTransform({
                            scale(scaleX = ratio * finalScale, scaleY = ratio * finalScale, pivot = androidx.compose.ui.geometry.Offset(startX, startY))
                        }) {
                            drawGeometry(color, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                        }
                    }
                }
                5 -> { // Diamond / Starburst Gradient
                    val steps = 30
                    val refDist = Math.hypot((layer.width / 2f).toDouble(), (layer.height / 2f).toDouble()).toFloat().coerceAtLeast(1f)
                    val curDist = Math.hypot((endX - startX).toDouble(), (endY - startY).toDouble()).toFloat()
                    val finalScale = if (hasCustomHandles) (curDist / refDist) else goScale
                    val dx = endX - startX
                    val dy = endY - startY
                    val lineAngle = if (Math.abs(dx) > 0.1f || Math.abs(dy) > 0.1f) {
                        Math.toDegrees(Math.atan2(dy.toDouble(), dx.toDouble())).toFloat()
                    } else {
                        45f
                    }

                    for (step in steps downTo 1) {
                        val ratio = step.toFloat() / steps
                        val color = getColorAtRatio(ratio)
                        withTransform({
                            scale(scaleX = ratio * finalScale, scaleY = ratio * finalScale, pivot = androidx.compose.ui.geometry.Offset(startX, startY))
                            rotate(degrees = lineAngle, pivot = androidx.compose.ui.geometry.Offset(startX, startY))
                        }) {
                            drawGeometry(color, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                        }
                    }
                }
                6 -> { // Reflected Radial Gradient
                    val reflectedColorStops = if (finalColorStops != null) {
                        val stopsList = mutableListOf<Pair<Float, androidx.compose.ui.graphics.Color>>()
                        finalColorStops.forEach { (fraction, color) ->
                            stopsList.add(Pair(0.5f - 0.5f * fraction, color))
                            stopsList.add(Pair(0.5f + 0.5f * fraction, color))
                        }
                        stopsList.sortBy { it.first }
                        stopsList.toTypedArray()
                    } else {
                        null
                    }
                    val dist = Math.hypot((endX - startX).toDouble(), (endY - startY).toDouble()).toFloat()
                    val radius = if (dist > 1f) dist else ((Math.min(layer.width, layer.height) / 2f) * goScale)
                    val gradBrush = if (reflectedColorStops != null) {
                        androidx.compose.ui.graphics.Brush.radialGradient(
                            colorStops = reflectedColorStops,
                            center = androidx.compose.ui.geometry.Offset(startX, startY),
                            radius = radius.coerceAtLeast(1f)
                        )
                    } else {
                        val reflectedColors = originalColors.reversed() + originalColors.drop(1)
                        androidx.compose.ui.graphics.Brush.radialGradient(
                            colors = reflectedColors,
                            center = androidx.compose.ui.geometry.Offset(startX, startY),
                            radius = radius.coerceAtLeast(1f)
                        )
                    }
                    drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                }
            }
        }
    }

    // 5. Pattern Overlay Pass
    if (patOverlay != null) {
        val poScale = (patOverlay.parameters["Scale"]?.value ?: 100f) / 100f
        val poOpacity = patOverlay.parameters["Opacity"]?.value ?: 1.0f
        val spacing = (15f * poScale).coerceAtLeast(10f)
        val step = spacing.coerceAtLeast((layer.width + layer.height) / 150f)
        var d = 0f
        while (d < layer.width + layer.height) {
            drawLine(
                color = androidx.compose.ui.graphics.Color.White.copy(alpha = poOpacity * 0.22f * layerOpacity),
                start = androidx.compose.ui.geometry.Offset(d, 0f),
                end = androidx.compose.ui.geometry.Offset(d - layer.height, layer.height),
                strokeWidth = 2f,
                blendMode = composeBlendMode
            )
            d += step
        }
    }

    // 6. Satin Metallic Waves Pass
    if (satinStyle != null) {
        val satSize = satinStyle.parameters["Size"]?.value ?: 14f
        val satOpacity = satinStyle.parameters["Opacity"]?.value ?: 0.5f
        val satPath = androidx.compose.ui.graphics.Path().apply {
            moveTo(0f, layer.height * 0.25f)
            quadraticTo(layer.width / 2f, layer.height * 0.7f, layer.width, layer.height * 0.3f)
        }
        val composePaint = androidx.compose.ui.graphics.Paint().apply {
            color = androidx.compose.ui.graphics.Color.White.copy(alpha = satOpacity * 0.40f * layerOpacity)
            style = androidx.compose.ui.graphics.PaintingStyle.Stroke
            strokeWidth = satSize
            blendMode = composeBlendMode
            if (satSize > 1f) {
                asFrameworkPaint().maskFilter = android.graphics.BlurMaskFilter(satSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL)
            }
        }
        val pathCachedObj = layerPath
        if (!pathCachedObj.asAndroidPath().isEmpty) {
            clipPath(pathCachedObj) {
                drawContext.canvas.drawPath(satPath, composePaint)
            }
        } else {
            drawContext.canvas.drawPath(satPath, composePaint)
        }
    }

    // 7. Inner Shadow Pass
    if (bordersShadows != null && (bordersShadows.parameters["InnerShadow_Enabled"]?.value ?: 0f) > 0.5f) {
        val isDistance = bordersShadows.parameters["InnerShadow_Distance"]?.value ?: 5f
        val isSize = bordersShadows.parameters["InnerShadow_Size"]?.value ?: 10f
        val isAngle = bordersShadows.parameters["InnerShadow_Angle"]?.value ?: 120f
        val isOpacity = bordersShadows.parameters["InnerShadow_Opacity"]?.value ?: 0.5f
        val isHardness = bordersShadows.parameters["InnerShadow_Hardness"]?.value ?: 0f
        val isChoke = bordersShadows.parameters["InnerShadow_Choke"]?.value ?: 0f

        val r = bordersShadows.parameters["InnerShadow_Color_R"]?.value ?: 0f
        val g = bordersShadows.parameters["InnerShadow_Color_G"]?.value ?: 0f
        val b = bordersShadows.parameters["InnerShadow_Color_B"]?.value ?: 0f
        val col = androidx.compose.ui.graphics.Color(r, g, b)

        val rads = Math.toRadians(isAngle.toDouble())
        val dx = (isDistance * Math.cos(rads)).toFloat()
        val dy = (isDistance * Math.sin(rads)).toFloat()
        val pathCachedObj = layerPath
        if (!pathCachedObj.asAndroidPath().isEmpty) {
            clipPath(pathCachedObj) {
                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                    drawGeometryWithBlurAndOffset(col, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = isSize * 2f), isSize, android.graphics.BlurMaskFilter.Blur.NORMAL, dx, dy)
                } else {
                    withTransform({ translate(left = dx, top = dy) }) {
                        drawGeometryWithBlur(col, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = isSize * 2f), isSize, android.graphics.BlurMaskFilter.Blur.NORMAL)
                    }
                }
            }
        } else {
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                drawGeometryWithBlurAndOffset(col, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = isSize), isSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL, dx, dy)
            } else {
                withTransform({ translate(left = dx, top = dy) }) {
                    drawGeometryWithBlur(col, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = isSize), isSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL)
                }
            }
        }
    } else if (innerShadow != null) {
        val isDistance = innerShadow.parameters["Distance"]?.value ?: 5f
        val isSize = innerShadow.parameters["Size"]?.value ?: 10f
        val isAngle = innerShadow.parameters["Angle"]?.value ?: 120f
        val isOpacity = innerShadow.parameters["Opacity"]?.value ?: 0.5f
        val rads = Math.toRadians(isAngle.toDouble())
        val dx = (isDistance * Math.cos(rads)).toFloat()
        val dy = (isDistance * Math.sin(rads)).toFloat()
        val pathCachedObj = layerPath
        if (!pathCachedObj.asAndroidPath().isEmpty) {
            clipPath(pathCachedObj) {
                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                    drawGeometryWithBlurAndOffset(androidx.compose.ui.graphics.Color.Black, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = isSize * 2f), isSize, android.graphics.BlurMaskFilter.Blur.NORMAL, dx, dy)
                } else {
                    withTransform({ translate(left = dx, top = dy) }) {
                        drawGeometryWithBlur(androidx.compose.ui.graphics.Color.Black, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = isSize * 2f), isSize, android.graphics.BlurMaskFilter.Blur.NORMAL)
                    }
                }
            }
        } else {
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                drawGeometryWithBlurAndOffset(androidx.compose.ui.graphics.Color.Black, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = isSize), isSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL, dx, dy)
            } else {
                withTransform({ translate(left = dx, top = dy) }) {
                    drawGeometryWithBlur(androidx.compose.ui.graphics.Color.Black, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = isSize), isSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL)
                }
            }
        }
    }

    // 8. Inner Glow Pass
    if (innerGlow != null) {
        val igSize = innerGlow.parameters["Size"]?.value ?: innerGlow.parameters["Choke"]?.value ?: 15f
        val igOpacity = innerGlow.parameters["Opacity"]?.value ?: 0.65f
        val igColor = androidx.compose.ui.graphics.Color(0xFF00E676)
        val pathCachedObj = layerPath
        if (!pathCachedObj.asAndroidPath().isEmpty) {
            clipPath(pathCachedObj) {
                drawGeometryWithBlur(igColor, igOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = igSize * 2f), igSize, android.graphics.BlurMaskFilter.Blur.NORMAL)
            }
        } else {
            drawGeometryWithBlur(igColor, igOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = igSize), igSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL)
        }
    }

    // 9. Stroke Pass
    if (bordersShadows != null) {
        // 1. Center Stroke
        if ((bordersShadows.parameters["CenterStroke_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadows.parameters["CenterStroke_Size"]?.value ?: 0f
            val opacity = bordersShadows.parameters["CenterStroke_Opacity"]?.value ?: 1f
            val r = bordersShadows.parameters["CenterStroke_Color_R"]?.value ?: 1f
            val g = bordersShadows.parameters["CenterStroke_Color_G"]?.value ?: 1f
            val b = bordersShadows.parameters["CenterStroke_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size))
            }
        }
        // 2. Inner stroke (clipped to layer path!)
        if ((bordersShadows.parameters["InnerStroke_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadows.parameters["InnerStroke_Size"]?.value ?: 0f
            val opacity = bordersShadows.parameters["InnerStroke_Opacity"]?.value ?: 1f
            val r = bordersShadows.parameters["InnerStroke_Color_R"]?.value ?: 1f
            val g = bordersShadows.parameters["InnerStroke_Color_G"]?.value ?: 1f
            val b = bordersShadows.parameters["InnerStroke_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                val pathCachedObj = layerPath
                if (pathCachedObj.asAndroidPath().isEmpty) {
                    drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size))
                } else {
                    clipPath(pathCachedObj) {
                        drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size * 2f))
                    }
                }
            }
        }
        // 3. Inner Border (clipped to layer path!)
        if ((bordersShadows.parameters["InnerBorder_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadows.parameters["InnerBorder_Size"]?.value ?: 0f
            val opacity = bordersShadows.parameters["InnerBorder_Opacity"]?.value ?: 1f
            val r = bordersShadows.parameters["InnerBorder_Color_R"]?.value ?: 1f
            val g = bordersShadows.parameters["InnerBorder_Color_G"]?.value ?: 1f
            val b = bordersShadows.parameters["InnerBorder_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                val pathCachedObj = layerPath
                if (pathCachedObj.asAndroidPath().isEmpty) {
                    drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size))
                } else {
                    clipPath(pathCachedObj) {
                        drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size * 2f))
                    }
                }
            }
        }
    } else if (strokeStyle != null) {
        val sSize = strokeStyle.parameters["Size"]?.value ?: 3f
        val sOpacity = strokeStyle.parameters["Opacity"]?.value ?: 1.0f
        drawGeometry(androidx.compose.ui.graphics.Color.White, sOpacity * 0.9f, androidx.compose.ui.graphics.drawscope.Stroke(width = sSize))
    }

    // 10. Bevel & Emboss Pass
    if (bevelStyle != null) {
        val bevSize = bevelStyle.parameters["Size"]?.value ?: 5f
        val bevDepth = bevelStyle.parameters["Depth"]?.value ?: 100f
        val bMult = (bevDepth / 100f).coerceIn(0.2f, 2f)
        val pathCachedObj = layerPath
        if (!pathCachedObj.asAndroidPath().isEmpty) {
            clipPath(pathCachedObj) {
                // Highlight (White) shifted top-left
                withTransform({ translate(left = -bevSize * 0.25f, top = -bevSize * 0.25f) }) {
                    drawGeometryWithBlur(androidx.compose.ui.graphics.Color.White, 0.35f * bMult, androidx.compose.ui.graphics.drawscope.Stroke(width = bevSize), bevSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL)
                }
                // Shadow (Black) shifted bottom-right
                withTransform({ translate(left = bevSize * 0.25f, top = bevSize * 0.25f) }) {
                    drawGeometryWithBlur(androidx.compose.ui.graphics.Color.Black, 0.45f * bMult, androidx.compose.ui.graphics.drawscope.Stroke(width = bevSize), bevSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL)
                }
            }
        } else {
            withTransform({ translate(left = -bevSize * 0.25f, top = -bevSize * 0.25f) }) {
                drawGeometryWithBlur(androidx.compose.ui.graphics.Color.White, 0.28f * bMult, androidx.compose.ui.graphics.drawscope.Stroke(width = bevSize * 0.5f), bevSize * 0.3f, android.graphics.BlurMaskFilter.Blur.NORMAL)
            }
            withTransform({ translate(left = bevSize * 0.25f, top = bevSize * 0.25f) }) {
                drawGeometryWithBlur(androidx.compose.ui.graphics.Color.Black, 0.38f * bMult, androidx.compose.ui.graphics.drawscope.Stroke(width = bevSize * 0.5f), bevSize * 0.3f, android.graphics.BlurMaskFilter.Blur.NORMAL)
            }
        }
    }

    // 11. Custom Noise Grain Pass
    if (noiseFil != null) {
        val amount = noiseFil.parameters["Amount"]?.value ?: 10f
        val rSeed = java.util.Random(layer.id.hashCode().toLong())
        val dotCount = (amount * 3.5f).toInt().coerceIn(10, 250)
        for (i in 0 until dotCount) {
            val nx = rSeed.nextFloat() * layer.width
            val ny = rSeed.nextFloat() * layer.height
            val colVal = if (rSeed.nextBoolean()) androidx.compose.ui.graphics.Color.White else androidx.compose.ui.graphics.Color.Black
            drawCircle(
                color = colVal.copy(alpha = 0.3f * layerOpacity),
                radius = 1f,
                center = androidx.compose.ui.geometry.Offset(nx, ny)
            )
        }
    }

    // 12. Dust & Scratches Pass
    if (dustScratch != null) {
        val dRadius = dustScratch.parameters["Radius"]?.value ?: 2f
        val rSeed = java.util.Random(layer.id.hashCode().toLong() + 199)
        val count = (dRadius * 0.12f + 4f).toInt()
        for (i in 0 until count) {
            val sx = rSeed.nextFloat() * layer.width
            val sy = rSeed.nextFloat() * layer.height
            drawLine(
                color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.5f * layerOpacity),
                start = androidx.compose.ui.geometry.Offset(sx, sy),
                end = androidx.compose.ui.geometry.Offset(sx + rSeed.nextFloat() * 10f - 5f, sy + rSeed.nextFloat() * 10f - 5f),
                strokeWidth = 1f
            )
            drawCircle(
                color = androidx.compose.ui.graphics.Color.Black.copy(alpha = 0.45f * layerOpacity),
                radius = 1.2f,
                center = androidx.compose.ui.geometry.Offset(rSeed.nextFloat() * layer.width, rSeed.nextFloat() * layer.height)
            )
        }
    }

    // 13. Edge Shaders (Median/Unsharp/Smart/High Filters)
    if (medFil != null || unsharpFil != null || smartFil != null || highFil != null) {
        val intense = if (highFil != null) 0.7f else 0.35f
        drawGeometry(androidx.compose.ui.graphics.Color.White, intense, androidx.compose.ui.graphics.drawscope.Stroke(width = 1.5f))
    }

    // 14. Color Halftone Pass
    if (halftoneFil != null) {
        val maxR = halftoneFil.parameters["MaxRadius"]?.value ?: 8f
        val spacing = (maxR * 2.8f).coerceAtLeast(8f)
        val stepX = spacing.coerceAtLeast(layer.width / 50f)
        val stepY = spacing.coerceAtLeast(layer.height / 50f)
        var hx = stepX / 2
        while (hx < layer.width) {
            var hy = stepY / 2
            while (hy < layer.height) {
                drawCircle(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.35f * layerOpacity), maxR * 0.25f, androidx.compose.ui.geometry.Offset(hx - 2f, hy - 2f))
                drawCircle(androidx.compose.ui.graphics.Color.Magenta.copy(alpha = 0.35f * layerOpacity), maxR * 0.25f, androidx.compose.ui.geometry.Offset(hx + 2f, hy - hx % 3f))
                drawCircle(androidx.compose.ui.graphics.Color.Yellow.copy(alpha = 0.35f * layerOpacity), maxR * 0.25f, androidx.compose.ui.geometry.Offset(hx, hy + 2f))
                hy += stepY
            }
            hx += stepX
        }
    }

    // 15. Crystallize / Mosaic / Pointillize Pass
    if (crysFil != null || mosFil != null || pointFil != null) {
        val cSize = crysFil?.parameters["CellSize"]?.value ?: mosFil?.parameters["CellSize"]?.value ?: pointFil?.parameters["CellSize"]?.value ?: 10f
        val spacing = cSize.coerceIn(8f, 95f)
        val stepX = spacing.coerceAtLeast(layer.width / 50f)
        val stepY = spacing.coerceAtLeast(layer.height / 50f)
        var mx = stepX / 2
        while (mx < layer.width) {
            var my = stepY / 2
            while (my < layer.height) {
                if (pointFil != null) {
                    drawCircle(effectiveColor.copy(alpha = 0.55f * layerOpacity), spacing * 0.32f, androidx.compose.ui.geometry.Offset(mx, my))
                } else if (mosFil != null) {
                    drawRect(
                        color = effectiveColor.copy(alpha = 0.40f * layerOpacity),
                        topLeft = androidx.compose.ui.geometry.Offset(mx - spacing/2 + 1f, my - spacing/2 + 1f),
                        size = androidx.compose.ui.geometry.Size(spacing - 2f, spacing - 2f)
                    )
                } else {
                    drawLine(
                        color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.2f * layerOpacity),
                        start = androidx.compose.ui.geometry.Offset(mx - spacing/2, my - spacing/2),
                        end = androidx.compose.ui.geometry.Offset(mx + spacing/2, my + spacing/2),
                        strokeWidth = 1f
                    )
                }
                my += stepY
            }
            mx += stepX
        }
    }

    // 16. Clouds Gaseous Smoke Pass
    if (cloudFil != null) {
        val details = cloudFil.parameters["DetailLevel"]?.value ?: 2f
        val rSeed = java.util.Random(layer.id.hashCode().toLong() * 3)
        for (i in 0 until (details * 2).toInt().coerceAtLeast(3)) {
            val cx = rSeed.nextFloat() * layer.width
            val cy = rSeed.nextFloat() * layer.height
            val cr = (layer.width + layer.height) * 0.22f * (0.8f + rSeed.nextFloat() * 0.5f)
            val col = when (i % 3) {
                0 -> androidx.compose.ui.graphics.Color(0xFF1E88E5)
                1 -> androidx.compose.ui.graphics.Color(0xFFAB47BC)
                else -> androidx.compose.ui.graphics.Color(0xFFEF5350)
            }
            drawCircle(col.copy(alpha = 0.12f * layerOpacity), cr, androidx.compose.ui.geometry.Offset(cx, cy))
        }
    }

    // 17. Cinematic Lens Flare Pass
    if (flareFil != null) {
        val bright = (flareFil.parameters["Brightness"]?.value ?: 100f) / 100f
        val lightColor = androidx.compose.ui.graphics.Color(0xFFFFF9C4)
        drawCircle(androidx.compose.ui.graphics.Color.White.copy(alpha = 0.9f * layerOpacity * bright), 20f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f, layer.height/2f))
        drawCircle(lightColor.copy(alpha = 0.45f * layerOpacity * bright), 50f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f, layer.height/2f))
        drawCircle(
            color = androidx.compose.ui.graphics.Color(0xFF00E5FF).copy(alpha = 0.22f * layerOpacity * bright),
            radius = 100f * bright,
            center = androidx.compose.ui.geometry.Offset(layer.width/2f, layer.height/2f),
            style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2.5f * bright)
        )
        val offsetUnitX = 35f * bright
        val offsetUnitY = -22f * bright
        drawCircle(androidx.compose.ui.graphics.Color(0xFFFFEA00).copy(alpha = 0.32f * layerOpacity * bright), 10f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f + offsetUnitX, layer.height/2f + offsetUnitY))
        drawCircle(androidx.compose.ui.graphics.Color(0xFFE040FB).copy(alpha = 0.22f * layerOpacity * bright), 16f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f - offsetUnitX * 1.8f, layer.height/2f - offsetUnitY * 1.8f))
        drawCircle(androidx.compose.ui.graphics.Color(0xFF00E676).copy(alpha = 0.18f * layerOpacity * bright), 7f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f + offsetUnitX * 2.5f, layer.height/2f + offsetUnitY * 2.5f))
    }

    // 18. Spotlight Lighting pass
    if (lightFil != null) {
        val intensity = (lightFil.parameters["Intensity"]?.value ?: 50f) / 100f
        val conePath = androidx.compose.ui.graphics.Path().apply {
            moveTo(0f, 0f)
            lineTo(layer.width * 0.85f, layer.height * 0.22f)
            lineTo(layer.width * 0.22f, layer.height * 0.85f)
            close()
        }
        drawPath(
            path = conePath,
            color = androidx.compose.ui.graphics.Color.White.copy(alpha = intensity * 0.2f * layerOpacity),
            blendMode = composeBlendMode
        )
    }

    // 19. Find Edges pass
    if (findFil != null) {
        drawGeometry(androidx.compose.ui.graphics.Color(0xFF00E5FF), 0.85f, androidx.compose.ui.graphics.drawscope.Stroke(width = 2.2f))
    }

    // 20. Emboss Contour Pass
    if (embFil != null) {
        withTransform({ translate(left = -1.5f, top = -1.5f) }) {
            drawGeometry(androidx.compose.ui.graphics.Color.White, 0.4f, androidx.compose.ui.graphics.drawscope.Stroke(width = 1.2f))
        }
        withTransform({ translate(left = 1.5f, top = 1.5f) }) {
            drawGeometry(androidx.compose.ui.graphics.Color.Black, 0.5f, androidx.compose.ui.graphics.drawscope.Stroke(width = 1.2f))
        }
    }

    // 21. Hand-penciled Sketch / Texture Burlap shaders
    if (sketchFil != null) {
        var sy = 0f
        val step = (layer.height / 150f).coerceAtLeast(10f)
        while (sy < layer.height) {
            drawLine(
                color = androidx.compose.ui.graphics.Color(0xFF616161).copy(alpha = 0.4f * layerOpacity),
                start = androidx.compose.ui.geometry.Offset(0f, sy),
                end = androidx.compose.ui.geometry.Offset(layer.width * 0.85f, sy + 12f),
                strokeWidth = 1f
            )
            sy += step
        }
    }
    if (texFil != null) {
        var gx = 0f
        val stepX = (layer.width / 150f).coerceAtLeast(8f)
        while (gx < layer.width) {
            drawLine(color = androidx.compose.ui.graphics.Color.Black.copy(alpha = 0.12f * layerOpacity), start = androidx.compose.ui.geometry.Offset(gx, 0f), end = androidx.compose.ui.geometry.Offset(gx, layer.height), strokeWidth = 1f)
            gx += stepX
        }
        var gy = 0f
        val stepY = (layer.height / 150f).coerceAtLeast(8f)
        while (gy < layer.height) {
            drawLine(color = androidx.compose.ui.graphics.Color.Black.copy(alpha = 0.12f * layerOpacity), start = androidx.compose.ui.geometry.Offset(0f, gy), end = androidx.compose.ui.geometry.Offset(layer.width, gy), strokeWidth = 1f)
            gy += stepY
        }
    }
    if (artFil != null || brushFil != null) {
        drawGeometry(androidx.compose.ui.graphics.Color.White.copy(alpha = 0.25f), 0.25f, androidx.compose.ui.graphics.drawscope.Stroke(width = 1.8f))
    }

    // 22. AI Face Mesh neural overlay
    if (neuralFil != null) {
        val nx1 = layer.width * 0.35f
        val nx2 = layer.width * 0.65f
        val ny = layer.height * 0.4f
        drawCircle(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.3f * layerOpacity), 7f, androidx.compose.ui.geometry.Offset(nx1, ny))
        drawCircle(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.3f * layerOpacity), 7f, androidx.compose.ui.geometry.Offset(nx2, ny))
        drawLine(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.25f * layerOpacity), androidx.compose.ui.geometry.Offset(nx1, ny), androidx.compose.ui.geometry.Offset(nx2, ny), strokeWidth = 1.2f)
        drawLine(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.25f * layerOpacity), androidx.compose.ui.geometry.Offset(layer.width / 2f, ny), androidx.compose.ui.geometry.Offset(layer.width / 2f, layer.height * 0.65f), strokeWidth = 1.2f)
    }

    // 23. Wind streak trails
    if (windFil != null) {
        val rSeed = java.util.Random(layer.id.hashCode().toLong() * 4)
        for (i in 0 until 10) {
            val wy = rSeed.nextFloat() * layer.height
            val length = rSeed.nextFloat() * 30f + 8f
            drawLine(
                color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.5f * layerOpacity),
                start = androidx.compose.ui.geometry.Offset(layer.width, wy),
                end = androidx.compose.ui.geometry.Offset(layer.width + length, wy),
                strokeWidth = 1.2f
            )
        }
    }

    // 24. Oil Paint strokes overlay
    if (oilFil != null) {
        val styliz = oilFil.parameters["Stylization"]?.value ?: 5f
        val rSeed = java.util.Random(layer.id.hashCode().toLong() * 11)
        for (i in 0 until (styliz * 1.3f).toInt().coerceAtLeast(3)) {
            val sy = layer.height * rSeed.nextFloat()
            drawLine(
                color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.25f * layerOpacity),
                start = androidx.compose.ui.geometry.Offset(0f, sy),
                end = androidx.compose.ui.geometry.Offset(layer.width, sy + rSeed.nextFloat() * 10f - 5f),
                strokeWidth = 2.5f + rSeed.nextFloat() * 3f,
                blendMode = composeBlendMode
            )
        }
    }

    // Paint Bezier control lines overlay if active and selected
    if (layer.type == com.example.studio.model.LayerType.VECTOR_BEZIER && layer.id == selectedLayerId) {
        val anchors = layer.brushPoints.toAnchorPoints()
        if (anchors.isNotEmpty()) {
            for (ap in anchors) {
                // If handleIn is active, draw line and handle circle
                if (ap.handleIn != ap.position) {
                    drawLine(
                        color = androidx.compose.ui.graphics.Color.LightGray.copy(alpha = 0.6f),
                        start = ap.position,
                        end = ap.handleIn,
                        strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                        pathEffect = dashEffect
                    )
                    drawCircle(
                        color = IndustrialAmber,
                        radius = 8.5f / totalScale.coerceAtLeast(0.5f),
                        center = ap.handleIn
                    )
                    drawCircle(
                        color = androidx.compose.ui.graphics.Color.White,
                        radius = 4f / totalScale.coerceAtLeast(0.5f),
                        center = ap.handleIn
                    )
                }

                // If handleOut is active, draw line and handle circle
                if (ap.handleOut != ap.position) {
                    drawLine(
                        color = androidx.compose.ui.graphics.Color.LightGray.copy(alpha = 0.6f),
                        start = ap.position,
                        end = ap.handleOut,
                        strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                        pathEffect = dashEffect
                    )
                    drawCircle(
                        color = IndustrialAmber,
                        radius = 8.5f / totalScale.coerceAtLeast(0.5f),
                        center = ap.handleOut
                    )
                    drawCircle(
                        color = androidx.compose.ui.graphics.Color.White,
                        radius = 4f / totalScale.coerceAtLeast(0.5f),
                        center = ap.handleOut
                    )
                }

                // Main anchor center point
                drawCircle(
                    color = androidx.compose.ui.graphics.Color(0xFF00E5FF),
                    radius = 9f / totalScale.coerceAtLeast(0.5f),
                    center = ap.position
                )
                drawCircle(
                    color = androidx.compose.ui.graphics.Color.White,
                    radius = 4.5f / totalScale.coerceAtLeast(0.5f),
                    center = ap.position
                )
            }
        } else {
            val start = androidx.compose.ui.geometry.Offset(0f, layer.height)
            val end = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
            val controlLocal = layer.brushPoints.getOrNull(0) ?: androidx.compose.ui.geometry.Offset(layer.width / 2f, 0f)
            drawLine(
                color = androidx.compose.ui.graphics.Color.LightGray.copy(alpha = 0.5f),
                start = start,
                end = controlLocal,
                strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                pathEffect = dashEffect
            )
            drawLine(
                color = androidx.compose.ui.graphics.Color.LightGray.copy(alpha = 0.5f),
                start = end,
                end = controlLocal,
                strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                pathEffect = dashEffect
            )
            drawCircle(
                color = IndustrialAmber,
                radius = 10f / totalScale.coerceAtLeast(0.5f),
                center = controlLocal
            )
            drawCircle(
                color = androidx.compose.ui.graphics.Color.White,
                radius = 5f / totalScale.coerceAtLeast(0.5f),
                center = controlLocal
            )
        }
    }

    // Sizing frames and anchors drawn locally
    if (layer.id == selectedLayerId) {
        drawRect(
            color = IndustrialAmber.copy(0.8f),
            topLeft = androidx.compose.ui.geometry.Offset(-6f, -6f),
            size = androidx.compose.ui.geometry.Size(layer.width + 12f, layer.height + 12f),
            style = androidx.compose.ui.graphics.drawscope.Stroke(
                width = 1.5f / totalScale.coerceAtLeast(0.5f),
                pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(12f / totalScale.coerceAtLeast(0.5f), 8f / totalScale.coerceAtLeast(0.5f)))
            )
        )
        drawCircle(
            color = EnergeticYellow,
            radius = 8f / totalScale.coerceAtLeast(0.5f),
            center = androidx.compose.ui.geometry.Offset.Zero
        )
        drawCircle(
            color = EnergeticYellow,
            radius = 11f / totalScale.coerceAtLeast(0.5f),
            center = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
        )
        drawCircle(
            color = androidx.compose.ui.graphics.Color(0xFFFF5722),
            radius = 5.5f / totalScale.coerceAtLeast(0.5f),
            center = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
        )

        // On-Canvas Gradient Overlay Guideline rendering moved to drawSingleConnectedLayer to float live and dynamically above cache layers
    }
    if (didSaveLayer) {
        drawContext.canvas.nativeCanvas.restore()
    }
}

private object CanvasMatrixHolder {
    val transformMatrix = android.graphics.Matrix()
    val matrixValues = FloatArray(9)
}

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawSingleConnectedLayer(
    layer: com.example.studio.model.StudioLayer,
    layerOpacity: Float,
    selectedLayerId: String?,
    pathCache: android.util.SparseArray<androidx.compose.ui.graphics.Path>,
    pathPointsCountCache: android.util.SparseIntArray,
    totalScale: Float,
    dashEffect: androidx.compose.ui.graphics.PathEffect,
    composeBlendMode: androidx.compose.ui.graphics.BlendMode,
    imageBitmapCache: Map<String, androidx.compose.ui.graphics.ImageBitmap>,
    sharedTransformMatrix: androidx.compose.ui.graphics.Matrix,
    backdropBitmap: android.graphics.Bitmap? = null,
    globalX: Float = 0f,
    globalY: Float = 0f,
    activeTool: String = "Brush",
    allLayers: List<com.example.studio.model.StudioLayer> = emptyList(),
    liveDragScaleX: Float = 1.0f,
    liveDragScaleY: Float = 1.0f,
    viewportWidth: Float = 0f,
    viewportHeight: Float = 0f,
    panX: Float = 0f,
    panY: Float = 0f,
    canvasWidth: Float = 0f,
    canvasHeight: Float = 0f
) {
    try {
        // Recursively resolve all ancestor parent groups, from top-most ancestor down to immediate parent
    val parentGroups = mutableListOf<com.example.studio.model.StudioLayer>()
    var currentParentId = layer.parentGroupId
    val visitedGroupIds = mutableSetOf<String>()
    while (currentParentId != null && !visitedGroupIds.contains(currentParentId)) {
        visitedGroupIds.add(currentParentId)
        val p = allLayers.find { it.id == currentParentId }
        if (p != null) {
            parentGroups.add(0, p)
            currentParentId = p.parentGroupId
        } else {
            break
        }
    }

    var computedOpacity = layerOpacity
    for (p in parentGroups) {
        computedOpacity *= p.opacity
    }

    var twirlFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var pinchFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var sphereFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    for (effect in layer.effects) {
        if (!effect.isEnabled) continue
        if (effect is com.example.studio.model.StudioEffect.PhotoshopEffect) {
            when (effect.effectType) {
                "Twirl" -> twirlFil = effect
                "Pinch" -> pinchFil = effect
                "Spherize" -> sphereFil = effect
            }
        }
    }

    val additionalTwirl = twirlFil?.let { (it.parameters["Angle"]?.value ?: 100f) * 0.12f } ?: 0f
    val additionalScale = (pinchFil?.let { 1f + (it.parameters["Amount"]?.value ?: 50f) / 100f * 0.15f } ?: 1f) *
                          (sphereFil?.let { 1f + (it.parameters["Amount"]?.value ?: 100f) / 100f * 0.20f } ?: 1f)

    drawContext.canvas.save()
    // Align all ancestor matrix transformations down the hierarchy
    for (parentGroup in parentGroups) {
        drawContext.canvas.translate(parentGroup.positionX, parentGroup.positionY)
        val parentMatrix = androidx.compose.ui.graphics.Matrix().apply {
            reset()
            val centerX = parentGroup.width * parentGroup.pivotX
            val centerY = parentGroup.height * parentGroup.pivotY
            translate(centerX, centerY)
            rotateZ(parentGroup.rotation)
            scale(parentGroup.scaleX, parentGroup.scaleY, 1f)
            translate(-centerX, -centerY)
        }
        drawContext.canvas.concat(parentMatrix)
    }
    drawContext.canvas.translate(layer.positionX, layer.positionY)
    if (liveDragScaleX != 1.0f || liveDragScaleY != 1.0f) {
        val pivotX = layer.width / 2f
        val pivotY = layer.height / 2f
        drawContext.canvas.translate(pivotX, pivotY)
        drawContext.canvas.scale(liveDragScaleX, liveDragScaleY)
        drawContext.canvas.translate(-pivotX, -pivotY)
    }

    val centerX = layer.width * layer.pivotX
    val centerY = layer.height * layer.pivotY

    val nativeMatrix = CanvasMatrixHolder.transformMatrix.apply {
        reset()
        // 1. Move pivot center to local origin (0, 0)
        preTranslate(-centerX, -centerY)

        // 2. Inject true 3D perspective and skew coefficients
        val vals = CanvasMatrixHolder.matrixValues
        getValues(vals)
        vals[android.graphics.Matrix.MSKEW_X] = layer.skewX
        vals[android.graphics.Matrix.MSKEW_Y] = layer.skewY
        vals[6] = layer.perspX // MPERSP_0 control point
        vals[7] = layer.perspY // MPERSP_1 control point
        setValues(vals)

        // 3. Move coordinate framework back to position
        postTranslate(centerX, centerY)

        // 4. Apply scale and rotation around center pivot
        postScale(layer.scaleX * additionalScale, layer.scaleY * additionalScale, centerX, centerY)
        postRotate(layer.rotation + additionalTwirl, centerX, centerY)
    }
    drawContext.canvas.nativeCanvas.concat(nativeMatrix)

    // Graphite-inspired Parametric Layer Caching via State Hash Tracking
    val isPainting = (activeTool == "Brush" || activeTool == "Eraser" || activeTool == "Sudge" || activeTool == "BlurTool") && layer.id == selectedLayerId
    val forceRealtime = isPainting || layer.type == com.example.studio.model.LayerType.FREEHAND_DRAWING

    if (forceRealtime) {
        drawAllEffectsAndLayersLocal(
            layer = layer,
            layerOpacity = computedOpacity,
            selectedLayerId = selectedLayerId,
            pathCache = pathCache,
            pathPointsCountCache = pathPointsCountCache,
            totalScale = totalScale,
            dashEffect = dashEffect,
            imageBitmapCache = imageBitmapCache,
            composeBlendMode = composeBlendMode,
            backdropBitmap = backdropBitmap,
            globalX = globalX,
            globalY = globalY,
            activeTool = activeTool,
            viewportWidth = viewportWidth,
            viewportHeight = viewportHeight,
            panX = panX,
            panY = panY,
            canvasWidth = canvasWidth,
            canvasHeight = canvasHeight
        )
    } else {
        val cacheNode = com.example.studio.ui.ParametricLayerCache.getOrCreateNode(layer.id)
        val currentHash = com.example.studio.ui.ParametricLayerCache.computeParamHash(layer)

        if (cacheNode.paramHash != currentHash || cacheNode.isDirty || cacheNode.cachedImageBitmap == null) {
            val w = maxOf(2, layer.width.toInt().coerceAtMost(2048))
            val h = maxOf(2, layer.height.toInt().coerceAtMost(2048))
            val existingBmp = cacheNode.cachedBitmap
            val bmp = if (existingBmp != null && existingBmp.width == w && existingBmp.height == h) {
                existingBmp.eraseColor(android.graphics.Color.TRANSPARENT)
                existingBmp
            } else {
                existingBmp?.recycle()
                android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
            }
            val nativeCanvas = android.graphics.Canvas(bmp)
            val tempCanvas = androidx.compose.ui.graphics.Canvas(nativeCanvas)
            val drawScope = androidx.compose.ui.graphics.drawscope.CanvasDrawScope()
            drawScope.draw(
                density = androidx.compose.ui.unit.Density(1.0f),
                layoutDirection = androidx.compose.ui.unit.LayoutDirection.Ltr,
                canvas = tempCanvas,
                size = androidx.compose.ui.geometry.Size(w.toFloat(), h.toFloat())
            ) {
                drawAllEffectsAndLayersLocal(
                    layer = layer,
                    layerOpacity = 1.0f,
                    selectedLayerId = null, // don't bake selected design markers in cache
                    pathCache = pathCache,
                    pathPointsCountCache = pathPointsCountCache,
                    totalScale = 1.0f,
                    dashEffect = dashEffect,
                    imageBitmapCache = imageBitmapCache,
                    composeBlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
                    backdropBitmap = backdropBitmap,
                    globalX = 0f,
                    globalY = 0f,
                    activeTool = activeTool,
                    viewportWidth = viewportWidth,
                    viewportHeight = viewportHeight,
                    panX = panX,
                    panY = panY,
                    canvasWidth = canvasWidth,
                    canvasHeight = canvasHeight
                )
            }
            cacheNode.cachedBitmap = bmp
            cacheNode.cachedImageBitmap = bmp.asImageBitmap()
            cacheNode.paramHash = currentHash
            cacheNode.isDirty = false
        }

        cacheNode.cachedImageBitmap?.let { imgBmp ->
            drawImage(
                image = imgBmp,
                topLeft = androidx.compose.ui.geometry.Offset.Zero,
                alpha = computedOpacity,
                blendMode = composeBlendMode
            )
        }

        if (layer.id == selectedLayerId) {
            val EnergeticYellow = androidx.compose.ui.graphics.Color(0xFFFFD600)
            val IndustrialAmber = androidx.compose.ui.graphics.Color(0xFFFF9100)
            drawRect(
                color = IndustrialAmber.copy(0.8f),
                topLeft = androidx.compose.ui.geometry.Offset(-6f, -6f),
                size = androidx.compose.ui.geometry.Size(layer.width + 12f, layer.height + 12f),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = 1.5f / totalScale.coerceAtLeast(0.5f),
                    pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(12f / totalScale.coerceAtLeast(0.5f), 8f / totalScale.coerceAtLeast(0.5f)))
                )
            )
            drawCircle(
                color = EnergeticYellow,
                radius = 8f / totalScale.coerceAtLeast(0.5f),
                center = androidx.compose.ui.geometry.Offset.Zero
            )
            drawCircle(
                color = EnergeticYellow,
                radius = 11f / totalScale.coerceAtLeast(0.5f),
                center = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
            )
            drawCircle(
                color = androidx.compose.ui.graphics.Color(0xFFFF5722),
                radius = 5.5f / totalScale.coerceAtLeast(0.5f),
                center = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
            )

            // Draw On-Canvas Gradient Overlay Vector Handle Guide Line and Pins dynamically
            val gradOverlay = layer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
            if (gradOverlay != null) {
                val goScale = (gradOverlay.parameters["Scale"]?.value ?: 100f) / 100f
                val goAngle = gradOverlay.parameters["Angle"]?.value ?: 90f
                
                val hasCustomHandles = gradOverlay.parameters["StartX"] != null
                val startX: Float
                val startY: Float
                val endX: Float
                val endY: Float
                if (hasCustomHandles) {
                    startX = (gradOverlay.parameters["StartX"]?.value ?: 0f) * layer.width
                    startY = (gradOverlay.parameters["StartY"]?.value ?: 0f) * layer.height
                    endX = (gradOverlay.parameters["EndX"]?.value ?: 1f) * layer.width
                    endY = (gradOverlay.parameters["EndY"]?.value ?: 1f) * layer.height
                } else {
                    val rads = Math.toRadians(goAngle.toDouble())
                    val cos = Math.cos(rads).toFloat()
                    val sin = Math.sin(rads).toFloat()
                    startX = layer.width / 2f - (layer.width / 2f * cos * goScale)
                    startY = layer.height / 2f - (layer.height / 2f * sin * goScale)
                    endX = layer.width / 2f + (layer.width / 2f * cos * goScale)
                    endY = layer.height / 2f + (layer.height / 2f * sin * goScale)
                }
                
                val startPt = androidx.compose.ui.geometry.Offset(startX, startY)
                val endPt = androidx.compose.ui.geometry.Offset(endX, endY)
                
                val lineThickness = 1.8f / totalScale.coerceAtLeast(0.5f)
                val outlineThickness = 3.8f / totalScale.coerceAtLeast(0.5f)
                
                // 1. Draw Black guideline shadow/outline for extreme contrast against any background
                drawLine(
                    color = androidx.compose.ui.graphics.Color.Black.copy(alpha = 0.65f),
                    start = startPt,
                    end = endPt,
                    strokeWidth = outlineThickness
                )
                
                // 2. Draw white/amber guideline
                drawLine(
                    color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.95f),
                    start = startPt,
                    end = endPt,
                    strokeWidth = lineThickness
                )
                drawLine(
                    color = IndustrialAmber.copy(0.75f),
                    start = startPt,
                    end = endPt,
                    strokeWidth = lineThickness * 0.5f
                )
                
                // Fetch colors for handles
                val goPresetIdx = (gradOverlay.parameters["Preset"]?.value ?: 0f).toInt().coerceIn(0, 7)
                val stopCount = if (goPresetIdx < 7) {
                    val presetColorList = gradientPresets[goPresetIdx]
                    presetColorList.size
                } else {
                    (gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
                }
                
                val customColorsList = mutableListOf<androidx.compose.ui.graphics.Color>()
                if (goPresetIdx < 7) {
                    val colors = gradientPresets[goPresetIdx]
                    customColorsList.addAll(colors)
                } else {
                    for (idx in 0 until stopCount) {
                        val rKey = "CustomStop_${idx}_R"
                        val gKey = "CustomStop_${idx}_G"
                        val bKey = "CustomStop_${idx}_B"
                        val aKey = "CustomStop_${idx}_A"
                        val rVal = gradOverlay.parameters[rKey]?.value ?: when(idx) {
                            0 -> gradOverlay.parameters["CustomStart_R"]?.value ?: 1.0f
                            1 -> gradOverlay.parameters["CustomEnd_R"]?.value ?: 0.0f
                            else -> 0.5f
                        }
                        val gVal = gradOverlay.parameters[gKey]?.value ?: when(idx) {
                            0 -> gradOverlay.parameters["CustomStart_G"]?.value ?: 0.0f
                            1 -> gradOverlay.parameters["CustomEnd_G"]?.value ?: 0.0f
                            else -> 0.5f
                        }
                        val bVal = gradOverlay.parameters[bKey]?.value ?: when(idx) {
                            0 -> gradOverlay.parameters["CustomStart_B"]?.value ?: 0.0f
                            1 -> gradOverlay.parameters["CustomEnd_B"]?.value ?: 1.0f
                            else -> 0.5f
                        }
                        val aVal = gradOverlay.parameters[aKey]?.value ?: 1.0f
                        customColorsList.add(androidx.compose.ui.graphics.Color(rVal, gVal, bVal, aVal))
                    }
                }
                
                val startColor = customColorsList.firstOrNull() ?: androidx.compose.ui.graphics.Color.White
                val endColor = customColorsList.lastOrNull() ?: androidx.compose.ui.graphics.Color.Black
                
                // Draw start circular handle with custom color preview & thick white border
                val handleRadius = 11.5f / totalScale.coerceAtLeast(0.5f)
                val blackBorderRadius = handleRadius + 2f / totalScale.coerceAtLeast(0.5f)
                
                // Black base shadow for start handle
                drawCircle(color = androidx.compose.ui.graphics.Color.Black.copy(0.5f), radius = blackBorderRadius, center = startPt)
                drawCircle(color = androidx.compose.ui.graphics.Color.White, radius = handleRadius, center = startPt)
                drawCircle(color = startColor, radius = handleRadius - 2.5f / totalScale.coerceAtLeast(0.5f), center = startPt)
                
                // Draw end circular handle
                drawCircle(color = androidx.compose.ui.graphics.Color.Black.copy(0.5f), radius = blackBorderRadius, center = endPt)
                drawCircle(color = androidx.compose.ui.graphics.Color.White, radius = handleRadius, center = endPt)
                drawCircle(color = endColor, radius = handleRadius - 2.5f / totalScale.coerceAtLeast(0.5f), center = endPt)
                
                // Let's draw interior stop tracking markers along the line
                val activeStopIndex = (gradOverlay.parameters["SelectedStopIndex"]?.value ?: 0f).toInt()
                
                for (idx in 0 until stopCount) {
                    val fraction = if (goPresetIdx < 7) {
                        idx.toFloat() / (stopCount - 1).coerceAtLeast(1)
                    } else {
                        gradOverlay.parameters["CustomStop_${idx}_Pos"]?.value ?: (idx.toFloat() / (stopCount - 1).coerceAtLeast(1))
                    }
                    val stopColor = customColorsList.getOrNull(idx) ?: androidx.compose.ui.graphics.Color.Gray
                    
                    val stopX = startX + (endX - startX) * fraction
                    val stopY = startY + (endY - startY) * fraction
                    
                    val markerRadius = 8.5f / totalScale.coerceAtLeast(0.5f)
                    val outerSquareSize = markerRadius * 2f
                    val ptOffset = androidx.compose.ui.geometry.Offset(stopX - markerRadius, stopY - markerRadius)
                    
                    // Black backing shadow
                    drawRect(
                        color = androidx.compose.ui.graphics.Color.Black.copy(0.55f),
                        topLeft = androidx.compose.ui.geometry.Offset(stopX - markerRadius - 2f / totalScale.coerceAtLeast(0.5f), stopY - markerRadius - 2f / totalScale.coerceAtLeast(0.5f)),
                        size = androidx.compose.ui.geometry.Size(outerSquareSize + 4f / totalScale.coerceAtLeast(0.5f), outerSquareSize + 4f / totalScale.coerceAtLeast(0.5f))
                    )
                    
                    // White/Yellow border
                    drawRect(
                        color = if (idx == activeStopIndex) EnergeticYellow else androidx.compose.ui.graphics.Color.White,
                        topLeft = ptOffset,
                        size = androidx.compose.ui.geometry.Size(outerSquareSize, outerSquareSize)
                    )
                    
                    // Internals colored square representing stop color
                    val innerSize = (markerRadius - 2.5f / totalScale.coerceAtLeast(0.5f)) * 2f
                    val innerOffset = markerRadius - 2.5f / totalScale.coerceAtLeast(0.5f)
                    drawRect(
                        color = stopColor,
                        topLeft = androidx.compose.ui.geometry.Offset(stopX - innerOffset, stopY - innerOffset),
                        size = androidx.compose.ui.geometry.Size(innerSize, innerSize)
                    )
                }
            }
        }
    }
    drawContext.canvas.restore()
} catch (e: Exception) {
    if (e is IllegalArgumentException || e is NullPointerException) {
        e.printStackTrace()
        try {
            drawAllEffectsAndLayersLocal(
                layer = layer,
                layerOpacity = layerOpacity,
                selectedLayerId = selectedLayerId,
                pathCache = pathCache,
                pathPointsCountCache = pathPointsCountCache,
                totalScale = totalScale,
                dashEffect = dashEffect,
                imageBitmapCache = imageBitmapCache,
                composeBlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
                backdropBitmap = backdropBitmap,
                globalX = globalX,
                globalY = globalY,
                activeTool = activeTool,
                viewportWidth = viewportWidth,
                viewportHeight = viewportHeight,
                panX = panX,
                panY = panY,
                canvasWidth = canvasWidth,
                canvasHeight = canvasHeight
            )
        } catch (ex: Exception) {
            ex.printStackTrace()
        }
    } else {
        throw e
    }
}
}

private fun getOrCreateBackdropBitmap(width: Int, height: Int, existing: android.graphics.Bitmap?): android.graphics.Bitmap {
    if (existing != null && existing.width == width && existing.height == height) {
        existing.eraseColor(android.graphics.Color.TRANSPARENT)
        return existing
    }
    existing?.recycle()
    return android.graphics.Bitmap.createBitmap(width, height, android.graphics.Bitmap.Config.ARGB_8888)
}

private fun androidx.compose.ui.graphics.drawscope.DrawScope.generateBackdropForLayer(
    layers: List<com.example.studio.model.StudioLayer>,
    currentIndex: Int,
    canvasWidth: Float,
    canvasHeight: Float,
    imageBitmapCache: Map<String, androidx.compose.ui.graphics.ImageBitmap>,
    pathCache: android.util.SparseArray<androidx.compose.ui.graphics.Path>,
    pathPointsCountCache: android.util.SparseIntArray,
    existingBitmap: android.graphics.Bitmap?
): android.graphics.Bitmap? {
    val w = canvasWidth.toInt().coerceIn(100, 4000)
    val h = canvasHeight.toInt().coerceIn(100, 4000)
    
    return try {
        val bitmap = getOrCreateBackdropBitmap(w, h, existingBitmap)
        val canvas = android.graphics.Canvas(bitmap)
        val composeCanvas = androidx.compose.ui.graphics.Canvas(canvas)
        val drawScope = androidx.compose.ui.graphics.drawscope.CanvasDrawScope()
        
        drawScope.draw(
            density = androidx.compose.ui.unit.Density(1.0f),
            layoutDirection = androidx.compose.ui.unit.LayoutDirection.Ltr,
            canvas = composeCanvas,
            size = androidx.compose.ui.geometry.Size(w.toFloat(), h.toFloat())
        ) {
            // Draw previous layers from back to front (largest index down to currentIndex + 1)
            for (idx in layers.size - 1 downTo currentIndex + 1) {
                val lyr = layers[idx]
                if (!lyr.isVisible) continue
                val lOpacity = lyr.opacity
                val cBlend = lyr.blendMode.toComposeBlendMode()
                
                drawSingleConnectedLayer(
                    layer = lyr,
                    layerOpacity = lOpacity,
                    selectedLayerId = null,
                    pathCache = pathCache,
                    pathPointsCountCache = pathPointsCountCache,
                    totalScale = 1.0f,
                    dashEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(12f, 8f)),
                    composeBlendMode = cBlend,
                    imageBitmapCache = imageBitmapCache,
                    sharedTransformMatrix = androidx.compose.ui.graphics.Matrix()
                )
            }
        }
        bitmap
    } catch (e: Exception) {
        e.printStackTrace()
        null
    }
}

@Composable
